import { 
  onAuthStateChanged, 
  signInAnonymously 
} from 'firebase/auth';
import { 
  collection, 
  doc, 
  setDoc, 
  getDoc, 
  query, 
  where, 
  getDocs,
  serverTimestamp,
  enableNetwork,
  disableNetwork
} from 'firebase/firestore';
import { 
  ref as dbRef,
  set as dbSet,
  get as dbGet,
  push as dbPush,
  serverTimestamp as dbServerTimestamp
} from 'firebase/database';
import { 
  ref, 
  uploadBytes, 
  getDownloadURL 
} from 'firebase/storage';

// Import from your existing Firebase configuration
import { 
  app,
  auth as firebaseAuth,
  db as firestore,
  rtdb as realtimeDb,
  storage as firebaseStorage,
  getAuthInstance,
  getDb,
  getRtdb,
  getStorageInstance
} from '../firebase';

// Hybrid service supporting both Firestore and Realtime Database
export class AudioProfileServiceHybrid {
  constructor(firebaseApp = app) {
    this.app = firebaseApp;
    // Use the existing singleton instances from firebase.js
    this.auth = getAuthInstance();
    this.firestore = getDb();
    this.realtimeDb = getRtdb();
    this.storage = getStorageInstance();
    this.currentUser = null;
    
    // Monitor auth state
    this.authUnsubscribe = onAuthStateChanged(this.auth, (user) => {
      this.currentUser = user;
      console.log('Auth state changed:', user ? user.uid : 'No user');
    });
  }
  
  // Ensure user is authenticated before operations
  async ensureAuthenticated() {
    if (!this.currentUser) {
      console.log('No authenticated user, signing in anonymously...');
      try {
        const userCredential = await signInAnonymously(this.auth);
        this.currentUser = userCredential.user;
        console.log('Signed in anonymously:', this.currentUser.uid);
      } catch (error) {
        console.error('Anonymous sign-in failed:', error);
        throw new Error('Authentication failed: ' + error.message);
      }
    }
    return this.currentUser;
  }
  
  // Create audio profile in both databases
  async createAudioProfile(audioBlob, fingerprint, metadata = {}) {
    try {
      // Ensure user is authenticated
      const user = await this.ensureAuthenticated();
      
      console.log('Creating audio profile for user:', user.uid);
      
      // Upload audio file to Storage
      const timestamp = Date.now();
      const audioFileName = `audio_profiles/${user.uid}/${timestamp}_audio.wav`;
      const storageRef = ref(this.storage, audioFileName);
      
      console.log('Uploading audio to Storage...');
      const uploadResult = await uploadBytes(storageRef, audioBlob);
      const audioUrl = await getDownloadURL(uploadResult.ref);
      console.log('Audio uploaded successfully:', audioUrl);
      
      // Prepare profile data
      const profileData = {
        userId: user.uid,
        audioUrl,
        fingerprint,
        metadata: {
          ...metadata,
          createdAt: timestamp,
          updatedAt: timestamp,
          fileSize: audioBlob.size,
          fileName: audioFileName,
          fingerprintLength: fingerprint.length
        }
      };
      
      // Save to Firestore
      const profileId = `${user.uid}_${timestamp}`;
      const firestoreRef = doc(this.firestore, 'audioProfiles', profileId);
      
      console.log('Saving profile to Firestore...');
      await setDoc(firestoreRef, {
        ...profileData,
        metadata: {
          ...profileData.metadata,
          createdAt: serverTimestamp(),
          updatedAt: serverTimestamp()
        }
      });
      
      // Also save to Realtime Database in chats/public/
      const roomId = `audio_${timestamp}_${Math.random().toString(36).substr(2, 9)}`;
      const realtimeDbRef = dbRef(this.realtimeDb, `chats/public/${roomId}`);
      
      console.log('Saving to Realtime Database...');
      const roomData = {
        name: metadata.name || 'Audio Room',
        description: metadata.keywords || '',
        type: 'audio',
        createdAt: dbServerTimestamp(),
        createdBy: user.uid,
        active: true,
        participants: {
          [user.uid]: {
            displayName: metadata.userName || 'Anonymous',
            lastActive: timestamp
          }
        },
        fingerprints: {
          [`fp_${timestamp}`]: {
            userId: user.uid,
            data: fingerprint,
            timestamp: dbServerTimestamp(),
            metadata
          }
        },
        messages: {},
        lastActivityTimestamp: timestamp,
        audioUrl,
        roomId
      };
      
      await dbSet(realtimeDbRef, roomData);
      
      console.log('Profile saved successfully:', profileId);
      
      return {
        id: profileId,
        roomId,
        ...profileData
      };
    } catch (error) {
      console.error('Error creating audio profile:', error);
      
      // Provide more specific error messages
      if (error.code === 'PERMISSION_DENIED') {
        throw new Error('Permission denied. Please check Realtime Database security rules.');
      } else if (error.code === 'permission-denied') {
        throw new Error('Permission denied. Please check Firestore security rules.');
      } else if (error.code === 'unauthenticated') {
        throw new Error('User not authenticated. Please sign in.');
      } else if (error.code === 'quota-exceeded') {
        throw new Error('Storage quota exceeded.');
      }
      
      throw error;
    }
  }
  
  // Get audio profile by ID (from Firestore)
  async getAudioProfile(profileId) {
    try {
      const user = await this.ensureAuthenticated();
      
      const profileRef = doc(this.firestore, 'audioProfiles', profileId);
      const profileDoc = await getDoc(profileRef);
      
      if (!profileDoc.exists()) {
        throw new Error('Profile not found');
      }
      
      const data = profileDoc.data();
      
      // Verify ownership
      if (data.userId !== user.uid) {
        throw new Error('Access denied to this profile');
      }
      
      return {
        id: profileDoc.id,
        ...data
      };
    } catch (error) {
      console.error('Error getting audio profile:', error);
      throw error;
    }
  }
  
  // Get room data from Realtime Database
  async getRoomData(roomId) {
    try {
      const user = await this.ensureAuthenticated();
      
      const roomRef = dbRef(this.realtimeDb, `chats/public/${roomId}`);
      const snapshot = await dbGet(roomRef);
      
      if (!snapshot.exists()) {
        throw new Error('Room not found');
      }
      
      const data = snapshot.val();
      
      // Optionally verify ownership
      if (data.userId !== user.uid) {
        console.warn('Accessing room created by different user');
      }
      
      return {
        roomId,
        ...data
      };
    } catch (error) {
      console.error('Error getting room data:', error);
      throw error;
    }
  }
  
  // Create audio room (Realtime Database only)
  async createAudioRoom(metadata = {}) {
    try {
      const user = await this.ensureAuthenticated();
      
      const timestamp = Date.now();
      const roomId = `audio_${timestamp}_${Math.random().toString(36).substr(2, 9)}`;
      const roomRef = dbRef(this.realtimeDb, `chats/public/${roomId}`);
      
      const roomData = {
        name: metadata.name || 'Audio Room',
        description: metadata.keywords || '',
        type: 'audio',
        createdAt: dbServerTimestamp(),
        createdBy: user.uid,
        active: true,
        participants: {
          [user.uid]: {
            displayName: metadata.userName || 'Anonymous',
            lastActive: timestamp
          }
        },
        messages: {},
        lastActivityTimestamp: timestamp,
        roomId
      };
      
      await dbSet(roomRef, roomData);
      
      return {
        roomId,
        ...roomData
      };
    } catch (error) {
      console.error('Error creating audio room:', error);
      throw error;
    }
  }
  
  // Get all profiles for current user (from Firestore)
  async getUserProfiles() {
    try {
      const user = await this.ensureAuthenticated();
      
      const q = query(
        collection(this.firestore, 'audioProfiles'),
        where('userId', '==', user.uid)
      );
      
      const querySnapshot = await getDocs(q);
      const profiles = [];
      
      querySnapshot.forEach((doc) => {
        profiles.push({
          id: doc.id,
          ...doc.data()
        });
      });
      
      return profiles;
    } catch (error) {
      console.error('Error getting user profiles:', error);
      throw error;
    }
  }
  
  // Compare fingerprints and store comparison result
  async compareFingerprints(fingerprint1, fingerprint2, similarity) {
    try {
      const user = await this.ensureAuthenticated();
      
      const comparisonData = {
        userId: user.uid,
        fingerprint1,
        fingerprint2,
        similarity,
        timestamp: serverTimestamp()
      };
      
      const comparisonRef = doc(collection(this.firestore, 'comparisons'));
      await setDoc(comparisonRef, comparisonData);
      
      return {
        id: comparisonRef.id,
        ...comparisonData
      };
    } catch (error) {
      console.error('Error saving comparison:', error);
      throw error;
    }
  }
  
  // Cleanup
  destroy() {
    if (this.authUnsubscribe) {
      this.authUnsubscribe();
    }
  }
}