import { 
  collection, 
  query, 
  where, 
  getDocs,
  doc,
  setDoc,
  getDoc,
  updateDoc,
  arrayUnion,
  serverTimestamp
} from 'firebase/firestore';
import { 
  ref as dbRef,
  set as dbSet,
  get as dbGet,
  push as dbPush,
  update as dbUpdate,
  serverTimestamp as dbServerTimestamp
} from 'firebase/database';

export class AudioMatchingService {
  constructor(firestore, realtimeDb) {
    this.firestore = firestore;
    this.realtimeDb = realtimeDb;
    this.MATCH_THRESHOLD = 0.7; // 70% similarity for robust matching
    this.LANDMARK_THRESHOLD = 0.15; // 15% similarity for landmark-based matching
    this.WINDOW_SIZE = 10; // Sliding window size for temporal matching
  }

  // Find existing room by audio fingerprint
  async findMatchingRoom(fingerprint, userId) {
    try {
      console.log('Starting audio fingerprint matching process...');
      
      // Get all audio rooms from Realtime Database
      const roomsRef = dbRef(this.realtimeDb, 'chats/public');
      const snapshot = await dbGet(roomsRef);
      
      if (!snapshot.exists()) {
        console.log('No rooms found in database');
        return null;
      }
      
      const rooms = snapshot.val();
      let bestMatch = null;
      let bestScore = 0;
      let roomsChecked = 0;
      
      // Check each room for audio fingerprints
      for (const [roomId, roomData] of Object.entries(rooms)) {
        if (!roomId.startsWith('audio_')) continue;
        
        roomsChecked++;
        
        // Check if room has fingerprints
        if (roomData.fingerprints) {
          for (const storedFingerprint of Object.values(roomData.fingerprints)) {
            const similarity = await this.calculateAdvancedSimilarity(
              fingerprint, 
              storedFingerprint.data
            );
            
            console.log(`Room ${roomId} similarity: ${(similarity * 100).toFixed(2)}%`);
            
            // Use different threshold based on fingerprint type
            const threshold = (fingerprint.landmarks || storedFingerprint.data.landmarks) 
              ? this.LANDMARK_THRESHOLD 
              : this.MATCH_THRESHOLD;
            
            if (similarity > threshold && similarity > bestScore) {
              bestMatch = { roomId, roomData, similarity };
              bestScore = similarity;
            }
          }
        }
      }
      
      console.log(`Checked ${roomsChecked} audio rooms`);
      
      if (bestMatch) {
        console.log(`Found match: ${bestMatch.roomId} with ${(bestMatch.similarity * 100).toFixed(2)}% similarity`);
      } else {
        console.log('No match found above threshold');
      }
      
      return bestMatch;
    } catch (error) {
      console.error('Error finding matching room:', error);
      throw error;
    }
  }

  // Advanced similarity calculation with sliding window for integer fingerprints
  async calculateAdvancedSimilarity(fingerprint1, fingerprint2) {
    if (!fingerprint1 || !fingerprint2) {
      console.log('Invalid fingerprints provided');
      return 0;
    }
    
    // Handle new fingerprint format with landmarks
    if (fingerprint1.landmarks && fingerprint2.landmarks) {
      return this.calculateLandmarkSimilarity(fingerprint1, fingerprint2);
    }
    
    // Ensure both fingerprints are valid arrays (legacy format)
    const fp1Array = Array.isArray(fingerprint1) ? fingerprint1 : (fingerprint1.legacy || fingerprint1.hashes || []);
    const fp2Array = Array.isArray(fingerprint2) ? fingerprint2 : (fingerprint2.legacy || fingerprint2.hashes || []);
    
    if (!Array.isArray(fp1Array) || !Array.isArray(fp2Array)) {
      console.log('Invalid fingerprint format');
      return 0;
    }
    
    // Use sliding window similarity for integer fingerprints
    const maxSimilarity = this.calculateSlidingWindowSimilarity(fp1Array, fp2Array);
    console.log(`Max similarity: ${(maxSimilarity * 100).toFixed(2)}%`);
    
    return maxSimilarity;
  }

  // Sliding window similarity calculation for integer fingerprints
  calculateSlidingWindowSimilarity(fp1, fp2) {
    if (!fp1.length || !fp2.length) return 0;
    
    let maxSimilarity = 0;
    const windowSize = Math.min(10, Math.min(fp1.length, fp2.length));
    
    for (let offset = -windowSize; offset <= windowSize; offset++) {
      let matches = 0;
      let comparisons = 0;
      
      for (let i = 0; i < fp1.length; i++) {
        const j = i + offset;
        if (j >= 0 && j < fp2.length) {
          // For integer hashes, use bitwise comparison
          const xor = fp1[i] ^ fp2[j];
          // Count matching bits (out of 32)
          const matchingBits = 32 - this.countSetBits(xor);
          const similarity = matchingBits / 32.0;
          
          matches += similarity;
          comparisons++;
        }
      }
      
      if (comparisons > 0) {
        const similarity = matches / comparisons;
        maxSimilarity = Math.max(maxSimilarity, similarity);
      }
    }
    
    return maxSimilarity;
  }

  // Count set bits in a number (Brian Kernighan's algorithm)
  countSetBits(n) {
    let count = 0;
    n = n >>> 0; // Convert to unsigned 32-bit integer
    while (n) {
      n &= n - 1;
      count++;
    }
    return count;
  }

  // Calculate similarity using landmark-based matching
  calculateLandmarkSimilarity(fingerprint1, fingerprint2) {
    const landmarks1 = fingerprint1.landmarks || [];
    const landmarks2 = fingerprint2.landmarks || [];
    
    if (landmarks1.length === 0 || landmarks2.length === 0) {
      return 0;
    }
    
    // Create hash lookup for fingerprint2
    const hashLookup = new Map();
    for (const landmark of landmarks2) {
      if (!hashLookup.has(landmark.hash)) {
        hashLookup.set(landmark.hash, []);
      }
      hashLookup.get(landmark.hash).push(landmark);
    }
    
    // Find matching landmarks
    let matches = 0;
    const timeDeltas = [];
    
    for (const landmark1 of landmarks1) {
      const candidates = hashLookup.get(landmark1.hash) || [];
      
      for (const landmark2 of candidates) {
        // Calculate time alignment
        const timeDiff = landmark2.time - landmark1.time;
        timeDeltas.push(timeDiff);
        matches++;
      }
    }
    
    // Find the most common time delta (indicates aligned matches)
    const MATCH_THRESHOLD = 5;
    if (timeDeltas.length >= MATCH_THRESHOLD) {
      const alignedMatches = this.findAlignedMatches(timeDeltas);
      const similarity = alignedMatches / Math.min(landmarks1.length, landmarks2.length);
      
      console.log(`Found ${alignedMatches} aligned matches, similarity: ${(similarity * 100).toFixed(2)}%`);
      return Math.min(1.0, similarity);
    }
    
    return 0;
  }

  // Find aligned matches based on consistent time deltas
  findAlignedMatches(timeDeltas) {
    if (timeDeltas.length === 0) return 0;
    
    // Count occurrences of each time delta
    const deltaCounts = new Map();
    for (const delta of timeDeltas) {
      deltaCounts.set(delta, (deltaCounts.get(delta) || 0) + 1);
    }
    
    // Find the most common delta
    let maxCount = 0;
    for (const count of deltaCounts.values()) {
      maxCount = Math.max(maxCount, count);
    }
    
    return maxCount;
  }

  // Create or join audio room
  async createOrJoinAudioRoom(audioData, metadata = {}) {
    try {
      const { fingerprint, userId, keywords, title } = audioData;
      
      console.log('Creating/joining room with fingerprint:', fingerprint.slice(0, 10));
      
      // First, try to find a matching room
      const matchingRoom = await this.findMatchingRoom(fingerprint, userId);
      
      if (matchingRoom) {
        // Join existing room
        console.log('Joining existing room:', matchingRoom.roomId);
        
        // Add user's fingerprint to the room
        await this.addFingerprintToRoom(
          matchingRoom.roomId, 
          fingerprint, 
          userId,
          metadata
        );
        
        return {
          roomId: matchingRoom.roomId,
          isNew: false,
          similarity: matchingRoom.similarity,
          ...matchingRoom.roomData
        };
      } else {
        // Create new room
        console.log('No match found, creating new room...');
        return await this.createNewAudioRoom(audioData, metadata);
      }
    } catch (error) {
      console.error('Error in createOrJoinAudioRoom:', error);
      throw error;
    }
  }

  // Create a new audio room in chats/public/
  async createNewAudioRoom(audioData, metadata = {}) {
    try {
      const { fingerprint, userId, keywords, title } = audioData;
      const timestamp = Date.now();
      const roomId = `audio_${timestamp}_${Math.random().toString(36).substr(2, 9)}`;
      
      const roomData = {
        name: title || 'Audio Room',
        description: keywords || '',
        type: 'audio',
        createdAt: dbServerTimestamp(),
        createdBy: userId,
        active: true,
        participants: {
          [userId]: {
            displayName: metadata.userName || 'Anonymous',
            lastActive: timestamp
          }
        },
        fingerprints: {
          [`fp_${timestamp}`]: {
            userId,
            data: fingerprint,
            timestamp: dbServerTimestamp(),
            metadata: {
              keywords,
              title,
              ...metadata
            }
          }
        },
        messages: {},
        lastActivityTimestamp: timestamp
      };
      
      // Create room in Realtime Database under chats/public/
      const roomRef = dbRef(this.realtimeDb, `chats/public/${roomId}`);
      await dbSet(roomRef, roomData);
      
      // Store fingerprint reference in Firestore for faster searching
      if (fingerprint && fingerprint.length > 0) {
        const fingerprintRef = doc(this.firestore, 'audioFingerprints', `${roomId}_${timestamp}`);
        await setDoc(fingerprintRef, {
          roomId,
          fingerprint,
          userId,
          timestamp: serverTimestamp(),
          metadata: {
            keywords,
            title,
            ...metadata
          }
        });
      }
      
      console.log('Created new audio room:', roomId);
      
      return {
        roomId,
        isNew: true,
        ...roomData
      };
    } catch (error) {
      console.error('Error creating audio room:', error);
      throw error;
    }
  }

  // Add a fingerprint to an existing room
  async addFingerprintToRoom(roomId, fingerprint, userId, metadata = {}) {
    try {
      const timestamp = Date.now();
      const fingerprintId = `fp_${timestamp}`;
      
      // Update room in Realtime Database
      const fingerprintRef = dbRef(
        this.realtimeDb, 
        `chats/public/${roomId}/fingerprints/${fingerprintId}`
      );
      
      await dbSet(fingerprintRef, {
        userId,
        data: fingerprint,
        timestamp: dbServerTimestamp(),
        metadata
      });
      
      // Update participant info
      const participantRef = dbRef(
        this.realtimeDb, 
        `chats/public/${roomId}/participants/${userId}`
      );
      
      await dbSet(participantRef, {
        displayName: metadata.userName || 'Anonymous',
        lastActive: timestamp
      });
      
      // Update last activity
      const roomRef = dbRef(this.realtimeDb, `chats/public/${roomId}`);
      await dbUpdate(roomRef, {
        lastActivityTimestamp: timestamp
      });
      
      // Also store in Firestore for searching
      const firestoreRef = doc(
        this.firestore, 
        'audioFingerprints', 
        `${roomId}_${timestamp}`
      );
      
      await setDoc(firestoreRef, {
        roomId,
        fingerprint,
        userId,
        timestamp: serverTimestamp(),
        metadata
      });
      
      console.log('Added fingerprint to room:', roomId);
    } catch (error) {
      console.error('Error adding fingerprint to room:', error);
      throw error;
    }
  }

  // Get all audio rooms
  async getAllAudioRooms() {
    try {
      const roomsRef = dbRef(this.realtimeDb, 'chats/public');
      const snapshot = await dbGet(roomsRef);
      
      if (!snapshot.exists()) {
        return [];
      }
      
      const rooms = snapshot.val();
      const audioRooms = [];
      
      for (const [roomId, roomData] of Object.entries(rooms)) {
        if (roomId.startsWith('audio_')) {
          audioRooms.push({
            roomId,
            ...roomData
          });
        }
      }
      
      return audioRooms;
    } catch (error) {
      console.error('Error getting audio rooms:', error);
      throw error;
    }
  }
}