// src/services/StripeSubscriptionService.js

import { detectEnvironment, getEnvironmentConfig } from '../utils/environmentDetection';

/**
 * Stripe Subscription Service
 * Handles subscription validation against environment-specific Stripe accounts
 */
class StripeSubscriptionService {
  constructor() {
    this.environment = detectEnvironment();
    this.config = getEnvironmentConfig();
  }

  /**
   * Get API endpoint based on environment
   */
  getApiEndpoint() {
    const baseUrl = this.environment === 'dev' 
      ? 'http://localhost:3001/api' // Your local backend
      : '/api'; // Production/test backend
    
    return `${baseUrl}/stripe`;
  }

  /**
   * Check if user has active subscription in current Stripe environment
   * @param {string} userId - Firebase user ID
   * @param {string} email - User email
   * @returns {Promise<object>} Subscription status
   */
  async checkSubscriptionStatus(userId, email) {
    try {
      console.log(`🔍 Checking subscription status in ${this.environment} environment for user:`, userId);
      
      const response = await fetch(`${this.getApiEndpoint()}/subscription-status`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Environment': this.environment
        },
        body: JSON.stringify({
          userId,
          email,
          environment: this.environment
        })
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();
      
      console.log(`✅ Stripe subscription check result (${this.environment}):`, data);
      
      return {
        success: true,
        isActive: data.isActive || false,
        subscription: data.subscription || null,
        customer: data.customer || null,
        environment: this.environment,
        stripeEnvironment: this.config.stripe.environment
      };
      
    } catch (error) {
      console.error(`❌ Error checking subscription status in ${this.environment}:`, error);
      
      // In development/test, we might want to allow manual override
      if (this.environment !== 'prod') {
        console.warn(`⚠️ Non-production environment - checking for manual override`);
        const manualOverride = this.getManualOverride(userId);
        if (manualOverride) {
          return manualOverride;
        }
      }
      
      return {
        success: false,
        isActive: false,
        error: error.message,
        environment: this.environment
      };
    }
  }

  /**
   * Manual override for development/testing
   * Allows developers to simulate premium status without actual Stripe subscriptions
   */
  getManualOverride(userId) {
    // Check localStorage for manual premium override (dev/test only)
    if (this.environment === 'dev' || this.environment === 'test') {
      const overrideKey = `premium_override_${userId}`;
      const override = localStorage.getItem(overrideKey);
      
      if (override) {
        const overrideData = JSON.parse(override);
        console.log(`🧪 Using manual premium override for ${this.environment}:`, overrideData);
        
        return {
          success: true,
          isActive: overrideData.isActive,
          subscription: {
            id: `test_sub_${Date.now()}`,
            status: 'active',
            plan: 'Premium',
            environment: this.environment
          },
          customer: {
            id: `test_cus_${Date.now()}`,
            email: overrideData.email
          },
          environment: this.environment,
          stripeEnvironment: this.config.stripe.environment,
          isManualOverride: true
        };
      }
    }
    
    return null;
  }

  /**
   * Set manual premium override (dev/test only)
   * @param {string} userId 
   * @param {boolean} isActive 
   * @param {string} email 
   */
  setManualOverride(userId, isActive, email) {
    if (this.environment === 'prod') {
      console.warn('❌ Manual overrides not allowed in production');
      return false;
    }
    
    const overrideKey = `premium_override_${userId}`;
    const overrideData = {
      isActive,
      email,
      setAt: new Date().toISOString(),
      environment: this.environment
    };
    
    localStorage.setItem(overrideKey, JSON.stringify(overrideData));
    console.log(`🧪 Set manual premium override for ${this.environment}:`, overrideData);
    
    return true;
  }

  /**
   * Clear manual premium override
   * @param {string} userId 
   */
  clearManualOverride(userId) {
    const overrideKey = `premium_override_${userId}`;
    localStorage.removeItem(overrideKey);
    console.log(`🧪 Cleared manual premium override for user:`, userId);
  }

  /**
   * Create customer in current Stripe environment
   * @param {object} customerData 
   */
  async createCustomer(customerData) {
    try {
      const response = await fetch(`${this.getApiEndpoint()}/create-customer`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Environment': this.environment
        },
        body: JSON.stringify({
          ...customerData,
          environment: this.environment
        })
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      return await response.json();
    } catch (error) {
      console.error('Error creating Stripe customer:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Get subscription details
   * @param {string} subscriptionId 
   */
  async getSubscriptionDetails(subscriptionId) {
    try {
      const response = await fetch(`${this.getApiEndpoint()}/subscription/${subscriptionId}`, {
        method: 'GET',
        headers: {
          'X-Environment': this.environment
        }
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      return await response.json();
    } catch (error) {
      console.error('Error getting subscription details:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Get environment info for debugging
   */
  getEnvironmentInfo() {
    return {
      environment: this.environment,
      config: this.config,
      apiEndpoint: this.getApiEndpoint()
    };
  }
}

// Export singleton instance
export const stripeSubscriptionService = new StripeSubscriptionService();
export default stripeSubscriptionService;
