import { Info, RefreshCw, AlertCircle } from 'lucide-react'
import Card from '../common/Card'
import SignalCard from './SignalCard'
import { CONTEXT_CATEGORIES, groupSignalsByCategory } from '../../utils/contextCategories'
import { useLiveData } from '../../contexts/LiveDataContext'

// Static class map — Tailwind JIT can't resolve template-literal classes.
// Keep in sync with CONTEXT_CATEGORIES[*].color values.
const CATEGORY_CLASSES = {
  emerald: { icon: 'text-emerald-400', label: 'text-emerald-400/80' },
  sky:     { icon: 'text-sky-400',     label: 'text-sky-400/80' },
  violet:  { icon: 'text-violet-400',  label: 'text-violet-400/80' },
  amber:   { icon: 'text-amber-400',   label: 'text-amber-400/80' },
  orange:  { icon: 'text-orange-400',  label: 'text-orange-400/80' },
  cyan:    { icon: 'text-cyan-400',    label: 'text-cyan-400/80' },
  rose:    { icon: 'text-rose-400',    label: 'text-rose-400/80' },
  yellow:  { icon: 'text-yellow-400',  label: 'text-yellow-400/80' },
}

function timeSince(ts) {
  if (!ts) return null
  const mins = Math.floor((Date.now() - ts) / 60000)
  if (mins < 1) return 'just now'
  if (mins < 60) return `${mins}m ago`
  const hrs = Math.floor(mins / 60)
  if (hrs < 24) return `${hrs}h ago`
  return `${Math.floor(hrs / 24)}d ago`
}

// Context panel for PredictionDetail.
//
// Phase 2: signals come from LiveDataContext.getContextSignalsForTags,
// which merges real BLS/EPA data (if refreshed) with mock fallbacks for
// tags not yet served by a real source. Refresh button triggers the
// contextService fetch.
export default function ContextPanel({ tags = [] }) {
  const {
    getContextSignalsForTags,
    runContextRefresh,
    contextRefreshing,
    contextLastRefresh,
    contextErrors,
    contextSources,
    contextSignals: rawContextSignals,
  } = useLiveData()

  if (!Array.isArray(tags) || tags.length === 0) return null

  const signals = getContextSignalsForTags(tags)
  const hasRealData = rawContextSignals.length > 0

  // Empty state — tags present but neither real nor mock coverage.
  if (signals.length === 0) {
    return (
      <Card className="p-5" hover={false}>
        <div className="flex items-center justify-between mb-2">
          <div className="flex items-center gap-2">
            <Info size={16} className="text-gray-500" />
            <h2 className="text-sm font-semibold text-gray-300">Context</h2>
          </div>
          <RefreshButton
            onClick={runContextRefresh}
            loading={contextRefreshing}
          />
        </div>
        <p className="text-xs text-gray-500">
          No context signals are loaded yet for this prediction&apos;s tags.
          Click refresh to pull from BLS / EPA.
        </p>
      </Card>
    )
  }

  const grouped = groupSignalsByCategory(signals)
  const latestAsOf = signals.map(s => s.asOf).filter(Boolean).sort().pop()
  // Count how many of the displayed signals are real (not mock)
  const realCount = signals.filter(s => rawContextSignals.some(r => r.id === s.id)).length
  const mockCount = signals.length - realCount

  return (
    <Card className="p-5" hover={false}>
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2 flex-wrap">
          <Info size={16} className="text-gray-400" />
          <h2 className="text-sm font-semibold text-gray-300">Context</h2>
          <span className="text-[10px] text-gray-600 bg-gray-800/60 px-1.5 py-0.5 rounded">
            {signals.length} {signals.length === 1 ? 'signal' : 'signals'}
          </span>
          {hasRealData && realCount > 0 && (
            <span className="text-[10px] text-emerald-400 bg-emerald-500/10 px-1.5 py-0.5 rounded">
              {realCount} live
            </span>
          )}
          {mockCount > 0 && (
            <span
              className="text-[10px] text-gray-500 bg-gray-800/40 px-1.5 py-0.5 rounded"
              title="Mock data — not yet served by a live source"
            >
              {mockCount} mock
            </span>
          )}
        </div>
        <div className="flex items-center gap-3">
          {contextLastRefresh && (
            <span className="text-[10px] text-gray-600 font-mono">
              refreshed {timeSince(contextLastRefresh)}
            </span>
          )}
          <RefreshButton onClick={runContextRefresh} loading={contextRefreshing} />
        </div>
      </div>

      <p className="text-[11px] text-gray-600 mb-4 leading-relaxed">
        Slow-moving reference indicators. Not weighted into outcome probabilities —
        these ground the prediction in objective data points.
        {latestAsOf && (
          <span className="ml-1 text-gray-500">
            Latest datum as of {new Date(latestAsOf).toLocaleDateString('en-US', {
              month: 'short', day: 'numeric', year: 'numeric',
            })}.
          </span>
        )}
      </p>

      {contextErrors && contextErrors.length > 0 && (
        <div className="mb-4 space-y-1 bg-red-500/5 border border-red-500/15 rounded-md p-2">
          {contextErrors.map((err, i) => (
            <p key={i} className="text-[11px] text-red-400/90 flex items-center gap-1.5">
              <AlertCircle size={10} className="shrink-0" />
              <span className="font-mono text-[10px]">{err.source}:</span> {err.error}
            </p>
          ))}
        </div>
      )}

      <div className="space-y-5">
        {Object.entries(grouped).map(([categoryId, catSignals]) => {
          const cat = CONTEXT_CATEGORIES[categoryId]
          if (!cat) return null
          const Icon = cat.icon
          const classes = CATEGORY_CLASSES[cat.color] || CATEGORY_CLASSES.emerald
          return (
            <div key={categoryId}>
              <div className="flex items-center gap-1.5 mb-2">
                <Icon size={12} className={classes.icon} />
                <span className={`text-[10px] uppercase tracking-wider font-semibold ${classes.label}`}>
                  {cat.label}
                </span>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2">
                {catSignals.map(signal => (
                  <SignalCard key={signal.id} signal={signal} />
                ))}
              </div>
            </div>
          )
        })}
      </div>

      {contextSources && Object.values(contextSources).some(Boolean) && (
        <p className="mt-4 text-[10px] text-gray-600 flex items-center gap-2 flex-wrap">
          Live sources:
          {[
            { key: 'bls', label: 'BLS' },
            { key: 'epa', label: 'EPA' },
            { key: 'census', label: 'Census' },
            { key: 'cdc', label: 'CDC' },
            { key: 'fbi', label: 'FBI' },
          ].map(({ key, label }) => (
            <span
              key={key}
              className={`flex items-center gap-1 ${contextSources[key] ? 'text-emerald-400/80' : 'text-gray-600'}`}
            >
              <span className={`w-1.5 h-1.5 rounded-full ${contextSources[key] ? 'bg-emerald-500' : 'bg-gray-700'}`} />
              {label}
            </span>
          ))}
        </p>
      )}
    </Card>
  )
}

function RefreshButton({ onClick, loading }) {
  return (
    <button
      onClick={onClick}
      disabled={loading}
      className="flex items-center gap-1 px-2 py-1 bg-gray-800/60 hover:bg-gray-800 disabled:opacity-50 border border-gray-700 rounded text-[10px] text-gray-400 transition-colors"
    >
      <RefreshCw size={10} className={loading ? 'animate-spin' : ''} />
      {loading ? 'Refreshing…' : 'Refresh'}
    </button>
  )
}
