export default function Card({ children, className = '', onClick, hover = true }) {
  return (
    <div
      onClick={onClick}
      className={`bg-gray-900 border border-gray-800 rounded-xl ${hover ? 'hover:border-gray-700 transition-all duration-200' : ''} ${onClick ? 'cursor-pointer' : ''} ${className}`}
    >
      {children}
    </div>
  )
}
