import { useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import { trackPageView } from '../utils/analytics';

// Custom hook to track page views in a React Router app
export const usePageTracking = () => {
  const location = useLocation();

  useEffect(() => {
    // Track page view whenever the location changes
    trackPageView(location.pathname + location.search);
  }, [location]);
};

// Custom hook to track component visibility (useful for tracking impressions)
export const useImpressionTracking = (elementId, eventName, eventCategory) => {
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            // Track the impression when element becomes visible
            if (window.gtag) {
              window.gtag('event', eventName, {
                event_category: eventCategory,
                event_label: elementId
              });
            }
            // Stop observing after first impression
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.5 } // Trigger when 50% of element is visible
    );

    const element = document.getElementById(elementId);
    if (element) {
      observer.observe(element);
    }

    return () => {
      if (element) {
        observer.unobserve(element);
      }
    };
  }, [elementId, eventName, eventCategory]);
};
