// DJ Streaming Diagnostic Component
// Add this to your DJ Studio to see real-time status

import React, { useState, useEffect } from 'react';
import { useDJMixer } from '../../contexts/DJMixerContext';

const DJStreamingDiagnostic = ({ isStreaming, streamingService }) => {
  const djMixer = useDJMixer();
  const [status, setStatus] = useState({});

  useEffect(() => {
    const checkStatus = () => {
      const liveKitService = streamingService?.getLiveKitService?.();
      const audioStream = djMixer?.mediaStreamDestinationRef?.current?.stream;
      const audioTracks = audioStream?.getAudioTracks() || [];

      setStatus({
        // DJ Mixer Context
        hasAudioContext: !!djMixer?.audioContextRef?.current,
        audioContextState: djMixer?.audioContextRef?.current?.state,
        hasMasterNodes: !!djMixer?.masterNodesRef?.current?.gain,
        hasMediaDestination: !!djMixer?.mediaStreamDestinationRef?.current,

        // Audio Stream
        hasAudioStream: !!audioStream,
        audioTrackCount: audioTracks.length,
        audioTrackLabel: audioTracks[0]?.label || 'N/A',
        audioTrackEnabled: audioTracks[0]?.enabled || false,

        // Streaming Status
        parentStreaming: isStreaming,
        hasStreamingService: !!streamingService,
        hasLiveKitService: !!liveKitService,
        liveKitConnected: liveKitService?.isConnected || false,
        liveKitRoomName: liveKitService?.currentRoom?.name || 'N/A',

        // LiveKit Stats
        ...(liveKitService?.getRoomStats ? liveKitService.getRoomStats() : {})
      });
    };

    // Check immediately and then every second
    checkStatus();
    const interval = setInterval(checkStatus, 1000);

    return () => clearInterval(interval);
  }, [djMixer, isStreaming, streamingService]);

  return (
    <div style={{
      position: 'fixed',
      top: '80px',
      right: '10px',
      background: 'rgba(0, 0, 0, 0.9)',
      color: '#0f0',
      padding: '15px',
      borderRadius: '8px',
      fontFamily: 'monospace',
      fontSize: '12px',
      maxWidth: '400px',
      zIndex: 9999,
      border: '2px solid #0f0'
    }}>
      <h3 style={{ margin: '0 0 10px 0', color: '#0ff' }}>🎛️ DJ Streaming Diagnostic</h3>

      <div style={{ marginBottom: '10px' }}>
        <strong style={{ color: '#ff0' }}>DJ Mixer Context:</strong>
        <div>Audio Context: {status.hasAudioContext ? '✅' : '❌'} ({status.audioContextState})</div>
        <div>Master Nodes: {status.hasMasterNodes ? '✅' : '❌'}</div>
        <div>Media Destination: {status.hasMediaDestination ? '✅' : '❌'}</div>
      </div>

      <div style={{ marginBottom: '10px' }}>
        <strong style={{ color: '#ff0' }}>DJ Audio Stream:</strong>
        <div>Has Stream: {status.hasAudioStream ? '✅' : '❌'}</div>
        <div>Audio Tracks: {status.audioTrackCount}</div>
        <div>Track Label: {status.audioTrackLabel}</div>
        <div>Track Enabled: {status.audioTrackEnabled ? '✅' : '❌'}</div>
      </div>

      <div style={{ marginBottom: '10px' }}>
        <strong style={{ color: '#ff0' }}>LiveKit Status:</strong>
        <div>Parent Streaming: {status.parentStreaming ? '✅' : '❌'}</div>
        <div>Has Service: {status.hasStreamingService ? '✅' : '❌'}</div>
        <div>LiveKit Service: {status.hasLiveKitService ? '✅' : '❌'}</div>
        <div>LiveKit Connected: {status.liveKitConnected ? '✅' : '❌'}</div>
        <div>Room: {status.liveKitRoomName}</div>
      </div>

      {status.liveKitConnected && (
        <div>
          <strong style={{ color: '#ff0' }}>LiveKit Stats:</strong>
          <div>Participants: {status.participantCount || 0}</div>
          <div>Published Tracks: {status.publishedTracks || 0}</div>
          <div>Subscribed Tracks: {status.subscribedTracks || 0}</div>
        </div>
      )}

      <button
        onClick={() => {
          console.log('=== FULL DIAGNOSTIC ===');
          console.log('Status:', status);
          console.log('DJ Mixer:', djMixer);
          console.log('Streaming Service:', streamingService);
          console.log('LiveKit Service:', streamingService?.getLiveKitService?.());
        }}
        style={{
          marginTop: '10px',
          padding: '5px 10px',
          background: '#0f0',
          color: '#000',
          border: 'none',
          borderRadius: '4px',
          cursor: 'pointer',
          fontWeight: 'bold'
        }}
      >
        Log Full Diagnostic
      </button>
    </div>
  );
};

export default DJStreamingDiagnostic;
