// src/contexts/SiteConfigContext.jsx
import React, { createContext, useContext, useState, useEffect } from 'react';
import { doc, getDoc, setDoc } from 'firebase/firestore';
import { db } from '../firebase';

// Create context
const SiteConfigContext = createContext();

// Default configuration
const DEFAULT_CONFIG = {
  siteName: 'TalkStudio',
  headerTagline: 'Find Conversations!',
  searchBarText: 'Search for topics...',
  footerText: '© 2025 TalkStudio. All rights reserved.',
  primaryColor: '#4F46E5',
  secondaryColor: '#1E40AF',
  // Maintenance mode settings
  maintenanceMode: {
    enabled: false,
    videoUrl: 'gs://talkstudio-fb.firebasestorage.app/backgrounds/wellbeback.mp4',
    adminAccess: true // Allow admins to bypass maintenance mode
  },
  // Always include at least one background with isActive=true
  backgrounds: [{
    id: 'default_bg',
    type: 'color',
    color: '#1e293b', // Dark blue color
    name: 'Default Background',
    isActive: true
  }],
  videoSettings: {
    autoplay: true,
    loop: true,
    muted: true,
    controls: false,
    playbackRate: 1
  },
  widgets: [],
  widgetSettings: {
    layout: 'Grid',
    borderRadius: 'Medium',
    shadow: 'Small',
    chartTheme: 'Default',
    chartAnimation: 'Fade',
    defaultTab: 'First',
    detailHeight: 'Standard'
  }
};

// Updated paths for post-migration environment
const CONFIG_PATHS = [
  { collection: 'system', document: 'config' },       // Original path
  { collection: 'siteConfig', document: 'default' },  // Alternative path
  { collection: 'config', document: 'siteConfig' }    // US-CENTRAL-1 standard path
];

export const SiteConfigProvider = ({ children }) => {
  const [config, setConfigState] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [configPath, setConfigPath] = useState(null);
  
  // Fetch config from Firestore
  useEffect(() => {
    console.log('SiteConfigContext: Setting up config fetch...');
    
    // Add timeout to prevent hanging forever
    const timeoutId = setTimeout(() => {
      if (loading) {
        console.warn('SiteConfigContext: Config fetch timed out after 3 seconds, using defaults');
        setConfigState(DEFAULT_CONFIG);
        setLoading(false);
      }
    }, 3000); // 3 second timeout
    
    const fetchConfig = async () => {
      console.log('SiteConfigContext: Starting to fetch config...');
      const startTime = Date.now();
      let configFound = false;

      try {
        // Try each possible config path
        for (const path of CONFIG_PATHS) {
          try {
            console.log(`Attempting to fetch config from ${path.collection}/${path.document}`);
            const configDoc = doc(db, path.collection, path.document);
            const docSnap = await getDoc(configDoc);
            
            if (docSnap.exists()) {
              // Get config from Firestore
              const configData = docSnap.data();
              
              // Ensure all required fields exist
              const mergedConfig = { ...DEFAULT_CONFIG, ...configData };
              
              // Set the config state
              setConfigState(mergedConfig);
              setConfigPath(path);
              setLoading(false);
              clearTimeout(timeoutId); // Clear the timeout as we found config
              configFound = true;
              
              const elapsed = Date.now() - startTime;
              console.log(`Successfully loaded config from ${path.collection}/${path.document} in ${elapsed}ms`);
              break;
            }
          } catch (pathErr) {
            console.warn(`Error accessing ${path.collection}/${path.document}:`, pathErr.message);
            // Continue to next path
          }
        }
        
        // If no config was found anywhere, use defaults
        if (!configFound) {
          console.warn('No site configuration found in any location, using default');
          setConfigState(DEFAULT_CONFIG);
          clearTimeout(timeoutId); // Clear timeout since we're using defaults
          
          // Try to create a new one with defaults at the US-CENTRAL-1 standard path
          try {
            const defaultPath = CONFIG_PATHS[2]; // US-CENTRAL-1 standard path
            const configDoc = doc(db, defaultPath.collection, defaultPath.document);
            await setDoc(configDoc, DEFAULT_CONFIG);
            setConfigPath(defaultPath);
            console.log(`Created default config in Firestore at ${defaultPath.collection}/${defaultPath.document}`);
          } catch (saveErr) {
            console.warn('Could not save default config:', saveErr.message);
            // Use the first path as fallback
            setConfigPath(CONFIG_PATHS[0]);
          }
          
          setLoading(false);
        }
      } catch (err) {
        console.error('Error fetching site config:', err);
        setError(err.message);
        // Use default config if there's an error
        setConfigState(DEFAULT_CONFIG);
        setConfigPath(CONFIG_PATHS[0]); // Use the first path as fallback
        setLoading(false);
        clearTimeout(timeoutId); // Clear timeout on error
        
        const elapsed = Date.now() - startTime;
        console.warn(`Using default config due to error after ${elapsed}ms`);
      }
    };
    
    fetchConfig();
    
    return () => {
      // Clear the timeout when component unmounts
      clearTimeout(timeoutId);
    };
  }, []);
  
  // Update specific field in the config
  const updateConfigField = (field, value) => {
    if (!config) return;
    
    setConfigState(prevConfig => ({
      ...prevConfig,
      [field]: value
    }));
  };
  
  // Update the entire config and save to Firestore
  const updateConfig = async (newConfig) => {
    if (!configPath) return false;
    
    try {
      const configDoc = doc(db, configPath.collection, configPath.document);
      await setDoc(configDoc, newConfig);
      setConfigState(newConfig);
      return true;
    } catch (err) {
      console.error('Error updating site config:', err);
      setError(err.message);
      
      // Try alternative paths if the primary fails
      for (const path of CONFIG_PATHS) {
        // Skip the path that just failed
        if (path.collection === configPath.collection && 
            path.document === configPath.document) continue;
        
        try {
          console.log(`Trying to save config to alternative path: ${path.collection}/${path.document}`);
          const altConfigDoc = doc(db, path.collection, path.document);
          await setDoc(altConfigDoc, newConfig);
          setConfigState(newConfig);
          setConfigPath(path);
          console.log(`Successfully saved config to ${path.collection}/${path.document}`);
          return true;
        } catch (altErr) {
          console.warn(`Failed to save to alternative path ${path.collection}/${path.document}:`, altErr.message);
        }
      }
      
      return false;
    }
  };
  
  // Set config without saving to Firestore (for temporary changes)
  const setConfig = (newConfig) => {
    setConfigState(newConfig);
  };
  
  // Context value
  const value = {
    config,
    loading,
    error,
    updateConfig,
    updateConfigField,
    setConfig,
    configPath
  };
  
  return (
    <SiteConfigContext.Provider value={value}>
      {children}
    </SiteConfigContext.Provider>
  );
};

// Custom hook to use the context
export const useSiteConfig = () => {
  const context = useContext(SiteConfigContext);
  if (context === undefined) {
    throw new Error('useSiteConfig must be used within a SiteConfigProvider');
  }
  return context;
};