// src/components/widgets/AnnouncementDetailPanel.jsx
import React, { useState, useEffect } from 'react';
import { X } from 'lucide-react';
import { 
  getDB, 
  doc, 
  getDoc,
  updateDoc,
  increment,
  arrayUnion,
  serverTimestamp
} from '../../utils/firebase-utils';
import { useAuth } from '../../contexts/AuthContext';
import './AnnouncementDetailPanel.css';

const AnnouncementDetailPanel = ({ announcement, onClose }) => {
  const [fullAnnouncement, setFullAnnouncement] = useState(announcement);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const { currentUser } = useAuth();
  
  useEffect(() => {
    const fetchAnnouncementDetails = async () => {
      if (!announcement || !announcement.id) {
        setError('Invalid announcement data');
        setLoading(false);
        return;
      }
      
      try {
        // Get db instance using the utility function to ensure proper region handling
        const db = getDB();
        if (!db) {
          console.error('Firestore database not available');
          setError('Database connection failed. Please try again later.');
          setLoading(false);
          return;
        }
        
        // Fetch the announcement document to get the most up-to-date data
        const announcementRef = doc(db, 'announcements', announcement.id);
        const announcementSnap = await getDoc(announcementRef);
        
        if (announcementSnap.exists()) {
          const announcementData = {
            id: announcementSnap.id,
            ...announcementSnap.data(),
            // Handle potential missing or invalid dates
            createdAt: announcementSnap.data().createdAt ? 
              (announcementSnap.data().createdAt.toDate ? announcementSnap.data().createdAt.toDate() : announcementSnap.data().createdAt) : 
              new Date()
          };
          
          setFullAnnouncement(announcementData);
          
          // Record that this user has viewed the announcement
          if (currentUser) {
            try {
              await updateDoc(announcementRef, {
                viewCount: increment(1),
                viewedBy: arrayUnion(currentUser.uid),
                lastViewedAt: serverTimestamp()
              });
            } catch (updateErr) {
              console.error('Failed to update announcement view stats:', updateErr);
              // Non-critical error, don't show to user
            }
          }
        } else {
          // If we can't find the announcement, use what we have
          setFullAnnouncement(announcement);
        }
      } catch (err) {
        console.error('Error fetching announcement details:', err);
        // Still use the passed-in announcement data if fetch fails
        setFullAnnouncement(announcement);
      } finally {
        setLoading(false);
      }
    };
    
    fetchAnnouncementDetails();
  }, [announcement, currentUser]);
  
  // Function to format dates
  const formatDate = (date) => {
    if (!date) return 'Unknown date';
    
    try {
      // Handle both Date objects and Firestore timestamps
      const dateObj = date instanceof Date ? date : 
                     (date.toDate ? date.toDate() : new Date(date));
      
      return new Intl.DateTimeFormat('en-US', {
        year: 'numeric',
        month: 'long',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      }).format(dateObj);
    } catch (err) {
      console.error('Error formatting date:', err);
      return 'Invalid date';
    }
  };
  
  if (loading) {
    return (
      <div className="announcement-detail-panel">
        <div className="panel-header">
          <h2>Announcement</h2>
          <button className="close-button" onClick={onClose}>
            <X size={24} />
          </button>
        </div>
        <div className="panel-content">
          <div className="loading-indicator">Loading announcement details...</div>
        </div>
      </div>
    );
  }
  
  if (error) {
    return (
      <div className="announcement-detail-panel">
        <div className="panel-header">
          <h2>Announcement</h2>
          <button className="close-button" onClick={onClose}>
            <X size={24} />
          </button>
        </div>
        <div className="panel-content">
          <div className="error-message">{error}</div>
        </div>
      </div>
    );
  }
  
  return (
    <div className="announcement-detail-panel">
      <div className="panel-header">
        <h2>Announcement</h2>
        <button className="close-button" onClick={onClose}>
          <X size={24} />
        </button>
      </div>
      
      <div className="panel-content">
        <div className="announcement-detail">
          <h3 className="announcement-title">{fullAnnouncement.title}</h3>
          
          <div className="announcement-meta">
            <span className="announcement-date">
              Posted: {formatDate(fullAnnouncement.createdAt)}
            </span>
            
            {(fullAnnouncement.authorName || fullAnnouncement.createdBy) && (
              <span className="announcement-author">
                By: {fullAnnouncement.authorName || fullAnnouncement.createdBy}
              </span>
            )}
          </div>
          
          <div className="announcement-content">
            {fullAnnouncement.content && (
              <p>{fullAnnouncement.content}</p>
            )}
          </div>
          
          {/* Display images - support both old and new formats */}
          {(fullAnnouncement.imageUrl || (fullAnnouncement.imageUrls && fullAnnouncement.imageUrls.length > 0)) && (
            <div className="announcement-images">
              {fullAnnouncement.imageUrls && fullAnnouncement.imageUrls.length > 0 ? (
                fullAnnouncement.imageUrls.map((imageUrl, index) => (
                  <div key={index} className="announcement-image">
                    <img 
                      src={imageUrl} 
                      alt={`${fullAnnouncement.title} - Image ${index + 1}`} 
                    />
                  </div>
                ))
              ) : (
                <div className="announcement-image">
                  <img 
                    src={fullAnnouncement.imageUrl} 
                    alt={fullAnnouncement.title} 
                  />
                </div>
              )}
            </div>
          )}
          
          {fullAnnouncement.linkUrl && (
            <div className="announcement-link">
              <a 
                href={fullAnnouncement.linkUrl} 
                target="_blank" 
                rel="noopener noreferrer"
              >
                {fullAnnouncement.linkText || 'Learn More'}
              </a>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AnnouncementDetailPanel;