// src/components/auth/GoogleLoginButton.jsx
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { FcGoogle } from 'react-icons/fc';
import { getAuth, signInWithPopup, GoogleAuthProvider, signInWithRedirect } from 'firebase/auth';
import { getFirestore, doc, getDoc, setDoc } from 'firebase/firestore';

/**
 * A standalone Google Login button component with enhanced error handling
 * Can be placed in any login/signup form
 */
const GoogleLoginButton = ({ redirectPath = '/', className = '' }) => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const navigate = useNavigate();
  
  const handleGoogleLogin = async () => {
    const auth = getAuth();
    const db = getFirestore();
    
    setLoading(true);
    setError('');
    
    try {
      console.log('Starting Google login process...');
      
      // Create a fresh provider for each login attempt
      const provider = new GoogleAuthProvider();
      provider.addScope('email');
      provider.addScope('profile');
      provider.setCustomParameters({ prompt: 'select_account' });
      
      // Try popup first, then fallback to redirect
      try {
        console.log('Attempting Google popup login...');
        const result = await signInWithPopup(auth, provider);
        console.log('Google popup login successful!');
        
        // Process user document in Firestore
        const user = result.user;
        const userDocRef = doc(db, 'users', user.uid);
        const userDoc = await getDoc(userDocRef);
        
        if (!userDoc.exists()) {
          console.log('Creating new user document for Google user');
          await setDoc(userDocRef, {
            email: user.email,
            displayName: user.displayName || user.email,
            photoURL: user.photoURL,
            createdAt: new Date(),
            provider: 'google',
            isAdmin: false,
            isAudit: false,
            isVIP: false
          });
        }
        
        // Navigate to intended destination
        navigate(redirectPath);
      } catch (popupError) {
        console.error('Popup method failed:', popupError);
        
        // Check if it's a popup-related error
        if (
          popupError.code === 'auth/popup-blocked' ||
          popupError.code === 'auth/popup-closed-by-user' ||
          popupError.code === 'auth/cancelled-popup-request' ||
          (popupError.message && popupError.message.includes('popup'))
        ) {
          // Try redirect method as fallback
          console.log('Falling back to redirect method...');
          setError('Popup login failed. Trying another method...');
          
          // Store the path for after login
          sessionStorage.setItem('authRedirect', redirectPath);
          
          // Use redirect (this will navigate away from the page)
          await signInWithRedirect(auth, provider);
          // Code below won't execute because of the redirect
        } else {
          // For other errors, rethrow
          throw popupError;
        }
      }
    } catch (err) {
      console.error('Google login failed:', err);
      
      // Set user-friendly error messages
      const errorMap = {
        'auth/internal-error': 'Internal authentication error. Please try again later.',
        'auth/network-request-failed': 'Network connection error. Please check your internet connection.',
        'auth/invalid-api-key': 'Authentication configuration error. Please contact support.',
        'auth/unauthorized-domain': 'This domain is not authorized for Google authentication.',
        'auth/popup-closed-by-user': 'Login popup was closed. Please try again.',
        'auth/user-cancelled': 'Sign in was cancelled. Please try again if you want to continue.'
      };
      
      setError(errorMap[err.code] || 'Google login failed. Please try again or use email login.');
    } finally {
      setLoading(false);
    }
  };
  
  return (
    <div className="google-login-container">
      <button
        className={`google-button ${className}`}
        onClick={handleGoogleLogin}
        disabled={loading}
        type="button"
      >
        <FcGoogle className="google-icon" size={20} />
        <span>{loading ? 'Signing in...' : 'Sign in with Google'}</span>
      </button>
      
      {error && <div className="error-message mt-2">{error}</div>}
      
      {error && error.includes('Trying another method') && (
        <div className="info-message mt-1">
          You will be redirected to Google for authentication...
        </div>
      )}
    </div>
  );
};

export default GoogleLoginButton;
