// src/utils/firebase-search-utils.js

import { getFirestore, collection, query, where, orderBy, limit, getDocs, doc, getDoc } from 'firebase/firestore';
import { getDatabase, ref, get, query as rtdbQuery, orderByChild, equalTo } from 'firebase/database';
import { getApp } from 'firebase/app';

// Debug logging function - enabled for development
const DEBUG_ENABLED = true;
const debug = (message, data) => {
  if (DEBUG_ENABLED) {
    console.log(`[FirebaseSearch] ${message}`, data || '');
  }
};

// Get Firestore instance with error handling
const getDB = () => {
  try {
    // Get the existing Firebase app instance
    const app = getApp();
    return getFirestore(app);
  } catch (error) {
    console.error('Error getting Firestore instance:', error);
    return null;
  }
};

// Get RTDB instance with error handling
const getRTDB = () => {
  try {
    // Get the existing Firebase app instance
    const app = getApp();
    return getDatabase(app);
  } catch (error) {
    console.error('Error getting Realtime Database instance:', error);
    return null;
  }
};

/**
 * Searches specifically for public chat rooms in RTDB only
 * Chat rooms are stored in the Realtime Database, not Firestore
 */
export const searchPublicChatRooms = async (searchTerm, resultLimit = 10) => {
  debug(`Starting RTDB search for: ${searchTerm}`);
  const results = [];
  
  try {
    // Only search in RTDB since that's where chat rooms are stored
    const rtdbResults = await searchRTDBPublicChats(searchTerm, resultLimit);
    if (rtdbResults.length > 0) {
      debug(`Found ${rtdbResults.length} results in RTDB`);
      results.push(...rtdbResults);
    }
    
    // If we don't have results, try the fallback search
    if (results.length === 0) {
      debug('No results found, trying fallback searches');
      const fallbackResults = await fallbackChatRoomSearch(searchTerm, resultLimit);
      results.push(...fallbackResults);
    }
    
    // Return empty array if no results found (don't use dummy data)
    return results;
  } catch (error) {
    debug('Error in searchPublicChatRooms:', error);
    // Return empty array on error instead of dummy data
    return [];
  }
};

/**
 * Search for chat rooms in the Realtime Database
 * All chat rooms are stored in RTDB, not Firestore
 */
const searchRTDBPublicChats = async (searchTerm, resultLimit) => {
  debug(`Searching RTDB for: ${searchTerm}`);
  const results = [];
  
  try {
    const db = getRTDB();
    if (!db) {
      throw new Error('RTDB is not available');
    }
    
    const searchTermLower = searchTerm.toLowerCase();
    
    // Try multiple possible paths where chat rooms might be stored
    const paths = [
      'chats/public',
      'public',
      'rooms',
      'chatRooms'
    ];
    
    for (const path of paths) {
      try {
        debug(`Checking ${path} path`);
        const chatsRef = ref(db, path);
        const snapshot = await get(chatsRef);
        
        if (snapshot.exists()) {
          debug(`Found data in ${path} path`);
          const rooms = snapshot.val();
          
          // Simple client-side filtering
          Object.entries(rooms).forEach(([id, room]) => {
            if (!room || !room.name) return;
            
            if (room.name.toLowerCase().includes(searchTermLower) || 
                (room.description && room.description.toLowerCase().includes(searchTermLower))) {
              results.push({
                id,
                ...room,
                matchType: room.name.toLowerCase().includes(searchTermLower) ? 'name' : 'description',
                dbPath: path // Track which path it came from
              });
            }
          });
          
          // If we found results in this path, don't check others
          if (results.length > 0) break;
        }
      } catch (error) {
        debug(`Error searching ${path} path:`, error);
      }
    }
    
    // Sort and limit results
    const sortedResults = results
      .sort((a, b) => {
        // Sort by match type first (name matches before description matches)
        if (a.matchType === 'name' && b.matchType !== 'name') return -1;
        if (a.matchType !== 'name' && b.matchType === 'name') return 1;
        
        // Then by active users (if available)
        const aUsers = a.activeUsers || 0;
        const bUsers = b.activeUsers || 0;
        return bUsers - aUsers;
      })
      .slice(0, resultLimit);
    
    return sortedResults;
  } catch (error) {
    debug('Error in searchRTDBPublicChats:', error);
    return [];
  }
};

// Remove the searchFirestorePublicChats function since chat rooms are not in Firestore
/**
 * A fallback search method that tries multiple paths in RTDB
 */
const fallbackChatRoomSearch = async (searchTerm, resultLimit) => {
  debug(`Running fallback search for: ${searchTerm}`);
  const results = [];
  
  try {
    // Try multiple paths in RTDB only
    const db = getRTDB();
    if (db) {
      // List of possible paths to check
      const paths = [
        'rooms',
        'chat_rooms',
        'chatRooms',
        'channels',
        'discussions'
      ];
      
      for (const path of paths) {
        try {
          debug(`Checking alternative path: ${path}`);
          const pathRef = ref(db, path);
          const snapshot = await get(pathRef);
          
          if (snapshot.exists()) {
            debug(`Found data in ${path} path`);
            const rooms = snapshot.val();
            const searchTermLower = searchTerm.toLowerCase();
            
            // Process results
            Object.entries(rooms).forEach(([id, room]) => {
              if (!room || typeof room !== 'object') return;
              
              // Extract name and description, allowing for different property names
              const name = room.name || room.title || room.displayName;
              const description = room.description || room.desc || room.about || room.info;
              
              if (!name) return;
              
              if (name.toLowerCase().includes(searchTermLower) || 
                  (description && description.toLowerCase().includes(searchTermLower))) {
                results.push({
                  id,
                  name,
                  description,
                  activeUsers: room.activeUsers || room.users || 0,
                  matchType: name.toLowerCase().includes(searchTermLower) ? 'name' : 'description',
                  type: 'public'
                });
              }
            });
          }
        } catch (error) {
          debug(`Error checking ${path} path:`, error);
        }
      }
    }
    
    // If we found results, return them
    if (results.length > 0) {
      return results.slice(0, resultLimit);
    }
    
    // If no results found, return empty array
    return [];
  } catch (error) {
    debug('Error in fallback chat room search:', error);
    return [];
  }
};

/**
 * Searches for artists in Firestore based on artist name, genre, or bio
 * Artists are stored in Firestore users collection with isArtist=true
 */
export const searchArtists = async (searchTerm, resultLimit = 10) => {
  debug(`Searching artists for: ${searchTerm}`);
  const results = [];
  
  try {
    const db = getDB();
    if (!db) {
      throw new Error('Firestore is not available');
    }
    
    const searchTermLower = searchTerm.toLowerCase();
    
    // Search in users collection for artists
    try {
      debug('Checking users collection for artists');
      const usersRef = collection(db, 'users');
      const artistQuery = query(usersRef, where('isArtist', '==', true));
      const snapshot = await getDocs(artistQuery);
      
      if (!snapshot.empty) {
        debug(`Found ${snapshot.size} artists in users collection`);
        
        snapshot.forEach(doc => {
          const artist = doc.data();
          
          // Check various fields for search term
          const artistName = artist.displayName || artist.username || '';
          const genre = artist.genre || '';
          const bio = artist.bio || '';
          const location = artist.location || '';
          
          if (artistName.toLowerCase().includes(searchTermLower) || 
              genre.toLowerCase().includes(searchTermLower) ||
              bio.toLowerCase().includes(searchTermLower) ||
              location.toLowerCase().includes(searchTermLower)) {
            
            let matchType = 'other';
            if (artistName.toLowerCase().includes(searchTermLower)) {
              matchType = 'name';
            } else if (genre.toLowerCase().includes(searchTermLower)) {
              matchType = 'genre';
            }
            
            results.push({
              id: doc.id,
              type: 'artist',
              name: artistName,
              genre: genre,
              bio: bio,
              location: location,
              followerCount: artist.followerCount || 0,
              streamCount: artist.streamCount || 0,
              profileImageUrl: artist.photoURL || '',
              matchType: matchType
            });
          }
        });
      } else {
        debug('No artists found in users collection');
      }
    } catch (error) {
      debug('Error searching users collection:', error);
    }
    
    // Sort results by relevance
    const sortedResults = results
      .sort((a, b) => {
        // Sort by match type first (name matches before genre matches)
        if (a.matchType === 'name' && b.matchType !== 'name') return -1;
        if (a.matchType !== 'name' && b.matchType === 'name') return 1;
        if (a.matchType === 'genre' && b.matchType === 'other') return -1;
        if (a.matchType === 'other' && b.matchType === 'genre') return 1;
        
        // Then by follower count
        return b.followerCount - a.followerCount;
      })
      .slice(0, resultLimit);
    
    return sortedResults;
  } catch (error) {
    debug('Error in searchArtists:', error);
    return [];
  }
};

/**
 * Searches for events in Firestore
 * Events include both upcoming and past events
 */
export const searchEvents = async (searchTerm, resultLimit = 10) => {
  debug(`Searching events for: ${searchTerm}`);
  const results = [];
  
  try {
    const db = getDB();
    if (!db) {
      throw new Error('Firestore is not available');
    }
    
    const searchTermLower = searchTerm.toLowerCase();
    
    // Search in events collection
    try {
      debug('Checking events collection');
      const eventsRef = collection(db, 'events');
      // Get all events - we'll filter client-side for better search flexibility
      const snapshot = await getDocs(eventsRef);
      
      if (!snapshot.empty) {
        debug(`Found ${snapshot.size} events in collection`);
        
        snapshot.forEach(doc => {
          const event = doc.data();
          
          // Check various fields for search term
          const eventTitle = event.title || '';
          const eventDescription = event.description || '';
          const artistName = event.artistName || '';
          const category = event.category || event.type || '';
          
          if (eventTitle.toLowerCase().includes(searchTermLower) || 
              eventDescription.toLowerCase().includes(searchTermLower) ||
              artistName.toLowerCase().includes(searchTermLower) ||
              category.toLowerCase().includes(searchTermLower)) {
            
            let matchType = 'other';
            if (eventTitle.toLowerCase().includes(searchTermLower)) {
              matchType = 'title';
            } else if (artistName.toLowerCase().includes(searchTermLower)) {
              matchType = 'artist';
            } else if (category.toLowerCase().includes(searchTermLower)) {
              matchType = 'category';
            }
            
            results.push({
              id: doc.id,
              type: 'event',
              title: eventTitle,
              description: eventDescription,
              artistName: artistName,
              category: category,
              status: event.status || 'scheduled',
              startTime: event.startTime,
              endTime: event.endTime,
              thumbnailUrl: event.thumbnailUrl || '',
              viewerCount: event.viewerCount || 0,
              artistAvatar: event.artistAvatar || '',
              artistVerified: event.artistVerified || false,
              matchType: matchType
            });
          }
        });
      } else {
        debug('No events found in events collection');
      }
    } catch (error) {
      debug('Error searching events collection:', error);
    }
    
    // Sort results by relevance and then by start time
    const sortedResults = results
      .sort((a, b) => {
        // Sort by match type first (title matches before artist matches)
        if (a.matchType === 'title' && b.matchType !== 'title') return -1;
        if (a.matchType !== 'title' && b.matchType === 'title') return 1;
        if (a.matchType === 'artist' && b.matchType === 'other') return -1;
        if (a.matchType === 'other' && b.matchType === 'artist') return 1;
        
        // Then by status priority (live > upcoming > past)
        const statusPriority = { 'live': 3, 'scheduled': 2, 'ended': 1 };
        const aPriority = statusPriority[a.status] || 0;
        const bPriority = statusPriority[b.status] || 0;
        if (aPriority !== bPriority) return bPriority - aPriority;
        
        // Finally by start time (newer first for live/ended, sooner first for scheduled)
        if (a.status === 'scheduled' && b.status === 'scheduled') {
          return a.startTime - b.startTime; // Upcoming events: sooner first
        } else {
          return b.startTime - a.startTime; // Live/ended events: newer first
        }
      })
      .slice(0, resultLimit);
    
    return sortedResults;
  } catch (error) {
    debug('Error in searchEvents:', error);
    return [];
  }
};

/**
 * Searches for regular users (people) in Firestore
 * These are users who are NOT artists (isArtist !== true)
 */
export const searchPeople = async (searchTerm, resultLimit = 10) => {
  debug(`Searching people for: ${searchTerm}`);
  const results = [];
  
  try {
    const db = getDB();
    if (!db) {
      throw new Error('Firestore is not available');
    }
    
    const searchTermLower = searchTerm.toLowerCase();
    
    // Search in users collection for non-artists
    try {
      debug('Checking users collection for people (non-artists)');
      const usersRef = collection(db, 'users');
      
      // Get all users - we'll filter client-side since we can't easily query for isArtist != true
      const snapshot = await getDocs(usersRef);
      
      if (!snapshot.empty) {
        debug(`Found ${snapshot.size} users, filtering for non-artists`);
        
        snapshot.forEach(doc => {
          const user = doc.data();
          
          // Skip if this user is an artist
          if (user.isArtist === true) return;
          
          // Check various fields for search term
          const userName = user.displayName || user.username || user.email || '';
          const bio = user.bio || '';
          const location = user.location || '';
          
          if (userName.toLowerCase().includes(searchTermLower) || 
              bio.toLowerCase().includes(searchTermLower) ||
              location.toLowerCase().includes(searchTermLower) ||
              (user.email && user.email.toLowerCase().includes(searchTermLower))) {
            
            let matchType = 'other';
            if (userName.toLowerCase().includes(searchTermLower)) {
              matchType = 'name';
            } else if (user.email && user.email.toLowerCase().includes(searchTermLower)) {
              matchType = 'email';
            }
            
            results.push({
              id: doc.id,
              type: 'user',
              name: userName,
              email: user.email || '',
              bio: bio,
              location: location,
              profileImageUrl: user.photoURL || '',
              createdAt: user.createdAt,
              matchType: matchType
            });
          }
        });
      } else {
        debug('No users found in users collection');
      }
    } catch (error) {
      debug('Error searching users collection:', error);
    }
    
    // Sort results by relevance
    const sortedResults = results
      .sort((a, b) => {
        // Sort by match type first (name matches before email matches)
        if (a.matchType === 'name' && b.matchType !== 'name') return -1;
        if (a.matchType !== 'name' && b.matchType === 'name') return 1;
        if (a.matchType === 'email' && b.matchType === 'other') return -1;
        if (a.matchType === 'other' && b.matchType === 'email') return 1;
        
        // Then by creation date (newer users first)
        const aTime = a.createdAt?.seconds || 0;
        const bTime = b.createdAt?.seconds || 0;
        return bTime - aTime;
      })
      .slice(0, resultLimit);
    
    return sortedResults;
  } catch (error) {
    debug('Error in searchPeople:', error);
    return [];
  }
};

/**
 * Performs a multi-collection search
 * - Chat rooms: searched in RTDB
 * - Artists: searched in Firestore
 * - Events: searched in Firestore
 * - People: searched in Firestore
 */
export const multiSearch = async (searchTerm, collections = ['publicChats'], resultLimit = 10) => {
  try {
    debug(`Starting multi-collection search for: ${searchTerm}`);
    const results = {
      publicChats: [],
      artists: [],
      people: [],
      events: []
    };
    
    // Search for public chats in RTDB
    if (collections.includes('publicChats')) {
      const chatResults = await searchPublicChatRooms(searchTerm, resultLimit);
      results.publicChats = chatResults;
    }
    
    // Search for artists in Firestore
    if (collections.includes('artists')) {
      const artistResults = await searchArtists(searchTerm, resultLimit);
      results.artists = artistResults;
    }
    
    // Search for people (non-artist users) in Firestore
    if (collections.includes('people')) {
      const peopleResults = await searchPeople(searchTerm, resultLimit);
      results.people = peopleResults;
    }
    
    // Search for events in Firestore
    if (collections.includes('events')) {
      const eventResults = await searchEvents(searchTerm, resultLimit);
      results.events = eventResults;
    }
    
    return results;
  } catch (error) {
    debug('Error in multiSearch:', error);
    // Return empty results on error to avoid breaking the UI
    return { publicChats: [], artists: [], people: [], events: [] };
  }
};

