/**
 * Fallback function for when the primary search fails - returns empty results
 * Makes the search component more resilient without showing fake data
 */
export const fallbackSearch = async (searchTerm, collections = ['publicChats'], resultLimit = 10) => {
  try {
    const results = await multiSearch(searchTerm, collections, resultLimit);
    return results;
  } catch (error) {
    debug('Error in search, returning empty results:', error);
    return { publicChats: [], artists: [], people: [], events: [] };
  }
};

// Export a wrapper function that handles errors gracefully
export const safeMultiSearch = async (searchTerm, collections = ['publicChats', 'artists', 'people', 'events'], resultLimit = 10) => {
  try {
    return await multiSearch(searchTerm, collections, resultLimit);
  } catch (error) {
    debug('Error in multiSearch, returning empty results:', error);
    // Return empty results instead of dummy data
    return { publicChats: [], artists: [], people: [], events: [] };
  }
};