// Shared CORS-tolerant fetch with proxy fallback.
//
// Tries a direct fetch first (works when the target API ships CORS headers),
// then falls through a list of public CORS proxies. Used by context sources
// that don't ship CORS (BLS especially). Extracted from the earlier inline
// logic in rssService so every new context service can share it.
//
// Returns a shape like: { ok, data, error, usedProxy }.
// - parse: 'json' | 'text' | 'raw' (raw returns the Response object, you handle it)
// - timeout defaults to 12s (context sources are not latency-sensitive)

const CORS_PROXIES = [
  url => `https://corsproxy.io/?${encodeURIComponent(url)}`,
  url => `https://api.allorigins.win/raw?url=${encodeURIComponent(url)}`,
]

export async function corsFetch(url, options = {}) {
  const {
    method = 'GET',
    body,
    headers,
    timeout = 12000,
    parse = 'json',
    proxyFirst = false, // set true if you already know the API lacks CORS
  } = options

  const buildAttempts = () => {
    const proxies = CORS_PROXIES.map(fn => ({ direct: false, url: fn(url) }))
    return proxyFirst
      ? [...proxies, { direct: true, url }]
      : [{ direct: true, url }, ...proxies]
  }

  let lastError = null
  for (const attempt of buildAttempts()) {
    try {
      const res = await fetch(attempt.url, {
        method,
        body,
        headers,
        signal: AbortSignal.timeout(timeout),
      })
      if (!res.ok) {
        lastError = `HTTP ${res.status}`
        continue
      }
      if (parse === 'raw') {
        return { ok: true, data: res, error: null, usedProxy: !attempt.direct }
      }
      if (parse === 'text') {
        return { ok: true, data: await res.text(), error: null, usedProxy: !attempt.direct }
      }
      return { ok: true, data: await res.json(), error: null, usedProxy: !attempt.direct }
    } catch (err) {
      lastError = err?.message || String(err)
    }
  }
  return { ok: false, data: null, error: lastError || 'All fetch attempts failed', usedProxy: false }
}
