import { useState, useEffect } from 'react';
import { db } from '../firebase';
import { 
  collection, 
  getDocs, 
  query,
  where,
  orderBy,
  limit,
  getDoc,
  doc
} from 'firebase/firestore';
import { getDatabase, ref, get, child, set, update } from 'firebase/database';

/**
 * Custom hook for fetching and managing chat rooms.
 * Provides validated chat room data with consistent field structure.
 * 
 * @param {Object} options - Configuration options
 * @param {boolean} options.loadOnMount - Whether to load rooms automatically on mount
 * @param {string} options.collection - Firestore collection name to use (default: 'publicChats')
 * @param {number} options.limit - Maximum number of rooms to fetch (default: 100)
 * @param {Array} options.filters - Additional Firestore query filters
 * @param {boolean} options.onlyActive - Whether to fetch only active rooms
 * @returns {Object} - Hook state and methods
 */
export const useChatRooms = (options = {}) => {
  const {
    loadOnMount = true,
    collectionName = 'publicChats',
    roomLimit = 100,
    filters = [],
    onlyActive = false
  } = options;

  const [rooms, setRooms] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [lastFetched, setLastFetched] = useState(null);

  /**
   * Helper function to fetch rooms from Realtime Database
   * @returns {Promise<Array>}
   */
  const fetchRoomsFromRTDB = async () => {
    try {
      console.log('Attempting to fetch rooms from Realtime Database (chats/public)');
      
      // Get RTDB instance
      const rtdb = getDatabase();
      const dbRef = ref(rtdb);
      
      // Get all rooms from the 'chats/public' path
      const snapshot = await get(child(dbRef, 'chats/public'));
      
      if (!snapshot.exists()) {
        console.log('No rooms found in Realtime Database');
        return [];
      }
      
      // Convert snapshot to array of room objects
      const roomsData = [];
      snapshot.forEach((childSnapshot) => {
        const id = childSnapshot.key;
        const data = childSnapshot.val();
        
        // Skip entries without a name
        if (!data.name) return;
        
        roomsData.push({
          id,
          ...data,
          // Add source information
          source: 'rtdb',
          rtdbPath: `chats/public/${id}`,
          // Handle active status and participant count
          active: data.active !== false, // Default to true if not specified
          participants: data.activeUsers || data.participantCount || 0,
          // Set default room type if not specified
          type: data.type || 'public'
        });
      });
      
      console.log(`Fetched ${roomsData.length} rooms from Realtime Database`);
      return roomsData;
    } catch (err) {
      console.error('Error fetching rooms from Realtime Database:', err);
      return [];
    }
  };

  /**
   * Validates and standardizes room data structure
   * 
   * @param {Array} roomsData - Raw room data from Firestore or RTDB
   * @returns {Array} - Standardized room data
   */
  const validateRoomsData = (roomsData) => {
    if (!roomsData || !Array.isArray(roomsData)) {
      console.error('Invalid rooms data:', roomsData);
      return [];
    }
    
    return roomsData.map(room => {
      if (!room || !room.id) {
        console.error('Invalid room object:', room);
        return null;
      }
      
      const validatedRoom = {
        ...room,
        // Ensure required fields exist with defaults if missing
        name: room.name || room.title || room.roomName || `Room ${room.id.substring(0, 6)}`,
        description: room.description || room.desc || room.about || '',
        isActive: room.isActive !== false, // Default to true if not specified
        createdAt: room.createdAt || room.created || null,
        // Store source information 
        source: room.source || 'unknown',
        hasAudioSignature: !!room.hasAudioSignature
      };
      
      if (validatedRoom.source === 'rtdb') {
        validatedRoom.rtdbPath = room.rtdbPath || `chats/public/${room.id}`;
      } else if (validatedRoom.source === 'firestore') {
        validatedRoom.collectionName = room.collectionName || 'rooms';
      }
      
      return validatedRoom;
    }).filter(room => room !== null);
  };

  /**
   * Fetches chat rooms from Firestore and RTDB
   * 
   * @param {Object} fetchOptions - Options to override defaults
   * @returns {Promise<Array>} - Validated room data
   */
  const fetchRooms = async (fetchOptions = {}) => {
    try {
      setLoading(true);
      setError(null);
      
      let allRooms = [];
      
      // Fetch from Realtime Database first (where most chat rooms are stored)
      try {
        const rtdbRooms = await fetchRoomsFromRTDB();
        if (rtdbRooms.length > 0) {
          console.log(`Found ${rtdbRooms.length} rooms in Realtime Database`);
          allRooms = [...allRooms, ...rtdbRooms];
        }
      } catch (rtdbErr) {
        console.error('Error fetching from Realtime Database:', rtdbErr);
      }
      
      // Get collection name from options or use default
      const targetCollection = fetchOptions.collectionName || collectionName;
      console.log('Fetching rooms from Firestore collection:', targetCollection);
      
      // If no rooms are found in the primary collection, we'll try these collections in order
      const fallbackCollections = ['publicChats', 'rooms', 'chatRooms']
        .filter(name => name !== targetCollection);
      
      // Try the primary collection first
      let firestoreRooms = await fetchRoomsFromCollection(targetCollection, fetchOptions);
      
      // If no rooms found, try fallback collections
      if (firestoreRooms.length === 0) {
        console.log(`No rooms found in ${targetCollection}, trying fallbacks...`);
        
        for (const fallbackCollection of fallbackCollections) {
          console.log(`Trying fallback collection: ${fallbackCollection}`);
          const fallbackData = await fetchRoomsFromCollection(fallbackCollection, fetchOptions);
          
          if (fallbackData.length > 0) {
            console.log(`Found ${fallbackData.length} rooms in ${fallbackCollection}`);
            firestoreRooms = fallbackData;
            break;
          }
        }
      }
      
      // Combine rooms from RTDB and Firestore
      allRooms = [...allRooms, ...firestoreRooms];
      
      // Validate and standardize room data
      const validatedRooms = validateRoomsData(allRooms);
      
      // Log final result
      console.log(`Total rooms found from all sources: ${validatedRooms.length}`);
      validatedRooms.forEach(room => {
        console.log(`- Room: ${room.name} (${room.id}) from ${room.source || 'unknown source'}`);
      });
      
      // Set state
      setRooms(validatedRooms);
      setLastFetched(new Date());
      setLoading(false);
      
      return validatedRooms;
    } catch (err) {
      console.error('Error fetching chat rooms:', err);
      setError(err.message || 'Failed to fetch chat rooms');
      setLoading(false);
      return [];
    }
  };
  
  /**
   * Helper function to fetch rooms from a specific collection
   * 
   * @param {string} collectionName - Firestore collection to query
   * @param {Object} options - Query options
   * @returns {Promise<Array>} - Room data from the collection
   */
  const fetchRoomsFromCollection = async (collectionName, options = {}) => {
    try {
      // Build query
      const roomsRef = collection(db, collectionName);
      
      // Start with base constraints
      let constraints = [];
      
      // Add optional constraints
      if (options.onlyActive || onlyActive) {
        constraints.push(where('isActive', '==', true));
      }
      
      // Add custom filters
      const filtersToApply = options.filters || filters;
      if (filtersToApply && filtersToApply.length > 0) {
        constraints = [...constraints, ...filtersToApply];
      }
      
      // Add ordering if provided
      if (options.orderBy) {
        constraints.push(orderBy(options.orderBy.field, options.orderBy.direction || 'desc'));
      }
      
      // Add limit
      const limitValue = options.limit || roomLimit;
      if (limitValue) {
        constraints.push(limit(limitValue));
      }
      
      // Execute query
      const roomsQuery = constraints.length > 0 
        ? query(roomsRef, ...constraints)
        : query(roomsRef);
        
      console.log(`Executing query on ${collectionName}:`, { constraints: constraints.length });
      
      // Attempt to execute the query
      const roomsSnapshot = await getDocs(roomsQuery);
      
      // Check if the snapshot is empty
      if (roomsSnapshot.empty) {
        console.log(`No chat rooms found in ${collectionName}`);
        return [];
      }
      
      // Map document data
      const roomsData = roomsSnapshot.docs.map(doc => {
        const data = doc.data();
        return {
          id: doc.id,
          ...data,
          source: 'firestore',
          collectionName, // Store source collection name
        };
      });
      
      console.log(`Fetched ${roomsData.length} chat rooms from ${collectionName}`);
      return roomsData;
    } catch (err) {
      console.error(`Error querying ${collectionName}:`, err);
      return [];
    }
  };

  // Auto-load rooms on mount if enabled
  useEffect(() => {
    if (loadOnMount) {
      console.log('useChatRooms: Auto-loading rooms on mount');
      fetchRooms().then(rooms => {
        console.log(`useChatRooms: Successfully loaded ${rooms.length} rooms`);
        
        // If we still have no rooms, check if we can find any manually
        if (rooms.length === 0) {
          console.log('Attempting additional room lookup...');
          
          // Try to get a sample room ID to confirm collections exist
          Promise.all([
            // Check RTDB
            new Promise(resolve => {
              try {
                const rtdb = getDatabase();
                const dbRef = ref(rtdb);
                get(child(dbRef, 'chats/public')).then(snapshot => {
                  if (snapshot.exists()) {
                    console.log('RTDB chats/public path exists and contains data');
                  } else {
                    console.log('RTDB chats/public path is empty or does not exist');
                  }
                  resolve();
                }).catch(err => {
                  console.error('Error checking RTDB:', err);
                  resolve();
                });
              } catch (err) {
                console.error('Error initializing RTDB check:', err);
                resolve();
              }
            }),
            
            // Check Firestore collections
            getDoc(doc(db, 'publicChats', 'sampleRoom')).catch(() => null),
            getDoc(doc(db, 'rooms', 'sampleRoom')).catch(() => null),
            getDoc(doc(db, 'chatRooms', 'sampleRoom')).catch(() => null)
          ]).then(() => {
            console.log('Completed collection verification');
          });
        }
      }).catch(err => {
        console.error('useChatRooms: Error auto-loading rooms:', err);
      });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return {
    rooms,
    loading,
    error,
    lastFetched,
    fetchRooms,
    validateRoomsData,
    fetchRoomsFromCollection,
    fetchRoomsFromRTDB
  };
};

export default useChatRooms;