import { LineChart, Line, ResponsiveContainer } from 'recharts'

export default function TrendSparkline({ data = [], trend = 'stable' }) {
  const chartData = data.map((v, i) => ({ v, i }))
  const color = trend === 'up' ? '#10b981' : trend === 'down' ? '#ef4444' : '#f59e0b'

  return (
    <ResponsiveContainer width="100%" height="100%">
      <LineChart data={chartData}>
        <Line
          type="monotone"
          dataKey="v"
          stroke={color}
          strokeWidth={1.5}
          dot={false}
          isAnimationActive={false}
        />
      </LineChart>
    </ResponsiveContainer>
  )
}
