import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip } from 'recharts'
import { categories, getCategoryById } from '../../utils/categories'

const COLORS = {
  politics: '#3b82f6',
  economics: '#10b981',
  sports: '#f97316',
  entertainment: '#ec4899',
  tech: '#8b5cf6',
  science: '#06b6d4',
  weather: '#eab308',
  geopolitics: '#ef4444',
}

export default function CategoryBreakdown({ predictions }) {
  const counts = {}
  for (const p of predictions) {
    counts[p.category] = (counts[p.category] || 0) + 1
  }

  const data = Object.entries(counts)
    .map(([id, count]) => ({
      name: getCategoryById(id).label,
      value: count,
      color: COLORS[id] || '#6b7280',
    }))
    .sort((a, b) => b.value - a.value)

  return (
    <div className="w-full">
      <ResponsiveContainer width="100%" height={180}>
        <PieChart>
          <Pie
            data={data}
            cx="50%"
            cy="50%"
            innerRadius={45}
            outerRadius={70}
            paddingAngle={3}
            dataKey="value"
          >
            {data.map((entry, i) => (
              <Cell key={i} fill={entry.color} stroke="none" />
            ))}
          </Pie>
          <Tooltip
            contentStyle={{ background: '#1f2937', border: '1px solid #374151', borderRadius: '8px', fontSize: '12px' }}
            itemStyle={{ color: '#f9fafb' }}
          />
        </PieChart>
      </ResponsiveContainer>
      <div className="flex flex-wrap gap-x-4 gap-y-1 justify-center mt-2">
        {data.map(d => (
          <span key={d.name} className="flex items-center gap-1.5 text-xs text-gray-400">
            <span className="w-2 h-2 rounded-full" style={{ background: d.color }} />
            {d.name} ({d.value})
          </span>
        ))}
      </div>
    </div>
  )
}
