export function calculateConfidence(inputs) {
  if (!inputs || inputs.length === 0) return 0
  let totalWeight = 0
  let weightedSum = 0
  for (const input of inputs) {
    const w = (input.weight || 0.5) * (input.reliability || 0.5)
    weightedSum += input.sentiment * w
    totalWeight += w
  }
  if (totalWeight === 0) return 0
  return Math.round((weightedSum / totalWeight) * 100)
}

export function getConfidenceColor(score) {
  if (score >= 70) return { bg: 'bg-emerald-500', text: 'text-emerald-400', ring: 'ring-emerald-500/20' }
  if (score >= 45) return { bg: 'bg-amber-500', text: 'text-amber-400', ring: 'ring-amber-500/20' }
  return { bg: 'bg-red-500', text: 'text-red-400', ring: 'ring-red-500/20' }
}

export function getConfidenceLabel(score) {
  if (score >= 80) return 'Very High'
  if (score >= 65) return 'High'
  if (score >= 45) return 'Moderate'
  if (score >= 25) return 'Low'
  return 'Very Low'
}

export function formatTimeRemaining(deadline) {
  const now = new Date()
  const end = new Date(deadline)
  const diff = end - now
  if (diff <= 0) return 'Expired'
  const days = Math.floor(diff / (1000 * 60 * 60 * 24))
  const hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60))
  if (days > 30) return `${Math.floor(days / 30)}mo remaining`
  if (days > 0) return `${days}d ${hours}h remaining`
  const mins = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60))
  return `${hours}h ${mins}m remaining`
}
