import React, { useState } from 'react';
import { MessageSquare, Play, AlertTriangle, Check } from 'lucide-react';
import { rtdb } from '../firebase';
import { ref, push, serverTimestamp, get } from 'firebase/database';

const TestBotInteraction = ({ roomId }) => {
  const [testMessage, setTestMessage] = useState('');
  const [sending, setSending] = useState(false);
  const [result, setResult] = useState(null);
  const [testType, setTestType] = useState('direct');

  // Function to send a direct bot message to the room
  const sendDirectBotMessage = async () => {
    if (!roomId || !testMessage.trim()) {
      setResult({
        success: false,
        message: 'Please select a room and enter a message to send.'
      });
      return;
    }

    setSending(true);
    setResult(null);

    try {
      // Create bot message
      const botMessage = {
        sender: 'MODERATION_BOT',
        senderName: 'Moderation Bot',
        content: testMessage,
        timestamp: serverTimestamp(),
        type: 'TEST_MESSAGE',
        isSystemMessage: true,
      };
      
      // Send to both botMessages and regular messages
      const botMessagesRef = ref(rtdb, `chats/public/${roomId}/botMessages`);
      await push(botMessagesRef, botMessage);
      
      const messagesRef = ref(rtdb, `chats/public/${roomId}/messages`);
      await push(messagesRef, {
        userId: 'MODERATION_BOT',
        text: testMessage,
        timestamp: serverTimestamp(),
        senderName: 'Moderation Bot',
        isSystemMessage: true,
        type: 'TEST_MESSAGE'
      });
      
      setResult({
        success: true,
        message: 'Test message sent successfully!'
      });
    } catch (error) {
      console.error('Error sending test message:', error);
      setResult({
        success: false,
        message: `Error: ${error.message}`
      });
    } finally {
      setSending(false);
    }
  };

  // Function to send a moderation trigger to the room
  const sendModerationTrigger = async () => {
    if (!roomId || !testMessage.trim()) {
      setResult({
        success: false,
        message: 'Please select a room and enter a message to send.'
      });
      return;
    }

    setSending(true);
    setResult(null);

    try {
      // Get room details to retrieve room name
      const roomRef = ref(rtdb, `chats/public/${roomId}`);
      const roomSnapshot = await get(roomRef);
      
      if (!roomSnapshot.exists()) {
        throw new Error(`Room with ID ${roomId} not found`);
      }
      
      // First send a regular user message with the test content
      const userMessage = {
        userId: 'ADMIN_TEST_USER',
        text: testMessage,
        timestamp: serverTimestamp(),
        senderName: 'Admin Tester',
        type: 'USER_MESSAGE'
      };
      
      const messagesRef = ref(rtdb, `chats/public/${roomId}/messages`);
      await push(messagesRef, userMessage);
      
      // Now simulate a moderation response
      const roomData = roomSnapshot.val() || {};
      const roomName = roomData.name || 'this room';
      
      // Create bot moderation message
      const botMessage = {
        sender: 'MODERATION_BOT',
        senderName: 'Moderation Bot',
        content: `Content moderated: "${testMessage}". This message was flagged as inappropriate for ${roomName}.`,
        timestamp: serverTimestamp(),
        type: 'MODERATION',
        isSystemMessage: true,
        moderatedMessageId: 'test-message-id', // This would normally be the real message ID
      };
      
      const botMessagesRef = ref(rtdb, `chats/public/${roomId}/botMessages`);
      await push(botMessagesRef, botMessage);
      
      // Also add to regular messages
      await push(messagesRef, {
        userId: 'MODERATION_BOT',
        text: botMessage.content,
        timestamp: serverTimestamp(),
        senderName: 'Moderation Bot',
        isSystemMessage: true,
        type: 'MODERATION'
      });
      
      setResult({
        success: true,
        message: 'Moderation test message sent successfully!'
      });
    } catch (error) {
      console.error('Error sending moderation test:', error);
      setResult({
        success: false,
        message: `Error: ${error.message}`
      });
    } finally {
      setSending(false);
    }
  };

  const handleSendTest = () => {
    if (testType === 'direct') {
      sendDirectBotMessage();
    } else {
      sendModerationTrigger();
    }
  };

  return (
    <div className="test-bot-interaction">
      <div className="test-header">
        <MessageSquare className="icon" size={18} />
        <h2>Test Bot Interaction</h2>
      </div>
      
      <div className="test-description">
        This tool allows you to test if the moderation bot is correctly set up and responding in the selected room.
      </div>
      
      <div className="test-form">
        <div className="test-type-selector">
          <div className="type-title">Test Type:</div>
          <div className="type-options">
            <label className={`type-option ${testType === 'direct' ? 'active' : ''}`}>
              <input
                type="radio"
                name="testType"
                value="direct"
                checked={testType === 'direct'}
                onChange={() => setTestType('direct')}
              />
              <span>Direct Bot Message</span>
            </label>
            <label className={`type-option ${testType === 'moderation' ? 'active' : ''}`}>
              <input
                type="radio"
                name="testType"
                value="moderation"
                checked={testType === 'moderation'}
                onChange={() => setTestType('moderation')}
              />
              <span>Simulated Moderation</span>
            </label>
          </div>
        </div>

        <div className="input-group">
          <textarea
            value={testMessage}
            onChange={(e) => setTestMessage(e.target.value)}
            placeholder={testType === 'direct' 
              ? "Enter a message for the bot to send..." 
              : "Enter a message that would trigger moderation..."}
            disabled={sending}
          />
        </div>
        
        <div className="test-actions">
          <button
            className="test-button"
            onClick={handleSendTest}
            disabled={sending || !testMessage.trim()}
          >
            <Play size={16} />
            <span>{sending ? 'Sending...' : 'Send Test'}</span>
          </button>
        </div>
      </div>
      
      {result && (
        <div className={`test-result ${result.success ? 'success' : 'error'}`}>
          {result.success ? (
            <Check size={18} className="result-icon" />
          ) : (
            <AlertTriangle size={18} className="result-icon" />
          )}
          <span>{result.message}</span>
        </div>
      )}
      
      <div className="help-info">
        <h3>How to test the bot</h3>
        <ul>
          <li><strong>Direct Bot Message</strong>: Sends a message directly from the bot to the chat room.</li>
          <li><strong>Simulated Moderation</strong>: Simulates a user sending a message and the bot responding with moderation.</li>
        </ul>
        <p className="note">
          Note: After sending a test, check the chat room to see if the bot messages appear. If they don't appear, there might be an issue with the bot configuration or Firebase permissions.
        </p>
      </div>
      
      <style jsx>{`
        .test-bot-interaction {
          background: white;
          border-radius: 8px;
          border: 1px solid #e2e8f0;
          padding: 1.5rem;
          margin-top: 1.5rem;
        }
        
        .test-header {
          display: flex;
          align-items: center;
          margin-bottom: 0.75rem;
        }
        
        .test-header .icon {
          color: #4f46e5;
          margin-right: 0.5rem;
        }
        
        .test-header h2 {
          font-size: 1.25rem;
          font-weight: 600;
          color: #1f2937;
          margin: 0;
        }
        
        .test-description {
          color: #4b5563;
          margin-bottom: 1.25rem;
        }
        
        .test-form {
          border: 1px solid #e5e7eb;
          border-radius: 8px;
          padding: 1rem;
          margin-bottom: 1rem;
        }
        
        .test-type-selector {
          margin-bottom: 1rem;
        }
        
        .type-title {
          font-weight: 500;
          margin-bottom: 0.5rem;
        }
        
        .type-options {
          display: flex;
          gap: 1rem;
        }
        
        .type-option {
          display: flex;
          align-items: center;
          padding: 0.5rem 0.75rem;
          border: 1px solid #d1d5db;
          border-radius: 4px;
          cursor: pointer;
        }
        
        .type-option.active {
          border-color: #4f46e5;
          background-color: #eef2ff;
        }
        
        .type-option input {
          margin-right: 0.5rem;
        }
        
        .input-group {
          margin-bottom: 1rem;
        }
        
        .input-group textarea {
          width: 100%;
          min-height: 100px;
          padding: 0.75rem;
          border: 1px solid #d1d5db;
          border-radius: 4px;
          font-size: 0.875rem;
          resize: vertical;
        }
        
        .test-actions {
          display: flex;
          justify-content: flex-end;
        }
        
        .test-button {
          display: flex;
          align-items: center;
          padding: 0.5rem 1rem;
          background-color: #4f46e5;
          color: white;
          border: none;
          border-radius: 4px;
          font-weight: 500;
          cursor: pointer;
          transition: background-color 0.2s;
        }
        
        .test-button:hover:not(:disabled) {
          background-color: #4338ca;
        }
        
        .test-button:disabled {
          opacity: 0.5;
          cursor: not-allowed;
        }
        
        .test-button span {
          margin-left: 0.5rem;
        }
        
        .test-result {
          display: flex;
          align-items: center;
          padding: 0.75rem 1rem;
          border-radius: 4px;
          margin-bottom: 1rem;
        }
        
        .test-result.success {
          background-color: #d1fae5;
          color: #065f46;
        }
        
        .test-result.error {
          background-color: #fee2e2;
          color: #b91c1c;
        }
        
        .result-icon {
          margin-right: 0.5rem;
          flex-shrink: 0;
        }
        
        .help-info {
          background-color: #f9fafb;
          border-radius: 8px;
          padding: 1rem;
        }
        
        .help-info h3 {
          font-size: 0.875rem;
          font-weight: 600;
          margin-top: 0;
          margin-bottom: 0.5rem;
        }
        
        .help-info ul {
          padding-left: 1.5rem;
          margin-bottom: 0.75rem;
        }
        
        .help-info li {
          margin-bottom: 0.25rem;
          font-size: 0.875rem;
        }
        
        .help-info .note {
          font-size: 0.75rem;
          color: #6b7280;
          font-style: italic;
          margin-bottom: 0;
        }
      `}</style>
    </div>
  );
};

export default TestBotInteraction;