import { createContext, useContext, useReducer, useCallback, useRef } from 'react'
import inputPipeline from '../services/inputPipeline'
import contextService from '../services/context/contextService'
import { MOCK_CONTEXT_SIGNALS } from '../utils/mockContextSignals'
// Voting now persists to Firebase RTDB (predict_votes/{predictionId}/{userId})
// so votes are shared across users and tabs. Old localStorage version kept
// as `votingService` import below if you need to fall back.
import votingService from '../services/firebaseVoting'

const LiveDataContext = createContext()

const initialState = {
  scanning: false,
  lastScan: null,
  newsArticles: [],
  rssItems: [],
  liveInputs: {},      // { predictionId: [inputs] }
  aiAnalyses: {},       // { predictionId: analysis }
  errors: [],
  sources: { news: false, rss: false, ai: false },
  scanCount: 0,

  // Phase 2 — context (Track B) state. Separate from Track A (news/rss/ai)
  // so UI and caches don't collide. Hydrated from localStorage on first
  // read via contextService.getCached() (see useReducer init below).
  contextSignals: [],                                // ContextSignal[]
  contextSources: { bls: false, epa: false, census: false, cdc: false, fbi: false },
  contextErrors: [],
  contextLastRefresh: null,
  contextRefreshing: false,
}

// Hydrate any existing cached context signals so the panel has data on
// first render (survives page reloads).
function initContextFromCache(state) {
  const cached = contextService.getCached()
  if (!cached) return state
  return {
    ...state,
    contextSignals: cached.signals || [],
    contextSources: cached.sources || state.contextSources,
    contextErrors: cached.errors || [],
    contextLastRefresh: cached.fetchedAt || null,
  }
}

function reducer(state, action) {
  switch (action.type) {
    case 'SCAN_START':
      return { ...state, scanning: true, errors: [] }
    case 'SCAN_COMPLETE': {
      const { newsInputs, rssInputs, newsArticles, rssItems, errors, sources } = action.payload
      const liveInputs = { ...state.liveInputs }

      for (const input of [...newsInputs, ...rssInputs]) {
        if (!liveInputs[input.predictionId]) liveInputs[input.predictionId] = []
        const existing = liveInputs[input.predictionId]
        const dup = existing.find(e => e.source === input.source && e.title === input.title)
        if (!dup) existing.push(input)
      }

      return {
        ...state,
        scanning: false,
        lastScan: Date.now(),
        newsArticles,
        rssItems,
        liveInputs,
        errors,
        sources,
        scanCount: state.scanCount + 1,
      }
    }
    case 'AI_ANALYSIS_COMPLETE': {
      const { predictionId, analysis, input } = action.payload
      const liveInputs = { ...state.liveInputs }
      if (input) {
        if (!liveInputs[predictionId]) liveInputs[predictionId] = []
        liveInputs[predictionId] = liveInputs[predictionId].filter(i => i.type !== 'ai')
        liveInputs[predictionId].push(input)
      }
      return {
        ...state,
        aiAnalyses: { ...state.aiAnalyses, [predictionId]: analysis },
        liveInputs,
      }
    }
    case 'ADD_ERROR':
      return { ...state, errors: [...state.errors, action.payload] }

    case 'CONTEXT_REFRESH_START':
      return { ...state, contextRefreshing: true, contextErrors: [] }
    case 'CONTEXT_REFRESH_COMPLETE': {
      const { signals, errors, sources, fetchedAt } = action.payload
      return {
        ...state,
        contextRefreshing: false,
        contextSignals: signals || [],
        contextErrors: errors || [],
        contextSources: sources || state.contextSources,
        contextLastRefresh: fetchedAt || Date.now(),
      }
    }
    case 'CONTEXT_REFRESH_FAILED':
      return {
        ...state,
        contextRefreshing: false,
        contextErrors: [...state.contextErrors, action.payload],
      }

    case 'CLEAR_CACHE':
      return { ...initialState }
    default:
      return state
  }
}

export function LiveDataProvider({ children }) {
  const [state, dispatch] = useReducer(reducer, initialState, initContextFromCache)
  const scanningRef = useRef(false)
  const contextRefreshingRef = useRef(false)

  const runScan = useCallback(async (predictions) => {
    if (scanningRef.current) return
    scanningRef.current = true
    dispatch({ type: 'SCAN_START' })

    try {
      const results = await inputPipeline.runFullScan(predictions)
      dispatch({ type: 'SCAN_COMPLETE', payload: results })
    } catch (err) {
      dispatch({ type: 'ADD_ERROR', payload: { source: 'Pipeline', error: err.message } })
    } finally {
      scanningRef.current = false
    }
  }, [])

  const runAiAnalysis = useCallback(async (prediction, articles = []) => {
    try {
      const { input, analysis, error } = await inputPipeline.runAiAnalysis(prediction, articles)
      if (error) {
        dispatch({ type: 'ADD_ERROR', payload: { source: 'AI', error } })
        return null
      }
      dispatch({ type: 'AI_ANALYSIS_COMPLETE', payload: { predictionId: prediction.id, analysis, input } })
      return analysis
    } catch (err) {
      dispatch({ type: 'ADD_ERROR', payload: { source: 'AI', error: err.message } })
      return null
    }
  }, [])

  const getLiveInputs = useCallback((predictionId) => {
    return state.liveInputs[predictionId] || []
  }, [state.liveInputs])

  const getAiAnalysis = useCallback((predictionId) => {
    return state.aiAnalyses[predictionId] || null
  }, [state.aiAnalyses])

  const runContextRefresh = useCallback(async () => {
    if (contextRefreshingRef.current) return
    contextRefreshingRef.current = true
    dispatch({ type: 'CONTEXT_REFRESH_START' })
    try {
      const payload = await contextService.runContextRefresh()
      dispatch({ type: 'CONTEXT_REFRESH_COMPLETE', payload })
    } catch (err) {
      dispatch({
        type: 'CONTEXT_REFRESH_FAILED',
        payload: { source: 'Context', error: err?.message || String(err) },
      })
    } finally {
      contextRefreshingRef.current = false
    }
  }, [])

  // Merge real (state) + mock signals for the requested tags. Real wins.
  // Kept here (not in contextService) so it reacts to React state changes
  // rather than relying on a localStorage re-read each call.
  const getContextSignalsForTags = useCallback((tags) => {
    if (!Array.isArray(tags) || tags.length === 0) return []
    const wanted = new Set(tags)
    const real = state.contextSignals.filter(s => wanted.has(s.tag))
    const realTags = new Set(real.map(s => s.tag))
    const mockFill = MOCK_CONTEXT_SIGNALS.filter(
      s => wanted.has(s.tag) && !realTags.has(s.tag)
    )
    return [...real, ...mockFill]
  }, [state.contextSignals])

  const clearCache = useCallback(() => {
    inputPipeline.clearAllCaches()
    contextService.clearCache()
    dispatch({ type: 'CLEAR_CACHE' })
  }, [])

  const value = {
    ...state,
    runScan,
    runAiAnalysis,
    getLiveInputs,
    getAiAnalysis,
    runContextRefresh,
    getContextSignalsForTags,
    clearCache,
    votingService,
  }

  return (
    <LiveDataContext.Provider value={value}>
      {children}
    </LiveDataContext.Provider>
  )
}

export function useLiveData() {
  const ctx = useContext(LiveDataContext)
  if (!ctx) throw new Error('useLiveData must be used within LiveDataProvider')
  return ctx
}
