// src/services/FirebaseTracerService.js
// Service for integrating the Firebase path tracer with the audit system

import { db } from '../firebase/firebase';
import { collection, addDoc, getDocs, query, orderBy, limit } from 'firebase/firestore';
import { enableFirebaseTracing, disableFirebaseTracing } from '../utils/firebaseTracingToggle';
import { getAllAccessedPaths, clearAccessedPaths } from '../utils/firebaseTracer';

/**
 * Start a new tracing session
 * @param {string} userId - The ID of the user starting the trace
 * @returns {Promise<string>} - The ID of the tracing session
 */
export const startTracingSession = async (userId) => {
  // Clear any existing paths
  clearAccessedPaths();
  
  // Enable tracing
  enableFirebaseTracing();
  
  // Create a new tracing session document
  const tracingSession = {
    startedAt: new Date(),
    startedBy: userId,
    status: 'active',
    pathCount: 0
  };
  
  // Save to Firestore
  const sessionsRef = collection(db, 'firebaseTracing');
  const docRef = await addDoc(sessionsRef, tracingSession);
  
  return docRef.id;
};

/**
 * End a tracing session and save the results
 * @param {string} sessionId - The ID of the tracing session
 * @param {string} userId - The ID of the user ending the trace
 * @returns {Promise<Object>} - The session data with paths
 */
export const endTracingSession = async (sessionId, userId) => {
  // Get all traced paths
  const paths = getAllAccessedPaths();
  
  // Disable tracing
  disableFirebaseTracing();
  
  // Update the session document
  const sessionData = {
    endedAt: new Date(),
    endedBy: userId,
    status: 'completed',
    pathCount: paths.length,
    paths: paths
  };
  
  // Get document reference and update it
  const sessionsRef = collection(db, 'firebaseTracing');
  const sessionDocRef = sessionsRef.doc(sessionId);
  await sessionDocRef.update(sessionData);
  
  return { ...sessionData, id: sessionId };
};

/**
 * Get recent tracing sessions
 * @param {number} limit - Maximum number of sessions to retrieve
 * @returns {Promise<Array>} - List of tracing sessions
 */
export const getRecentTracingSessions = async (limitCount = 10) => {
  // Query for recent sessions
  const sessionsRef = collection(db, 'firebaseTracing');
  const q = query(sessionsRef, orderBy('startedAt', 'desc'), limit(limitCount));
  const querySnapshot = await getDocs(q);
  
  // Format results
  const sessions = [];
  querySnapshot.forEach(doc => {
    sessions.push({
      id: doc.id,
      ...doc.data()
    });
  });
  
  return sessions;
};

/**
 * Generate Firebase rules from traced paths
 * @param {Array} paths - Array of traced paths
 * @param {Object} ruleTemplates - Templates for read/write rules
 * @returns {Object} - Generated rules for Database and Firestore
 */
export const generateFirebaseRulesFromPaths = (paths, ruleTemplates = {}) => {
  // Default rule templates if not provided
  const templates = {
    database: {
      read: ruleTemplates?.database?.read || "auth != null",
      write: ruleTemplates?.database?.write || "auth != null"
    },
    firestore: {
      read: ruleTemplates?.firestore?.read || "request.auth != null",
      write: ruleTemplates?.firestore?.write || "request.auth != null"
    }
  };
  
  // Helper function to build path tree from flat paths
  const buildPathTree = (paths, dbType) => {
    const filtered = paths.filter(path => path.startsWith(`${dbType}/`))
                        .map(path => path.replace(`${dbType}/`, ''));
    
    const pathTree = {};
    
    filtered.forEach(path => {
      let parts = path.split('/');
      let current = pathTree;
      
      parts.forEach(part => {
        if (!current[part]) {
          current[part] = {};
        }
        current = current[part];
      });
    });
    
    return pathTree;
  };

  // Generate database rules recursively
  const generateDatabaseRules = (pathObj, indent = 2) => {
    let rules = '';
    const indentStr = ' '.repeat(indent);
    
    Object.keys(pathObj).forEach((key, index, arr) => {
      rules += `${indentStr}"${key}": {\n`;
      
      // If this node has children
      if (Object.keys(pathObj[key]).length > 0) {
        rules += generateDatabaseRules(pathObj[key], indent + 2);
      }
      
      // Add read/write rules
      rules += `${indentStr}  ".read": "${templates.database.read}",\n`;
      rules += `${indentStr}  ".write": "${templates.database.write}"\n`;
      
      // Close the path object
      rules += `${indentStr}}${index < arr.length - 1 ? ',' : ''}\n`;
    });
    
    return rules;
  };

  // Generate Firestore rules
  const generateFirestoreRules = (pathObj, parentPath = '') => {
    let rules = '';
    
    Object.keys(pathObj).forEach(key => {
      const currentPath = parentPath ? `${parentPath}/${key}` : key;
      
      // Format path for Firestore rules
      const formattedPath = currentPath.split('/').map(segment => {
        return segment.includes(':') ? `{${segment.replace(':', '')}}` : segment;
      }).join('/');
      
      rules += `    match /${formattedPath} {\n`;
      rules += `      allow read: if ${templates.firestore.read};\n`;
      rules += `      allow write: if ${templates.firestore.write};\n`;
      rules += `    }\n\n`;
      
      // Process children
      if (Object.keys(pathObj[key]).length > 0) {
        rules += generateFirestoreRules(pathObj[key], currentPath);
      }
    });
    
    return rules;
  };
  
  // Build path trees
  const databasePathTree = buildPathTree(paths, 'database');
  const firestorePathTree = buildPathTree(paths, 'firestore');
  
  // Generate Realtime Database rules
  let databaseRulesContent = '{\n  "rules": {\n';
  
  if (Object.keys(databasePathTree).length > 0) {
    databaseRulesContent += generateDatabaseRules(databasePathTree);
  } else {
    databaseRulesContent += '    ".read": "auth != null",\n';
    databaseRulesContent += '    ".write": "auth != null"\n';
  }
  
  databaseRulesContent += '  }\n}';

  // Generate Firestore rules
  let firestoreRulesContent = 'rules_version = \'2\';\nservice cloud.firestore {\n  match /databases/{database}/documents {\n\n';
  
  if (Object.keys(firestorePathTree).length > 0) {
    firestoreRulesContent += generateFirestoreRules(firestorePathTree);
  } else {
    firestoreRulesContent += '    match /{document=**} {\n';
    firestoreRulesContent += '      allow read: if request.auth != null;\n';
    firestoreRulesContent += '      allow write: if request.auth != null;\n';
    firestoreRulesContent += '    }\n';
  }
  
  firestoreRulesContent += '  }\n}';
  
  return {
    database: databaseRulesContent,
    firestore: firestoreRulesContent
  };
};

/**
 * Save generated rules to the audit log
 * @param {string} userId - The ID of the user saving the rules
 * @param {Object} rules - The generated rules
 * @returns {Promise<string>} - The ID of the rules document
 */
export const saveGeneratedRules = async (userId, rules) => {
  // Create a new rules document
  const rulesData = {
    createdAt: new Date(),
    createdBy: userId,
    databaseRules: rules.database,
    firestoreRules: rules.firestore,
    status: 'generated',
    source: 'path-tracer'
  };
  
  // Save to Firestore
  const rulesRef = collection(db, 'firebaseRules');
  const docRef = await addDoc(rulesRef, rulesData);
  
  return docRef.id;
};
