import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { db } from '../../firebase';
import { 
  collection, 
  query, 
  where, 
  orderBy, 
  onSnapshot, 
  addDoc, 
  serverTimestamp, 
  getDocs, 
  updateDoc,
  doc,
  getDoc
} from 'firebase/firestore';
import MessageList from './MessageList';
import NewMessageForm from './NewMessageForm';
import './Messages.css';

const MessagesPage = () => {
  const { currentUser } = useAuth();
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [activeConversation, setActiveConversation] = useState(null);
  const [conversations, setConversations] = useState([]);
  const [activeRecipientId, setActiveRecipientId] = useState(null);
  const [replyingTo, setReplyingTo] = useState(null);

  // Helper function to get display name (username preferred, fallback to displayName)
  const getDisplayName = (user) => {
    return user.username || user.displayName || user.email || 'Unknown User';
  };

  // Helper function to format display name with @ for username
  const formatDisplayName = (user) => {
    return user.username ? `@${user.username}` : (user.displayName || user.email || 'Unknown User');
  };

  // Fetch all user's conversations
  useEffect(() => {
    if (!currentUser) return;

    setLoading(true);
    
    // Query messages where the current user is either the sender or recipient
    const userConversationsQuery = query(
      collection(db, "conversations"),
      where("participants", "array-contains", currentUser.uid),
      orderBy("lastMessageTime", "desc")
    );

    const unsubscribe = onSnapshot(userConversationsQuery, (snapshot) => {
      const conversationList = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      
      setConversations(conversationList);
      setLoading(false);
    }, (err) => {
      console.error("Error fetching conversations:", err);
      setError("Failed to load conversations. Please try again later.");
      setLoading(false);
    });

    return unsubscribe;
  }, [currentUser]);

  // Load messages for the active conversation
  useEffect(() => {
    if (!currentUser || !activeConversation) return;

    const messagesQuery = query(
      collection(db, "messages"),
      where("conversationId", "==", activeConversation),
      orderBy("timestamp", "asc")
    );

    const unsubscribe = onSnapshot(messagesQuery, (snapshot) => {
      const messageList = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      
      setMessages(messageList);
    }, (err) => {
      console.error("Error fetching messages:", err);
      setError("Failed to load messages. Please try again later.");
    });

    // Set the active recipient ID when conversation changes
    if (activeConversation) {
      const conversation = conversations.find(c => c.id === activeConversation);
      if (conversation) {
        const otherParticipantId = conversation.participants.find(
          id => id !== currentUser.uid
        );
        setActiveRecipientId(otherParticipantId);
      }
    }

    return unsubscribe;
  }, [currentUser, activeConversation, conversations]);

  // Send a new message
  const sendMessage = async (receiverUsername, content, parentMessageId = null) => {
    if (!currentUser || !content.trim()) {
      console.log("Message not sent - missing user or content", { 
        hasUser: !!currentUser, 
        contentLength: content ? content.length : 0,
        content
      });
      return;
    }

    try {
      setError('');
      
      let receiverId = activeRecipientId;
      let conversationId = activeConversation;
      const actualParentMessageId = parentMessageId || replyingTo;
      
      console.log("Sending message", {
        receiverUsername,
        content,
        parentMessageId: actualParentMessageId,
        activeRecipient: receiverId,
        activeConversation: conversationId
      });
      
      // If no active conversation or starting a new one, find recipient by username
      if (!conversationId) {
        if (!receiverUsername.trim()) {
          setError('Please enter a recipient username');
          return;
        }
        
        // Check if user exists
        const usersRef = collection(db, "users");
        const q = query(usersRef, where("username", "==", receiverUsername));
        const querySnapshot = await getDocs(q);
        
        if (querySnapshot.empty) {
          setError(`User ${receiverUsername} not found`);
          return;
        }
        
        const receiverData = querySnapshot.docs[0].data();
        receiverId = querySnapshot.docs[0].id;
        
        // Check if a conversation already exists with this user
        const conversationQuery = query(
          collection(db, "conversations"),
          where("participants", "array-contains", currentUser.uid)
        );
        
        const conversationSnapshot = await getDocs(conversationQuery);
        const existingConversation = conversationSnapshot.docs.find(doc => 
          doc.data().participants.includes(receiverId)
        );
        
        if (existingConversation) {
          conversationId = existingConversation.id;
        } else {
          // Create a new conversation with username-based display names
          const currentUserDisplayName = getDisplayName({
            username: currentUser.username,
            displayName: currentUser.displayName,
            email: currentUser.email
          });
          
          const receiverDisplayName = getDisplayName(receiverData);
          
          const newConversationRef = await addDoc(collection(db, "conversations"), {
            participants: [currentUser.uid, receiverId],
            participantNames: {
              [currentUser.uid]: currentUserDisplayName,
              [receiverId]: receiverDisplayName
            },
            participantInfo: {
              [currentUser.uid]: {
                displayName: currentUserDisplayName,
                username: currentUser.username,
                photoURL: currentUser.photoURL
              },
              [receiverId]: {
                displayName: receiverDisplayName,
                username: receiverData.username,
                photoURL: receiverData.photoURL
              }
            },
            lastMessageTime: serverTimestamp(),
            lastMessage: content,
            unreadCounts: {
              [receiverId]: 1, // Initialize with 1 unread message for the recipient
              [currentUser.uid]: 0 // Creator has read the message
            }
          });
          
          conversationId = newConversationRef.id;
        }
        
        setActiveConversation(conversationId);
        setActiveRecipientId(receiverId);
      }
      
      // Create the message data object
      const messageData = {
        conversationId,
        senderId: currentUser.uid,
        receiverId,
        content,
        timestamp: serverTimestamp(),
        read: false
      };
      
      // Only add parentMessageId if it exists
      if (actualParentMessageId) {
        messageData.parentMessageId = actualParentMessageId;
      }
      
      // Add the message to the messages collection
      const messageRef = await addDoc(collection(db, "messages"), messageData);
      console.log("Message added successfully", { messageId: messageRef.id });
      
      // Update the conversation's last message
      if (conversationId) {
        // First, get the current conversation to check unreadCounts structure
        const conversationDoc = await getDoc(doc(db, "conversations", conversationId));
        let updateData = {
          lastMessage: content,
          lastMessageTime: serverTimestamp()
        };
        
        // Initialize unreadCounts if it doesn't exist
        if (!conversationDoc.data().unreadCounts) {
          updateData.unreadCounts = {};
          updateData.unreadCounts[receiverId] = 1;
        } else {
          // Increment unread count for recipient
          updateData[`unreadCounts.${receiverId}`] = (conversationDoc.data().unreadCounts[receiverId] || 0) + 1;
        }
        
        await updateDoc(doc(db, "conversations", conversationId), updateData);
      }
      
      // Reset replyingTo after sending the message
      setReplyingTo(null);
      
    } catch (err) {
      console.error("Error sending message:", err);
      setError("Failed to send message. Please try again.");
    }
  };

  // Handle selecting a conversation
  const selectConversation = async (conversationId) => {
    setActiveConversation(conversationId);
    setReplyingTo(null); // Reset replying state when changing conversations
    // Active recipient will be set in the useEffect that watches activeConversation
    
    // Mark messages as read when selecting a conversation
    if (conversationId && currentUser) {
      try {
        // Update the unread count for this conversation
        await updateDoc(doc(db, "conversations", conversationId), {
          [`unreadCounts.${currentUser.uid}`]: 0
        });
      } catch (err) {
        console.error("Error marking conversation as read:", err);
      }
    }
  };

  // Handle replying to a message
  const replyToMessage = (messageId) => {
    console.log("Replying to message:", messageId);
    
    // Find the message being replied to
    const message = messages.find(m => m.id === messageId);
    if (message) {
      console.log("Found message to reply to:", message);
      
      // Make sure we have the right conversation active
      setActiveConversation(message.conversationId);
      
      // Set the message we're replying to
      setReplyingTo(messageId);
    } else {
      console.warn("Message not found:", messageId);
    }
  };
  
  // Get the text of the message being replied to (if any)
  const getReplyPreview = () => {
    if (!replyingTo) return null;
    
    const message = messages.find(m => m.id === replyingTo);
    if (!message) return null;
    
    return {
      content: message.content,
      isFromCurrentUser: message.senderId === currentUser.uid
    };
  };

  const replyPreview = getReplyPreview();

  return (
    <div className="messages-page">
      <h1>Messages</h1>
      
      {error && <div className="error-message">{error}</div>}
      
      <div className="messages-container">
        <div className="conversations-sidebar">
          <h2>Conversations</h2>
          
          {loading ? (
            <div className="loading">Loading conversations...</div>
          ) : (
            <ul className="conversation-list">
              {conversations.map(conversation => {
                // Find the other participant (not the current user)
                const otherParticipantId = conversation.participants.find(
                  id => id !== currentUser.uid
                );
                
                // Get participant info with username priority
                let participantInfo = { displayName: 'Unknown User' };
                
                if (conversation.participantInfo && conversation.participantInfo[otherParticipantId]) {
                  const rawInfo = conversation.participantInfo[otherParticipantId];
                  participantInfo = {
                    ...rawInfo,
                    displayName: formatDisplayName(rawInfo)
                  };
                } else if (conversation.participantNames && conversation.participantNames[otherParticipantId]) {
                  // Fallback to participantNames
                  const name = conversation.participantNames[otherParticipantId];
                  participantInfo = {
                    displayName: name.startsWith('@') ? name : (name.includes('@') ? `@${name.split('@')[0]}` : name),
                    photoURL: null
                  };
                }
                
                // Check if conversation has unread messages for current user
                const unreadCount = conversation.unreadCounts && 
                  conversation.unreadCounts[currentUser.uid] ? 
                  conversation.unreadCounts[currentUser.uid] : 0;
                
                return (
                  <li 
                    key={conversation.id} 
                    className={`conversation-item ${activeConversation === conversation.id ? 'active' : ''} ${unreadCount > 0 ? 'unread' : ''}`}
                    onClick={() => selectConversation(conversation.id)}
                  >
                    <div className="avatar-container">
                      {participantInfo.photoURL ? (
                        <img 
                          src={participantInfo.photoURL} 
                          alt={participantInfo.displayName} 
                          className="conversation-avatar" 
                        />
                      ) : (
                        <div className="conversation-avatar-placeholder">
                          {participantInfo.displayName.charAt(0)}
                        </div>
                      )}
                      {unreadCount > 0 && (
                        <span className="unread-badge">{unreadCount > 99 ? '99+' : unreadCount}</span>
                      )}
                    </div>
                    <div className="conversation-info">
                      <div className="conversation-name">
                        {participantInfo.displayName}
                      </div>
                      <div className="conversation-preview">
                        {conversation.lastMessage}
                      </div>
                    </div>
                  </li>
                );
              })}
              
              {conversations.length === 0 && (
                <div className="no-conversations">
                  No conversations yet. Start a new message to begin chatting.
                </div>
              )}
            </ul>
          )}
          
          <button 
            className="new-conversation-button"
            onClick={() => {
              setActiveConversation(null);
              setActiveRecipientId(null);
              setReplyingTo(null);
            }}
          >
            New Message
          </button>
        </div>
        
        <div className="message-content">
          {activeConversation ? (
            <>
              {/* Message Header */}
              <div className="message-header">
                {(() => {
                  const conversation = conversations.find(c => c.id === activeConversation);
                  if (!conversation) return null;
                  
                  const otherParticipantId = conversation.participants.find(
                    id => id !== currentUser.uid
                  );
                  
                  let participantInfo = { displayName: 'Unknown User' };
                  
                  if (conversation.participantInfo && conversation.participantInfo[otherParticipantId]) {
                    const rawInfo = conversation.participantInfo[otherParticipantId];
                    participantInfo = {
                      ...rawInfo,
                      displayName: formatDisplayName(rawInfo)
                    };
                  } else if (conversation.participantNames && conversation.participantNames[otherParticipantId]) {
                    const name = conversation.participantNames[otherParticipantId];
                    participantInfo = {
                      displayName: name.startsWith('@') ? name : (name.includes('@') ? `@${name.split('@')[0]}` : name),
                      photoURL: null
                    };
                  }
                  
                  return (
                    <>
                      {participantInfo.photoURL ? (
                        <img 
                          src={participantInfo.photoURL} 
                          alt={participantInfo.displayName} 
                          className="message-header-avatar"
                        />
                      ) : (
                        <div className="message-header-avatar-placeholder">
                          {participantInfo.displayName.charAt(0)}
                        </div>
                      )}
                      <div className="message-header-info">
                        <h3>{participantInfo.displayName}</h3>
                        <p>Direct Message</p>
                      </div>
                    </>
                  );
                })()}
              </div>
              
              <MessageList 
                messages={messages} 
                currentUser={currentUser} 
                onReply={replyToMessage} 
              />
              
              {replyPreview && (
                <div className="reply-preview">
                  <div className="reply-preview-header">
                    <span>Replying to: </span>
                    <button 
                      className="cancel-reply" 
                      onClick={() => setReplyingTo(null)}
                    >
                      ✕
                    </button>
                  </div>
                  <div className={`reply-preview-content ${replyPreview.isFromCurrentUser ? 'own' : 'other'}`}>
                    {replyPreview.content}
                  </div>
                </div>
              )}
              
              <NewMessageForm 
                onSendMessage={(content) => {
                  console.log("Message content from existing conversation form:", content);
                  
                  // Make sure content exists and is not empty before sending
                  if (content && content.trim()) {
                    sendMessage("", content, replyingTo);
                  } else {
                    setError("Message cannot be empty");
                  }
                }}
                placeholder={replyingTo ? "Write your reply..." : "Type your message..."}
                buttonText="Send"
                showRecipientField={false}
              />
            </>
          ) : (
            <div className="new-message-container">
              <h2>New Message</h2>
              <NewMessageForm 
                onSendMessage={(recipient, content) => {
                  console.log("New message from new conversation form:", recipient, content);
                  
                  // Make sure content exists and is not empty before sending
                  if (content && content.trim()) {
                    sendMessage(recipient, content);
                  } else {
                    setError("Message cannot be empty");
                  }
                }}
                showRecipientField={true}
                placeholder="Type your message..."
                buttonText="Send"
              />
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default MessagesPage;