// src/admin/CounterManager.jsx
import React, { useState, useEffect } from 'react';
import { RefreshCw, Check, AlertCircle } from 'lucide-react';
import { getFirestore, doc, collection, getDocs, updateDoc, writeBatch } from 'firebase/firestore';

const CounterManager = () => {
  const [counters, setCounters] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [resetting, setResetting] = useState(false);
  const [resetSuccess, setResetSuccess] = useState(false);
  const [resetError, setResetError] = useState(null);

  // Fetch all counters from Firestore
  useEffect(() => {
    const fetchCounters = async () => {
      setLoading(true);
      setError(null);
      
      try {
        const db = getFirestore();
        const counterCollection = collection(db, 'counters');
        const snapshot = await getDocs(counterCollection);
        
        const counterData = [];
        snapshot.forEach(doc => {
          counterData.push({
            id: doc.id,
            ...doc.data()
          });
        });
        
        setCounters(counterData);
      } catch (err) {
        console.error('Error fetching counters:', err);
        setError('Failed to load counters. Please try again later.');
      } finally {
        setLoading(false);
      }
    };
    
    fetchCounters();
  }, []);

  // Reset all counters
  const resetAllCounters = async () => {
    setResetting(true);
    setResetSuccess(false);
    setResetError(null);
    
    try {
      const db = getFirestore();
      const batch = writeBatch(db);
      
      // Reset each counter to zero
      counters.forEach(counter => {
        const counterRef = doc(db, 'counters', counter.id);
        batch.update(counterRef, { count: 0, lastReset: new Date() });
      });
      
      await batch.commit();
      
      // Update local state
      const updatedCounters = counters.map(counter => ({
        ...counter,
        count: 0,
        lastReset: new Date()
      }));
      
      setCounters(updatedCounters);
      setResetSuccess(true);
      
      // Hide success message after 3 seconds
      setTimeout(() => {
        setResetSuccess(false);
      }, 3000);
    } catch (err) {
      console.error('Error resetting counters:', err);
      setResetError('Failed to reset counters. Please try again later.');
    } finally {
      setResetting(false);
    }
  };

  // Reset a specific counter
  const resetCounter = async (counterId) => {
    setResetting(true);
    setResetSuccess(false);
    setResetError(null);
    
    try {
      const db = getFirestore();
      const counterRef = doc(db, 'counters', counterId);
      
      await updateDoc(counterRef, {
        count: 0,
        lastReset: new Date()
      });
      
      // Update local state
      const updatedCounters = counters.map(counter => {
        if (counter.id === counterId) {
          return {
            ...counter,
            count: 0,
            lastReset: new Date()
          };
        }
        return counter;
      });
      
      setCounters(updatedCounters);
      setResetSuccess(true);
      
      // Hide success message after 3 seconds
      setTimeout(() => {
        setResetSuccess(false);
      }, 3000);
    } catch (err) {
      console.error(`Error resetting counter ${counterId}:`, err);
      setResetError(`Failed to reset counter ${counterId}. Please try again later.`);
    } finally {
      setResetting(false);
    }
  };

  // Format date for display
  const formatDate = (timestamp) => {
    if (!timestamp) return 'Never';
    
    const date = timestamp instanceof Date 
      ? timestamp 
      : timestamp.toDate ? timestamp.toDate() : new Date(timestamp);
    
    return date.toLocaleString();
  };

  return (
    <div className="counter-manager">
      <h2 className="text-2xl font-bold mb-6">Counter Manager</h2>
      
      <div className="mb-6">
        <p className="text-gray-600 mb-4">
          Manage and reset system counters. Resetting counters will set their values back to zero.
          This action cannot be undone.
        </p>
        
        {/* Status messages */}
        {resetSuccess && (
          <div className="flex items-center p-4 mb-4 bg-green-100 border-l-4 border-green-500 text-green-700">
            <Check className="mr-2" size={20} />
            <span>Counters reset successfully!</span>
          </div>
        )}
        
        {resetError && (
          <div className="flex items-center p-4 mb-4 bg-red-100 border-l-4 border-red-500 text-red-700">
            <AlertCircle className="mr-2" size={20} />
            <span>{resetError}</span>
          </div>
        )}
        
        {/* Reset All Button */}
        <button
          onClick={resetAllCounters}
          disabled={loading || resetting || counters.length === 0}
          className={`mb-6 flex items-center px-4 py-2 font-medium rounded-md text-white 
            ${loading || resetting || counters.length === 0 
              ? 'bg-gray-400 cursor-not-allowed' 
              : 'bg-red-600 hover:bg-red-700'}`}
        >
          <RefreshCw className={`mr-2 ${resetting ? 'animate-spin' : ''}`} size={18} />
          {resetting ? 'Resetting All Counters...' : 'Reset All Counters'}
        </button>
      </div>
      
      {/* Counters Table */}
      <div className="bg-white shadow overflow-hidden border-b border-gray-200 sm:rounded-lg">
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-gray-50">
            <tr>
              <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Counter Name
              </th>
              <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Current Value
              </th>
              <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Last Reset
              </th>
              <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Actions
              </th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {loading ? (
              <tr>
                <td colSpan="4" className="px-6 py-4 text-center text-sm text-gray-500">
                  Loading counters...
                </td>
              </tr>
            ) : error ? (
              <tr>
                <td colSpan="4" className="px-6 py-4 text-center text-sm text-red-500">
                  {error}
                </td>
              </tr>
            ) : counters.length === 0 ? (
              <tr>
                <td colSpan="4" className="px-6 py-4 text-center text-sm text-gray-500">
                  No counters found.
                </td>
              </tr>
            ) : (
              counters.map((counter) => (
                <tr key={counter.id}>
                  <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                    {counter.name || counter.id}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                    {counter.count || 0}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                    {formatDate(counter.lastReset)}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                    <button
                      onClick={() => resetCounter(counter.id)}
                      disabled={resetting}
                      className={`inline-flex items-center px-3 py-1 border border-transparent text-xs font-medium rounded-md 
                        ${resetting 
                          ? 'bg-gray-300 text-gray-500 cursor-not-allowed' 
                          : 'bg-indigo-100 text-indigo-700 hover:bg-indigo-200'}`}
                    >
                      <RefreshCw className={`mr-1 ${resetting ? 'animate-spin' : ''}`} size={12} />
                      Reset
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default CounterManager;