import React, { useState, useEffect } from 'react';
import { getFirestore, collection, query, where, orderBy, onSnapshot, doc, getDoc } from 'firebase/firestore';
import { getStorageInstance } from '../firebase';
import { ref, listAll, getDownloadURL, getMetadata } from 'firebase/storage';
import { useAuth } from '../contexts/AuthContext';
import { useNavigate, useSearchParams } from 'react-router-dom';
import ReplayPlayer from '../components/video/ReplayPlayer';
import './WatchReplayPage.css';

const WatchReplayPage = () => {
  const { currentUser } = useAuth();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const eventId = searchParams.get('event'); // Get event ID from URL
  
  const [pastEvents, setPastEvents] = useState([]);
  const [selectedEvent, setSelectedEvent] = useState(null);
  const [selectedEventData, setSelectedEventData] = useState(null); // Firestore event data
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [filter, setFilter] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [previewTimeLeft, setPreviewTimeLeft] = useState(null);
  const [showRegistrationPrompt, setShowRegistrationPrompt] = useState(false);

  const storage = getStorageInstance();

  const isAnonymousUser = () => {
    return !currentUser || currentUser.isAnonymous;
  };

  useEffect(() => {
    fetchPastEvents();
    
    // If eventId is provided, load that specific event
    if (eventId) {
      loadSpecificEvent(eventId);
    }
  }, [eventId]);

  // Load specific event from Firestore and find its recording
  const loadSpecificEvent = async (eventId) => {
    try {
      console.log('🎬 Loading specific event:', eventId);
      const db = getFirestore();
      const eventDoc = await getDoc(doc(db, 'events', eventId));
      
      if (eventDoc.exists()) {
        const eventData = {
          id: eventDoc.id,
          ...eventDoc.data()
        };
        
        console.log('📦 Event data loaded:', eventData);
        setSelectedEventData(eventData);
        
        // Try to find recording in Firebase Storage
        await findEventRecording(eventId, eventData);
      } else {
        console.error('❌ Event not found:', eventId);
        setError('Event not found');
      }
    } catch (error) {
      console.error('❌ Error loading specific event:', error);
      setError('Failed to load event');
    }
  };

  // Find recording file in Firebase Storage
  const findEventRecording = async (eventId, eventData) => {
    try {
      console.log('📹 Searching for recording for event:', eventId);
      
      // Check if event already has recordingUrl in Firestore
      if (eventData.recordingUrl) {
        console.log('✅ Recording URL found in Firestore:', eventData.recordingUrl);
        setSelectedEvent({
          id: eventData.id,
          name: eventData.title,
          url: eventData.recordingUrl,
          description: eventData.description,
          streamer: eventData.artistName,
          thumbnail: eventData.thumbnailUrl,
          eventData: eventData // Include full event data
        });
        return;
      }
      
      // Search Firebase Storage for recording files
      const replaysRef = ref(storage, 'replays/');
      const result = await listAll(replaysRef);
      
      // Look for files that match the event ID
      const matchingFiles = [];
      
      for (const itemRef of result.items) {
        try {
          const metadata = await getMetadata(itemRef);
          const customMetadata = metadata.customMetadata || {};
          
          // Check if file matches this event
          if (customMetadata.eventId === eventId || 
              itemRef.name.includes(eventId) ||
              itemRef.name.includes(eventData.title?.replace(/[^a-zA-Z0-9]/g, '_'))) {
            
            const downloadURL = await getDownloadURL(itemRef);
            matchingFiles.push({
              id: itemRef.fullPath,
              name: customMetadata.title || eventData.title,
              url: downloadURL,
              description: eventData.description,
              streamer: eventData.artistName,
              thumbnail: eventData.thumbnailUrl,
              eventData: eventData,
              storageMetadata: metadata
            });
          }
        } catch (error) {
          console.warn('⚠️ Error checking file:', itemRef.name, error);
        }
      }
      
      if (matchingFiles.length > 0) {
        console.log('✅ Found recording files:', matchingFiles);
        setSelectedEvent(matchingFiles[0]); // Use the first match
      } else {
        console.log('⚠️ No recording found for event:', eventId);
        // Still set the event data even without recording
        setSelectedEvent({
          id: eventData.id,
          name: eventData.title,
          url: null, // No recording available
          description: eventData.description,
          streamer: eventData.artistName,
          thumbnail: eventData.thumbnailUrl,
          eventData: eventData
        });
      }
    } catch (error) {
      console.error('❌ Error finding recording:', error);
      setError('Failed to find recording');
    }
  };

  // 5-minute preview timer for anonymous users
  useEffect(() => {
    if (selectedEvent && isAnonymousUser()) {
      // Start 5-minute countdown
      const PREVIEW_TIME = 5 * 60; // 5 minutes in seconds
      setPreviewTimeLeft(PREVIEW_TIME);
      
      const timer = setInterval(() => {
        setPreviewTimeLeft(prev => {
          if (prev <= 1) {
            clearInterval(timer);
            setShowRegistrationPrompt(true);
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
      
      return () => clearInterval(timer);
    }
  }, [selectedEvent, currentUser]);

  const fetchPastEvents = () => {
    try {
      console.log('🎬 Fetching past events from Firestore...');
      setLoading(true);
      setError(null);

      const db = getFirestore();
      
      // Query for events with status 'ended'
      const pastEventsQuery = query(
        collection(db, 'events'),
        where('status', '==', 'ended'),
        orderBy('startTime', 'desc') // Newest first
      );

      const unsubscribe = onSnapshot(pastEventsQuery, 
        (snapshot) => {
          console.log('✅ Past events query successful:', {
            eventsCount: snapshot.docs.length
          });
          
          const eventsList = snapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data(),
            // Convert Firestore timestamp to Date if needed
            startTime: doc.data().startTime?.toDate ? doc.data().startTime.toDate() : new Date(doc.data().startTime),
            endTime: doc.data().endTime?.toDate ? doc.data().endTime.toDate() : new Date(doc.data().endTime || doc.data().startTime)
          }));
          
          console.log('📽️ Past events loaded:', eventsList.map(e => ({
            title: e.title,
            status: e.status,
            startTime: e.startTime.toLocaleString(),
            hasRecording: !!e.recordingUrl
          })));
          
          setPastEvents(eventsList);
          setLoading(false);
        },
        (error) => {
          console.error('❌ Error loading past events:', error);
          setError('Failed to load past events. Please try again later.');
          setLoading(false);
        }
      );
      
      return unsubscribe;
    } catch (err) {
      console.error('❌ Error setting up past events listener:', err);
      setError('Failed to load past events. Please try again later.');
      setLoading(false);
    }
  };

  const filteredEvents = pastEvents.filter(event => {
    const matchesSearch = event.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         event.artistName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         event.description?.toLowerCase().includes(searchTerm.toLowerCase());
    
    const matchesFilter = filter === 'all' || event.category === filter;
    
    return matchesSearch && matchesFilter;
  });

  const getUniqueCategories = () => {
    const categories = [...new Set(pastEvents.map(event => event.category))].filter(Boolean);
    return categories;
  };

  const formatDate = (date) => {
    return date.toLocaleDateString('en-US', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const formatDuration = (startTime, endTime) => {
    const diffMs = endTime.getTime() - startTime.getTime();
    const diffMins = Math.round(diffMs / (1000 * 60));
    
    if (diffMins < 60) {
      return `${diffMins} minutes`;
    } else {
      const hours = Math.floor(diffMins / 60);
      const minutes = diffMins % 60;
      return `${hours}h ${minutes}m`;
    }
  };

  const formatPreviewTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handleWatchEvent = (event) => {
    setSelectedEvent(event);
    setShowRegistrationPrompt(false);
    
    // Reset preview timer for anonymous users
    if (isAnonymousUser()) {
      setPreviewTimeLeft(5 * 60);
    }
  };

  const handleRegisterPrompt = () => {
    navigate('/signup', { 
      state: { 
        returnTo: `/watch-replays`,
        message: 'Sign up to continue watching replays without time limits!' 
      } 
    });
  };

  if (loading) {
    return (
      <div className="watch-replay-page">
        <div className="loading-container">
          <div className="loading-spinner"></div>
          <p>Loading past events...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="watch-replay-page">
        <div className="error-container">
          <h2>Error Loading Past Events</h2>
          <p>{error}</p>
          <button onClick={fetchPastEvents} className="retry-button">
            Try Again
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="watch-replay-page">
      {/* Registration Prompt Modal */}
      {showRegistrationPrompt && (
        <div className="registration-prompt-overlay">
          <div className="registration-prompt">
            <h2>🎆 Preview Time Expired!</h2>
            <p>You've enjoyed 5 minutes of free preview. Sign up to continue watching without limits!</p>
            <div className="prompt-actions">
              <button className="register-btn" onClick={handleRegisterPrompt}>
                Sign Up Free
              </button>
              <button className="close-btn" onClick={() => {
                setShowRegistrationPrompt(false);
                setSelectedEvent(null);
              }}>
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="replay-header">
        <h1>Watch Past Events</h1>
        <p>Browse and watch recordings of completed events</p>
        
        {/* Preview Timer for Anonymous Users */}
        {selectedEvent && isAnonymousUser() && previewTimeLeft !== null && (
          <div className="preview-timer">
            <span className="timer-label">Preview time remaining:</span>
            <span className={`timer-value ${previewTimeLeft < 60 ? 'warning' : ''}`}>
              {formatPreviewTime(previewTimeLeft)}
            </span>
          </div>
        )}
      </div>

      {/* Search and Filter Controls */}
      <div className="replay-controls">
        <div className="search-container">
          <input
            type="text"
            placeholder="Search past events..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="search-input"
          />
        </div>
        
        <div className="filter-container">
          <select
            value={filter}
            onChange={(e) => setFilter(e.target.value)}
            className="filter-select"
          >
            <option value="all">All Categories</option>
            {getUniqueCategories().map(category => (
              <option key={category} value={category}>
                {category.charAt(0).toUpperCase() + category.slice(1)}
              </option>
            ))}
          </select>
        </div>

        <button onClick={fetchPastEvents} className="refresh-button">
          Refresh
        </button>
      </div>

      {/* Video Player with Chat Integration */}
      {selectedEvent && (
        <div className="video-player-container">
          {selectedEvent.url ? (
            <div className="replay-player-wrapper">
              <ReplayPlayer
                replay={selectedEvent}
                onClose={() => {
                  setSelectedEvent(null);
                  setSelectedEventData(null);
                  setPreviewTimeLeft(null);
                  setShowRegistrationPrompt(false);
                  // Remove event parameter from URL
                  if (eventId) {
                    navigate('/watch-replays', { replace: true });
                  }
                }}
                previewMode={isAnonymousUser()}
                timeRemaining={previewTimeLeft}
              />
              
              {/* Original Event Chat Integration */}
              {selectedEventData && (
                <div className="chat-integration">
                  <div className="chat-header">
                    <h3>Event Chat</h3>
                    <p>Original chat from: {selectedEventData.title}</p>
                  </div>
                  
                  {/* Chat iframe or component - use original event chat link */}
                  <div className="chat-frame">
                    <iframe
                      src={`/events/${selectedEventData.id}/chat-only`}
                      title="Event Chat"
                      className="event-chat-frame"
                      sandbox="allow-scripts allow-same-origin"
                    />
                  </div>
                  
                  <div className="chat-info">
                    <p><strong>Event Date:</strong> {new Date(selectedEventData.startTime).toLocaleString()}</p>
                    <p><strong>Artist:</strong> {selectedEventData.artistName}</p>
                    {selectedEventData.category && (
                      <p><strong>Category:</strong> {selectedEventData.category}</p>
                    )}
                  </div>
                </div>
              )}
            </div>
          ) : (
            <div className="no-recording-message">
              <h2>📼 No Recording Available</h2>
              <p>This event doesn't have a recording yet, but you can still view the original chat!</p>
              
              {selectedEventData && (
                <div className="event-info-display">
                  <h3>{selectedEventData.title}</h3>
                  <p>{selectedEventData.description}</p>
                  <p><strong>Date:</strong> {new Date(selectedEventData.startTime).toLocaleString()}</p>
                  
                  <button 
                    className="view-event-btn"
                    onClick={() => navigate(`/events/${selectedEventData.id}`)}
                  >
                    View Original Event Page
                  </button>
                </div>
              )}
            </div>
          )}
        </div>
      )}

      {/* Past Events Grid */}
      <div className="replay-grid">
        {filteredEvents.length === 0 ? (
          <div className="no-replays">
            <h3>No past events found</h3>
            <p>
              {searchTerm || filter !== 'all' 
                ? 'Try adjusting your search or filter criteria.'
                : 'No past events are available yet.'
              }
            </p>
          </div>
        ) : (
          filteredEvents.map((event) => (
            <div key={event.id} className="replay-card">
              <div className="replay-thumbnail">
                {event.thumbnailUrl ? (
                  <img src={event.thumbnailUrl} alt={event.title} />
                ) : (
                  <div className="placeholder-thumbnail">
                    <svg viewBox="0 0 24 24" fill="currentColor">
                      <path d="M8 5v14l11-7z"/>
                    </svg>
                  </div>
                )}
                <div className="play-overlay" onClick={() => handleWatchEvent(event)}>
                  <svg viewBox="0 0 24 24" fill="currentColor">
                    <path d="M8 5v14l11-7z"/>
                  </svg>
                  {isAnonymousUser() && (
                    <div className="preview-badge">5 min preview</div>
                  )}
                </div>
              </div>
              
              <div className="replay-info">
                <h3 className="replay-title">{event.title}</h3>
                
                <div className="replay-meta">
                  <span className="streamer">By: {event.artistName || 'Unknown Artist'}</span>
                  <span className="duration">Duration: {formatDuration(event.startTime, event.endTime)}</span>
                </div>
                
                {event.description && (
                  <p className="replay-description">{event.description}</p>
                )}
                
                <div className="replay-details">
                  <span className="event-date">{formatDate(event.startTime)}</span>
                  <span className="event-category">{event.category || 'General'}</span>
                </div>
                
                <div className="replay-status">
                  {event.recordingUrl ? (
                    <span className="available">✅ Recording Available</span>
                  ) : (
                    <span className="unavailable">❌ Recording Not Available</span>
                  )}
                </div>
                
                <div className="replay-actions">
                  <button 
                    className="watch-button"
                    onClick={() => handleWatchEvent(event)}
                    disabled={!event.recordingUrl}
                  >
                    {isAnonymousUser() ? 'Preview (5 min)' : 'Watch Full Event'}
                  </button>
                  
                  {event.recordingUrl && (
                    <a 
                      href={event.recordingUrl}
                      download={event.title}
                      className="download-button"
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      Download
                    </a>
                  )}
                </div>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Stats Footer */}
      {pastEvents.length > 0 && (
        <div className="replay-stats">
          <p>
            Showing {filteredEvents.length} of {pastEvents.length} past events
            {searchTerm && ` matching "${searchTerm}"`}
          </p>
          {isAnonymousUser() && (
            <p className="preview-notice">
              <strong>👤 Viewing as guest:</strong> You can preview any event for 5 minutes. 
              <button 
                className="signup-link"
                onClick={() => navigate('/signup')}
              >
                Sign up free
              </button> 
              for unlimited access!
            </p>
          )}
        </div>
      )}
    </div>
  );
};

export default WatchReplayPage;