import React, { useState, useEffect } from 'react';
import { useParams, useLocation } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import EventChatRoom from './EventChatRoom';
import './EventChatOnlyPage.css';

const EventChatOnlyPage = () => {
  const { eventId } = useParams();
  const location = useLocation();
  const { currentUser } = useAuth();
  const [event, setEvent] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [isStudioMode, setIsStudioMode] = useState(false);

  useEffect(() => {
    const loadEvent = async () => {
      try {
        // Check if this is studio mode (no specific eventId but from studio route)
        if (location.pathname.includes('/studio/chat-only')) {
          setIsStudioMode(true);
          // Try to find the user's most recent event or create a default
          const { getFirestore, collection, query, where, orderBy, limit, getDocs } = await import('firebase/firestore');
          const db = getFirestore();
          
          if (currentUser) {
            // Look for user's most recent event
            const eventsQuery = query(
              collection(db, 'events'),
              where('artistId', '==', currentUser.uid),
              orderBy('createdAt', 'desc'),
              limit(1)
            );
            
            const eventsSnapshot = await getDocs(eventsQuery);
            
            if (!eventsSnapshot.empty) {
              const latestEvent = eventsSnapshot.docs[0];
              setEvent({
                id: latestEvent.id,
                ...latestEvent.data()
              });
            } else {
              // No events found, create a default studio chat
              setEvent({
                id: 'studio-default',
                title: 'Studio Chat',
                artistName: currentUser.displayName || 'Artist',
                status: 'live'
              });
            }
          } else {
            // Not logged in, show generic studio chat
            setEvent({
              id: 'studio-public',
              title: 'Studio Chat',
              artistName: 'TalkStudio',
              status: 'live'
            });
          }
        } else if (eventId) {
          // Standard event mode
          const { getFirestore, doc, getDoc } = await import('firebase/firestore');
          const db = getFirestore();
          
          const eventDoc = await getDoc(doc(db, 'events', eventId));
          
          if (eventDoc.exists()) {
            setEvent({
              id: eventDoc.id,
              ...eventDoc.data()
            });
          } else {
            setError('Event not found');
          }
        } else {
          setError('No event specified');
        }
      } catch (err) {
        console.error('Failed to load event:', err);
        setError('Failed to load event');
      } finally {
        setLoading(false);
      }
    };

    loadEvent();
  }, [eventId, location.pathname, currentUser]);

  if (loading) {
    return (
      <div className="chat-only-loading">
        <div className="loading-spinner"></div>
        <p>Loading chat...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="chat-only-error">
        <h2>Error</h2>
        <p>{error}</p>
      </div>
    );
  }

  return (
    <div className="event-chat-only-page">
      {/* Minimal header with just event info */}
      <div className="minimal-chat-header">
        <div className="event-info">
          <h3>{event?.title || 'Event Chat'}</h3>
          {event?.artistName && (
            <span className="artist-name">by {event.artistName}</span>
          )}
        </div>
        <div className="chat-status">
          {event?.status === 'live' && (
            <span className="live-indicator">
              <div className="live-dot"></div>
              LIVE
            </span>
          )}
        </div>
      </div>

      {/* Full-height chat component */}
      <div className="chat-container">
        <EventChatRoom />
      </div>
    </div>
  );
};

export default EventChatOnlyPage;