import React, { useState, useRef, useEffect } from 'react';
import { Volume2, VolumeX, Play, Users, Calendar, Clock } from 'lucide-react';
import './EventThumbnail.css';

const EventThumbnail = ({ event, onEventClick }) => {
  const [isMuted, setIsMuted] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isHovered, setIsHovered] = useState(false);
  const videoRef = useRef(null);

  // Format the event time
  const formatEventTime = (timestamp) => {
    const date = new Date(timestamp);
    const now = new Date();
    const diffMs = date.getTime() - now.getTime();
    const diffHours = Math.round(diffMs / (1000 * 60 * 60));
    const diffDays = Math.round(diffMs / (1000 * 60 * 60 * 24));

    if (diffMs < 0) {
      // Past event
      const pastDays = Math.abs(diffDays);
      if (pastDays === 0) {
        return 'Earlier today';
      } else if (pastDays === 1) {
        return 'Yesterday';
      } else if (pastDays < 7) {
        return `${pastDays} days ago`;
      } else {
        return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      }
    } else {
      // Future event
      if (diffHours < 1) {
        return 'Starting soon';
      } else if (diffHours < 24) {
        return `In ${diffHours} hours`;
      } else if (diffDays === 1) {
        return 'Tomorrow';
      } else {
        return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      }
    }
  };

  // Handle mouse enter/leave for auto-play
  useEffect(() => {
    if (videoRef.current && event.videoUrl) {
      if (isHovered) {
        videoRef.current.play().catch(err => {
          console.log('Auto-play prevented:', err);
        });
        setIsPlaying(true);
      } else {
        videoRef.current.pause();
        setIsPlaying(false);
      }
    }
  }, [isHovered, event.videoUrl]);

  // Toggle mute
  const toggleMute = (e) => {
    e.stopPropagation();
    setIsMuted(!isMuted);
    if (videoRef.current) {
      videoRef.current.muted = !isMuted;
    }
  };

  const handleClick = () => {
    if (onEventClick) {
      onEventClick(event);
    }
  };

  const isLive = event.status === 'live';
  const isPast = event.status === 'ended';

  return (
    <div 
      className={`event-thumbnail ${isLive ? 'live' : ''} ${isPast ? 'past' : ''}`}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      onClick={handleClick}
    >
      <div className="thumbnail-media">
        {event.videoUrl && isHovered ? (
          <video 
            ref={videoRef}
            src={event.videoUrl}
            muted={isMuted}
            loop
            playsInline
            className="thumbnail-video"
          />
        ) : event.thumbnailUrl ? (
          <img 
            src={event.thumbnailUrl} 
            alt={event.title}
            className="thumbnail-image"
          />
        ) : (
          <div className="thumbnail-placeholder">
            <Play size={32} />
          </div>
        )}

        {/* Live indicator */}
        {isLive && (
          <div className="live-badge">
            <div className="live-dot"></div>
            <span>LIVE</span>
          </div>
        )}

        {/* Mute/unmute button - only show when video is playing */}
        {event.videoUrl && isHovered && (
          <button 
            className="mute-button"
            onClick={toggleMute}
            aria-label={isMuted ? 'Unmute' : 'Mute'}
          >
            {isMuted ? <VolumeX size={16} /> : <Volume2 size={16} />}
          </button>
        )}

        {/* Hover overlay */}
        {isHovered && (
          <div className="hover-overlay">
            <div className="play-icon">
              <Play size={24} />
            </div>
          </div>
        )}
      </div>

      <div className="thumbnail-info">
        <h3 className="event-title">{event.title}</h3>
        
        {event.artistName && (
          <p className="event-artist">{event.artistName}</p>
        )}

        <div className="event-meta">
          <div className="meta-item">
            <Clock size={14} />
            <span>{formatEventTime(event.startTime)}</span>
          </div>
          
          {event.viewerCount !== undefined && (
            <div className="meta-item">
              <Users size={14} />
              <span>{event.viewerCount}</span>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default EventThumbnail;