import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { 
  getFirestore, 
  collection, 
  query, 
  where, 
  onSnapshot, 
  doc, 
  updateDoc,
  orderBy,
  limit
} from 'firebase/firestore';
import {
  Server,
  Activity,
  Users,
  Zap,
  AlertTriangle,
  CheckCircle,
  XCircle,
  TrendingUp,
  Monitor,
  Cpu,
  HardDrive,
  Wifi,
  Radio,
  Settings,
  RefreshCw,
  Pause,
  Play,
  StopCircle
} from 'lucide-react';
import './StreamServerManagement.css';

const StreamServerManagement = () => {
  const { currentUser } = useAuth();
  
  // Server status
  const [serverStatus, setServerStatus] = useState({
    online: true,
    cpu: 45,
    memory: 62,
    bandwidth: 78,
    activeStreams: 12,
    totalViewers: 1247,
    uptime: '2d 14h 32m'
  });
  
  // Active streams
  const [activeStreams, setActiveStreams] = useState([]);
  const [streamHistory, setStreamHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  
  // Server configuration
  const [serverConfig, setServerConfig] = useState({
    maxStreams: 50,
    maxViewersPerStream: 1000,
    recordingEnabled: true,
    qualityPresets: ['480p', '720p', '1080p'],
    rtmpPort: 1935,
    httpPort: 8080,
    autoScale: true
  });
  
  useEffect(() => {
    const unsubscribeStreams = loadStreamData();
    const cleanupMonitoring = startServerMonitoring();
    
    return () => {
      if (unsubscribeStreams) unsubscribeStreams();
      if (cleanupMonitoring) cleanupMonitoring();
    };
  }, []);

  const loadStreamData = () => {
    const db = getFirestore();
    
    // Load active streams
    const activeStreamsQuery = query(
      collection(db, 'events'),
      where('status', '==', 'live'),
      orderBy('startTime', 'desc')
    );
    
    const unsubscribeActive = onSnapshot(activeStreamsQuery, (snapshot) => {
      const streams = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      setActiveStreams(streams);
    });
    
    // Load stream history
    const historyQuery = query(
      collection(db, 'events'),
      where('status', 'in', ['ended', 'error']),
      orderBy('startTime', 'desc'),
      limit(20)
    );
    
    const unsubscribeHistory = onSnapshot(historyQuery, (snapshot) => {
      const history = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      setStreamHistory(history);
      setLoading(false);
    });
    
    return () => {
      unsubscribeActive();
      unsubscribeHistory();
    };
  };

  const startServerMonitoring = () => {
    // Simulate real-time server monitoring
    const interval = setInterval(() => {
      setServerStatus(prev => ({
        ...prev,
        cpu: Math.max(20, Math.min(90, prev.cpu + (Math.random() - 0.5) * 10)),
        memory: Math.max(30, Math.min(95, prev.memory + (Math.random() - 0.5) * 8)),
        bandwidth: Math.max(40, Math.min(100, prev.bandwidth + (Math.random() - 0.5) * 15)),
        activeStreams: activeStreams.length,
        totalViewers: activeStreams.reduce((sum, stream) => sum + (stream.viewerCount || 0), 0)
      }));
    }, 5000);
    
    return () => clearInterval(interval);
  };

  const restartStream = async (streamId) => {
    try {
      const db = getFirestore();
      await updateDoc(doc(db, 'events', streamId), {
        serverAction: 'restart',
        lastServerAction: Date.now()
      });
      
      console.log('🔄 Stream restart initiated:', streamId);
    } catch (error) {
      console.error('Failed to restart stream:', error);
    }
  };

  const stopStream = async (streamId) => {
    try {
      const db = getFirestore();
      await updateDoc(doc(db, 'events', streamId), {
        status: 'ended',
        endTime: Date.now(),
        serverAction: 'stop'
      });
      
      console.log('⏹️ Stream stopped:', streamId);
    } catch (error) {
      console.error('Failed to stop stream:', error);
    }
  };

  const getHealthStatus = () => {
    const { cpu, memory, bandwidth } = serverStatus;
    if (cpu > 80 || memory > 90 || bandwidth > 95) return 'critical';
    if (cpu > 60 || memory > 70 || bandwidth > 80) return 'warning';
    return 'healthy';
  };

  const getHealthColor = (status) => {
    switch (status) {
      case 'healthy': return '#4ecdc4';
      case 'warning': return '#ffd93d';
      case 'critical': return '#ff6b6b';
      default: return '#95a5a6';
    }
  };

  const getStreamQualityIcon = (quality) => {
    switch (quality) {
      case 'excellent': return <CheckCircle className="quality-excellent" />;
      case 'good': return <CheckCircle className="quality-good" />;
      case 'poor': return <AlertTriangle className="quality-poor" />;
      case 'error': return <XCircle className="quality-error" />;
      default: return <Monitor className="quality-unknown" />;
    }
  };

  if (loading) {
    return (
      <div className="server-loading">
        <div className="loading-spinner"></div>
        <p>Loading Stream Server...</p>
      </div>
    );
  }

  return (
    <div className="stream-server-management">
      {/* Server Overview */}
      <div className="server-overview">
        <div className="overview-header">
          <div className="server-info">
            <Server size={24} />
            <div>
              <h1>Stream Server Control</h1>
              <div className="server-status">
                <div className={`status-dot ${serverStatus.online ? 'online' : 'offline'}`}></div>
                <span>Server {serverStatus.online ? 'Online' : 'Offline'}</span>
                <span className="uptime">Uptime: {serverStatus.uptime}</span>
              </div>
            </div>
          </div>
          
          <div className="server-actions">
            <button className="action-btn restart">
              <RefreshCw size={16} />
              Restart Server
            </button>
            <button className="action-btn settings">
              <Settings size={16} />
              Configure
            </button>
          </div>
        </div>
        
        {/* Health Metrics */}
        <div className="health-metrics">
          <div className="metric-card">
            <div className="metric-header">
              <Cpu size={20} />
              <span>CPU Usage</span>
            </div>
            <div className="metric-value">{serverStatus.cpu}%</div>
            <div className="metric-bar">
              <div 
                className="metric-fill" 
                style={{ 
                  width: `${serverStatus.cpu}%`,
                  backgroundColor: getHealthColor(serverStatus.cpu > 80 ? 'critical' : serverStatus.cpu > 60 ? 'warning' : 'healthy')
                }}
              ></div>
            </div>
          </div>
          
          <div className="metric-card">
            <div className="metric-header">
              <HardDrive size={20} />
              <span>Memory</span>
            </div>
            <div className="metric-value">{serverStatus.memory}%</div>
            <div className="metric-bar">
              <div 
                className="metric-fill" 
                style={{ 
                  width: `${serverStatus.memory}%`,
                  backgroundColor: getHealthColor(serverStatus.memory > 90 ? 'critical' : serverStatus.memory > 70 ? 'warning' : 'healthy')
                }}
              ></div>
            </div>
          </div>
          
          <div className="metric-card">
            <div className="metric-header">
              <Wifi size={20} />
              <span>Bandwidth</span>
            </div>
            <div className="metric-value">{serverStatus.bandwidth}%</div>
            <div className="metric-bar">
              <div 
                className="metric-fill" 
                style={{ 
                  width: `${serverStatus.bandwidth}%`,
                  backgroundColor: getHealthColor(serverStatus.bandwidth > 95 ? 'critical' : serverStatus.bandwidth > 80 ? 'warning' : 'healthy')
                }}
              ></div>
            </div>
          </div>
          
          <div className="metric-card">
            <div className="metric-header">
              <Activity size={20} />
              <span>Health</span>
            </div>
            <div className="metric-value" style={{ color: getHealthColor(getHealthStatus()) }}>
              {getHealthStatus().toUpperCase()}
            </div>
            <div className="health-indicator">
              <div 
                className="health-dot" 
                style={{ backgroundColor: getHealthColor(getHealthStatus()) }}
              ></div>
            </div>
          </div>
        </div>
        
        {/* Quick Stats */}
        <div className="quick-stats">
          <div className="stat-item">
            <Radio size={20} />
            <div>
              <span className="stat-value">{serverStatus.activeStreams}</span>
              <span className="stat-label">Active Streams</span>
            </div>
          </div>
          
          <div className="stat-item">
            <Users size={20} />
            <div>
              <span className="stat-value">{serverStatus.totalViewers.toLocaleString()}</span>
              <span className="stat-label">Total Viewers</span>
            </div>
          </div>
          
          <div className="stat-item">
            <TrendingUp size={20} />
            <div>
              <span className="stat-value">{Math.round(serverStatus.totalViewers / Math.max(1, serverStatus.activeStreams))}</span>
              <span className="stat-label">Avg Viewers/Stream</span>
            </div>
          </div>
          
          <div className="stat-item">
            <Zap size={20} />
            <div>
              <span className="stat-value">{Math.round(serverStatus.bandwidth * 2.4)}Gbps</span>
              <span className="stat-label">Data Transfer</span>
            </div>
          </div>
        </div>
      </div>

      {/* Active Streams */}
      <div className="active-streams-section">
        <h2>Active Streams ({activeStreams.length})</h2>
        
        {activeStreams.length === 0 ? (
          <div className="no-streams">
            <Radio size={48} />
            <h3>No Active Streams</h3>
            <p>All streams are currently offline</p>
          </div>
        ) : (
          <div className="streams-grid">
            {activeStreams.map((stream) => (
              <div key={stream.id} className="stream-card">
                <div className="stream-header">
                  <div className="stream-info">
                    <h3>{stream.title}</h3>
                    <p className="artist-name">{stream.artistName}</p>
                  </div>
                  
                  <div className="stream-status">
                    <div className="live-indicator">
                      <div className="live-dot"></div>
                      LIVE
                    </div>
                    {getStreamQualityIcon(stream.quality || 'good')}
                  </div>
                </div>
                
                <div className="stream-metrics">
                  <div className="metric">
                    <Users size={16} />
                    <span>{stream.viewerCount || 0} viewers</span>
                  </div>
                  
                  <div className="metric">
                    <Activity size={16} />
                    <span>{stream.bitrate || 3000} kbps</span>
                  </div>
                  
                  <div className="metric">
                    <Monitor size={16} />
                    <span>{stream.resolution || '1080p'}</span>
                  </div>
                  
                  <div className="metric">
                    <Zap size={16} />
                    <span>{Math.round((stream.viewerCount || 0) * 2.5)}MB/s</span>
                  </div>
                </div>
                
                <div className="stream-actions">
                  <button 
                    className="action-btn pause"
                    onClick={() => restartStream(stream.id)}
                  >
                    <RefreshCw size={14} />
                    Restart
                  </button>
                  
                  <button 
                    className="action-btn stop"
                    onClick={() => stopStream(stream.id)}
                  >
                    <StopCircle size={14} />
                    Stop
                  </button>
                </div>
                
                <div className="stream-timeline">
                  <div className="timeline-item">
                    <span>Started: {new Date(stream.actualStartTime || stream.startTime).toLocaleTimeString()}</span>
                  </div>
                  <div className="timeline-item">
                    <span>Duration: {Math.round((Date.now() - (stream.actualStartTime || stream.startTime)) / 60000)}m</span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Stream History */}
      <div className="stream-history-section">
        <h2>Recent Stream History</h2>
        
        <div className="history-table">
          <div className="table-header">
            <div className="col-title">Event</div>
            <div className="col-artist">Artist</div>
            <div className="col-viewers">Peak Viewers</div>
            <div className="col-duration">Duration</div>
            <div className="col-status">Status</div>
            <div className="col-date">Date</div>
          </div>
          
          <div className="table-body">
            {streamHistory.map((stream) => (
              <div key={stream.id} className="table-row">
                <div className="col-title">
                  <div className="stream-title">{stream.title}</div>
                  <div className="stream-category">{stream.category}</div>
                </div>
                
                <div className="col-artist">{stream.artistName}</div>
                
                <div className="col-viewers">
                  {stream.analytics?.peakViewers || stream.viewerCount || 0}
                </div>
                
                <div className="col-duration">
                  {stream.endTime && stream.actualStartTime 
                    ? Math.round((stream.endTime - stream.actualStartTime) / 60000) + 'm'
                    : '-'
                  }
                </div>
                
                <div className="col-status">
                  <span className={`status-badge ${stream.status}`}>
                    {stream.status === 'ended' ? 'Completed' : 
                     stream.status === 'error' ? 'Error' : 
                     stream.status}
                  </span>
                </div>
                
                <div className="col-date">
                  {new Date(stream.startTime).toLocaleDateString()}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default StreamServerManagement;