// src/components/streaming/FeaturedStream.jsx
//
// Hero-slot panel for the home page. Always renders something nice:
//   - If a live event exists in Firestore (events where status='live'):
//       shows title, artist, category, viewer count, "Watch live" CTA.
//   - If nothing is live:
//       shows a friendly default with "Go live" / "Browse events" CTAs.
//   - On query error:
//       falls back to the same friendly default; never shows a red error
//       state to the visitor.
//
// Use this instead of LiveStreamViewer on landing pages where we don't
// know in advance whether any stream exists.

import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  getFirestore,
  collection,
  query,
  where,
  orderBy,
  limit,
  onSnapshot,
} from 'firebase/firestore';
import { Radio, Video, Mic, Users, ArrowRight, Sparkles } from 'lucide-react';

import { useAuth } from '../../contexts/AuthContext';

const FeaturedStream = () => {
  const navigate = useNavigate();
  const { currentUser } = useAuth();
  const [event, setEvent] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let unsub = null;
    try {
      const db = getFirestore();
      const q = query(
        collection(db, 'events'),
        where('status', '==', 'live'),
        orderBy('startTime', 'desc'),
        limit(1),
      );
      unsub = onSnapshot(
        q,
        (snap) => {
          if (!snap.empty) {
            const d = snap.docs[0];
            setEvent({ id: d.id, ...d.data() });
          } else {
            setEvent(null);
          }
          setLoading(false);
        },
        (err) => {
          // Permission issues, missing index, etc. Just fall back to the
          // friendly default instead of bubbling a red error.
          // eslint-disable-next-line no-console
          console.warn('[FeaturedStream] query failed, showing default:', err.message);
          setEvent(null);
          setLoading(false);
        },
      );
    } catch (e) {
      // eslint-disable-next-line no-console
      console.warn('[FeaturedStream] setup failed:', e);
      setLoading(false);
    }
    return () => {
      if (unsub) unsub();
    };
  }, []);

  if (loading) {
    return (
      <Shell>
        <div style={{ color: '#475569', fontSize: '0.9rem' }}>Looking for live streams…</div>
      </Shell>
    );
  }

  if (event) {
    return (
      <Shell
        accent="live"
        onClick={() => navigate(`/events/${event.id}`)}
        role="button"
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 12 }}>
          <span
            style={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: 4,
              padding: '2px 8px',
              borderRadius: 4,
              background: '#dc2626',
              color: 'white',
              fontSize: 10,
              fontWeight: 600,
              letterSpacing: '0.1em',
            }}
          >
            <span
              style={{
                width: 6,
                height: 6,
                borderRadius: '50%',
                background: 'white',
                animation: 'fs-pulse 1.6s ease-in-out infinite',
              }}
            />
            LIVE
          </span>
          {event.category && (
            <span style={{ fontSize: 11, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '0.08em' }}>
              {event.category}
            </span>
          )}
        </div>

        <h2 style={{ margin: '0 0 4px', fontSize: '1.5rem', fontWeight: 600 }}>
          {event.title || 'Live now'}
        </h2>
        {event.artistName && (
          <div style={{ color: '#cbd5e1', fontSize: '0.95rem', marginBottom: 12 }}>
            {event.artistName}
          </div>
        )}

        {event.description && (
          <p
            style={{
              margin: '0 0 16px',
              color: '#94a3b8',
              fontSize: '0.9rem',
              lineHeight: 1.45,
              display: '-webkit-box',
              WebkitLineClamp: 2,
              WebkitBoxOrient: 'vertical',
              overflow: 'hidden',
            }}
          >
            {event.description}
          </p>
        )}

        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginTop: 'auto', gap: 12 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 12, color: '#64748b', fontSize: 12 }}>
            {typeof event.viewerCount === 'number' && (
              <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}>
                <Users size={14} /> {event.viewerCount}
              </span>
            )}
          </div>
          <span
            style={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: 6,
              padding: '8px 14px',
              background: '#dc2626',
              color: 'white',
              borderRadius: 8,
              fontSize: 13,
              fontWeight: 500,
            }}
          >
            Watch live <ArrowRight size={14} />
          </span>
        </div>

        <style>{`
          @keyframes fs-pulse {
            0%, 100% { opacity: 1; }
            50%      { opacity: 0.35; }
          }
        `}</style>
      </Shell>
    );
  }

  // ----- Default (no live stream) -----
  return (
    <Shell accent="quiet">
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 12, color: '#64748b', fontSize: 11, letterSpacing: '0.08em', textTransform: 'uppercase' }}>
        <Radio size={14} /> No one streaming right now
      </div>

      <h2 style={{ margin: '0 0 8px', fontSize: '1.4rem', fontWeight: 600 }}>
        The stage is yours.
      </h2>
      <p style={{ margin: '0 0 16px', color: '#94a3b8', fontSize: '0.92rem', lineHeight: 1.5 }}>
        Be the first to go live tonight, or hum a tune into the mic and we'll
        sketch you something to share.
      </p>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, marginTop: 'auto' }}>
        <button
          onClick={() =>
            // Every signed-in user is a creator by default, so "Go live" drops
            // them straight into the streaming portal — no artist-signup gate.
            // Logged-out / anonymous users just need to authenticate first.
            navigate(
              currentUser && !currentUser.isAnonymous
                ? '/artist-streaming'
                : '/login',
            )
          }
          style={ctaStyle('primary')}
        >
          <Video size={14} style={{ marginRight: 6 }} />
          Go live
        </button>
        <button
          onClick={() => navigate('/sketch')}
          style={ctaStyle('ghost')}
        >
          <Sparkles size={14} style={{ marginRight: 6 }} />
          Sketch something
        </button>
      </div>
    </Shell>
  );
};

const Shell = ({ children, accent, onClick, role }) => (
  <div
    onClick={onClick}
    role={role}
    style={{
      width: '100%',
      minHeight: 280,
      padding: '1.25rem',
      display: 'flex',
      flexDirection: 'column',
      background:
        accent === 'live'
          ? 'linear-gradient(160deg, rgba(220,38,38,0.18), rgba(15,23,42,0.6))'
          : 'linear-gradient(160deg, rgba(99,102,241,0.10), rgba(15,23,42,0.5))',
      color: '#e2e8f0',
      cursor: role === 'button' ? 'pointer' : 'default',
      transition: 'transform 0.15s, box-shadow 0.15s',
    }}
    onMouseEnter={(e) => {
      if (role === 'button') e.currentTarget.style.transform = 'translateY(-1px)';
    }}
    onMouseLeave={(e) => {
      if (role === 'button') e.currentTarget.style.transform = '';
    }}
  >
    {children}
  </div>
);

const ctaStyle = (variant) => ({
  background: variant === 'primary' ? '#dc2626' : 'transparent',
  border: variant === 'primary' ? 'none' : '1px solid rgba(165,180,252,0.5)',
  color: variant === 'primary' ? 'white' : '#a5b4fc',
  padding: '10px 12px',
  borderRadius: 8,
  fontSize: 13,
  cursor: 'pointer',
  display: 'inline-flex',
  alignItems: 'center',
  justifyContent: 'center',
});

export default FeaturedStream;
