import React, { useState, useEffect } from 'react';
import { getDatabase, ref, get } from 'firebase/database';
import { getFirestore, collection, getDocs, limit, query } from 'firebase/firestore';
import { getStorage, ref as storageRef, listAll } from 'firebase/storage';

// Simple standalone Firebase Console with no external dependencies
const SimpleFirebaseConsole = () => {
  const [dbStatus, setDbStatus] = useState('unknown');
  const [firestoreStatus, setFirestoreStatus] = useState('unknown');
  const [storageStatus, setStorageStatus] = useState('unknown');
  const [isOpen, setIsOpen] = useState(true);
  const [logs, setLogs] = useState([]);

  // Check Firebase connections on mount
  useEffect(() => {
    checkConnections();
  }, []);

  const checkConnections = async () => {
    // Test Realtime Database
    try {
      const db = getDatabase();
      const publicRef = ref(db, 'public');
      const snapshot = await get(publicRef);
      setDbStatus(snapshot.exists() ? 'connected' : 'empty');
      addLog('Realtime DB', 'Connected successfully');
    } catch (error) {
      setDbStatus('error');
      addLog('Realtime DB', `Error: ${error.message}`, 'error');
    }

    // Test Firestore
    try {
      const db = getFirestore();
      const postsQuery = query(collection(db, 'posts'), limit(1));
      const snapshot = await getDocs(postsQuery);
      setFirestoreStatus(snapshot.empty ? 'empty' : 'connected');
      addLog('Firestore', 'Connected successfully');
    } catch (error) {
      setFirestoreStatus('error');
      addLog('Firestore', `Error: ${error.message}`, 'error');
    }

    // Test Storage
    try {
      const storage = getStorage();
      const backgroundRef = storageRef(storage, 'backgrounds');
      const result = await listAll(backgroundRef);
      setStorageStatus(result.items.length > 0 ? 'connected' : 'empty');
      addLog('Storage', `Connected successfully. Found ${result.items.length} backgrounds`);
    } catch (error) {
      setStorageStatus('error');
      addLog('Storage', `Error: ${error.message}`, 'error');
    }
  };

  const addLog = (source, message, type = 'info') => {
    const timestamp = new Date().toLocaleTimeString();
    setLogs(prev => [
      { id: `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`, timestamp, source, message, type },
      ...prev.slice(0, 49) // Keep last 50 logs
    ]);
  };

  // Status indicator styles
  const getStatusColor = (status) => {
    switch (status) {
      case 'connected': return '#4ade80'; // Green
      case 'empty': return '#f59e0b';     // Amber
      case 'error': return '#ef4444';     // Red
      default: return '#9ca3af';          // Gray
    }
  };

  return (
    <div
      style={{
        position: 'fixed',
        bottom: '20px',
        right: '20px',
        width: '350px',
        maxHeight: isOpen ? '500px' : '40px',
        backgroundColor: 'rgba(17, 24, 39, 0.95)',
        color: 'white',
        borderRadius: '8px',
        overflow: 'hidden',
        transition: 'max-height 0.3s ease',
        boxShadow: '0 4px 15px rgba(0,0,0,0.3)',
        zIndex: 9999,
        fontFamily: 'system-ui, -apple-system, sans-serif',
        fontSize: '13px',
        border: '1px solid #4f46e5'
      }}
    >
      {/* Header */}
      <div
        style={{
          padding: '10px 15px',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          borderBottom: isOpen ? '1px solid #4f46e5' : 'none',
          backgroundColor: '#1e1b4b',
          cursor: 'pointer'
        }}
        onClick={() => setIsOpen(!isOpen)}
      >
        <div style={{ fontWeight: 'bold', display: 'flex', alignItems: 'center' }}>
          <span style={{ marginRight: '8px' }}>🔥</span>
          Firebase Console
        </div>
        <div style={{ display: 'flex', gap: '8px' }}>
          <div
            style={{
              width: '10px',
              height: '10px',
              borderRadius: '50%',
              backgroundColor: getStatusColor(dbStatus)
            }}
            title={`Realtime DB: ${dbStatus}`}
          />
          <div
            style={{
              width: '10px',
              height: '10px',
              borderRadius: '50%',
              backgroundColor: getStatusColor(firestoreStatus)
            }}
            title={`Firestore: ${firestoreStatus}`}
          />
          <div
            style={{
              width: '10px',
              height: '10px',
              borderRadius: '50%',
              backgroundColor: getStatusColor(storageStatus)
            }}
            title={`Storage: ${storageStatus}`}
          />
          <span>{isOpen ? '▼' : '▲'}</span>
        </div>
      </div>

      {/* Content */}
      {isOpen && (
        <>
          {/* Status Bar */}
          <div style={{ padding: '8px 15px', borderBottom: '1px solid rgba(79, 70, 229, 0.3)', display: 'flex', justifyContent: 'space-between' }}>
            <div>
              <span style={{ fontWeight: 'bold', marginRight: '5px' }}>RTDB:</span>
              <span style={{ color: getStatusColor(dbStatus) }}>{dbStatus}</span>
            </div>
            <div>
              <span style={{ fontWeight: 'bold', marginRight: '5px' }}>Firestore:</span>
              <span style={{ color: getStatusColor(firestoreStatus) }}>{firestoreStatus}</span>
            </div>
            <div>
              <span style={{ fontWeight: 'bold', marginRight: '5px' }}>Storage:</span>
              <span style={{ color: getStatusColor(storageStatus) }}>{storageStatus}</span>
            </div>
          </div>

          {/* Action Buttons */}
          <div style={{ padding: '8px 15px', borderBottom: '1px solid rgba(79, 70, 229, 0.3)', display: 'flex', gap: '8px' }}>
            <button
              onClick={checkConnections}
              style={{
                padding: '5px 10px',
                backgroundColor: '#4f46e5',
                color: 'white',
                border: 'none',
                borderRadius: '4px',
                cursor: 'pointer',
                fontSize: '12px'
              }}
            >
              Refresh Status
            </button>
            <button
              onClick={() => setLogs([])}
              style={{
                padding: '5px 10px',
                backgroundColor: '#1f2937',
                color: 'white',
                border: '1px solid #4b5563',
                borderRadius: '4px',
                cursor: 'pointer',
                fontSize: '12px'
              }}
            >
              Clear Logs
            </button>
          </div>

          {/* Logs */}
          <div style={{ height: '320px', overflowY: 'auto', padding: '0 5px' }}>
            {logs.length === 0 ? (
              <div style={{ padding: '10px 15px', color: '#9ca3af', fontStyle: 'italic' }}>
                No logs yet. Click "Refresh Status" to check Firebase connections.
              </div>
            ) : (
              logs.map(log => (
                <div
                  key={log.id}
                  style={{
                    padding: '8px 10px',
                    borderBottom: '1px solid rgba(255,255,255,0.1)',
                    fontSize: '12px',
                    color: log.type === 'error' ? '#f87171' : '#e5e7eb'
                  }}
                >
                  <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '3px' }}>
                    <span style={{ fontWeight: 'bold', color: '#a5b4fc' }}>{log.source}</span>
                    <span style={{ color: '#9ca3af', fontSize: '11px' }}>{log.timestamp}</span>
                  </div>
                  <div>{log.message}</div>
                </div>
              ))
            )}
          </div>
        </>
      )}
    </div>
  );
};

export default SimpleFirebaseConsole;