/**
 * ReplayList.jsx - Archive/event list component for TalkStudio.space Watch-Replays
 * Path: C:\Users\Tom\Documents\GitHub\presence-react3\presence-react\src\components\WatchReplays\ReplayList.jsx
 * 
 * Displays list of available replay events with filtering, search, and pagination
 */

import React, { useState, useEffect, useCallback } from 'react';
import ReplayService from '../../services/recording/ReplayServiceDirect';

const ReplayList = ({ 
  onReplaySelect, 
  selectedEventId = null,
  className = '',
  showSearch = true,
  showFilters = true,
  itemsPerPage = 12 
}) => {
  // State management
  const [replays, setReplays] = useState([]);
  const [filteredReplays, setFilteredReplays] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [hasError, setHasError] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');

  // Search and filtering
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedFilter, setSelectedFilter] = useState('all');
  const [sortBy, setSortBy] = useState('recent');
  const [isSearching, setIsSearching] = useState(false);

  // Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);

  // Available filters
  const filterOptions = [
    { value: 'all', label: 'All Replays', icon: '📹' },
    { value: 'recent', label: 'Recent', icon: '🕒' },
    { value: 'popular', label: 'Popular', icon: '🔥' },
    { value: 'long', label: 'Long Form', icon: '⏱️' },
    { value: 'short', label: 'Short Form', icon: '⚡' }
  ];

  const sortOptions = [
    { value: 'recent', label: 'Most Recent' },
    { value: 'oldest', label: 'Oldest First' },
    { value: 'popular', label: 'Most Popular' },
    { value: 'duration_long', label: 'Longest First' },
    { value: 'duration_short', label: 'Shortest First' },
    { value: 'title', label: 'Title A-Z' }
  ];

  /**
   * Load replays from service
   */
  const loadReplays = useCallback(async (page = 1) => {
    try {
      setIsLoading(true);
      setLoadingProgress(0);
      setHasError(false);

      const options = {
        limit: itemsPerPage,
        orderBy: getSortField(sortBy),
        orderDirection: getSortDirection(sortBy)
      };

      setLoadingProgress(30);

      let replayData;
      if (selectedFilter === 'recent') {
        replayData = await ReplayService.getRecentReplays(itemsPerPage);
      } else if (selectedFilter === 'popular') {
        replayData = await ReplayService.getPopularReplays(itemsPerPage);
      } else {
        replayData = await ReplayService.getReplayEvents(options);
      }

      setLoadingProgress(70);

      // Apply additional filters
      const filtered = applyFilters(replayData);
      
      setReplays(replayData);
      setFilteredReplays(filtered);
      setTotalPages(Math.ceil(filtered.length / itemsPerPage));
      setCurrentPage(page);

      setLoadingProgress(100);
      setIsLoading(false);

    } catch (error) {
      console.error('Failed to load replays:', error);
      setHasError(true);
      setErrorMessage(error.message || 'Failed to load replays');
      setIsLoading(false);
    }
  }, [itemsPerPage, selectedFilter, sortBy]);

  /**
   * Search replays
   */
  const searchReplays = useCallback(async (term) => {
    if (!term.trim()) {
      setFilteredReplays(applyFilters(replays));
      setIsSearching(false);
      return;
    }

    try {
      setIsSearching(true);
      const searchResults = await ReplayService.searchReplayEvents(term.trim(), {
        limit: 50
      });
      
      const filtered = applyFilters(searchResults);
      setFilteredReplays(filtered);
      setTotalPages(Math.ceil(filtered.length / itemsPerPage));
      setCurrentPage(1);
      
    } catch (error) {
      console.error('Search failed:', error);
    } finally {
      setIsSearching(false);
    }
  }, [replays, itemsPerPage]);

  /**
   * Apply filters to replay list
   */
  const applyFilters = useCallback((replayList) => {
    let filtered = [...replayList];

    // Apply category filters
    switch (selectedFilter) {
      case 'long':
        filtered = filtered.filter(replay => (replay.duration || 0) > 1800); // > 30 minutes
        break;
      case 'short':
        filtered = filtered.filter(replay => (replay.duration || 0) <= 1800); // <= 30 minutes
        break;
      case 'recent':
      case 'popular':
      case 'all':
      default:
        // Already handled in loadReplays
        break;
    }

    // Apply sorting
    filtered.sort((a, b) => {
      switch (sortBy) {
        case 'recent':
          return new Date(b.createdAt) - new Date(a.createdAt);
        case 'oldest':
          return new Date(a.createdAt) - new Date(b.createdAt);
        case 'popular':
          return (b.viewCount || 0) - (a.viewCount || 0);
        case 'duration_long':
          return (b.duration || 0) - (a.duration || 0);
        case 'duration_short':
          return (a.duration || 0) - (b.duration || 0);
        case 'title':
          return (a.title || '').localeCompare(b.title || '');
        default:
          return 0;
      }
    });

    return filtered;
  }, [selectedFilter, sortBy]);

  /**
   * Get sort field for query
   */
  const getSortField = (sort) => {
    switch (sort) {
      case 'recent':
      case 'oldest':
        return 'createdAt';
      case 'popular':
        return 'viewCount';
      case 'duration_long':
      case 'duration_short':
        return 'duration';
      case 'title':
        return 'title';
      default:
        return 'createdAt';
    }
  };

  /**
   * Get sort direction for query
   */
  const getSortDirection = (sort) => {
    switch (sort) {
      case 'recent':
      case 'popular':
      case 'duration_long':
        return 'desc';
      case 'oldest':
      case 'duration_short':
      case 'title':
        return 'asc';
      default:
        return 'desc';
    }
  };

  /**
   * Handle search input
   */
  const handleSearchChange = useCallback((e) => {
    const term = e.target.value;
    setSearchTerm(term);
    
    // Debounce search
    const timeoutId = setTimeout(() => {
      searchReplays(term);
    }, 300);

    return () => clearTimeout(timeoutId);
  }, [searchReplays]);

  /**
   * Handle filter change
   */
  const handleFilterChange = useCallback((filter) => {
    setSelectedFilter(filter);
    setCurrentPage(1);
  }, []);

  /**
   * Handle sort change
   */
  const handleSortChange = useCallback((sort) => {
    setSortBy(sort);
    setCurrentPage(1);
  }, []);

  /**
   * Format duration
   */
  const formatDuration = (seconds) => {
    if (!seconds) return 'Unknown';
    
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    
    if (hours > 0) {
      return `${hours}h ${minutes}m`;
    }
    return `${minutes}m`;
  };

  /**
   * Format date
   */
  const formatDate = (date) => {
    if (!date) return 'Unknown';
    
    const now = new Date();
    const replayDate = new Date(date);
    const diffInHours = (now - replayDate) / (1000 * 60 * 60);
    
    if (diffInHours < 24) {
      return `${Math.floor(diffInHours)}h ago`;
    } else if (diffInHours < 168) { // 7 days
      return `${Math.floor(diffInHours / 24)}d ago`;
    } else {
      return replayDate.toLocaleDateString();
    }
  };

  /**
   * Get paginated items
   */
  const getPaginatedItems = () => {
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    return filteredReplays.slice(startIndex, endIndex);
  };

  /**
   * Handle page change
   */
  const handlePageChange = (page) => {
    setCurrentPage(page);
    // Scroll to top of list
    document.querySelector('.replay-list-container')?.scrollTo({ top: 0, behavior: 'smooth' });
  };

  /**
   * Effect hooks
   */
  useEffect(() => {
    loadReplays();
  }, [loadReplays]);

  useEffect(() => {
    if (replays.length > 0) {
      const filtered = applyFilters(replays);
      setFilteredReplays(filtered);
      setTotalPages(Math.ceil(filtered.length / itemsPerPage));
      setCurrentPage(1);
    }
  }, [selectedFilter, sortBy, replays, applyFilters, itemsPerPage]);

  /**
   * Render loading state
   */
  if (isLoading) {
    return (
      <div className={`p-6 ${className}`}>
        <div className="text-center">
          <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4 mx-auto"></div>
          <div className="text-lg font-medium mb-2">Loading Replays</div>
          <div className="w-64 bg-gray-200 rounded-full h-2 mx-auto">
            <div 
              className="bg-indigo-500 h-2 rounded-full transition-all duration-300"
              style={{ width: `${loadingProgress}%` }}
            ></div>
          </div>
          <div className="text-sm text-gray-500 mt-2">{loadingProgress}%</div>
        </div>
      </div>
    );
  }

  /**
   * Render error state
   */
  if (hasError) {
    return (
      <div className={`p-6 text-center ${className}`}>
        <div className="text-red-400 text-6xl mb-4">⚠️</div>
        <div className="text-xl font-medium mb-2">Error Loading Replays</div>
        <div className="text-gray-600 mb-4">{errorMessage}</div>
        <button 
          onClick={() => loadReplays()}
          className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg transition-colors"
        >
          Try Again
        </button>
      </div>
    );
  }

  const paginatedItems = getPaginatedItems();

  return (
    <div className={`replay-list-container ${className}`}>
      {/* Header with Search and Filters */}
      <div className="mb-6 space-y-4">
        {/* Title */}
        <div className="flex items-center justify-between">
          <h2 className="text-2xl font-bold text-gray-900">Watch Replays</h2>
          <div className="text-sm text-gray-500">
            {filteredReplays.length} replay{filteredReplays.length !== 1 ? 's' : ''}
          </div>
        </div>

        {/* Search Bar */}
        {showSearch && (
          <div className="relative">
            <input
              type="text"
              placeholder="Search replays..."
              value={searchTerm}
              onChange={handleSearchChange}
              className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
            />
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              {isSearching ? (
                <div className="w-4 h-4 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
              ) : (
                <svg className="h-5 w-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                </svg>
              )}
            </div>
          </div>
        )}

        {/* Filters and Sort */}
        {showFilters && (
          <div className="flex flex-col sm:flex-row gap-4 items-start sm:items-center justify-between">
            {/* Category Filters */}
            <div className="flex flex-wrap gap-2">
              {filterOptions.map(option => (
                <button
                  key={option.value}
                  onClick={() => handleFilterChange(option.value)}
                  className={`px-3 py-1.5 rounded-full text-sm font-medium transition-colors ${
                    selectedFilter === option.value
                      ? 'bg-indigo-100 text-indigo-700 border border-indigo-200'
                      : 'bg-gray-100 text-gray-600 hover:bg-gray-200 border border-gray-200'
                  }`}
                >
                  <span className="mr-1">{option.icon}</span>
                  {option.label}
                </button>
              ))}
            </div>

            {/* Sort Dropdown */}
            <div className="relative">
              <select
                value={sortBy}
                onChange={(e) => handleSortChange(e.target.value)}
                className="appearance-none bg-white border border-gray-300 rounded-lg px-4 py-2 pr-8 text-sm focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
              >
                {sortOptions.map(option => (
                  <option key={option.value} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </select>
              <div className="absolute inset-y-0 right-0 flex items-center px-2 pointer-events-none">
                <svg className="w-4 h-4 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                </svg>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Replay Grid */}
      {paginatedItems.length === 0 ? (
        <div className="text-center py-12">
          <div className="text-gray-400 text-6xl mb-4">🎬</div>
          <div className="text-xl font-medium text-gray-600 mb-2">
            {searchTerm ? 'No replays found' : 'No replays available'}
          </div>
          <div className="text-gray-500">
            {searchTerm ? 'Try adjusting your search terms' : 'Check back later for new replays'}
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
          {paginatedItems.map(replay => (
            <div
              key={replay.id}
              onClick={() => onReplaySelect?.(replay)}
              className={`bg-white rounded-lg shadow-md hover:shadow-lg transition-all duration-200 cursor-pointer transform hover:scale-105 ${
                selectedEventId === replay.id ? 'ring-2 ring-indigo-500' : ''
              }`}
            >
              {/* Thumbnail */}
              <div className="aspect-video bg-gray-200 rounded-t-lg relative overflow-hidden">
                {replay.thumbnailUrl ? (
                  <img
                    src={replay.thumbnailUrl}
                    alt={replay.title || 'Replay thumbnail'}
                    className="w-full h-full object-cover"
                    loading="lazy"
                  />
                ) : (
                  <div className="w-full h-full flex items-center justify-center bg-gradient-to-br from-indigo-400 to-purple-500">
                    <svg className="w-12 h-12 text-white opacity-75" fill="currentColor" viewBox="0 0 20 20">
                      <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" clipRule="evenodd" />
                    </svg>
                  </div>
                )}
                
                {/* Duration Badge */}
                {replay.duration && (
                  <div className="absolute bottom-2 right-2 bg-black bg-opacity-75 text-white text-xs px-2 py-1 rounded">
                    {formatDuration(replay.duration)}
                  </div>
                )}

                {/* Quality Badge */}
                <div className="absolute top-2 right-2 bg-indigo-600 text-white text-xs px-2 py-1 rounded">
                  HD
                </div>
              </div>

              {/* Content */}
              <div className="p-4">
                <h3 className="font-semibold text-gray-900 mb-1 line-clamp-2">
                  {replay.title || 'Untitled Replay'}
                </h3>
                
                {replay.description && (
                  <p className="text-sm text-gray-600 mb-2 line-clamp-2">
                    {replay.description}
                  </p>
                )}

                <div className="flex items-center justify-between text-xs text-gray-500">
                  <span>{formatDate(replay.createdAt)}</span>
                  {replay.viewCount !== undefined && (
                    <span className="flex items-center gap-1">
                      <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20">
                        <path d="M10 12a2 2 0 100-4 2 2 0 000 4z" />
                        <path fillRule="evenodd" d="M.458 10C1.732 5.943 5.522 3 10 3s8.268 2.943 9.542 7c-1.274 4.057-5.064 7-9.542 7S1.732 14.057.458 10zM14 10a4 4 0 11-8 0 4 4 0 018 0z" clipRule="evenodd" />
                      </svg>
                      {replay.viewCount}
                    </span>
                  )}
                </div>

                {/* Tags */}
                {replay.tags && replay.tags.length > 0 && (
                  <div className="flex flex-wrap gap-1 mt-2">
                    {replay.tags.slice(0, 3).map(tag => (
                      <span
                        key={tag}
                        className="inline-block bg-gray-100 text-gray-600 text-xs px-2 py-0.5 rounded-full"
                      >
                        {tag}
                      </span>
                    ))}
                    {replay.tags.length > 3 && (
                      <span className="text-xs text-gray-500">
                        +{replay.tags.length - 3} more
                      </span>
                    )}
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="mt-8 flex items-center justify-center">
          <nav className="flex items-center space-x-1">
            {/* Previous Button */}
            <button
              onClick={() => handlePageChange(currentPage - 1)}
              disabled={currentPage === 1}
              className="px-3 py-2 text-sm font-medium text-gray-500 hover:text-gray-700 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Previous
            </button>

            {/* Page Numbers */}
            {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
              let pageNum;
              if (totalPages <= 5) {
                pageNum = i + 1;
              } else if (currentPage <= 3) {
                pageNum = i + 1;
              } else if (currentPage >= totalPages - 2) {
                pageNum = totalPages - 4 + i;
              } else {
                pageNum = currentPage - 2 + i;
              }

              return (
                <button
                  key={pageNum}
                  onClick={() => handlePageChange(pageNum)}
                  className={`px-3 py-2 text-sm font-medium rounded-md ${
                    currentPage === pageNum
                      ? 'bg-indigo-600 text-white'
                      : 'text-gray-700 hover:bg-gray-100'
                  }`}
                >
                  {pageNum}
                </button>
              );
            })}

            {/* Next Button */}
            <button
              onClick={() => handlePageChange(currentPage + 1)}
              disabled={currentPage === totalPages}
              className="px-3 py-2 text-sm font-medium text-gray-500 hover:text-gray-700 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Next
            </button>
          </nav>
        </div>
      )}
    </div>
  );
};

export default ReplayList;
