// src/components/premium/FreeTierBanner.jsx
//
// Thin banner shown on data-heavy pages (Deals, Markets) for free-tier users,
// reminding them the numbers are masked and pointing to the pricing page.

import React from 'react';
import { Link } from 'react-router-dom';
import { Lock, ArrowRight } from 'lucide-react';
import { useSubscription } from '../../hooks/useSubscription';

const FreeTierBanner = ({ section = 'this page' }) => {
  const { tier, loading } = useSubscription();

  if (loading) return null;
  if (tier !== 'free') return null;

  return (
    <div
      style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        gap: 12,
        padding: '8px 14px',
        margin: '0 0 16px 0',
        background: 'linear-gradient(90deg, rgba(59,130,246,0.08), rgba(139,92,246,0.08))',
        border: '1px solid rgba(59,130,246,0.25)',
        borderRadius: 8,
        fontSize: 13,
        color: '#cbd5e1',
      }}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
        <Lock size={14} style={{ color: '#f59e0b', flexShrink: 0 }} />
        <span>
          You&apos;re viewing {section} in preview mode. Numbers are masked for free users.
        </span>
      </div>
      <Link
        to="/premium-membership"
        style={{
          display: 'inline-flex',
          alignItems: 'center',
          gap: 4,
          padding: '4px 10px',
          background: '#3b82f6',
          color: 'white',
          textDecoration: 'none',
          borderRadius: 6,
          fontWeight: 600,
          fontSize: 12,
          flexShrink: 0,
        }}
      >
        Unlock data <ArrowRight size={12} />
      </Link>
    </div>
  );
};

export default FreeTierBanner;
