// src/components/debug/AdminAccessFix.jsx
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { getFirestore, doc, getDoc, setDoc, updateDoc } from 'firebase/firestore';

/**
 * This component provides an emergency fix for admin access issues.
 * It allows a logged-in user to gain admin status by visiting this page
 * and clicking the button to set their isAdmin flag to true.
 */
const AdminAccessFix = () => {
  const { currentUser } = useAuth();
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState('');
  const [userDoc, setUserDoc] = useState(null);
  const navigate = useNavigate();

  // Check the current admin status
  useEffect(() => {
    const fetchUserData = async () => {
      if (!currentUser) return;
      
      try {
        setLoading(true);
        const db = getFirestore();
        const userDocRef = doc(db, 'users', currentUser.uid);
        const docSnap = await getDoc(userDocRef);
        
        if (docSnap.exists()) {
          setUserDoc(docSnap.data());
        }
      } catch (err) {
        console.error('Error fetching user data:', err);
        setError('Failed to fetch user data. Please try again.');
      } finally {
        setLoading(false);
      }
    };
    
    fetchUserData();
  }, [currentUser]);

  // Handle making the user an admin
  const handleMakeAdmin = async () => {
    if (!currentUser) {
      setError('You must be logged in to use this feature.');
      return;
    }
    
    try {
      setLoading(true);
      setError('');
      
      const db = getFirestore();
      const userDocRef = doc(db, 'users', currentUser.uid);
      const docSnap = await getDoc(userDocRef);
      
      if (docSnap.exists()) {
        // Update existing document
        await updateDoc(userDocRef, {
          isAdmin: true
        });
      } else {
        // Create new document
        await setDoc(userDocRef, {
          email: currentUser.email,
          displayName: currentUser.displayName || currentUser.email,
          createdAt: new Date(),
          isAdmin: true,
          isAudit: false
        });
      }
      
      // Also set the isAdmin property on the user object
      if (currentUser) {
        currentUser.isAdmin = true;
      }
      
      setSuccess(true);
      setUserDoc(prev => ({ ...prev, isAdmin: true }));
      
      // Redirect to admin panel after a short delay
      setTimeout(() => {
        navigate('/admin');
      }, 2000);
    } catch (err) {
      console.error('Error making user admin:', err);
      setError('Failed to update admin status. Please try again.');
    } finally {
      setLoading(false);
    }
  };
  
  // Handle navigating to admin panel
  const handleGoToAdmin = () => {
    navigate('/admin');
  };

  return (
    <div className="flex items-center justify-center min-h-screen bg-gray-100">
      <div className="bg-white p-8 rounded-lg shadow-md max-w-md w-full">
        <h1 className="text-2xl font-bold text-gray-800 mb-6">Admin Access Fix</h1>
        
        {!currentUser ? (
          <div className="text-red-600 mb-4">
            You must be logged in to use this feature. Please log in and try again.
          </div>
        ) : (
          <>
            <div className="mb-6">
              <h2 className="text-lg font-medium text-gray-700 mb-2">User Information</h2>
              <div className="bg-gray-50 p-4 rounded border border-gray-200">
                <p><span className="font-medium">Email:</span> {currentUser.email || 'Anonymous'}</p>
                <p><span className="font-medium">UID:</span> {currentUser.uid}</p>
                <p>
                  <span className="font-medium">Admin Status:</span>{' '}
                  {userDoc?.isAdmin === true ? (
                    <span className="text-green-600 font-medium">Admin</span>
                  ) : (
                    <span className="text-orange-600 font-medium">Not Admin</span>
                  )}
                </p>
              </div>
            </div>
            
            {success ? (
              <div className="bg-green-50 p-4 rounded-md border border-green-200 mb-6">
                <p className="text-green-700">
                  ✅ Admin access granted! You can now access the admin panel.
                </p>
              </div>
            ) : (
              <button
                onClick={handleMakeAdmin}
                disabled={loading || userDoc?.isAdmin === true}
                className={`w-full py-2 px-4 rounded-md font-medium text-white ${
                  loading || userDoc?.isAdmin === true
                    ? 'bg-gray-400 cursor-not-allowed'
                    : 'bg-blue-600 hover:bg-blue-700'
                } transition-colors mb-4`}
              >
                {loading ? 'Processing...' : userDoc?.isAdmin === true ? 'Already Admin' : 'Grant Admin Access'}
              </button>
            )}
            
            {userDoc?.isAdmin === true && (
              <button
                onClick={handleGoToAdmin}
                className="w-full py-2 px-4 rounded-md font-medium text-white bg-indigo-600 hover:bg-indigo-700 transition-colors"
              >
                Go to Admin Panel
              </button>
            )}
            
            {error && <p className="text-red-600 mt-4">{error}</p>}
            
            <div className="mt-8 text-sm text-gray-500">
              <p className="mb-2">
                <b>How this works:</b> This utility sets your account's <code>isAdmin</code> flag to true in the Firestore database,
                bypassing the normal admin authorization flow.
              </p>
              <p>
                <b>Note:</b> Only use this utility if you are authorized to have admin access but are experiencing issues with the normal admin login flow.
              </p>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default AdminAccessFix;
