// src/components/monetization/TipWallet.jsx
import React, { useState, useEffect } from 'react';
import { useWallet } from '../../contexts/WalletContext';
import { useAuth } from '../../contexts/AuthContext';
import { Elements } from '@stripe/react-stripe-js';
import { getStripeInstance } from '../../services/StripeInitializer';
import WalletTopUp from './WalletTopUp';
import { 
  Wallet, 
  Plus, 
  ArrowUpRight, 
  ArrowDownLeft, 
  History, 
  DollarSign,
  TrendingUp,
  Gift,
  Clock,
  User,
  ChevronDown,
  ChevronUp,
  ExternalLink
} from 'lucide-react';
import './TipWallet.css';

const TipWallet = ({ isOpen, onClose, mode = 'full' }) => {
  const { currentUser } = useAuth();
  const { 
    wallet, 
    loading, 
    balance, 
    formatCurrency, 
    transactions, 
    tipsSent, 
    tipsReceived,
    totalTipAmountSent,
    totalTipAmountReceived,
    canSendTips
  } = useWallet();
  
  const [stripePromise, setStripePromise] = useState(null);
  const [showTopUp, setShowTopUp] = useState(false);
  const [activeTab, setActiveTab] = useState('overview');
  const [showAllTransactions, setShowAllTransactions] = useState(false);
  const [showAllTips, setShowAllTips] = useState(false);

  // Load Stripe (skip in production)
  useEffect(() => {
    const hostname = window.location.hostname;
    const isProduction = hostname === 'talkstudio.space' || hostname === 'talkstud.io';

    if (isProduction) {
      console.log('Skipping Stripe initialization in production');
      return;
    }

    const loadStripe = async () => {
      const stripe = await getStripeInstance();
      setStripePromise(stripe);
    };
    loadStripe();
  }, []);

  // Don't render for anonymous users
  if (!currentUser || currentUser.isAnonymous) {
    return null;
  }

  // The modal is mounted permanently by MainNavigation, so a closed wallet must
  // render nothing at all — otherwise the loading state leaks a spinner onto
  // whatever page the user is actually on.
  if (mode !== 'compact' && !isOpen) {
    return null;
  }

  if (loading) {
    const spinner = (
      <div className="wallet-loading">
        <div className="loading-spinner"></div>
        <p>Loading wallet...</p>
      </div>
    );

    if (mode === 'compact') {
      return spinner;
    }

    return (
      <div className="wallet-modal open">
        <div className="wallet-modal-backdrop" onClick={onClose}></div>
        <div className="wallet-modal-content">{spinner}</div>
      </div>
    );
  }

  const handleTopUpSuccess = (result) => {
    console.log('Top-up successful:', result);
    setShowTopUp(false);
  };

  const formatDate = (date) => {
    if (!date) return 'Unknown';
    return new Intl.DateTimeFormat('en-US', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    }).format(new Date(date));
  };

  const getTransactionIcon = (type) => {
    switch (type) {
      case 'load':
        return <ArrowDownLeft size={16} className="transaction-icon load" />;
      case 'spend':
        return <ArrowUpRight size={16} className="transaction-icon spend" />;
      default:
        return <DollarSign size={16} className="transaction-icon" />;
    }
  };

  // Compact mode for embedding in other components
  if (mode === 'compact') {
    return (
      <div className="wallet-compact">
        <div className="wallet-balance-compact">
          <Wallet size={16} />
          <span className="balance-text">{formatCurrency(balance)}</span>
          <button 
            className="topup-btn-compact"
            onClick={() => setShowTopUp(true)}
            title="Add money to wallet"
          >
            <Plus size={14} />
          </button>
        </div>
        
        {stripePromise && (
          <Elements stripe={stripePromise}>
            <WalletTopUp 
              isOpen={showTopUp}
              onClose={() => setShowTopUp(false)}
              onSuccess={handleTopUpSuccess}
            />
          </Elements>
        )}
      </div>
    );
  }

  const recentTransactions = transactions.slice(0, showAllTransactions ? transactions.length : 5);
  const recentTips = [...tipsSent, ...tipsReceived]
    .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
    .slice(0, showAllTips ? undefined : 5);

  return (
    <>
      <div className={`wallet-modal ${isOpen ? 'open' : ''}`}>
        <div className="wallet-modal-backdrop" onClick={onClose}></div>
        <div className="wallet-modal-content">
          {/* Header */}
          <div className="wallet-header">
            <div className="header-title">
              <Wallet size={24} />
              <h2>Tip Wallet</h2>
            </div>
            <button className="close-btn" onClick={onClose}>
              <ExternalLink size={20} />
            </button>
          </div>

          {/* Tab Navigation */}
          <div className="wallet-tabs">
            <button 
              className={`tab-btn ${activeTab === 'overview' ? 'active' : ''}`}
              onClick={() => setActiveTab('overview')}
            >
              Overview
            </button>
            <button 
              className={`tab-btn ${activeTab === 'transactions' ? 'active' : ''}`}
              onClick={() => setActiveTab('transactions')}
            >
              Transactions
            </button>
            <button 
              className={`tab-btn ${activeTab === 'tips' ? 'active' : ''}`}
              onClick={() => setActiveTab('tips')}
            >
              Tips
            </button>
          </div>

          {/* Overview Tab */}
          {activeTab === 'overview' && (
            <div className="wallet-content">
              {/* Balance Card */}
              <div className="balance-card">
                <div className="balance-header">
                  <h3>Current Balance</h3>
                  <button 
                    className="topup-btn"
                    onClick={() => setShowTopUp(true)}
                  >
                    <Plus size={16} />
                    Add Money
                  </button>
                </div>
                <div className="balance-amount">
                  {formatCurrency(balance)}
                </div>
                <div className="balance-subtitle">
                  Available for tips and purchases
                </div>
              </div>

              {/* Stats Grid */}
              <div className="stats-grid">
                <div className="stat-card">
                  <div className="stat-icon">
                    <TrendingUp size={20} />
                  </div>
                  <div className="stat-content">
                    <div className="stat-value">{formatCurrency(wallet?.totalLoaded || 0)}</div>
                    <div className="stat-label">Total Loaded</div>
                  </div>
                </div>
                
                <div className="stat-card">
                  <div className="stat-icon">
                    <Gift size={20} />
                  </div>
                  <div className="stat-content">
                    <div className="stat-value">{formatCurrency(totalTipAmountSent)}</div>
                    <div className="stat-label">Tips Sent</div>
                  </div>
                </div>
                
                <div className="stat-card">
                  <div className="stat-icon">
                    <ArrowDownLeft size={20} />
                  </div>
                  <div className="stat-content">
                    <div className="stat-value">{formatCurrency(totalTipAmountReceived)}</div>
                    <div className="stat-label">Tips Received</div>
                  </div>
                </div>
              </div>

              {/* Recent Activity */}
              <div className="recent-activity">
                <div className="section-header">
                  <h4>Recent Activity</h4>
                  <button 
                    className="view-all-btn"
                    onClick={() => setActiveTab('transactions')}
                  >
                    View All
                  </button>
                </div>
                
                {recentTransactions.length > 0 ? (
                  <div className="transaction-list">
                    {recentTransactions.map((transaction) => (
                      <div key={transaction.id} className="transaction-item">
                        {getTransactionIcon(transaction.type)}
                        <div className="transaction-details">
                          <div className="transaction-description">
                            {transaction.description}
                          </div>
                          <div className="transaction-date">
                            {formatDate(transaction.createdAt)}
                          </div>
                        </div>
                        <div className={`transaction-amount ${transaction.type}`}>
                          {transaction.type === 'load' ? '+' : '-'}{formatCurrency(transaction.amount)}
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="empty-state">
                    <History size={32} />
                    <p>No transactions yet</p>
                    <p className="empty-subtitle">Add money to your wallet to get started</p>
                  </div>
                )}
              </div>
            </div>
          )}

          {/* Transactions Tab */}
          {activeTab === 'transactions' && (
            <div className="wallet-content">
              <div className="section-header">
                <h4>All Transactions</h4>
                <div className="transaction-summary">
                  {transactions.length} transactions
                </div>
              </div>
              
              {transactions.length > 0 ? (
                <div className="transaction-list">
                  {transactions.map((transaction) => (
                    <div key={transaction.id} className="transaction-item detailed">
                      {getTransactionIcon(transaction.type)}
                      <div className="transaction-details">
                        <div className="transaction-description">
                          {transaction.description}
                        </div>
                        <div className="transaction-meta">
                          <span className="transaction-date">
                            {formatDate(transaction.createdAt)}
                          </span>
                          <span className="transaction-status">
                            {transaction.status}
                          </span>
                        </div>
                        <div className="balance-change">
                          Balance: {formatCurrency(transaction.balanceBefore)} → {formatCurrency(transaction.balanceAfter)}
                        </div>
                      </div>
                      <div className={`transaction-amount ${transaction.type}`}>
                        {transaction.type === 'load' ? '+' : '-'}{formatCurrency(transaction.amount)}
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="empty-state">
                  <History size={48} />
                  <p>No transactions yet</p>
                  <p className="empty-subtitle">Your transaction history will appear here</p>
                </div>
              )}
            </div>
          )}

          {/* Tips Tab */}
          {activeTab === 'tips' && (
            <div className="wallet-content">
              <div className="section-header">
                <h4>Tip History</h4>
                <div className="tip-summary">
                  {tipsSent.length} sent • {tipsReceived.length} received
                </div>
              </div>
              
              {recentTips.length > 0 ? (
                <div className="tip-list">
                  {recentTips.map((tip) => {
                    const isSent = tip.senderId === currentUser.uid;
                    return (
                      <div key={tip.id} className={`tip-item ${isSent ? 'sent' : 'received'}`}>
                        <div className="tip-icon">
                          {isSent ? <ArrowUpRight size={16} /> : <ArrowDownLeft size={16} />}
                        </div>
                        <div className="tip-details">
                          <div className="tip-description">
                            {isSent ? 'Tip sent' : 'Tip received'}
                            {tip.message && (
                              <span className="tip-message">: "{tip.message}"</span>
                            )}
                          </div>
                          <div className="tip-meta">
                            <span className="tip-date">
                              {formatDate(tip.createdAt)}
                            </span>
                            {tip.streamId && (
                              <span className="tip-stream">
                                During stream
                              </span>
                            )}
                          </div>
                        </div>
                        <div className={`tip-amount ${isSent ? 'sent' : 'received'}`}>
                          {isSent ? '-' : '+'}{formatCurrency(tip.amount)}
                        </div>
                      </div>
                    );
                  })}
                </div>
              ) : (
                <div className="empty-state">
                  <Gift size={48} />
                  <p>No tips yet</p>
                  <p className="empty-subtitle">
                    {canSendTips() 
                      ? 'Send your first tip to support an artist!' 
                      : 'Tip history will appear here'}
                  </p>
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      {/* Top-Up Modal */}
      {stripePromise && (
        <Elements stripe={stripePromise}>
          <WalletTopUp 
            isOpen={showTopUp}
            onClose={() => setShowTopUp(false)}
            onSuccess={handleTopUpSuccess}
          />
        </Elements>
      )}
    </>
  );
};

export default TipWallet;