// src/utils/backgroundUtils.js

/**
 * Background Utility Functions
 * Handles background management for various components
 */


/**
 * Validates background URLs (both images and videos)
 * @param {string} url - The URL to validate
 * @param {string} type - 'image' or 'video'
 * @returns {Promise<{valid: boolean, error: string|null}>} - Validation result with error message if any
 */
export const validateBackgroundUrl = async (url, type = 'image') => {
    if (!url) return { valid: false, error: 'No URL provided' };
    
    console.log(`Validating ${type} URL:`, url);
    
    // Check if URL is relative - those are always considered valid
    if (url.startsWith('/') && !url.startsWith('//')) {
      console.log('URL is relative path, considered valid');
      return { valid: true, error: null };
    }
    
    // Check if Firebase Storage URL - handle special case for CORS
    if (url.includes('firebasestorage.googleapis.com')) {
      console.log('Firebase Storage URL detected');
      
      // For Firebase Storage URLs, we need to ensure they include the token
      if (!url.includes('?')) {
        console.warn('Firebase Storage URL missing token parameters');
        return { 
          valid: false, 
          error: 'Firebase Storage URL is missing authentication token' 
        };
      }
    }
    
    // For external URLs, test loading
    return new Promise((resolve) => {
      if (type === 'image') {
        console.log('Testing image loading...');
        const img = new Image();
        
        img.onload = () => {
          console.log('Image loaded successfully:', url);
          resolve({ valid: true, error: null });
        };
        
        img.onerror = (e) => {
          console.error('Image loading failed:', e);
          resolve({ 
            valid: false, 
            error: 'Image could not be loaded. It may be inaccessible or have CORS restrictions.' 
          });
        };
        
        // Add cache-busting parameter to avoid cached errors
        img.src = url.includes('?') ? `${url}&_cb=${Date.now()}` : `${url}?_cb=${Date.now()}`;
      } else if (type === 'video') {
        console.log('Testing video loading...');
        const video = document.createElement('video');
        
        video.onloadeddata = () => {
          console.log('Video loaded successfully:', url);
          resolve({ valid: true, error: null });
        };
        
        video.onerror = (e) => {
          console.error('Video loading failed:', e);
          resolve({ 
            valid: false, 
            error: 'Video could not be loaded. It may be inaccessible or have CORS restrictions.' 
          });
        };
        
        // Add cache-busting parameter to avoid cached errors
        video.src = url.includes('?') ? `${url}&_cb=${Date.now()}` : `${url}?_cb=${Date.now()}`;
      } else if (type === 'color') {
        // Colors are always valid
        console.log('Color type is always valid');
        resolve({ valid: true, error: null });
      } else {
        console.warn('Unknown background type:', type);
        resolve({ 
          valid: false, 
          error: `Unknown background type: ${type}` 
        });
      }
      
      // Timeout after 5 seconds
      setTimeout(() => {
        console.warn(`URL validation timed out after 5 seconds: ${url}`);
        resolve({ 
          valid: false, 
          error: 'Validation timed out. Resource may be slow or inaccessible.' 
        });
      }, 5000);
    });
  };
  
  /**
   * Creates a background object from a URL
   * @param {string} url - The URL of the background media (or color code for type='color')
   * @param {string} type - 'image', 'video', or 'color'
   * @returns {Object} - A background object
   */
  export const createBackgroundObject = (url, type = 'image') => {
    const id = Date.now().toString();
    
    if (type === 'color') {
      return {
        id,
        color: url,  // For color type, url is actually a color code
        type,
        isActive: true,
        createdAt: new Date().toISOString(),
      };
    }
    
    return {
      id,
      url,
      type,
      isActive: true,
      createdAt: new Date().toISOString(),
    };
  };
  
  /**
   * Gets a default background object
   * @returns {Object} - A default background object
   */
  export const getDefaultBackground = () => {
    // Force use of the color fallback for now
    // This avoids potential hanging when trying to load the default image
    return {
      id: 'default',
      color: '#1e293b', // Slate-800 from Tailwind
      type: 'color',
      isActive: true,
      isDefault: true,
    };
  };
  
  /**
   * Get the active background from a list of backgrounds
   * @param {Array} backgrounds - Array of background objects
   * @returns {Object|null} - The active background or null
   */
  export const getActiveBackground = (backgrounds) => {
    if (!backgrounds || !Array.isArray(backgrounds) || backgrounds.length === 0) {
      return getDefaultBackground();
    }
    
    const activeBackground = backgrounds.find(bg => bg.isActive);
    return activeBackground || backgrounds[0] || getDefaultBackground();
  };
  
  /**
   * Initialize background configuration if it doesn't exist
   * @param {Object} config - The current configuration object
   * @returns {Object} - Updated configuration with backgrounds initialized
   */
  export const initializeBackgrounds = (config) => {
    console.log('Initializing backgrounds...', config ? 'Config exists' : 'No config');
    
    if (!config) {
      const defaultConfig = {
        backgrounds: [getDefaultBackground()],
        videoSettings: {
          autoplay: true,
          loop: true,
          muted: true,
          controls: false,
          playbackRate: 1
        }
      };
      console.log('Created default config with background:', defaultConfig.backgrounds[0]);
      return defaultConfig;
    }
    
    // Create a copy of the config to avoid direct mutations
    let updatedConfig = { ...config };
    
    // Log initial state
    if (updatedConfig.backgrounds) {
      console.log(`Found ${updatedConfig.backgrounds.length} backgrounds in config`);
      if (updatedConfig.backgrounds.length > 0) {
        const active = updatedConfig.backgrounds.find(bg => bg.isActive);
        console.log('Active background:', active || 'None');
      }
    } else {
      console.log('No backgrounds array found in config');
    }
    
    // Ensure backgrounds array exists
    if (!updatedConfig.backgrounds || !Array.isArray(updatedConfig.backgrounds)) {
      console.log('Creating new backgrounds array with default background');
      updatedConfig.backgrounds = [getDefaultBackground()];
    } else if (updatedConfig.backgrounds.length === 0) {
      // If array exists but is empty, add default background
      console.log('Backgrounds array is empty, adding default background');
      updatedConfig.backgrounds = [getDefaultBackground()];
    }
    
    // Filter out invalid backgrounds (ones with missing required properties)
    const originalLength = updatedConfig.backgrounds.length;
    updatedConfig.backgrounds = updatedConfig.backgrounds.filter(bg => {
      if (!bg) {
        console.warn('Found null or undefined background entry, removing');
        return false;
      }
      
      // Check if background has necessary properties based on type
      if (bg.type === 'color') {
        const isValid = bg.color !== undefined;
        if (!isValid) console.warn('Found invalid color background (missing color property):', bg);
        return isValid;
      } else {
        const isValid = bg.url !== undefined && bg.type !== undefined;
        if (!isValid) console.warn('Found invalid background (missing url or type):', bg);
        return isValid;
      }
    });
    
    if (originalLength !== updatedConfig.backgrounds.length) {
      console.log(`Filtered out ${originalLength - updatedConfig.backgrounds.length} invalid backgrounds`);
    }
    
    // If we filtered out all backgrounds, add the default
    if (updatedConfig.backgrounds.length === 0) {
      console.log('No valid backgrounds remain, adding default background');
      updatedConfig.backgrounds = [getDefaultBackground()];
    }
    
    // Ensure there's at least one active background
    if (!updatedConfig.backgrounds.some(bg => bg.isActive)) {
      console.log('No active background found, setting first background as active');
      updatedConfig.backgrounds[0].isActive = true;
    }
    
    // Ensure video settings exist with defaults
    updatedConfig.videoSettings = {
      autoplay: true,
      loop: true,
      muted: true,
      controls: false,
      playbackRate: 1,
      ...updatedConfig.videoSettings
    };
    
    // Check for and fix Firebase Storage URLs without proper parameters
    updatedConfig.backgrounds = updatedConfig.backgrounds.map(bg => {
      if (bg.type === 'image' || bg.type === 'video') {
        // Only process URLs that exist and are Firebase Storage URLs
        if (bg.url && bg.url.includes('firebasestorage.googleapis.com')) {
          // Ensure URL has necessary parameters
          if (!bg.url.includes('?')) {
            console.warn('Fixing Firebase Storage URL missing parameters:', bg.url);
            return {
              ...bg,
              url: `${bg.url}?alt=media&token=background-${Date.now()}`
            };
          }
        }
      }
      return bg;
    });
    
    console.log('Background initialization complete:', 
      `${updatedConfig.backgrounds.length} backgrounds,`,
      `Active: ${updatedConfig.backgrounds.find(bg => bg.isActive)?.id || 'None'}`
    );
    
    return updatedConfig;
  };