/**
 * Advanced BPM Detection using Web Audio API
 * Implements beat detection algorithms for DJ applications
 */

export class BPMDetector {
  constructor(audioContext) {
    this.audioContext = audioContext;
    this.sampleRate = audioContext.sampleRate;
  }

  /**
   * Detect BPM from audio buffer using multiple algorithms
   * @param {AudioBuffer} audioBuffer - The audio buffer to analyze
   * @returns {Promise<number|null>} - The detected BPM or null if detection failed
   */
  async detectBPM(audioBuffer) {
    try {
      // Use the first channel for analysis
      const channelData = audioBuffer.getChannelData(0);
      
      // Combine multiple detection methods for better accuracy
      const methods = [
        this.detectBPMByPeaks(channelData),
        this.detectBPMBySpectrum(audioBuffer),
        this.detectBPMByEnergy(channelData)
      ];
      
      const results = await Promise.all(methods);
      const validResults = results.filter(bpm => bpm !== null && bpm >= 60 && bpm <= 200);
      
      if (validResults.length === 0) return null;
      
      // Return the median of valid results for better accuracy
      validResults.sort((a, b) => a - b);
      const median = validResults[Math.floor(validResults.length / 2)];
      
      return Math.round(median);
    } catch (error) {
      console.error('BPM detection failed:', error);
      return null;
    }
  }

  /**
   * Peak-based BPM detection
   * @param {Float32Array} channelData - Audio channel data
   * @returns {number|null} - Detected BPM
   */
  detectBPMByPeaks(channelData) {
    const peaks = this.findPeaks(channelData);
    if (peaks.length < 10) return null;
    
    const intervals = [];
    for (let i = 1; i < peaks.length; i++) {
      const interval = (peaks[i] - peaks[i - 1]) / this.sampleRate;
      if (interval > 0.2 && interval < 2) { // Filter reasonable intervals
        intervals.push(interval);
      }
    }
    
    if (intervals.length < 5) return null;
    
    // Find the most common interval
    const histogram = this.createIntervalHistogram(intervals);
    const dominantInterval = this.findDominantInterval(histogram);
    
    return dominantInterval ? Math.round(60 / dominantInterval) : null;
  }

  /**
   * Spectrum-based BPM detection using FFT
   * @param {AudioBuffer} audioBuffer - The audio buffer
   * @returns {number|null} - Detected BPM
   */
  async detectBPMBySpectrum(audioBuffer) {
    try {
      // Create offline audio context for processing
      const offlineContext = new OfflineAudioContext(
        1, 
        audioBuffer.length, 
        audioBuffer.sampleRate
      );
      
      // Apply high-pass filter to focus on beat frequencies
      const source = offlineContext.createBufferSource();
      const filter = offlineContext.createBiquadFilter();
      
      source.buffer = audioBuffer;
      filter.type = 'highpass';
      filter.frequency.value = 60; // Focus on frequencies above 60Hz
      
      source.connect(filter);
      filter.connect(offlineContext.destination);
      
      source.start(0);
      const filteredBuffer = await offlineContext.startRendering();
      
      // Analyze filtered audio for beat patterns
      return this.analyzeBeats(filteredBuffer.getChannelData(0));
    } catch (error) {
      console.error('Spectrum-based BPM detection failed:', error);
      return null;
    }
  }

  /**
   * Energy-based BPM detection
   * @param {Float32Array} channelData - Audio channel data
   * @returns {number|null} - Detected BPM
   */
  detectBPMByEnergy(channelData) {
    const windowSize = Math.floor(this.sampleRate * 0.05); // 50ms windows
    const energyValues = [];
    
    // Calculate energy for each window
    for (let i = 0; i < channelData.length - windowSize; i += windowSize) {
      let energy = 0;
      for (let j = i; j < i + windowSize; j++) {
        energy += channelData[j] * channelData[j];
      }
      energyValues.push(energy / windowSize);
    }
    
    // Find energy peaks
    const energyPeaks = this.findEnergyPeaks(energyValues);
    if (energyPeaks.length < 10) return null;
    
    // Calculate intervals between energy peaks
    const intervals = [];
    for (let i = 1; i < energyPeaks.length; i++) {
      const interval = (energyPeaks[i] - energyPeaks[i - 1]) * windowSize / this.sampleRate;
      if (interval > 0.3 && interval < 2) {
        intervals.push(interval);
      }
    }
    
    if (intervals.length < 5) return null;
    
    // Find dominant interval
    const avgInterval = intervals.reduce((sum, interval) => sum + interval, 0) / intervals.length;
    return Math.round(60 / avgInterval);
  }

  /**
   * Find peaks in audio data
   * @param {Float32Array} data - Audio data
   * @returns {number[]} - Array of peak positions
   */
  findPeaks(data) {
    const peaks = [];
    const threshold = this.calculateDynamicThreshold(data);
    const minDistance = Math.floor(this.sampleRate * 0.1); // 100ms minimum between peaks
    
    for (let i = minDistance; i < data.length - minDistance; i++) {
      if (Math.abs(data[i]) > threshold) {
        let isPeak = true;
        
        // Check if this is a local maximum
        for (let j = i - minDistance; j < i + minDistance; j++) {
          if (Math.abs(data[j]) > Math.abs(data[i])) {
            isPeak = false;
            break;
          }
        }
        
        if (isPeak) {
          peaks.push(i);
          i += minDistance; // Skip ahead to avoid duplicate peaks
        }
      }
    }
    
    return peaks;
  }

  /**
   * Calculate dynamic threshold for peak detection
   * @param {Float32Array} data - Audio data
   * @returns {number} - Threshold value
   */
  calculateDynamicThreshold(data) {
    // Calculate RMS (Root Mean Square) for dynamic threshold
    let sum = 0;
    for (let i = 0; i < data.length; i++) {
      sum += data[i] * data[i];
    }
    const rms = Math.sqrt(sum / data.length);
    return rms * 2; // Threshold is 2x RMS
  }

  /**
   * Create histogram of intervals
   * @param {number[]} intervals - Array of time intervals
   * @returns {Map} - Histogram of intervals
   */
  createIntervalHistogram(intervals) {
    const histogram = new Map();
    const binSize = 0.01; // 10ms bins
    
    intervals.forEach(interval => {
      const bin = Math.round(interval / binSize) * binSize;
      histogram.set(bin, (histogram.get(bin) || 0) + 1);
    });
    
    return histogram;
  }

  /**
   * Find the most common interval from histogram
   * @param {Map} histogram - Interval histogram
   * @returns {number|null} - Dominant interval
   */
  findDominantInterval(histogram) {
    let maxCount = 0;
    let dominantInterval = null;
    
    for (const [interval, count] of histogram) {
      if (count > maxCount) {
        maxCount = count;
        dominantInterval = interval;
      }
    }
    
    return maxCount >= 3 ? dominantInterval : null; // Need at least 3 occurrences
  }

  /**
   * Find energy peaks in energy array
   * @param {number[]} energyValues - Array of energy values
   * @returns {number[]} - Array of peak positions
   */
  findEnergyPeaks(energyValues) {
    const peaks = [];
    const threshold = this.calculateEnergyThreshold(energyValues);
    const minDistance = 2; // Minimum distance between peaks in array indices
    
    for (let i = minDistance; i < energyValues.length - minDistance; i++) {
      if (energyValues[i] > threshold) {
        let isPeak = true;
        
        for (let j = i - minDistance; j <= i + minDistance; j++) {
          if (energyValues[j] > energyValues[i]) {
            isPeak = false;
            break;
          }
        }
        
        if (isPeak) {
          peaks.push(i);
          i += minDistance;
        }
      }
    }
    
    return peaks;
  }

  /**
   * Calculate energy threshold
   * @param {number[]} energyValues - Array of energy values
   * @returns {number} - Threshold value
   */
  calculateEnergyThreshold(energyValues) {
    const sortedValues = [...energyValues].sort((a, b) => a - b);
    const percentile90 = sortedValues[Math.floor(sortedValues.length * 0.9)];
    return percentile90 * 0.7; // 70% of 90th percentile
  }

  /**
   * Analyze beats using autocorrelation
   * @param {Float32Array} data - Audio data
   * @returns {number|null} - Detected BPM
   */
  analyzeBeats(data) {
    const maxLag = Math.floor(this.sampleRate * 2); // 2 seconds max lag
    const minLag = Math.floor(this.sampleRate * 0.3); // 0.3 seconds min lag
    
    let maxCorrelation = 0;
    let bestLag = 0;
    
    // Calculate autocorrelation
    for (let lag = minLag; lag < maxLag; lag += 100) { // Skip samples for performance
      let correlation = 0;
      let count = 0;
      
      for (let i = 0; i < data.length - lag; i += 1000) { // Sample every 1000th point
        correlation += data[i] * data[i + lag];
        count++;
      }
      
      correlation /= count;
      
      if (correlation > maxCorrelation) {
        maxCorrelation = correlation;
        bestLag = lag;
      }
    }
    
    if (maxCorrelation > 0.1 && bestLag > 0) {
      const bpm = Math.round(60 * this.sampleRate / bestLag);
      return bpm >= 60 && bpm <= 200 ? bpm : null;
    }
    
    return null;
  }
}

/**
 * Convenience function to detect BPM
 * @param {AudioBuffer} audioBuffer - The audio buffer to analyze
 * @param {AudioContext} audioContext - The audio context
 * @returns {Promise<number|null>} - The detected BPM
 */
export async function detectBPM(audioBuffer, audioContext) {
  const detector = new BPMDetector(audioContext);
  return await detector.detectBPM(audioBuffer);
}

export default BPMDetector;