import { getDatabase, ref, push, set, get, update, onValue, query, orderByChild, equalTo } from 'firebase/database';
import { getAuth } from 'firebase/auth';
import TopicService from './TopicService';

class IdeaService {
  constructor() {
    this.database = getDatabase();
    this.auth = getAuth();
    this.ideasPath = 'ideas';
  }

  /**
   * Get current user ID
   */
  getCurrentUserId() {
    return this.auth.currentUser?.uid;
  }

  /**
   * Create a new idea
   */
  async createIdea({ topicId, title, description, creatorName = null, sortOrder = 0 }) {
    try {
      const userId = this.getCurrentUserId();
      if (!userId) {
        throw new Error('No authenticated user');
      }

      console.log('💡 Creating idea:', title);

      const now = Date.now();
      const ideaData = {
        topicId,
        title,
        description,
        creatorId: userId,
        creatorName: creatorName || 'Anonymous',
        sortOrder,
        isActive: true,
        upvoteCount: 0,
        commentCount: 0,
        createdAt: now,
        updatedAt: now,
      };

      const ideaRef = push(ref(this.database, this.ideasPath));
      await set(ideaRef, ideaData);

      // Increment idea count in parent topic
      await TopicService.incrementIdeaCount(topicId);

      console.log('✅ Idea created with ID:', ideaRef.key);
      return ideaRef.key;
    } catch (error) {
      console.error('❌ Failed to create idea:', error);
      throw error;
    }
  }

  /**
   * Get an idea by ID
   */
  async getIdea(ideaId) {
    try {
      console.log('🔍 Loading idea:', ideaId);

      const ideaRef = ref(this.database, `${this.ideasPath}/${ideaId}`);
      const snapshot = await get(ideaRef);

      if (!snapshot.exists()) {
        console.log('🚫 Idea not found:', ideaId);
        return null;
      }

      const data = snapshot.val();
      return {
        id: ideaId,
        ...data,
      };
    } catch (error) {
      console.error('❌ Failed to load idea:', error);
      throw error;
    }
  }

  /**
   * Stream all ideas (real-time)
   */
  streamAllIdeas(callback) {
    const ideasRef = query(
      ref(this.database, this.ideasPath),
      orderByChild('createdAt')
    );

    const unsubscribe = onValue(ideasRef, (snapshot) => {
      const ideas = [];

      if (snapshot.exists()) {
        const data = snapshot.val();

        Object.entries(data).forEach(([key, value]) => {
          // Only include active ideas
          if (value.isActive) {
            ideas.push({
              id: key,
              ...value,
            });
          }
        });

        // Sort by createdAt (newest first)
        ideas.sort((a, b) => b.createdAt - a.createdAt);
      }

      callback(ideas);
    });

    return unsubscribe;
  }

  /**
   * Stream ideas by topic (real-time)
   */
  streamIdeasByTopic(topicId, callback) {
    const ideasRef = query(
      ref(this.database, this.ideasPath),
      orderByChild('topicId'),
      equalTo(topicId)
    );

    const unsubscribe = onValue(ideasRef, (snapshot) => {
      const ideas = [];

      if (snapshot.exists()) {
        const data = snapshot.val();

        Object.entries(data).forEach(([key, value]) => {
          // Only include active ideas
          if (value.isActive) {
            ideas.push({
              id: key,
              ...value,
            });
          }
        });

        // Sort by upvoteCount first, then by createdAt
        ideas.sort((a, b) => {
          if (b.upvoteCount !== a.upvoteCount) {
            return b.upvoteCount - a.upvoteCount;
          }
          return b.createdAt - a.createdAt;
        });
      }

      callback(ideas);
    });

    return unsubscribe;
  }

  /**
   * Get all ideas (one-time fetch)
   */
  async getAllIdeas() {
    try {
      console.log('🔍 Loading all ideas');

      const ideasRef = query(
        ref(this.database, this.ideasPath),
        orderByChild('createdAt')
      );
      const snapshot = await get(ideasRef);

      const ideas = [];

      if (snapshot.exists()) {
        const data = snapshot.val();

        Object.entries(data).forEach(([key, value]) => {
          // Only include active ideas
          if (value.isActive) {
            ideas.push({
              id: key,
              ...value,
            });
          }
        });

        ideas.sort((a, b) => b.createdAt - a.createdAt);
      }

      return ideas;
    } catch (error) {
      console.error('❌ Failed to load ideas:', error);
      return [];
    }
  }

  /**
   * Get ideas by topic (one-time fetch)
   */
  async getIdeasByTopic(topicId) {
    try {
      console.log('🔍 Loading ideas for topic:', topicId);

      const ideasRef = query(
        ref(this.database, this.ideasPath),
        orderByChild('topicId'),
        equalTo(topicId)
      );
      const snapshot = await get(ideasRef);

      const ideas = [];

      if (snapshot.exists()) {
        const data = snapshot.val();

        Object.entries(data).forEach(([key, value]) => {
          // Only include active ideas
          if (value.isActive) {
            ideas.push({
              id: key,
              ...value,
            });
          }
        });

        // Sort by upvoteCount first, then by createdAt
        ideas.sort((a, b) => {
          if (b.upvoteCount !== a.upvoteCount) {
            return b.upvoteCount - a.upvoteCount;
          }
          return b.createdAt - a.createdAt;
        });
      }

      return ideas;
    } catch (error) {
      console.error('❌ Failed to load ideas:', error);
      return [];
    }
  }

  /**
   * Update an idea
   */
  async updateIdea(ideaId, updates) {
    try {
      const userId = this.getCurrentUserId();
      if (!userId) {
        throw new Error('No authenticated user');
      }

      console.log('📝 Updating idea:', ideaId);

      updates.updatedAt = Date.now();

      const ideaRef = ref(this.database, `${this.ideasPath}/${ideaId}`);
      await update(ideaRef, updates);

      console.log('✅ Idea updated');
      return true;
    } catch (error) {
      console.error('❌ Failed to update idea:', error);
      throw error;
    }
  }

  /**
   * Delete/deactivate an idea
   */
  async deleteIdea(ideaId) {
    try {
      const userId = this.getCurrentUserId();
      if (!userId) {
        throw new Error('No authenticated user');
      }

      console.log('🗑️ Deactivating idea:', ideaId);

      // Get the idea to find its topic
      const idea = await this.getIdea(ideaId);
      if (!idea) return false;

      const ideaRef = ref(this.database, `${this.ideasPath}/${ideaId}`);
      await update(ideaRef, {
        isActive: false,
        updatedAt: Date.now(),
      });

      // Decrement idea count in parent topic
      await TopicService.decrementIdeaCount(idea.topicId);

      console.log('✅ Idea deactivated');
      return true;
    } catch (error) {
      console.error('❌ Failed to deactivate idea:', error);
      throw error;
    }
  }

  /**
   * Increment upvote count
   */
  async incrementUpvoteCount(ideaId) {
    try {
      const idea = await this.getIdea(ideaId);
      if (!idea) return;

      await this.updateIdea(ideaId, {
        upvoteCount: (idea.upvoteCount || 0) + 1,
      });
    } catch (error) {
      console.error('❌ Failed to increment upvote count:', error);
    }
  }

  /**
   * Decrement upvote count
   */
  async decrementUpvoteCount(ideaId) {
    try {
      const idea = await this.getIdea(ideaId);
      if (!idea) return;

      const newCount = Math.max(0, (idea.upvoteCount || 0) - 1);
      await this.updateIdea(ideaId, {
        upvoteCount: newCount,
      });
    } catch (error) {
      console.error('❌ Failed to decrement upvote count:', error);
    }
  }

  /**
   * Increment comment count
   */
  async incrementCommentCount(ideaId) {
    try {
      const idea = await this.getIdea(ideaId);
      if (!idea) return;

      await this.updateIdea(ideaId, {
        commentCount: (idea.commentCount || 0) + 1,
      });
    } catch (error) {
      console.error('❌ Failed to increment comment count:', error);
    }
  }

  /**
   * Decrement comment count
   */
  async decrementCommentCount(ideaId) {
    try {
      const idea = await this.getIdea(ideaId);
      if (!idea) return;

      const newCount = Math.max(0, (idea.commentCount || 0) - 1);
      await this.updateIdea(ideaId, {
        commentCount: newCount,
      });
    } catch (error) {
      console.error('❌ Failed to decrement comment count:', error);
    }
  }
}

export default new IdeaService();
