// src/components/chat/VipChatRooms.jsx
import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { MessageSquare, Users, Crown, Lock, Clock } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { usePayment } from '../../contexts/PaymentContext';
import { getVipChatRooms } from '../../models/ChatRoom';
import VipAccessPrompt from '../vip/VipAccessPrompt';

/**
 * VIP Chat Rooms Component
 * 
 * Displays a list of VIP-only chat rooms and handles access control
 */
const VipChatRooms = ({ externalVipRooms = [] }) => {
  const navigate = useNavigate();
  const { currentUser } = useAuth();
  const { isPremium } = usePayment();
  
  const [vipRooms, setVipRooms] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [showVipPrompt, setShowVipPrompt] = useState(false);
  const [selectedRoom, setSelectedRoom] = useState(null);
  
  // Determine if user is VIP based on both old and new methods
  const isUserVIP = currentUser?.isVIP === true || isPremium === true;
  
  // Fetch VIP rooms
  useEffect(() => {
    const fetchVipRooms = async () => {
      try {
        setLoading(true);
        
        // If external VIP rooms are provided, use them
        if (externalVipRooms && externalVipRooms.length > 0) {
          setVipRooms(externalVipRooms);
          setLoading(false);
          return;
        }
        
        // Otherwise fetch from the database
        const rooms = await getVipChatRooms();
        setVipRooms(rooms);
        setLoading(false);
      } catch (err) {
        console.error('Error fetching VIP rooms:', err);
        setError('Failed to load VIP rooms');
        setLoading(false);
      }
    };
    
    fetchVipRooms();
  }, [externalVipRooms]);
  
  // Handle room click
  const handleRoomClick = (room) => {
    // If user is a VIP member, allow access
    if (isUserVIP) {
      navigate(`/room/${room.id}`);
      return;
    }
    
    // Otherwise, show the VIP upgrade prompt
    setSelectedRoom(room);
    setShowVipPrompt(true);
  };
  
  // Close VIP prompt
  const handleCloseVipPrompt = () => {
    setShowVipPrompt(false);
    setSelectedRoom(null);
  };
  
  // Format last activity time
  const formatLastActivity = (timestamp) => {
    if (!timestamp) return 'No activity';
    
    const now = new Date();
    const lastActivity = timestamp.toDate ? timestamp.toDate() : new Date(timestamp);
    const diffInMinutes = Math.floor((now - lastActivity) / (1000 * 60));
    
    if (diffInMinutes < 1) return 'Just now';
    if (diffInMinutes === 1) return '1 minute ago';
    if (diffInMinutes < 60) return `${diffInMinutes} minutes ago`;
    
    const diffInHours = Math.floor(diffInMinutes / 60);
    if (diffInHours === 1) return '1 hour ago';
    if (diffInHours < 24) return `${diffInHours} hours ago`;
    
    const diffInDays = Math.floor(diffInHours / 24);
    if (diffInDays === 1) return 'Yesterday';
    if (diffInDays < 7) return `${diffInDays} days ago`;
    
    return lastActivity.toLocaleDateString();
  };
  
  if (loading) {
    return (
      <div className="vip-rooms-loading">
        <div className="spinner"></div>
        <p>Loading VIP rooms...</p>
      </div>
    );
  }
  
  if (error) {
    return (
      <div className="vip-rooms-error">
        <p>{error}</p>
      </div>
    );
  }
  
  return (
    <div className="vip-chat-rooms">
      {/* VIP Access Prompt */}
      {showVipPrompt && (
        <VipAccessPrompt 
          onClose={handleCloseVipPrompt}
          targetRoomId={selectedRoom?.id}
          targetRoomName={selectedRoom?.name}
        />
      )}
      
      <div className="vip-rooms-header">
        <h2>
          <Crown size={18} className="vip-icon" />
          VIP Chat Rooms
        </h2>
        
        {isUserVIP ? (
          <div className="vip-badge">
            <Crown size={14} />
            <span>VIP Member</span>
          </div>
        ) : (
          <div className="vip-status">
            <Lock size={14} />
            <span>Restricted Access</span>
          </div>
        )}
      </div>
      
      <div className="vip-rooms-list">
        {vipRooms.length === 0 ? (
          <div className="no-vip-rooms">
            <p>No VIP chat rooms available</p>
          </div>
        ) : (
          vipRooms.map((room) => (
            <div
              key={room.id}
              className="vip-room-item"
              onClick={() => handleRoomClick(room)}
            >
              <div className="room-icon">
                <Crown size={16} className="vip-room-icon" />
              </div>
              
              <div className="room-info">
                <div className="room-name">{room.name}</div>
                
                {room.description && (
                  <div className="room-description">{room.description}</div>
                )}
                
                <div className="room-meta">
                  <div className="room-members">
                    <Users size={12} />
                    <span>{room.memberCount || 0}</span>
                  </div>
                  
                  {room.lastActivity && (
                    <div className="room-activity">
                      <Clock size={12} />
                      <span>{formatLastActivity(room.lastActivity)}</span>
                    </div>
                  )}
                </div>
              </div>
              
              {!isUserVIP && (
                <div className="room-locked">
                  <Lock size={16} />
                </div>
              )}
            </div>
          ))
        )}
      </div>
      
      {!isUserVIP && (
        <div className="vip-upgrade-banner">
          <div className="upgrade-message">
            <Crown size={18} />
            <span>Upgrade to VIP for exclusive chat access</span>
          </div>
          
          <button 
            className="upgrade-button"
            onClick={() => navigate('/premium-membership')}
          >
            Upgrade
          </button>
        </div>
      )}
      
      {/* Styles */}
      <style>{`
        .vip-chat-rooms {
          margin-top: 1.5rem;
          margin-bottom: 1rem;
          border: 1px solid #e5e7eb;
          border-radius: 8px;
          overflow: hidden;
        }
        
        .vip-rooms-header {
          background: linear-gradient(135deg, #6366f1, #4f46e5);
          color: white;
          padding: 0.75rem 1rem;
          display: flex;
          justify-content: space-between;
          align-items: center;
        }
        
        .vip-rooms-header h2 {
          margin: 0;
          font-size: 1rem;
          font-weight: 600;
          display: flex;
          align-items: center;
          gap: 0.5rem;
        }
        
        .vip-icon {
          color: #facc15;
        }
        
        .vip-badge {
          background-color: rgba(255, 255, 255, 0.2);
          display: flex;
          align-items: center;
          gap: 0.25rem;
          padding: 0.25rem 0.5rem;
          border-radius: 4px;
          font-size: 0.75rem;
        }
        
        .vip-status {
          background-color: rgba(0, 0, 0, 0.2);
          display: flex;
          align-items: center;
          gap: 0.25rem;
          padding: 0.25rem 0.5rem;
          border-radius: 4px;
          font-size: 0.75rem;
        }
        
        .vip-rooms-list {
          max-height: 400px;
          overflow-y: auto;
        }
        
        .vip-room-item {
          display: flex;
          align-items: center;
          padding: 1rem;
          border-bottom: 1px solid #f3f4f6;
          cursor: pointer;
          transition: background-color 0.2s;
          position: relative;
        }
        
        .vip-room-item:hover {
          background-color: #f9fafb;
        }
        
        .room-icon {
          margin-right: 0.75rem;
        }
        
        .vip-room-icon {
          color: #facc15;
        }
        
        .room-info {
          flex-grow: 1;
          min-width: 0;
        }
        
        .room-name {
          font-weight: 500;
          margin-bottom: 0.25rem;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
          color: #111827;
        }
        
        .room-description {
          font-size: 0.875rem;
          color: #6b7280;
          margin-bottom: 0.5rem;
          overflow: hidden;
          text-overflow: ellipsis;
          display: -webkit-box;
          -webkit-line-clamp: 2;
          -webkit-box-orient: vertical;
        }
        
        .room-meta {
          display: flex;
          gap: 0.75rem;
          font-size: 0.75rem;
          color: #6b7280;
        }
        
        .room-members,
        .room-activity {
          display: flex;
          align-items: center;
          gap: 0.25rem;
        }
        
        .room-locked {
          background-color: rgba(0, 0, 0, 0.05);
          width: 32px;
          height: 32px;
          border-radius: 50%;
          display: flex;
          align-items: center;
          justify-content: center;
          color: #6b7280;
        }
        
        .vip-upgrade-banner {
          background-color: #f3f4f6;
          padding: 0.75rem 1rem;
          display: flex;
          justify-content: space-between;
          align-items: center;
        }
        
        .upgrade-message {
          display: flex;
          align-items: center;
          gap: 0.5rem;
          font-size: 0.875rem;
          color: #4b5563;
        }
        
        .upgrade-button {
          background-color: #4f46e5;
          color: white;
          border: none;
          border-radius: 4px;
          padding: 0.25rem 0.75rem;
          font-size: 0.75rem;
          font-weight: 500;
          cursor: pointer;
          transition: background-color 0.2s;
        }
        
        .upgrade-button:hover {
          background-color: #4338ca;
        }
        
        .vip-rooms-loading,
        .vip-rooms-error,
        .no-vip-rooms {
          padding: 1.5rem;
          text-align: center;
          color: #6b7280;
        }
        
        .spinner {
          width: 1.5rem;
          height: 1.5rem;
          border: 2px solid rgba(79, 70, 229, 0.25);
          border-top-color: #4f46e5;
          border-radius: 50%;
          animation: spin 1s linear infinite;
          margin: 0 auto 0.5rem;
        }
        
        @keyframes spin {
          to {
            transform: rotate(360deg);
          }
        }
      `}</style>
    </div>
  );
};

export default VipChatRooms;