// src/pages/HostProfilePage.jsx
//
// Screen D: the show's home — who the host is, when they are next on, and
// everything they have already played. Replaces the old artist page's
// purple-gradient header with the shared indigo system.
//
// The archive tabs carry over the creator work that already lived here:
// Activity (streaming plans, releases, clips) and the media library.

import React, { useCallback, useEffect, useState } from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import {
  doc, getDoc, setDoc, deleteDoc, updateDoc, increment,
} from 'firebase/firestore';
import { db } from '../firebase';
import TalkStudioNav from '../components/layout/TalkStudioNav';
import { useAuth } from '../contexts/AuthContext';
import ActivityFeed from '../components/activity/ActivityFeed';
import ActivityComposer from '../components/activity/ActivityComposer';
import MediaLibrary from '../components/media/MediaLibrary';
import { tipService } from '../services/tipService';
import {
  listRoomsByHost,
  listReplays,
  getNextOccurrenceForHost,
  listUpcomingOccurrences,
  toggleRsvp,
  hasRsvp,
  downloadIcs,
  formatDayTime,
  formatDuration,
  cadenceLabel,
  occurrenceDate,
} from '../services/scheduledRoomsService';
import './DiscoverPage.css';
import './HostProfilePage.css';

const TIP_AMOUNT = 3;

const HostProfilePage = () => {
  const { artistId } = useParams();
  const { currentUser } = useAuth();
  const navigate = useNavigate();

  const hostId = artistId || currentUser?.uid;
  const isOwner = Boolean(currentUser && hostId === currentUser.uid);

  const [host, setHost] = useState(null);
  const [error, setError] = useState(null);
  const [tab, setTab] = useState('replays');
  const [replays, setReplays] = useState(null);
  const [shows, setShows] = useState([]);
  const [upcoming, setUpcoming] = useState([]);
  const [nextShow, setNextShow] = useState(null);
  const [going, setGoing] = useState(false);
  const [following, setFollowing] = useState(false);
  const [tipNote, setTipNote] = useState(null);
  const [tipping, setTipping] = useState(false);
  const [activityToken, setActivityToken] = useState(0);

  useEffect(() => {
    if (!hostId) {
      navigate('/login');
      return;
    }
    let cancelled = false;
    getDoc(doc(db, 'users', hostId))
      .then(snap => {
        if (cancelled) return;
        if (!snap.exists()) { setError('No host at this address.'); return; }
        setHost({ id: snap.id, ...snap.data() });
      })
      .catch(err => {
        console.warn('[HostProfile] load failed:', err.message);
        if (!cancelled) setError('Could not load this profile.');
      });
    return () => { cancelled = true; };
  }, [hostId, navigate]);

  useEffect(() => {
    if (!hostId) return;
    listReplays({ hostId, max: 24 }).then(setReplays).catch(() => setReplays([]));
    listRoomsByHost(hostId).then(setShows).catch(() => setShows([]));
    getNextOccurrenceForHost(hostId).then(setNextShow).catch(() => setNextShow(null));
    listUpcomingOccurrences({ window: 'week', max: 100 })
      .then(rows => setUpcoming(rows.filter(o => o.hostId === hostId)))
      .catch(() => setUpcoming([]));
  }, [hostId]);

  useEffect(() => {
    if (!currentUser || !nextShow) { setGoing(false); return; }
    hasRsvp(currentUser.uid, nextShow.id).then(setGoing).catch(() => setGoing(false));
  }, [currentUser, nextShow]);

  useEffect(() => {
    if (!currentUser || !hostId || isOwner) { setFollowing(false); return; }
    getDoc(doc(db, 'follows', `${currentUser.uid}_${hostId}`))
      .then(snap => setFollowing(snap.exists()))
      .catch(() => setFollowing(false));
  }, [currentUser, hostId, isOwner]);

  const requireAuth = useCallback(() => {
    if (currentUser) return true;
    navigate(`/login?next=${encodeURIComponent(`/artist/${hostId}`)}`);
    return false;
  }, [currentUser, hostId, navigate]);

  const handleFollow = async () => {
    if (!requireAuth()) return;
    const next = !following;
    setFollowing(next);
    try {
      const ref = doc(db, 'follows', `${currentUser.uid}_${hostId}`);
      if (next) {
        await setDoc(ref, { followerId: currentUser.uid, followingId: hostId, createdAt: new Date() });
      } else {
        await deleteDoc(ref);
      }
      await updateDoc(doc(db, 'users', hostId), { followerCount: increment(next ? 1 : -1) }).catch(() => {});
      setHost(prev => (prev
        ? { ...prev, followerCount: Math.max(0, (prev.followerCount || 0) + (next ? 1 : -1)) }
        : prev));
    } catch (err) {
      setFollowing(!next);
      console.warn('[HostProfile] follow failed:', err.message);
    }
  };

  const handleRsvp = async () => {
    if (!requireAuth() || !nextShow) return;
    const next = !going;
    setGoing(next);
    try {
      await toggleRsvp({ user: currentUser, occurrence: nextShow });
    } catch (err) {
      setGoing(!next);
      console.warn('[HostProfile] RSVP failed:', err.message);
    }
  };

  const handleTip = async () => {
    if (!requireAuth()) return;
    setTipping(true);
    setTipNote(null);
    try {
      const result = await tipService.processTip({
        eventId: nextShow?.id || hostId,
        creatorId: hostId,
        amount: TIP_AMOUNT,
        tipperId: currentUser.uid,
      });
      setTipNote(result.success ? `Tipped €${TIP_AMOUNT} — thanks!` : (result.message || 'Tip failed'));
    } catch (err) {
      setTipNote(err.message || 'Could not send that tip');
    } finally {
      setTipping(false);
    }
  };

  if (error) {
    return (
      <div className="ts-app">
        <TalkStudioNav active="discover" />
        <div className="ts-page"><div className="ts-empty">{error} <Link to="/">Back to Discover</Link></div></div>
      </div>
    );
  }

  if (!host) {
    return (
      <div className="ts-app">
        <TalkStudioNav active="discover" />
        <div className="ts-page"><div className="ts-skeleton host-identity-skeleton" /></div>
      </div>
    );
  }

  const name = host.displayName || host.username || 'Host';
  const genres = host.genres && host.genres.length
    ? host.genres
    : (host.genre ? host.genre.split(',').map(g => g.trim()).filter(Boolean) : []);
  const metaLine = [
    host.location,
    genres.length ? genres.join(' / ') : null,
    `${host.followerCount || 0} followers`,
  ].filter(Boolean).join(' · ');

  const tabs = [
    { id: 'replays', label: `Replays (${replays ? replays.length : 0})` },
    { id: 'schedule', label: 'Schedule' },
    { id: 'activity', label: 'Activity' },
    ...(isOwner ? [{ id: 'media', label: 'Clips & pictures' }] : []),
    { id: 'about', label: 'About' },
  ];

  return (
    <div className="ts-app host-profile">
      <TalkStudioNav active="discover" />

      <div className="ts-page host-page">
        {/* ---------------- identity ---------------- */}
        <section className="host-identity">
          <div
            className="host-avatar"
            style={host.photoURL ? { backgroundImage: `url(${host.photoURL})` } : undefined}
          >
            {!host.photoURL && name.charAt(0).toUpperCase()}
          </div>

          <div className="host-identity-body">
            <h1 className="host-name">{name}</h1>
            <div className="host-meta">{metaLine}</div>
            {host.tagline && <div className="host-tagline">{host.tagline}</div>}
            <p className="host-bio">{host.bio || 'This host hasn\'t written a bio yet.'}</p>
            {genres.length > 0 && (
              <div className="host-chips">
                {genres.map(genre => <span key={genre} className="ts-chip">{genre}</span>)}
              </div>
            )}
            {host.streamSchedule && (
              <div className="host-usual">Usually live {host.streamSchedule}</div>
            )}
          </div>

          <div className="host-identity-actions">
            {isOwner ? (
              <>
                <Link to="/schedule" className="ts-btn ts-btn--primary ts-btn--md">Schedule a room</Link>
                <Link to="/artist-edit-profile" className="ts-btn ts-btn--neutral ts-btn--md">Edit profile</Link>
                <Link to={`/artist-legacy/${hostId}`} className="ts-btn ts-btn--neutral ts-btn--md">
                  Analytics
                </Link>
              </>
            ) : (
              <>
                <button
                  type="button"
                  className={`ts-btn ts-btn--md ${following ? 'ts-btn--going' : 'ts-btn--primary'}`}
                  onClick={handleFollow}
                >
                  {following ? 'Following' : 'Follow'}
                </button>
                <button
                  type="button"
                  className="ts-btn ts-btn--tip ts-btn--md"
                  onClick={handleTip}
                  disabled={tipping}
                >
                  {tipping ? 'Sending…' : 'Tip'}
                </button>
              </>
            )}
          </div>
        </section>

        {tipNote && <div className="host-tip-note">{tipNote}</div>}

        {/* ---------------- next show ---------------- */}
        {nextShow ? (
          <section className="host-next">
            <div className="host-next-body">
              <div className="ts-mono host-next-eyebrow">
                {nextShow.state === 'live' ? 'ON AIR NOW' : 'NEXT SHOW'}
              </div>
              <div className="host-next-title">
                <Link to={`/r/${nextShow.slug}`}>{nextShow.title}</Link>
                {nextShow.state === 'live' ? '' : ` — ${formatDayTime(nextShow.startAt)}`}
              </div>
              <div className="host-next-sub">
                {formatDuration(nextShow.durationMin)} · {nextShow.rsvpCount || 0} going ·{' '}
                <span className="ts-mono">talkstudio.space/r/{nextShow.slug}</span>
              </div>
            </div>
            <div className="host-next-actions">
              {nextShow.state === 'live' ? (
                <Link to={`/r/${nextShow.slug}`} className="ts-btn ts-btn--live ts-btn--md">Listen now</Link>
              ) : (
                <button
                  type="button"
                  className={`ts-btn ts-btn--md ${going ? 'ts-btn--going' : 'ts-btn--primary'}`}
                  onClick={handleRsvp}
                >
                  {going ? 'Going ✓' : 'Notify me'}
                </button>
              )}
              <button
                type="button"
                className="ts-btn ts-btn--neutral ts-btn--md"
                onClick={() => downloadIcs(nextShow)}
              >
                Add to calendar
              </button>
            </div>
          </section>
        ) : isOwner && (
          <section className="host-next host-next--empty">
            <div className="host-next-body">
              <div className="ts-mono host-next-eyebrow">NO SHOW SCHEDULED</div>
              <div className="host-next-sub">
                Set one up and it keeps the same link every week.
              </div>
            </div>
            <div className="host-next-actions">
              <Link to="/schedule" className="ts-btn ts-btn--primary ts-btn--md">Schedule a room</Link>
            </div>
          </section>
        )}

        {/* ---------------- archive ---------------- */}
        <section className="host-archive">
          <div className="host-tabs">
            {tabs.map(item => (
              <button
                key={item.id}
                type="button"
                className={`host-tab ${tab === item.id ? 'active' : ''}`}
                onClick={() => setTab(item.id)}
              >
                {item.label}
              </button>
            ))}
            <span className="host-archive-note">
              {host.isPremium
                ? 'Archive kept for premium hosts'
                : 'Archive kept for premium hosts · 30 days on the free tier'}
            </span>
          </div>

          {tab === 'replays' && (
            replays && replays.length === 0 ? (
              <div className="ts-empty">No replays yet.</div>
            ) : (
              <div className="discover-replays">
                {(replays || [null, null, null, null]).map((replay, i) => (
                  replay ? (
                    <Link
                      key={replay.id}
                      to={`/r/${replay.slug}/replay/${replay.id}`}
                      className="ts-card ts-card--sm discover-replay"
                    >
                      <div
                        className="ts-art discover-replay-art host-replay-art"
                        style={replay.artworkUrl ? { backgroundImage: `url(${replay.artworkUrl})` } : undefined}
                      >
                        <span className="ts-mono discover-replay-len">
                          {formatDuration(replay.durationMin)}
                        </span>
                        <span className="discover-replay-plays">▶ {replay.playCount || 0}</span>
                      </div>
                      <div className="discover-replay-caption">
                        <div className="discover-replay-title">{replay.title}</div>
                        <div className="discover-replay-sub">
                          {name} ·{' '}
                          {occurrenceDate(replay.startAt)?.toLocaleDateString([], { month: 'short', day: 'numeric' })}
                        </div>
                      </div>
                    </Link>
                  ) : (
                    // eslint-disable-next-line react/no-array-index-key
                    <div key={`skeleton-${i}`} className="ts-skeleton discover-replay-skeleton" />
                  )
                ))}
              </div>
            )
          )}

          {tab === 'schedule' && (
            upcoming.length === 0 ? (
              <div className="ts-empty">
                Nothing on the schedule this week.
                {shows.length > 0 && ' Their shows run on a longer cadence — check back.'}
              </div>
            ) : (
              <div className="ts-card ts-card--quiet discover-table">
                {upcoming.map(occurrence => (
                  <div key={occurrence.id} className="discover-table-row host-schedule-row">
                    <div className="ts-mono discover-cell-time">{formatDayTime(occurrence.startAt)}</div>
                    <div>
                      <Link to={`/r/${occurrence.slug}`} className="discover-cell-title">
                        {occurrence.title}
                      </Link>
                      <div className="discover-cell-sub">
                        {cadenceLabel(occurrence.repeat)} · {formatDuration(occurrence.durationMin)} ·{' '}
                        {occurrence.rsvpCount || 0} going
                      </div>
                    </div>
                    <div className="discover-cell-actions">
                      <button
                        type="button"
                        className="ts-btn ts-btn--sm ts-btn--neutral"
                        onClick={() => downloadIcs(occurrence)}
                      >
                        Calendar
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )
          )}

          {tab === 'activity' && (
            <div className="host-activity">
              {isOwner && <ActivityComposer onPosted={() => setActivityToken(t => t + 1)} />}
              <ActivityFeed
                userId={hostId}
                isOwner={isOwner}
                reloadToken={activityToken}
                emptyMessage={isOwner ? null : `${name} hasn't posted any activity yet.`}
              />
            </div>
          )}

          {tab === 'media' && isOwner && (
            <div className="host-media">
              <p className="host-media-hint">
                Clips and pictures you upload once — attach them to an activity post,
                use them as show art, or as the visuals behind a set.
              </p>
              <MediaLibrary ownerId={hostId} />
            </div>
          )}

          {tab === 'about' && (
            <div className="host-about">
              <p className="host-bio">{host.bio || 'No bio yet.'}</p>
              {host.websiteUrl && (
                <p><a href={host.websiteUrl} target="_blank" rel="noopener noreferrer">{host.websiteUrl}</a></p>
              )}
              <div className="host-links">
                {Object.entries(host.socialLinks || {})
                  .filter(([, handle]) => handle)
                  .map(([platform, handle]) => (
                    <span key={platform} className="ts-chip ts-chip--neutral">
                      {platform} · {handle}
                    </span>
                  ))}
              </div>
              {shows.length > 0 && (
                <div className="host-shows-list">
                  <div className="ts-label">Shows</div>
                  {shows.map(show => (
                    <div key={show.id} className="host-show-row">
                      <Link to={`/r/${show.slug}`}>{show.title}</Link>
                      <span className="discover-cell-sub">
                        {cadenceLabel(show.repeat)} · {formatDuration(show.durationMin)}
                      </span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </section>
      </div>
    </div>
  );
};

export default HostProfilePage;
