// src/services/walletService.js
import { 
  doc, 
  getDoc, 
  setDoc, 
  updateDoc, 
  collection, 
  addDoc, 
  query, 
  where, 
  orderBy, 
  onSnapshot,
  serverTimestamp,
  runTransaction,
  increment 
} from 'firebase/firestore';

// Import the initialized Firestore instance from your Firebase config
import { db } from '../firebase.js';

/**
 * Wallet Service - Manages user tip wallets and transactions
 */
export class WalletService {
  
  /**
   * Get user's wallet information
   */
  static async getUserWallet(userId) {
    try {
      const walletRef = doc(db, 'wallets', userId);
      const walletDoc = await getDoc(walletRef);
      
      if (walletDoc.exists()) {
        return {
          id: walletDoc.id,
          ...walletDoc.data()
        };
      } else {
        // Create initial wallet if it doesn't exist
        const initialWallet = {
          userId,
          balance: 0,
          totalLoaded: 0,
          totalSpent: 0,
          createdAt: serverTimestamp(),
          updatedAt: serverTimestamp()
        };
        
        await setDoc(walletRef, initialWallet);
        return {
          id: userId,
          ...initialWallet,
          createdAt: new Date(),
          updatedAt: new Date()
        };
      }
    } catch (error) {
      console.error('Error getting user wallet:', error);
      throw error;
    }
  }

  /**
   * Load money into user's wallet
   */
  static async loadWallet(userId, amount, paymentMethodId, paymentIntentId = null) {
    try {
      if (amount <= 0) {
        throw new Error('Load amount must be positive');
      }

      return await runTransaction(db, async (transaction) => {
        const walletRef = doc(db, 'wallets', userId);
        const walletDoc = await transaction.get(walletRef);
        
        let currentBalance = 0;
        let totalLoaded = 0;
        
        if (walletDoc.exists()) {
          const walletData = walletDoc.data();
          currentBalance = walletData.balance || 0;
          totalLoaded = walletData.totalLoaded || 0;
        }
        
        const newBalance = currentBalance + amount;
        const newTotalLoaded = totalLoaded + amount;
        
        // Update wallet
        transaction.set(walletRef, {
          userId,
          balance: newBalance,
          totalLoaded: newTotalLoaded,
          totalSpent: walletDoc.exists() ? (walletDoc.data().totalSpent || 0) : 0,
          updatedAt: serverTimestamp(),
          createdAt: walletDoc.exists() ? walletDoc.data().createdAt : serverTimestamp()
        }, { merge: true });
        
        // Create transaction record
        const transactionRef = doc(collection(db, 'walletTransactions'));
        transaction.set(transactionRef, {
          userId,
          type: 'load',
          amount,
          description: `Wallet top-up: $${amount.toFixed(2)}`,
          balanceBefore: currentBalance,
          balanceAfter: newBalance,
          paymentMethodId,
          paymentIntentId,
          status: 'completed',
          createdAt: serverTimestamp()
        });
        
        return {
          transactionId: transactionRef.id,
          newBalance,
          amount
        };
      });
    } catch (error) {
      console.error('Error loading wallet:', error);
      throw error;
    }
  }

  /**
   * Process tip with revenue splits
   */
  static async processTipWithSplits(senderId, recipientId, amount, tipMessage = '', streamId = null, eventId = null, venueId = null) {
    try {
      if (amount <= 0) {
        throw new Error('Tip amount must be positive');
      }

      return await runTransaction(db, async (transaction) => {
        // === PHASE 1: ALL READS FIRST ===
        
        // Get tip settings
        const tipSettingsRef = doc(db, 'admin', 'tipSettings');
        const tipSettingsDoc = await transaction.get(tipSettingsRef);
        
        // Get venue info if specified
        let venuesDoc = null;
        if (venueId) {
          const venuesRef = doc(db, 'admin', 'venues');
          venuesDoc = await transaction.get(venuesRef);
        }
        
        // Get sender wallet
        const senderWalletRef = doc(db, 'wallets', senderId);
        const senderWalletDoc = await transaction.get(senderWalletRef);
        
        // Get artist wallet
        const artistWalletRef = doc(db, 'wallets', recipientId);
        const artistWalletDoc = await transaction.get(artistWalletRef);
        
        // Get tip statistics
        const tipStatsRef = doc(db, 'admin', 'tipStats');
        const tipStatsDoc = await transaction.get(tipStatsRef);
        
        // === PHASE 2: PROCESS DATA ===
        
        const tipSettings = tipSettingsDoc.exists() ? tipSettingsDoc.data() : {
          defaultSplits: { artist: 50, platform: 30, venue: 20 },
          enabled: true,
          minimumTip: 1.00,
          maximumTip: 500.00
        };

        if (!tipSettings.enabled) {
          throw new Error('Tipping is currently disabled');
        }

        if (amount < tipSettings.minimumTip) {
          throw new Error(`Minimum tip amount is ${tipSettings.minimumTip.toFixed(2)}`);
        }

        if (amount > tipSettings.maximumTip) {
          throw new Error(`Maximum tip amount is ${tipSettings.maximumTip.toFixed(2)}`);
        }

        // Process venue info
        let venueInfo = null;
        if (venueId && venuesDoc && venuesDoc.exists()) {
          const venues = venuesDoc.data().venues || [];
          venueInfo = venues.find(v => v.id === venueId);
        }

        // Calculate splits
        const splits = {
          artist: (tipSettings.defaultSplits.artist / 100) * amount,
          platform: (tipSettings.defaultSplits.platform / 100) * amount,
          venue: venueInfo ? ((venueInfo.defaultSplit || tipSettings.defaultSplits.venue) / 100) * amount : 0
        };

        // Ensure splits add up to the total (handle rounding)
        const totalSplits = splits.artist + splits.platform + splits.venue;
        if (Math.abs(totalSplits - amount) > 0.01) {
          const difference = amount - totalSplits;
          splits.artist += difference; // Give any rounding difference to the artist
        }

        // Validate sender wallet
        if (!senderWalletDoc.exists()) {
          throw new Error('Sender wallet not found');
        }
        
        const senderWalletData = senderWalletDoc.data();
        const senderCurrentBalance = senderWalletData.balance || 0;
        
        if (senderCurrentBalance < amount) {
          throw new Error('Insufficient wallet balance');
        }
        
        const senderNewBalance = senderCurrentBalance - amount;
        const senderNewTotalSpent = (senderWalletData.totalSpent || 0) + amount;
        
        // Prepare artist wallet data
        let artistWalletData = null;
        let artistNewBalance = 0;
        let artistBalanceBefore = 0;
        
        if (artistWalletDoc.exists()) {
          artistWalletData = artistWalletDoc.data();
          artistBalanceBefore = artistWalletData.balance || 0;
          artistNewBalance = artistBalanceBefore + splits.artist;
        } else {
          artistBalanceBefore = 0;
          artistNewBalance = splits.artist;
        }
        
        // Prepare tip statistics
        const currentStats = tipStatsDoc.exists() ? tipStatsDoc.data() : {
          totalTips: 0,
          totalVolume: 0,
          platformRevenue: 0,
          artistRevenue: 0,
          venueRevenue: 0,
          todayTips: 0,
          todayVolume: 0
        };

        const today = new Date().toDateString();
        const isToday = tipStatsDoc.exists() && 
          tipStatsDoc.data().lastUpdated?.toDate?.()?.toDateString() === today;
        
        // === PHASE 3: ALL WRITES ===
        
        // Update sender wallet
        transaction.update(senderWalletRef, {
          balance: senderNewBalance,
          totalSpent: senderNewTotalSpent,
          updatedAt: serverTimestamp()
        });
        
        // Create sender wallet transaction
        const senderTransactionRef = doc(collection(db, 'walletTransactions'));
        transaction.set(senderTransactionRef, {
          userId: senderId,
          type: 'spend',
          amount: amount,
          description: `Tip sent: ${amount.toFixed(2)}`,
          balanceBefore: senderCurrentBalance,
          balanceAfter: senderNewBalance,
          recipientId: recipientId,
          streamId,
          eventId,
          venueId,
          tipMessage,
          splits: splits,
          status: 'completed',
          createdAt: serverTimestamp()
        });

        // Process artist payment
        if (splits.artist > 0) {
          if (artistWalletDoc.exists()) {
            transaction.update(artistWalletRef, {
              balance: artistNewBalance,
              totalReceived: (artistWalletData.totalReceived || 0) + splits.artist,
              updatedAt: serverTimestamp()
            });
          } else {
            // Create initial artist wallet
            transaction.set(artistWalletRef, {
              userId: recipientId,
              balance: splits.artist,
              totalReceived: splits.artist,
              totalLoaded: 0,
              totalSpent: 0,
              createdAt: serverTimestamp(),
              updatedAt: serverTimestamp()
            });
          }
          
          // Create artist wallet transaction
          const artistTransactionRef = doc(collection(db, 'walletTransactions'));
          transaction.set(artistTransactionRef, {
            userId: recipientId,
            type: 'tip_received',
            amount: splits.artist,
            description: `Tip received: ${splits.artist.toFixed(2)} (${((splits.artist/amount)*100).toFixed(1)}%)`,
            balanceBefore: artistBalanceBefore,
            balanceAfter: artistNewBalance,
            senderId: senderId,
            streamId,
            eventId,
            venueId,
            originalAmount: amount,
            status: 'completed',
            createdAt: serverTimestamp()
          });
        }

        // Create revenue records for platform and venue
        if (splits.platform > 0) {
          const platformRevenueRef = doc(collection(db, 'platformRevenue'));
          transaction.set(platformRevenueRef, {
            type: 'tip_commission',
            amount: splits.platform,
            percentage: tipSettings.defaultSplits.platform,
            originalAmount: amount,
            senderId: senderId,
            recipientId: recipientId,
            streamId,
            eventId,
            venueId,
            createdAt: serverTimestamp()
          });
        }

        if (splits.venue > 0 && venueInfo) {
          const venueRevenueRef = doc(collection(db, 'venueRevenue'));
          transaction.set(venueRevenueRef, {
            venueId: venueId,
            venueName: venueInfo.name,
            type: 'tip_commission',
            amount: splits.venue,
            percentage: venueInfo.defaultSplit || tipSettings.defaultSplits.venue,
            originalAmount: amount,
            senderId: senderId,
            recipientId: recipientId,
            streamId,
            eventId,
            createdAt: serverTimestamp()
          });
        }
        
        // Create tip record
        const tipRef = doc(collection(db, 'tips'));
        transaction.set(tipRef, {
          senderId: senderId,
          recipientId: recipientId,
          amount: amount,
          message: tipMessage,
          streamId,
          eventId,
          venueId,
          splits: splits,
          paymentMethod: 'wallet',
          walletTransactionId: senderTransactionRef.id,
          status: 'completed',
          createdAt: serverTimestamp()
        });

        // Update tip statistics
        transaction.set(tipStatsRef, {
          totalTips: currentStats.totalTips + 1,
          totalVolume: currentStats.totalVolume + amount,
          platformRevenue: currentStats.platformRevenue + splits.platform,
          artistRevenue: currentStats.artistRevenue + splits.artist,
          venueRevenue: currentStats.venueRevenue + splits.venue,
          todayTips: isToday ? currentStats.todayTips + 1 : 1,
          todayVolume: isToday ? currentStats.todayVolume + amount : amount,
          lastUpdated: serverTimestamp()
        });
        
        return {
          tipId: tipRef.id,
          walletTransactionId: senderTransactionRef.id,
          newBalance: senderNewBalance,
          amount: amount,
          splits: splits,
          venueInfo: venueInfo
        };
      });
    } catch (error) {
      console.error('Error processing tip with splits:', error);
      throw error;
    }
  }

  /**
   * Get wallet transaction history
   */
  static getWalletTransactions(userId, callback) {
    try {
      const transactionsRef = collection(db, 'walletTransactions');
      const q = query(
        transactionsRef,
        where('userId', '==', userId),
        orderBy('createdAt', 'desc')
      );

      return onSnapshot(
        q,
        (snapshot) => {
          callback(snapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data(),
            createdAt: doc.data().createdAt?.toDate() || new Date()
          })));
        },
        (error) => {
          console.error('Error getting wallet transactions:', error);
          callback([]);
        }
      );
    } catch (error) {
      console.error('Error getting wallet transactions:', error);
      throw error;
    }
  }

  /**
   * Get tips sent by user
   */
  static getUserTipsSent(userId, callback) {
    try {
      const tipsRef = collection(db, 'tips');
      const q = query(
        tipsRef,
        where('senderId', '==', userId),
        orderBy('createdAt', 'desc')
      );

      return onSnapshot(
        q,
        (snapshot) => {
          callback(snapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data(),
            createdAt: doc.data().createdAt?.toDate() || new Date()
          })));
        },
        (error) => {
          console.error('Error getting tips sent:', error);
          callback([]);
        }
      );
    } catch (error) {
      console.error('Error getting tips sent:', error);
      throw error;
    }
  }

  /**
   * Get tips received by user
   */
  static getUserTipsReceived(userId, callback) {
    try {
      const tipsRef = collection(db, 'tips');
      const q = query(
        tipsRef,
        where('recipientId', '==', userId),
        orderBy('createdAt', 'desc')
      );

      return onSnapshot(
        q,
        (snapshot) => {
          callback(snapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data(),
            createdAt: doc.data().createdAt?.toDate() || new Date()
          })));
        },
        (error) => {
          console.error('Error getting tips received:', error);
          callback([]);
        }
      );
    } catch (error) {
      console.error('Error getting tips received:', error);
      throw error;
    }
  }

  /**
   * Get wallet balance in real-time
   */
  static subscribeToWallet(userId, callback) {
    try {
      const walletRef = doc(db, 'wallets', userId);
      
      return onSnapshot(
        walletRef,
        (doc) => {
          if (doc.exists()) {
            callback({
              id: doc.id,
              ...doc.data(),
              createdAt: doc.data().createdAt?.toDate() || new Date(),
              updatedAt: doc.data().updatedAt?.toDate() || new Date()
            });
          } else {
            // Initialize wallet if it doesn't exist
            this.getUserWallet(userId)
              .then(callback)
              .catch((error) => {
                console.error('Error initializing wallet:', error);
                callback(null);
              });
          }
        },
        (error) => {
          // Always resolve the subscriber, or callers wait on a wallet forever
          console.error('Error subscribing to wallet:', error);
          callback(null);
        }
      );
    } catch (error) {
      console.error('Error subscribing to wallet:', error);
      throw error;
    }
  }

  /**
   * Validate wallet transaction
   */
  static async validateTransaction(transactionId) {
    try {
      const transactionRef = doc(db, 'walletTransactions', transactionId);
      const transactionDoc = await getDoc(transactionRef);
      
      if (!transactionDoc.exists()) {
        throw new Error('Transaction not found');
      }
      
      return {
        id: transactionDoc.id,
        ...transactionDoc.data(),
        createdAt: transactionDoc.data().createdAt?.toDate() || new Date()
      };
    } catch (error) {
      console.error('Error validating transaction:', error);
      throw error;
    }
  }

  /**
   * Get wallet statistics
   */
  static async getWalletStats(userId) {
    try {
      const wallet = await this.getUserWallet(userId);
      
      // Get tips sent count
      const tipsSentRef = collection(db, 'tips');
      const tipsSentQuery = query(tipsSentRef, where('senderId', '==', userId));
      
      // Get tips received count (for artists)
      const tipsReceivedRef = collection(db, 'tips');
      const tipsReceivedQuery = query(tipsReceivedRef, where('recipientId', '==', userId));
      
      // Note: In a production app, you might want to cache these stats
      // For now, we'll return basic wallet info
      return {
        balance: wallet.balance || 0,
        totalLoaded: wallet.totalLoaded || 0,
        totalSpent: wallet.totalSpent || 0,
        walletAge: wallet.createdAt ? Math.floor((Date.now() - wallet.createdAt.getTime()) / (1000 * 60 * 60 * 24)) : 0
      };
    } catch (error) {
      console.error('Error getting wallet stats:', error);
      throw error;
    }
  }
}

export default WalletService;