// src/utils/roomSortingUtils.js
// Room sorting utilities for consistent room ordering across the app

/**
 * Define the custom sort order for room types
 * Lower number = higher priority (appears first)
 */
export const ROOM_TYPE_PRIORITY = {
  'public': 1,
  'registered': 2, 
  'private': 3,
  'vip': 4,
  'event': 5
};

/**
 * Define the custom sort order for room filter buttons
 * This ensures the filter buttons appear in the correct order
 */
export const ROOM_FILTER_ORDER = [
  'all',
  'public', 
  'registered',
  'private',
  'vip'
];

/**
 * Sort rooms by type priority, then by activity, then by name
 * @param {Array} rooms - Array of room objects
 * @returns {Array} - Sorted array of rooms
 */
export const sortRoomsByTypeAndActivity = (rooms) => {
  return rooms.sort((a, b) => {
    // First, sort by room type priority
    const aTypePriority = ROOM_TYPE_PRIORITY[a.type || 'public'] || 999;
    const bTypePriority = ROOM_TYPE_PRIORITY[b.type || 'public'] || 999;
    
    if (aTypePriority !== bTypePriority) {
      return aTypePriority - bTypePriority;
    }
    
    // If same type, sort by activity (most recent first)
    const aActivity = a.lastActivityTimestamp || a.createdAt || 0;
    const bActivity = b.lastActivityTimestamp || b.createdAt || 0;
    
    if (aActivity !== bActivity) {
      return bActivity - aActivity; // Descending order (most recent first)
    }
    
    // If same activity, sort by name alphabetically
    const aName = (a.name || '').toLowerCase();
    const bName = (b.name || '').toLowerCase();
    
    return aName.localeCompare(bName);
  });
};

/**
 * Sort rooms within a specific type by activity and name
 * @param {Array} rooms - Array of room objects (should all be the same type)
 * @returns {Array} - Sorted array of rooms
 */
export const sortRoomsByActivity = (rooms) => {
  return rooms.sort((a, b) => {
    // Sort by activity (most recent first)
    const aActivity = a.lastActivityTimestamp || a.createdAt || 0;
    const bActivity = b.lastActivityTimestamp || b.createdAt || 0;
    
    if (aActivity !== bActivity) {
      return bActivity - aActivity; // Descending order (most recent first)
    }
    
    // If same activity, sort by name alphabetically
    const aName = (a.name || '').toLowerCase();
    const bName = (b.name || '').toLowerCase();
    
    return aName.localeCompare(bName);
  });
};

/**
 * Get display name for room type
 * @param {string} roomType - Room type identifier
 * @returns {string} - Human readable room type name
 */
export const getRoomTypeDisplayName = (roomType) => {
  const displayNames = {
    'public': 'Public',
    'registered': 'Registered',
    'private': 'Private', 
    'vip': 'V.I.P.',
    'event': 'Event'
  };
  
  return displayNames[roomType] || 'Public';
};

/**
 * Get room type icon component name
 * @param {string} roomType - Room type identifier
 * @returns {string} - Icon component name for lucide-react
 */
export const getRoomTypeIcon = (roomType) => {
  const icons = {
    'public': 'Globe',
    'registered': 'Users',
    'private': 'Lock',
    'vip': 'Star',
    'event': 'Calendar'
  };
  
  return icons[roomType] || 'Globe';
};

/**
 * Check if user can access a room type
 * @param {string} roomType - Room type to check
 * @param {Object} currentUser - Current user object
 * @param {boolean} isPremium - Whether user has premium membership
 * @returns {boolean} - Whether user can access this room type
 */
export const canUserAccessRoomType = (roomType, currentUser, isPremium = false) => {
  switch (roomType) {
    case 'public':
      return true; // Everyone can access public rooms
      
    case 'registered':
      return currentUser && !currentUser.isAnonymous;
      
    case 'private':
      return currentUser && !currentUser.isAnonymous; // Can attempt to join with access code
      
    case 'vip':
      return currentUser && !currentUser.isAnonymous && isPremium;
      
    case 'event':
      return true; // Events are generally public but may have restrictions
      
    default:
      return true; // Default to accessible
  }
};
