import { useState, useEffect, useCallback } from 'react';
import { AudioProfileServiceHybrid } from '../services/AudioProfileServiceHybrid';
import { useAudioDetectionFixed } from './useAudioDetectionFixed';

export const useAudioProfileHybrid = (firebaseApp = null) => {
  const [service, setService] = useState(null);
  const [isReady, setIsReady] = useState(false);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);
  const [error, setError] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  
  const audioDetection = useAudioDetectionFixed();
  
  // Initialize service
  useEffect(() => {
    // Use the existing Firebase configuration
    const audioProfileService = new AudioProfileServiceHybrid(firebaseApp);
    setService(audioProfileService);
    
    // Monitor auth state
    const unsubscribe = audioProfileService.auth.onAuthStateChanged((user) => {
      setCurrentUser(user);
      setIsAuthenticated(!!user);
      setIsReady(true);
    });
    
    return () => {
      unsubscribe();
      audioProfileService.destroy();
    };
  }, [firebaseApp]);
  
  // Create audio profile (saves to both Firestore and Realtime Database)
  const createProfile = useCallback(async (audioBlob, metadata = {}) => {
    if (!service || !audioDetection.isReady) {
      throw new Error('Service not ready');
    }
    
    setIsLoading(true);
    setError(null);
    
    try {
      // Create audio fingerprint
      console.log('Generating fingerprint...');
      const audioContext = new (window.AudioContext || window.webkitAudioContext)();
      const fingerprint = await audioDetection.processAudioData(audioBlob, audioContext);
      audioContext.close();
      
      // Create profile in both Firebase services
      console.log('Creating profile in Firebase...');
      const profile = await service.createAudioProfile(audioBlob, fingerprint, metadata);
      
      console.log('Profile created successfully:', profile.id, 'Room:', profile.roomId);
      return profile;
    } catch (err) {
      console.error('Error creating profile:', err);
      setError(err.message);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, [service, audioDetection]);
  
  // Create just an audio room (Realtime Database only)
  const createRoom = useCallback(async (metadata = {}) => {
    if (!service) {
      throw new Error('Service not ready');
    }
    
    setIsLoading(true);
    setError(null);
    
    try {
      const room = await service.createAudioRoom(metadata);
      console.log('Room created successfully:', room.roomId);
      return room;
    } catch (err) {
      console.error('Error creating room:', err);
      setError(err.message);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, [service]);
  
  // Get profile from Firestore
  const getProfile = useCallback(async (profileId) => {
    if (!service) {
      throw new Error('Service not ready');
    }
    
    setIsLoading(true);
    setError(null);
    
    try {
      const profile = await service.getAudioProfile(profileId);
      return profile;
    } catch (err) {
      console.error('Error getting profile:', err);
      setError(err.message);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, [service]);
  
  // Get room data from Realtime Database
  const getRoom = useCallback(async (roomId) => {
    if (!service) {
      throw new Error('Service not ready');
    }
    
    setIsLoading(true);
    setError(null);
    
    try {
      const room = await service.getRoomData(roomId);
      return room;
    } catch (err) {
      console.error('Error getting room:', err);
      setError(err.message);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, [service]);
  
  // Get all profiles for current user (Firestore)
  const getUserProfiles = useCallback(async () => {
    if (!service) {
      throw new Error('Service not ready');
    }
    
    setIsLoading(true);
    setError(null);
    
    try {
      const profiles = await service.getUserProfiles();
      return profiles;
    } catch (err) {
      console.error('Error getting profiles:', err);
      setError(err.message);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, [service]);
  
  // Compare two audio profiles
  const compareProfiles = useCallback(async (profile1, profile2) => {
    if (!service || !audioDetection.isReady) {
      throw new Error('Service not ready');
    }
    
    setIsLoading(true);
    setError(null);
    
    try {
      // Calculate similarity
      const similarity = await audioDetection.calculateSimilarity(
        profile1.fingerprint,
        profile2.fingerprint
      );
      
      // Store comparison result
      const comparison = await service.compareFingerprints(
        profile1.fingerprint,
        profile2.fingerprint,
        similarity
      );
      
      return {
        ...comparison,
        similarityPercent: similarity * 100
      };
    } catch (err) {
      console.error('Error comparing profiles:', err);
      setError(err.message);
      throw err;
    } finally {
      setIsLoading(false);
    }
  }, [service, audioDetection]);
  
  // Sign in anonymously if not authenticated
  const ensureAuth = useCallback(async () => {
    if (!service) {
      throw new Error('Service not ready');
    }
    
    try {
      await service.ensureAuthenticated();
      return true;
    } catch (err) {
      console.error('Authentication error:', err);
      setError(err.message);
      throw err;
    }
  }, [service]);
  
  return {
    isReady,
    isAuthenticated,
    currentUser,
    error,
    isLoading,
    createProfile,
    createRoom,
    getProfile,
    getRoom,
    getUserProfiles,
    compareProfiles,
    ensureAuth
  };
};