// src/utils/storageDebugger.js
// Utility for debugging Firebase Storage issues

import { storage } from '../firebase';
import { ref, uploadBytes, getDownloadURL, deleteObject, listAll, getMetadata } from 'firebase/storage';

/**
 * Comprehensive diagnostic for Firebase Storage
 * Helps identify issues with permissions, configuration, and connectivity
 */
export const runStorageDiagnostic = async () => {
  console.log('🔍 Starting Firebase Storage Diagnostic');
  
  const results = {
    initialized: false,
    bucket: null,
    hasListPermission: false,
    hasReadPermission: false,
    hasWritePermission: false,
    hasDeletePermission: false,
    errors: []
  };
  
  // Check basic initialization
  if (!storage) {
    console.error('❌ Firebase Storage is not initialized');
    results.errors.push('Storage object is undefined or null');
    return results;
  }
  
  try {
    // Check if storage instance has required properties
    if (!storage.app) {
      console.error('❌ Firebase Storage is missing app property');
      results.errors.push('Storage object is missing app property');
      return results;
    }
    
    const bucket = storage.app.options?.storageBucket;
    console.log('✅ Storage bucket:', bucket);
    results.initialized = true;
    results.bucket = bucket;
    
    if (!bucket) {
      console.error('❌ Firebase Storage bucket is not configured');
      results.errors.push('Storage bucket is not configured');
      return results;
    }
    
    // Test listing items
    try {
      console.log('🔍 Testing list permission...');
      const listRef = ref(storage, 'backgrounds');
      const listResult = await listAll(listRef);
      
      console.log(`✅ List permission granted. Found ${listResult.items.length} items in 'backgrounds' folder`);
      results.hasListPermission = true;
      
      // If items exist, test reading the first one
      if (listResult.items.length > 0) {
        try {
          console.log('🔍 Testing read permission...');
          const firstItem = listResult.items[0];
          
          // Try to get metadata
          const metadata = await getMetadata(firstItem);
          console.log('✅ Read permission granted. Item details:', metadata.name, metadata.contentType);
          results.hasReadPermission = true;
          
          // Try to get URL
          const url = await getDownloadURL(firstItem);
          console.log('✅ URL retrieval successful:', url.substring(0, 50) + '...');
        } catch (readError) {
          console.error('❌ Read permission test failed:', readError);
          results.errors.push(`Read test error: ${readError.message}`);
        }
      } else {
        console.log('⚠️ No existing items to test read permission');
      }
    } catch (listError) {
      console.error('❌ List permission test failed:', listError);
      results.errors.push(`List test error: ${listError.message}`);
    }
    
    // Test writing
    try {
      console.log('🔍 Testing write permission...');
      const testFilePath = `backgrounds/test_${Date.now()}.txt`;
      const uploadRef = ref(storage, testFilePath);
      
      // Create a small test file
      const testBlob = new Blob(['test content'], { type: 'text/plain' });
      
      // Upload test file
      const uploadResult = await uploadBytes(uploadRef, testBlob, {
        contentType: 'text/plain',
        customMetadata: {
          purpose: 'diagnostic-test',
          timestamp: new Date().toISOString()
        }
      });
      
      console.log('✅ Write permission granted. Test file uploaded:', testFilePath);
      results.hasWritePermission = true;
      
      // Test deletion
      try {
        console.log('🔍 Testing delete permission...');
        await deleteObject(uploadRef);
        console.log('✅ Delete permission granted. Test file deleted');
        results.hasDeletePermission = true;
      } catch (deleteError) {
        console.error('❌ Delete permission test failed:', deleteError);
        results.errors.push(`Delete test error: ${deleteError.message}`);
      }
    } catch (writeError) {
      console.error('❌ Write permission test failed:', writeError);
      results.errors.push(`Write test error: ${writeError.message}`);
      
      // Check for specific errors
      if (writeError.code === 'storage/unauthorized') {
        console.error('❌ You do not have permission to upload to Firebase Storage');
        results.errors.push('Unauthorized: You may need to update Firebase Storage rules');
      }
    }
    
    // Print summary
    console.log('\n📊 Firebase Storage Diagnostic Summary:');
    console.log(`Initialized: ${results.initialized ? '✅' : '❌'}`);
    console.log(`Storage Bucket: ${results.bucket ? '✅ ' + results.bucket : '❌ Not configured'}`);
    console.log(`List Permission: ${results.hasListPermission ? '✅' : '❌'}`);
    console.log(`Read Permission: ${results.hasReadPermission ? '✅' : '❌'}`);
    console.log(`Write Permission: ${results.hasWritePermission ? '✅' : '❌'}`);
    console.log(`Delete Permission: ${results.hasDeletePermission ? '✅' : '❌'}`);
    
    // Recommended Firebase Storage rules if there are permission issues
    if (!results.hasWritePermission) {
      console.log('\n📝 Recommended Firebase Storage Rules:\n');
      console.log(`
rules_version = '2';
service firebase.storage {
  match /b/{bucket}/o {
    // Allow admin access with authentication
    match /backgrounds/{fileName} {
      allow read: if true;  // Anyone can view backgrounds
      allow write: if request.auth != null;  // Only authenticated users can upload
      allow delete: if request.auth != null;  // Only authenticated users can delete
    }
    
    // Default rules for other storage paths
    match /{allPaths=**} {
      allow read: if true;
      allow write: if request.auth != null;
    }
  }
}
      `);
    }
    
    return results;
  } catch (error) {
    console.error('❌ Firebase Storage diagnostic error:', error);
    results.errors.push(`General error: ${error.message}`);
    return results;
  }
};

// Add to window for console access
window.runStorageDiagnostic = runStorageDiagnostic;

export default { runStorageDiagnostic };