import { memo } from 'react'
import { Link } from 'react-router-dom'
import { Clock, Users, ArrowRight, MapPin } from 'lucide-react'
import Card from '../common/Card'
import Badge from '../common/Badge'
import ConfidenceBar from '../common/ConfidenceBar'
import TrendIndicator from '../common/TrendIndicator'
import { useCountdown } from '../../hooks/useCountdown'
import { getConfidenceColor } from '../../utils/weights'
import { deriveMarketTags, getMarket } from '../../utils/markets'

function PredictionCard({ prediction }) {
  const { label: timeLeft, isExpired } = useCountdown(prediction.deadline)
  const topOutcome = prediction.outcomes[0]
  const { bg } = getConfidenceColor(topOutcome.probability)
  const totalVotes = prediction.communityVotes.agree + prediction.communityVotes.disagree
  // Show up to 3 market tags so the chip row doesn't wrap into multi-line mess.
  const marketTags = deriveMarketTags(prediction).slice(0, 3)

  return (
    <Card className="p-5 flex flex-col gap-3 animate-fade-in group relative overflow-hidden">
      <div className={`absolute left-0 top-0 bottom-0 w-1 ${bg}`} />

      <div className="flex items-center justify-between gap-2">
        <Badge category={prediction.category} />
        <span className={`flex items-center gap-1 text-xs ${isExpired ? 'text-red-400' : 'text-gray-500'}`}>
          <Clock size={12} />
          {timeLeft}
        </span>
      </div>

      <Link to={`/predict/${prediction.id}`} className="group/link">
        <h3 className="font-semibold text-gray-100 leading-snug line-clamp-2 group-hover/link:text-blue-400 transition-colors">
          {prediction.title}
        </h3>
      </Link>

      <p className="text-xs text-gray-500 line-clamp-2 leading-relaxed">
        {prediction.description}
      </p>

      {marketTags.length > 0 && (
        <div className="flex items-center gap-1 flex-wrap">
          <MapPin size={11} className="text-blue-400/70 shrink-0" />
          {marketTags.map(id => {
            const m = getMarket(id)
            if (!m) return null
            return (
              <span
                key={id}
                className="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-medium bg-blue-500/10 text-blue-300 border border-blue-500/20"
              >
                {m.label}
              </span>
            )
          })}
        </div>
      )}

      <div className="space-y-2 mt-1">
        {prediction.outcomes.slice(0, 3).map((outcome, i) => (
          <div key={i} className="flex items-center gap-2">
            <span className="text-xs text-gray-400 min-w-[100px] truncate">{outcome.label}</span>
            <ConfidenceBar value={outcome.probability} size="sm" />
            <TrendIndicator trend={outcome.trend} size={12} />
          </div>
        ))}
      </div>

      <div className="flex items-center justify-between pt-2 mt-auto border-t border-gray-800/50">
        <div className="flex items-center gap-3 text-xs text-gray-500">
          <span>{prediction.inputs.length} sources</span>
          <span className="flex items-center gap-1">
            <Users size={12} />
            {totalVotes.toLocaleString()}
          </span>
        </div>
        <Link
          to={`/predict/${prediction.id}`}
          className="flex items-center gap-1 text-xs text-blue-400 hover:text-blue-300 transition-colors"
        >
          Details <ArrowRight size={12} />
        </Link>
      </div>
    </Card>
  )
}

export default memo(PredictionCard)
