// src/utils/firebaseDiagnostic.js
// Utility to diagnose Firebase initialization issues

import { getFirestore, collection, getDocs, query, limit } from 'firebase/firestore';
import { getAuth, signInAnonymously } from 'firebase/auth';
import { getStorage, ref as storageRef, listAll } from 'firebase/storage';
import { getFunctions, httpsCallable } from 'firebase/functions';
import { getDatabase, ref as dbRef, get } from 'firebase/database';
import { app } from '../firebase';

/**
 * Run a comprehensive diagnostic on Firebase services
 * Use this to identify configuration issues
 */
export const runFirebaseDiagnostic = async () => {
  console.log('🔍 Starting Firebase Diagnostic');
  console.log('🔧 Firebase SDK Version:', getFirebaseVersion());
  
  const results = {
    app: false,
    auth: false,
    firestore: false,
    storage: false,
    functions: false,
    rtdb: false,
  };
  
  // Test app initialization
  try {
    console.log('📋 Checking Firebase app initialization');
    if (app && app.name) {
      console.log('✅ Firebase app initialized successfully:', app.name);
      results.app = true;
    } else {
      console.error('❌ Firebase app initialization failed or incomplete');
    }
  } catch (error) {
    console.error('❌ Firebase app error:', error);
  }
  
  // Test Firestore
  try {
    console.log('📋 Checking Firestore initialization');
    const db = getFirestore(app);
    
    if (db) {
      console.log('✅ Firestore initialized');
      results.firestore = true;
      
      // Try a simple read operation
      console.log('📋 Testing Firestore read operation');
      try {
        const testQuery = query(collection(db, 'users'), limit(1));
        const snapshot = await getDocs(testQuery);
        console.log(`✅ Firestore read successful: ${snapshot.docs.length} documents retrieved`);
      } catch (readError) {
        console.error('❌ Firestore read failed:', readError.message);
      }
    } else {
      console.error('❌ Firestore initialization failed');
    }
  } catch (error) {
    console.error('❌ Firestore error:', error);
  }
  
  // Test Authentication
  try {
    console.log('📋 Checking Authentication initialization');
    const auth = getAuth(app);
    
    if (auth) {
      console.log('✅ Authentication initialized');
      results.auth = true;
      
      // Only attempt anonymous sign-in if explicitly approved
      if (window.confirmAuthTest) {
        try {
          console.log('📋 Testing anonymous authentication (only if approved)');
          await signInAnonymously(auth);
          console.log('✅ Anonymous authentication successful');
        } catch (authOpError) {
          console.error('❌ Anonymous authentication failed:', authOpError.message);
        }
      }
    } else {
      console.error('❌ Authentication initialization failed');
    }
  } catch (error) {
    console.error('❌ Authentication error:', error);
  }
  
  // Test Storage
  try {
    console.log('📋 Checking Storage initialization');
    const storage = getStorage(app);
    
    if (storage) {
      console.log('✅ Storage initialized');
      results.storage = true;
      
      // Try to list root items (this will likely fail due to permissions, but tests the connection)
      try {
        console.log('📋 Testing Storage operation');
        const rootRef = storageRef(storage);
        await listAll(rootRef);
        console.log('✅ Storage operation successful');
      } catch (storageOpError) {
        // This is expected to fail with permission errors, which is fine for a test
        if (storageOpError.code === 'storage/unauthorized') {
          console.log('⚠️ Storage permission denied (expected for security reasons)');
        } else {
          console.error('❌ Storage operation failed:', storageOpError.message);
        }
      }
    } else {
      console.error('❌ Storage initialization failed');
    }
  } catch (error) {
    console.error('❌ Storage error:', error);
  }
  
  // Test Cloud Functions
  try {
    console.log('📋 Checking Cloud Functions initialization');
    const functions = getFunctions(app);
    
    if (functions) {
      console.log('✅ Cloud Functions initialized');
      results.functions = true;
      
      // To test an actual function, you would need a real function name
      // This is commented out to avoid unintended function calls
      /*
      try {
        console.log('📋 Testing Cloud Function invocation');
        const testFunction = httpsCallable(functions, 'helloWorld');
        const result = await testFunction();
        console.log('✅ Function call successful:', result.data);
      } catch (functionsOpError) {
        console.error('❌ Function call failed:', functionsOpError.message);
      }
      */
    } else {
      console.error('❌ Cloud Functions initialization failed');
    }
  } catch (error) {
    console.error('❌ Cloud Functions error:', error);
  }
  
  // Test Realtime Database
  try {
    console.log('📋 Checking Realtime Database initialization');
    const database = getDatabase(app);
    
    if (database) {
      console.log('✅ Realtime Database initialized');
      results.rtdb = true;
      
      // Try to check the connection status - this should be accessible even without special permissions
      try {
        console.log('📋 Testing Realtime Database connection status');
        const connectionRef = dbRef(database, '.info/connected');
        const snapshot = await get(connectionRef);
        const connected = snapshot.val();
        console.log(`✅ RTDB connection status: ${connected ? 'Connected' : 'Disconnected'}`);
      } catch (rtdbOpError) {
        console.error('❌ RTDB operation failed:', rtdbOpError.message);
        
        // Check specific error types
        if (rtdbOpError.code === 'PERMISSION_DENIED') {
          console.error('🔒 This appears to be a permissions issue. Check Firebase security rules for Realtime Database.');
          console.log('ℹ️ In production, ensure the user is authenticated before accessing the database.');
          console.log('ℹ️ For testing, you can update your rules to allow read access to .info/connected');
        }
      }
    } else {
      console.error('❌ Realtime Database initialization failed');
    }
  } catch (error) {
    console.error('❌ Realtime Database error:', error);
  }
  
  // Summary
  console.log('📊 Firebase Diagnostic Summary:');
  console.log(`App Initialization: ${results.app ? '✅' : '❌'}`);
  console.log(`Authentication: ${results.auth ? '✅' : '❌'}`);
  console.log(`Firestore: ${results.firestore ? '✅' : '❌'}`);
  console.log(`Realtime Database: ${results.rtdb ? '✅' : '❌'}`);
  console.log(`Storage: ${results.storage ? '✅' : '❌'}`);
  console.log(`Cloud Functions: ${results.functions ? '✅' : '❌'}`);
  
  return results;
};

/**
 * Get Firebase SDK version (approximation)
 * @returns {string} Version info
 */
const getFirebaseVersion = () => {
  try {
    // This is a hack to extract version info from the Firebase SDK
    const firebaseString = app.toString();
    const versionMatch = firebaseString.match(/Firebase\/JS\/([0-9.]+)/);
    return versionMatch ? versionMatch[1] : 'Unknown';
  } catch (e) {
    return 'Unable to determine';
  }
};

// Add to window for console access
window.runFirebaseDiagnostic = runFirebaseDiagnostic;

export default { runFirebaseDiagnostic };