// src/pages/UnifiedMeetingCreator.jsx
//
// Unified Meeting Creator — a single "smart form" that merges the app's
// scattered creation flows (LiveKit RTMP events, chat rooms, private rooms,
// DJ/audio sets, in-person meetups) behind one adaptive UI.
//
// Design: the "Nocturne" design system from the design handoff, ported to
// scoped CSS (UnifiedMeetingCreator.css) + inline styles that reference its
// CSS custom properties. Icons use lucide-react (already a dependency) in
// place of the prototype's Phosphor sprite sheet.
//
// Wiring: "Create meeting" persists a real room to Realtime Database
// (chats/public — the same shape src/components/chat/CreateRoomPage.jsx
// writes) and routes the user into the real /room/:id. Event/DJ specifics
// beyond a room (LiveKit RTMP ingress, audio fingerprints) are represented in
// the Ready screen but left to the existing per-type backends — see README
// note about a future unified endpoint. If persistence isn't possible
// (e.g. signed out), the flow falls back to a client-only demo so the UI is
// still fully explorable.

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { getAuth } from 'firebase/auth';
import { getDatabase, ref, push, set } from 'firebase/database';
import { getFirestore, addDoc, collection, serverTimestamp } from 'firebase/firestore';
import liveKitIngressService from '../services/livekit/LiveKitIngressService.js';
import { formatLocalTime, getUserTimezone, validateEventDateTime } from '../utils/timezoneUtils.js';
import {
  Building2, Plus, LayoutList, Users, Settings as SettingsIcon, Search, PanelRight,
  X, Sparkles, Clock, StickyNote, LogOut, Zap, Calendar, Lock, MapPin,
  Mic, MicOff, Video, ScreenShare, PhoneOff,
} from 'lucide-react';
import { useAuth } from '../contexts/AuthContext.jsx';
import './UnifiedMeetingCreator.css';

/* ── static data ─────────────────────────────────────────────────────── */

const NAV = [
  { id: 'create', Icon: Plus, label: 'Create meeting' },
  { id: 'meetings', Icon: LayoutList, label: 'My meetings' },
  { id: 'contacts', Icon: Users, label: 'Contacts' },
  { id: 'settings', Icon: SettingsIcon, label: 'Settings' },
];

const TABS = [
  { id: 'templates', Icon: Sparkles, label: 'Templates', hint: 'Start from a meeting type.' },
  { id: 'recent', Icon: Clock, label: 'Recent', hint: 'Meetings you created or joined.' },
  { id: 'contacts', Icon: Users, label: 'Contacts', hint: 'Invite people in one click.' },
  { id: 'notes', Icon: StickyNote, label: 'Notes', hint: 'Scratchpad for this meeting.' },
];

const TYPES = [
  { id: 'instant', label: 'Instant hangout', desc: 'Start now, share a link.', Icon: Zap },
  { id: 'scheduled', label: 'Scheduled stream', desc: 'Plan a start time and capacity.', Icon: Calendar },
  { id: 'private', label: 'Private room', desc: 'Invite-only, unlisted.', Icon: Lock },
  { id: 'dj', label: 'DJ / audio set', desc: 'Audio-first, listener matching.', Icon: Sparkles },
  { id: 'meetup', label: 'In-person meetup', desc: 'Pin a real-world location.', Icon: MapPin },
];

const RECENT = [
  { title: 'Design review', when: 'Yesterday, 45 min', tag: 'Ended' },
  { title: 'Weekly standup', when: 'Mon · 15 min', tag: 'Ended' },
  { title: 'Investor sync', when: 'Tomorrow 10:00', tag: 'Scheduled' },
];
const MEETINGS = [
  { title: 'Investor sync', when: 'Tomorrow · 10:00', tag: 'Scheduled' },
  { title: 'Design review', when: 'Yesterday, 45 min', tag: 'Ended' },
  { title: 'Weekly standup', when: 'Mon · 15 min', tag: 'Ended' },
  { title: 'DJ set — late night', when: 'Fri · 90 min', tag: 'Ended' },
];
const CONTACTS = [
  { ini: 'JR', name: 'Jordan Reyes', sub: 'jordan@studio.co', last: 'met yesterday' },
  { ini: 'AL', name: 'Alex Lin', sub: 'alex@lin.dev', last: 'met Mon' },
  { ini: 'PK', name: 'Priya Kapoor', sub: 'priya@kapoor.io', last: 'never' },
];
const COMMANDS = [
  { group: 'Meetings', Icon: LayoutList, label: 'Investor sync', meta: 'Tomorrow 10:00', id: 'meetings' },
  { group: 'Meetings', Icon: LayoutList, label: 'Design review', meta: 'Ended yesterday', id: 'meetings' },
  { group: 'Contacts', Icon: Users, label: 'Jordan Reyes', meta: 'jordan@studio.co', id: 'contacts' },
  { group: 'Contacts', Icon: Users, label: 'Alex Lin', meta: 'alex@lin.dev', id: 'contacts' },
  { group: 'Actions', Icon: Zap, label: 'Start an instant meeting', meta: '⌘N', id: 'create' },
  { group: 'Actions', Icon: PanelRight, label: 'Toggle tool panel', meta: '⌘\\', id: '__panel' },
  { group: 'Actions', Icon: SettingsIcon, label: 'Open settings', meta: '', id: 'settings' },
];

const DEFAULTS = {
  title: '', description: '', startTime: '', duration: 60, maxViewers: 100,
  inviteEmails: '', location: '', audioSignature: true,
  joinAccess: 'anyone', broadcastMethod: 'camera',
};

const slugify = (s) =>
  (s || 'meeting').toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '') || 'meeting';

/* ── component ───────────────────────────────────────────────────────── */

export default function UnifiedMeetingCreator() {
  const navigate = useNavigate();
  const { currentUser } = useAuth();

  const [view, setView] = useState('create');
  const [meetingType, setMeetingType] = useState('instant');
  const [form, setForm] = useState({ ...DEFAULTS });
  const [titleError, setTitleError] = useState(false);
  const [locationDetecting, setLocationDetecting] = useState(false);
  const [copiedField, setCopiedField] = useState(null);
  const [creating, setCreating] = useState(false);

  // The real room we created (or null when running the client-only demo).
  const [createdRoom, setCreatedRoom] = useState(null);

  // in-meeting device state (demo lobby)
  const [micOn, setMicOn] = useState(true);
  const [camOn, setCamOn] = useState(true);
  const [screenOn, setScreenOn] = useState(false);

  // shell UI state
  const [panel, setPanel] = useState(true);
  const [tab, setTab] = useState('templates');
  const [cmd, setCmd] = useState(false);
  const [q, setQ] = useState('');
  const [mobile, setMobile] = useState(false);
  const [tight, setTight] = useState(false);
  const [detent, setDetent] = useState(0); // 0 peek · 1 half · 2 full

  const copyTimer = useRef(null);

  const setField = useCallback((patch) => setForm((f) => ({ ...f, ...patch })), []);

  /* keyboard shortcuts */
  useEffect(() => {
    const onKey = (e) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
        e.preventDefault(); setCmd((v) => !v); setQ('');
      }
      if ((e.metaKey || e.ctrlKey) && e.key === '\\') {
        e.preventDefault(); setPanel((v) => !v);
      }
      if (e.key === 'Escape') setCmd(false);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, []);

  /* responsive breakpoints (matchMedia, per design) — with a window-resize
     fallback so the layout tracks the viewport even where programmatic
     resizes don't dispatch matchMedia 'change' events. */
  useEffect(() => {
    const mq = window.matchMedia('(max-width: 840px)');
    const tq = window.matchMedia('(min-width: 841px) and (max-width: 1100px)');
    const apply = () => {
      const isMobile = mq.matches;
      const isTight = tq.matches;
      setMobile(isMobile);
      setTight(isTight);
      setPanel(!isMobile && !isTight);
    };
    const onMQ = () => { setMobile(mq.matches); setDetent(0); };
    const onTQ = () => { setTight(tq.matches); setPanel(!tq.matches); };
    mq.addEventListener('change', onMQ);
    tq.addEventListener('change', onTQ);
    window.addEventListener('resize', apply);
    apply();
    return () => {
      mq.removeEventListener('change', onMQ);
      tq.removeEventListener('change', onTQ);
      window.removeEventListener('resize', apply);
    };
  }, []);

  useEffect(() => () => { if (copyTimer.current) clearTimeout(copyTimer.current); }, []);

  /* derived */
  const isScheduled = meetingType === 'scheduled';
  const isPrivate = meetingType === 'private';
  const isMeetup = meetingType === 'meetup';
  const isDj = meetingType === 'dj';
  const showBroadcast = ['instant', 'scheduled', 'dj'].includes(meetingType);
  const typeLabel = (TYPES.find((t) => t.id === meetingType) || {}).label || 'Meeting';

  const watchLink = createdRoom
    ? `${window.location.origin}${createdRoom.watch}`
    : `https://presence.app/m/${slugify(form.title)}`;
  const rtmpServer = createdRoom?.rtmp?.server || 'rtmp://ingest.presence.app/live';
  const streamKey = createdRoom?.rtmp?.key || `${slugify(form.title)}-9f21`;
  const initials = (form.title || currentUser?.displayName || 'You').trim().slice(0, 2).toUpperCase();
  const showObsPanel = (showBroadcast && form.broadcastMethod === 'obs') || !!createdRoom?.rtmp;

  /* navigation between views */
  const go = useCallback((id) => { setView(id); setCmd(false); }, []);
  const selectType = useCallback((id) => { setMeetingType(id); setView('create'); }, []);

  /* location detect — real geolocation + OSM reverse-geocode, with fallback */
  const detectLocation = useCallback(() => {
    setLocationDetecting(true);
    if (!navigator.geolocation) {
      setField({ location: 'San Francisco, CA' });
      setLocationDetecting(false);
      return;
    }
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude, longitude } = pos.coords;
        try {
          const r = await fetch(
            `https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}&zoom=18&addressdetails=1`,
            { headers: { 'Accept-Language': 'en' } }
          );
          const data = r.ok ? await r.json() : null;
          const a = data && data.address;
          let str;
          if (a && (a.city || a.town || a.village)) {
            str = (a.city || a.town || a.village) + (a.state || a.country ? `, ${a.state || a.country}` : '');
          } else if (a && a.county) {
            str = `${a.county}, ${a.state || a.country}`;
          } else if (data && data.display_name) {
            str = data.display_name.split(',').slice(0, 2).join(',');
          } else {
            str = `${latitude.toFixed(4)}, ${longitude.toFixed(4)}`;
          }
          setField({ location: str });
        } catch {
          setField({ location: `${latitude.toFixed(4)}, ${longitude.toFixed(4)}` });
        } finally {
          setLocationDetecting(false);
        }
      },
      () => { setField({ location: 'San Francisco, CA' }); setLocationDetecting(false); },
      { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
    );
  }, [setField]);

  /* A given type/broadcast combination that needs an RTMP ingest or a
     scheduled/audio-first live stream is backed by a real Event (Firestore
     `events` + LiveKit ingress). Everything else is a lightweight chat room
     (RTDB chats/public). */
  const usesEvent = useCallback(
    (type) => type === 'scheduled' || type === 'dj' || (type === 'instant' && form.broadcastMethod === 'obs'),
    [form.broadcastMethod]
  );

  /* Chat-room backend — matches src/components/chat/CreateRoomPage.jsx's
     RTDB write shape. Used for instant (camera/screen), private and meetup. */
  const createRoomRecord = useCallback(async (type, title) => {
    const user = getAuth().currentUser || currentUser;
    if (!user) throw new Error('not-authenticated');

    const rtdb = getDatabase();
    const newRoomRef = push(ref(rtdb, 'chats/public'));
    const ts = Date.now();
    const cleanTitle = title.trim();

    const roomData = {
      name: cleanTitle,
      description: (form.description || '').trim(),
      createdAt: ts,
      createdBy: user.uid,
      creatorName: user.displayName || 'Anonymous',
      lastActivityTimestamp: ts,
      messageCount: 0,
      isPublic: form.joinAccess === 'anyone',
      status: 'active',
      nameLower: cleanTitle.toLowerCase(),
      descriptionLower: (form.description || '').trim().toLowerCase(),
      activeUserTimestamps: { [user.uid]: ts },
      // Unified-creator metadata (preserved for the future unified backend).
      meetingType: type,
      joinAccess: form.joinAccess,
      broadcastMethod: showBroadcast ? form.broadcastMethod : null,
    };
    if (type === 'private') {
      roomData.isPrivate = true;
      if (form.inviteEmails.trim()) {
        roomData.inviteEmails = form.inviteEmails.split(',').map((s) => s.trim()).filter(Boolean);
      }
    }
    if (type === 'meetup' && form.location.trim()) roomData.location = form.location.trim();

    await set(newRoomRef, roomData);

    try {
      const actRef = push(ref(rtdb, 'activities'));
      await set(actRef, {
        type: 'room', userId: user.uid, userName: user.displayName || 'Anonymous',
        userAvatar: user.photoURL || null, roomId: newRoomRef.key, roomName: cleanTitle, timestamp: ts,
      });
    } catch { /* non-fatal */ }

    return { id: newRoomRef.key, kind: 'room', route: `/room/${newRoomRef.key}`, watch: `/room/${newRoomRef.key}`, rtmp: null };
  }, [currentUser, form, showBroadcast]);

  /* Event chat room in RTDB — a trimmed version of
     CreateEventModal.createEventChatRoom (keeps the shape session/chat views
     expect). Non-fatal on failure. */
  const createEventChatRoomRTDB = useCallback(async (eventId, ev, tz) => {
    const rtdb = getDatabase();
    const path = `chats/public/event_${eventId}`;
    const now = Date.now();
    await set(ref(rtdb, path), {
      type: 'event', eventId, eventTitle: ev.title,
      artistId: ev.artistId, artistName: ev.artistName, artistAvatar: ev.artistAvatar,
      isActive: false, allowUserStreaming: true, artistPriority: true, maxConcurrentUserStreams: 8,
      moderationEnabled: true, autoModeration: true, slowModeEnabled: false, slowModeDelay: 0,
      accessLevel: ev.accessLevel, allowAnonymous: ev.accessLevel === 'free',
      artistVideoActive: false, userStreams: {},
      totalMessages: 0, activeUsers: 0, peakUsers: 0,
      createdAt: now, updatedAt: now, timezone: tz.timezone, timezoneOffset: tz.offsetString,
    });
    try {
      await push(ref(rtdb, `${path}/messages`), {
        type: 'system', message: `Welcome to ${ev.title}!`, timestamp: now, userId: 'system', userName: 'System',
      });
    } catch { /* non-fatal */ }
  }, []);

  /* Event backend — mirrors CreateEventModal.createEvent (Firestore `events`
     + LiveKit RTMP ingress + event chat room), minus the imperative DOM
     modal. Used for scheduled / DJ / instant-OBS. Requires a signed-in,
     non-anonymous user (matching the event modal's rule). */
  const createEventRecord = useCallback(async (type, title) => {
    const user = getAuth().currentUser || currentUser;
    if (!user || user.isAnonymous) throw new Error('event-requires-account');

    const fdb = getFirestore();
    const tz = getUserTimezone();
    const now = Date.now();
    const scheduled = type === 'scheduled';

    if (scheduled && form.startTime && !validateEventDateTime(form.startTime)) {
      throw new Error('invalid-start-time');
    }
    const startTimeMs = scheduled && form.startTime ? new Date(form.startTime).getTime() : now;
    const durationMin = Number(form.duration) || 60;
    const endTimeMs = startTimeMs + durationMin * 60 * 1000;
    const category = type === 'dj' ? 'music' : scheduled ? 'performance' : 'talk';
    const cleanTitle = title.trim();

    const eventData = {
      title: cleanTitle,
      description: (form.description || '').trim(),
      category,
      artistId: user.uid,
      artistName: user.displayName || 'Event Creator',
      artistAvatar: user.photoURL || null,
      artistVerified: false,
      status: 'scheduled',
      startTime: startTimeMs,
      endTime: endTimeMs,
      duration: durationMin,
      maxViewers: Number(form.maxViewers) || 100,
      accessLevel: 'free', // join gating is tracked via `joinAccess` below
      chatEnabled: true,
      reactionsEnabled: true,
      recordingEnabled: true,
      tipsEnabled: false,
      activityGracePeriod: 30 * 60 * 1000,
      streamEndTime: null,
      autoEndEnabled: false,
      maxStreamDuration: null,
      timezone: tz.timezone,
      timezoneOffset: tz.offsetString,
      localStartTime: formatLocalTime(new Date(startTimeMs)),
      viewerCount: 0,
      peakViewers: 0,
      totalViews: 0,
      revenue: 0,
      // Unified-creator metadata.
      meetingType: type,
      joinAccess: form.joinAccess,
      broadcastMethod: form.broadcastMethod,
      audioSignature: type === 'dj' ? !!form.audioSignature : null,
      createdAt: serverTimestamp(),
      updatedAt: serverTimestamp(),
    };

    const eventRef = await addDoc(collection(fdb, 'events'), eventData);
    const eventId = eventRef.id;

    // RTMP ingress — only needed when broadcasting from OBS.
    let rtmp = null;
    if (form.broadcastMethod === 'obs') {
      try {
        const res = await liveKitIngressService.createRTMPIngress(`event_${eventId}`, {
          eventId, videoBitrate: 2000000, audioBitrate: 128000, width: 1280, height: 720, framerate: 30,
        });
        rtmp = {
          server: res.rtmpUrl || 'rtmp://talkstudio-2c55dh9q.livekit.cloud/x/',
          key: res.streamKey || eventId,
        };
      } catch {
        rtmp = { server: 'rtmp://talkstudio-2c55dh9q.livekit.cloud/x/', key: eventId };
      }
    }

    try { await createEventChatRoomRTDB(eventId, eventData, tz); } catch { /* non-fatal */ }

    return { id: eventId, kind: 'event', route: `/events/${eventId}/session`, watch: `/events/${eventId}`, rtmp };
  }, [currentUser, form, createEventChatRoomRTDB]);

  /* Dispatch to the right backend for the chosen type. */
  const persistMeeting = useCallback(
    (type, title) => (usesEvent(type) ? createEventRecord(type, title) : createRoomRecord(type, title)),
    [usesEvent, createEventRecord, createRoomRecord]
  );

  /* create → ready (real backend when possible, demo otherwise) */
  const createMeeting = useCallback(async (type, title) => {
    setCreating(true);
    try {
      const meeting = await persistMeeting(type, title);
      setCreatedRoom(meeting);
    } catch {
      setCreatedRoom(null); // fall back to the client-only demo flow
    } finally {
      setCreating(false);
      setView('ready');
    }
  }, [persistMeeting]);

  const startNow = useCallback(() => {
    const title = form.title.trim() || 'Quick hangout';
    setMeetingType('instant');
    if (!form.title.trim()) setField({ title });
    createMeeting('instant', title);
  }, [form.title, setField, createMeeting]);

  const validateAndCreate = useCallback(() => {
    if (!form.title.trim()) { setTitleError(true); return; }
    createMeeting(meetingType, form.title);
  }, [form.title, meetingType, createMeeting]);

  const resetForm = useCallback(() => {
    setForm({ ...DEFAULTS });
    setTitleError(false);
  }, []);

  const enterMeeting = useCallback(() => {
    if (createdRoom) navigate(createdRoom.route);
    else setView('lobby'); // demo lobby when no real room was created
  }, [createdRoom, navigate]);

  const backToCreate = useCallback(() => { setCreatedRoom(null); setView('create'); }, []);

  const copyText = useCallback((text, field) => {
    if (navigator.clipboard) navigator.clipboard.writeText(text).catch(() => {});
    setCopiedField(field);
    if (copyTimer.current) clearTimeout(copyTimer.current);
    copyTimer.current = setTimeout(() => setCopiedField(null), 1500);
  }, []);

  const inviteContact = useCallback((name) => {
    setForm((f) => ({ ...f, inviteEmails: f.inviteEmails ? `${f.inviteEmails}, ${name}` : name }));
    setMeetingType('private');
    setView('create');
  }, []);

  /* command palette results */
  const cmdGroups = useMemo(() => {
    const query = q.trim().toLowerCase();
    const matched = COMMANDS.filter(
      (c) => !query || `${c.label} ${c.meta} ${c.group}`.toLowerCase().includes(query)
    );
    const groups = [];
    matched.forEach((c) => {
      let g = groups.find((x) => x.group === c.group);
      if (!g) { g = { group: c.group, items: [] }; groups.push(g); }
      g.items.push(c);
    });
    return groups;
  }, [q]);

  const runCommand = useCallback((c) => {
    if (c.id === '__panel') { setPanel((v) => !v); setCmd(false); }
    else go(c.id);
  }, [go]);

  /* identity block */
  const displayName = currentUser?.displayName || (currentUser?.isAnonymous ? 'Guest' : 'You');
  const identityEmail = currentUser?.email || (currentUser?.isAnonymous ? 'Anonymous session' : 'you@presence.app');
  const identityIni = displayName.trim().slice(0, 2).toUpperCase();

  /* layout values (mirror the prototype's renderVals) */
  const wide = !mobile && panel;
  const sheetH = detent === 0 ? '92px' : detent === 1 ? '56%' : 'calc(100% - 44px)';
  const activeNav = ['meetings', 'contacts', 'settings'].includes(view) ? view : 'create';
  const tabMeta = TABS.find((t) => t.id === tab) || TABS[0];

  /* ── render helpers ── */
  const cssv = {}; // (kept for readability; inline styles use var(--…) directly)

  const seg = (name, current, value, onSelect, label) => (
    <label className="seg-opt">
      <input type="radio" name={name} checked={current === value} onChange={() => onSelect(value)} />
      {label}
    </label>
  );

  return (
    <div className="umc-root" style={cssv}>

      {/* ── sidebar (desktop) ── */}
      {!mobile && (
        <aside style={{
          width: 230, flex: 'none', display: 'flex', flexDirection: 'column',
          background: 'var(--color-surface)', borderRight: '1px solid var(--color-divider)', padding: '14px 10px',
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 9, padding: '4px 8px 14px' }}>
            <Building2 size={18} color="var(--color-accent)" strokeWidth={1.7} />
            <span style={{ fontFamily: 'var(--font-heading)', fontWeight: 500, fontSize: 14, letterSpacing: '-.01em' }}>Presence</span>
          </div>
          <nav style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 1 }}>
            {NAV.map(({ id, Icon, label }) => (
              <button key={id} className="nv" data-on={activeNav === id ? '1' : '0'} onClick={() => go(id)}>
                <Icon size={15} strokeWidth={1.8} style={{ flex: 'none' }} />
                {label}
              </button>
            ))}
          </nav>
          <div style={{ marginTop: 10, paddingTop: 10, borderTop: '1px solid var(--color-divider)' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 9, padding: '4px 8px 8px' }}>
              <span style={{ width: 26, height: 26, flex: 'none', borderRadius: '50%', display: 'grid', placeItems: 'center', background: 'var(--color-accent-800)', color: 'var(--color-accent-100)', fontSize: 11 }}>{identityIni}</span>
              <div style={{ minWidth: 0 }}>
                <p style={{ margin: 0, fontSize: 12, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{displayName}</p>
                <p style={{ margin: 0, fontSize: 10.5, color: 'var(--color-neutral-600)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{identityEmail}</p>
              </div>
            </div>
            <button className="nv" onClick={() => navigate('/')}>
              <LogOut size={15} strokeWidth={1.8} />Exit
            </button>
          </div>
        </aside>
      )}

      {/* ── main column ── */}
      <div style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column' }}>

        {/* top bar */}
        <header style={{
          flex: 'none', display: 'flex', alignItems: 'center', gap: 14, padding: '11px 20px',
          borderBottom: '1px solid var(--color-divider)', background: 'var(--color-surface)',
        }}>
          {mobile && <Building2 size={18} color="var(--color-accent)" strokeWidth={1.7} style={{ flex: 'none' }} />}
          {!mobile && (
            <div style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 12.5, color: 'var(--color-neutral-500)', minWidth: 0, whiteSpace: 'nowrap' }}>
              <span style={{ minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', color: 'var(--color-text)' }}>
                {{ create: 'Create meeting', ready: "You're ready", lobby: form.title || 'Meeting', meetings: 'My meetings', contacts: 'Contacts', settings: 'Settings' }[view]}
              </span>
            </div>
          )}
          <button onClick={() => { setCmd(true); setQ(''); }} style={{
            marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 9, width: 'min(460px,42vw)', minWidth: 0,
            padding: '7px 11px', border: '1px solid var(--color-divider)', borderRadius: 8, background: 'var(--color-bg)',
            color: 'var(--color-neutral-500)', font: 'inherit', fontSize: 13, cursor: 'pointer', textAlign: 'left',
          }}>
            <Search size={14} strokeWidth={1.9} />
            <span style={{ flex: 1, minWidth: 0, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
              {tight ? 'Search…' : 'Meetings, contacts, actions…'}
            </span>
            <span style={{ flex: 'none', fontSize: 10.5, padding: '2px 6px', borderRadius: 4, border: '1px solid var(--color-divider)' }}>⌘K</span>
          </button>
          {!mobile && (
            <button className="icb" onClick={() => setPanel((v) => !v)} title="Toggle tool panel" style={{
              width: 32, height: 32, flex: 'none', display: 'grid', placeItems: 'center',
              border: '1px solid var(--color-divider)', borderRadius: 8, background: 'transparent', color: 'var(--color-neutral-400)', cursor: 'pointer',
            }}>
              <PanelRight size={15} strokeWidth={1.8} />
            </button>
          )}
        </header>

        {/* main content */}
        <main style={{ flex: 1, overflowY: 'auto', padding: mobile ? '18px 14px 170px' : '26px 28px' }}>

          {view === 'create' && (
            <div className="umc-fadein" style={{ maxWidth: 760, display: 'flex', flexDirection: 'column', gap: 'var(--space-6)' }}>
              <div>
                <h1 style={{ marginBottom: 4 }}>Create a meeting</h1>
                <p className="text-muted" style={{ margin: 0 }}>Pick a type below, or just start now — everything else is optional.</p>
              </div>

              {/* start now banner */}
              <div className="card elev-md" style={{ border: '1px solid var(--color-accent)', flexDirection: 'row', alignItems: 'center', gap: 'var(--space-4)', padding: 'var(--space-4)' }}>
                <Zap size={24} color="var(--color-accent)" strokeWidth={1.8} style={{ flex: 'none' }} />
                <div style={{ flex: 1 }}>
                  <div className="card-title">Start now</div>
                  <p className="card-body" style={{ margin: 0 }}>An instant camera hangout — share the link the moment it's live.</p>
                </div>
                <button className="btn btn-primary" onClick={startNow} disabled={creating} style={{ whiteSpace: 'nowrap' }}>
                  {creating ? 'Starting…' : 'Start now'}
                </button>
              </div>

              {/* type picker */}
              <div>
                <h6 style={{ marginBottom: 'var(--space-3)' }}>Meeting type</h6>
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit,minmax(130px,1fr))', gap: 'var(--space-3)' }}>
                  {TYPES.map(({ id, label, desc, Icon }) => {
                    const sel = id === meetingType;
                    return (
                      <div key={id} className="qa" onClick={() => selectType(id)} style={{
                        cursor: 'pointer', padding: 'var(--space-3)', borderRadius: 'var(--radius-md)',
                        background: sel ? 'var(--color-accent-900)' : 'var(--color-surface)',
                        boxShadow: sel ? '0 0 0 1px var(--color-accent)' : 'var(--shadow-sm)',
                        border: '1px solid transparent',
                      }}>
                        <Icon size={16} strokeWidth={1.8} color={sel ? 'var(--color-accent)' : 'var(--color-neutral-500)'} />
                        <div style={{ fontFamily: 'var(--font-heading)', fontSize: 14, marginTop: 8, color: sel ? 'var(--color-accent-100)' : 'var(--color-text)' }}>{label}</div>
                        <div className="text-muted" style={{ fontSize: 12, marginTop: 2 }}>{desc}</div>
                      </div>
                    );
                  })}
                </div>
              </div>

              {/* form card */}
              <div className="card elev-sm" style={{ padding: 'var(--space-6)', gap: 'var(--space-4)' }}>
                <div className="field">
                  <label htmlFor="umc-title">Title</label>
                  <input className="input" id="umc-title" value={form.title}
                    onChange={(e) => { setField({ title: e.target.value }); setTitleError(false); }}
                    placeholder="What's this meeting called?" />
                  {titleError && <div style={{ color: 'var(--color-accent-300)', fontSize: 12, marginTop: 4 }}>Please give your meeting a title.</div>}
                </div>
                <div className="field">
                  <label htmlFor="umc-desc">Description</label>
                  <textarea className="input" id="umc-desc" rows={3} value={form.description}
                    onChange={(e) => setField({ description: e.target.value })}
                    placeholder="Optional — what's it about?" />
                </div>

                {isScheduled && (
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 'var(--space-3)' }}>
                    <div className="field">
                      <label htmlFor="umc-start">Start time</label>
                      <input className="input" id="umc-start" type="datetime-local" value={form.startTime} onChange={(e) => setField({ startTime: e.target.value })} />
                    </div>
                    <div className="field">
                      <label htmlFor="umc-dur">Duration (min)</label>
                      <input className="input" id="umc-dur" type="number" min={15} step={15} value={form.duration} onChange={(e) => setField({ duration: e.target.value })} />
                    </div>
                    <div className="field">
                      <label htmlFor="umc-max">Max viewers</label>
                      <input className="input" id="umc-max" type="number" min={1} value={form.maxViewers} onChange={(e) => setField({ maxViewers: e.target.value })} />
                    </div>
                  </div>
                )}

                {isPrivate && (
                  <div className="field">
                    <label htmlFor="umc-invite">Invite by email</label>
                    <textarea className="input" id="umc-invite" rows={2} value={form.inviteEmails}
                      onChange={(e) => setField({ inviteEmails: e.target.value })} placeholder="comma-separated emails" />
                  </div>
                )}

                {isMeetup && (
                  <div className="field">
                    <label htmlFor="umc-loc">Location</label>
                    <div style={{ display: 'flex', gap: 'var(--space-2)' }}>
                      <input className="input" id="umc-loc" value={form.location} onChange={(e) => setField({ location: e.target.value })} placeholder="Add a location" />
                      <button type="button" className="btn btn-secondary btn-icon" onClick={detectLocation} title="Detect current location">
                        <MapPin size={16} strokeWidth={1.8} />
                      </button>
                    </div>
                    {locationDetecting && <div className="text-muted" style={{ fontSize: 12, marginTop: 4 }}>Detecting…</div>}
                  </div>
                )}

                {isDj && (
                  <label className="radio">
                    <input type="checkbox" checked={form.audioSignature} onChange={(e) => setField({ audioSignature: e.target.checked })} />
                    <span className="dot" style={{ borderRadius: 4 }} />
                    Generate an audio signature for smart listener matching
                  </label>
                )}

                <div className="field">
                  <label>Who can join</label>
                  <div className="seg">
                    {seg('umc-join', form.joinAccess, 'anyone', (v) => setField({ joinAccess: v }), 'Anyone')}
                    {seg('umc-join', form.joinAccess, 'registered', (v) => setField({ joinAccess: v }), 'Registered')}
                    {seg('umc-join', form.joinAccess, 'invite', (v) => setField({ joinAccess: v }), 'Invite only')}
                  </div>
                </div>

                {showBroadcast && (
                  <div className="field">
                    <label>Broadcast method</label>
                    <div className="seg">
                      {seg('umc-bcast', form.broadcastMethod, 'camera', (v) => setField({ broadcastMethod: v }), 'Camera')}
                      {seg('umc-bcast', form.broadcastMethod, 'screen', (v) => setField({ broadcastMethod: v }), 'Screen share')}
                      {seg('umc-bcast', form.broadcastMethod, 'obs', (v) => setField({ broadcastMethod: v }), 'OBS / RTMP')}
                    </div>
                  </div>
                )}

                <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 'var(--space-2)', marginTop: 'var(--space-2)' }}>
                  <button className="btn btn-secondary" onClick={resetForm}>Reset</button>
                  <button className="btn btn-primary" onClick={validateAndCreate} disabled={creating}>
                    {creating ? 'Creating…' : 'Create meeting'}
                  </button>
                </div>
              </div>
            </div>
          )}

          {view === 'ready' && (
            <div className="umc-fadein" style={{ display: 'flex', justifyContent: 'flex-start' }}>
              <div className="card elev-lg" style={{ width: 'min(560px,100%)', padding: 'var(--space-6)', gap: 'var(--space-4)' }}>
                <span className="tag tag-accent" style={{ alignSelf: 'flex-start' }}>{typeLabel}</span>
                <h2 style={{ margin: 0 }}>{form.title}</h2>
                <p className="text-muted" style={{ margin: 0 }}>
                  {createdRoom ? "You're ready to go. Share the link below or enter now." : "You're ready to go (preview). Share the link below or enter now."}
                </p>

                <div className="field">
                  <label>Watch / join link</label>
                  <div style={{ display: 'flex', gap: 'var(--space-2)' }}>
                    <input className="input" readOnly value={watchLink} />
                    <button className="btn btn-secondary" onClick={() => copyText(watchLink, 'link')} style={{ whiteSpace: 'nowrap' }}>
                      {copiedField === 'link' ? 'Copied' : 'Copy'}
                    </button>
                  </div>
                </div>

                {showObsPanel && (
                  <>
                    <div className="hr" />
                    <div className="card" style={{ background: 'var(--color-accent-900)', gap: 'var(--space-3)' }}>
                      <div className="card-kicker">Streaming to OBS</div>
                      <div className="field">
                        <label>Server URL</label>
                        <div style={{ display: 'flex', gap: 'var(--space-2)' }}>
                          <input className="input" readOnly value={rtmpServer} />
                          <button className="btn btn-secondary" onClick={() => copyText(rtmpServer, 'server')}>{copiedField === 'server' ? 'Copied' : 'Copy'}</button>
                        </div>
                      </div>
                      <div className="field">
                        <label>Stream key</label>
                        <div style={{ display: 'flex', gap: 'var(--space-2)' }}>
                          <input className="input" readOnly value={streamKey} />
                          <button className="btn btn-secondary" onClick={() => copyText(streamKey, 'key')}>{copiedField === 'key' ? 'Copied' : 'Copy'}</button>
                        </div>
                      </div>
                      <p className="text-muted" style={{ fontSize: 12, margin: 0 }}>Open OBS → Settings → Stream → Service: Custom → paste the Server URL and Stream key, then Start Streaming.</p>
                    </div>
                  </>
                )}

                <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 'var(--space-2)', marginTop: 'var(--space-2)' }}>
                  <button className="btn btn-secondary" onClick={backToCreate}>Back</button>
                  <button className="btn btn-primary" onClick={enterMeeting}>Enter meeting</button>
                </div>
              </div>
            </div>
          )}

          {view === 'lobby' && (
            <div className="umc-fadein" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-3)' }}>
                <h3 style={{ margin: 0 }}>{form.title || 'Meeting'}</h3>
                <span className="tag tag-accent-2">LIVE</span>
                <div style={{ flex: 1 }} />
                <button className="btn btn-secondary" onClick={backToCreate}>Leave</button>
              </div>

              <div style={{ display: 'flex', gap: 'var(--space-4)', alignItems: 'flex-start', flexWrap: 'wrap' }}>
                <div style={{ flex: 1, minWidth: 280, display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 'var(--space-3)' }}>
                  <div className="om-tile">
                    {camOn ? <div className="om-avatar">{initials}</div> : <span className="text-muted" style={{ fontSize: 12 }}>Camera off</span>}
                    <span className="tag tag-neutral" style={{ position: 'absolute', bottom: 8, left: 8 }}>You</span>
                  </div>
                  <div className="om-tile"><div className="om-avatar" style={{ background: 'var(--color-accent-2-800)', color: 'var(--color-accent-2-100)' }}>JR</div><span className="tag tag-neutral" style={{ position: 'absolute', bottom: 8, left: 8 }}>Jordan</span></div>
                  <div className="om-tile"><div className="om-avatar">AL</div><span className="tag tag-neutral" style={{ position: 'absolute', bottom: 8, left: 8 }}>Alex</span></div>
                  <div className="om-tile"><span className="text-muted" style={{ fontSize: 12 }}>Waiting for others…</span></div>
                </div>

                <div className="card elev-sm" style={{ width: 280, flex: 'none', padding: 'var(--space-3)', gap: 'var(--space-3)', height: 340 }}>
                  <div className="card-kicker">Chat</div>
                  <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 'var(--space-2)', overflow: 'auto' }}>
                    <div style={{ fontSize: 13 }}><strong>Jordan</strong> <span className="text-muted">joined the room</span></div>
                    <div style={{ fontSize: 13 }}><strong>Alex</strong> <span className="text-muted">can you hear me ok?</span></div>
                    <div style={{ fontSize: 13 }}><strong>You</strong> <span className="text-muted">loud and clear</span></div>
                  </div>
                  <input className="input" placeholder="Send a message…" />
                </div>
              </div>

              <div style={{ display: 'flex', justifyContent: 'center', gap: 'var(--space-3)', padding: 'var(--space-3) 0' }}>
                <div className={`om-ctrl ${micOn ? 'om-ctrl-on' : ''}`} onClick={() => setMicOn((v) => !v)} title="Toggle microphone">
                  {micOn ? <Mic size={18} /> : <MicOff size={18} />}
                </div>
                <div className={`om-ctrl ${camOn ? 'om-ctrl-on' : ''}`} onClick={() => setCamOn((v) => !v)} title="Toggle camera">
                  <Video size={18} />
                </div>
                <div className={`om-ctrl ${screenOn ? 'om-ctrl-on' : ''}`} onClick={() => setScreenOn((v) => !v)} title="Toggle screen share">
                  <ScreenShare size={18} />
                </div>
                <div className="om-ctrl" onClick={backToCreate} title="Leave meeting" style={{ color: 'var(--color-accent-300)' }}>
                  <PhoneOff size={18} />
                </div>
              </div>
            </div>
          )}

          {view === 'meetings' && (
            <div className="umc-fadein" style={{ maxWidth: 900 }}>
              <h1 style={{ fontSize: 26, letterSpacing: '-.02em', margin: '0 0 4px' }}>My meetings</h1>
              <p className="text-muted" style={{ margin: '0 0 20px' }}>Everything you created or joined.</p>
              <div style={{ borderRadius: 10, background: 'var(--color-surface)', boxShadow: 'var(--shadow-sm)', overflow: 'hidden' }}>
                {MEETINGS.map((m, i) => (
                  <div key={i} className="rw" style={{ display: 'flex', alignItems: 'center', gap: 14, padding: '13px 16px', borderTop: '1px solid var(--color-divider)' }}>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <p style={{ margin: 0, fontSize: 13.5 }}>{m.title}</p>
                      <p style={{ margin: '1px 0 0', fontSize: 11.5, color: 'var(--color-neutral-600)' }}>{m.when}</p>
                    </div>
                    <span className="tag tag-neutral">{m.tag}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {view === 'contacts' && (
            <div className="umc-fadein" style={{ maxWidth: 900 }}>
              <h1 style={{ fontSize: 26, letterSpacing: '-.02em', margin: '0 0 4px' }}>Contacts</h1>
              <p className="text-muted" style={{ margin: '0 0 20px' }}>People you meet with often.</p>
              <div style={{ borderRadius: 10, background: 'var(--color-surface)', boxShadow: 'var(--shadow-sm)', overflow: 'hidden' }}>
                {CONTACTS.map((c, i) => (
                  <div key={i} className="rw" style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '12px 16px', borderTop: '1px solid var(--color-divider)' }}>
                    <span style={{ width: 26, height: 26, flex: 'none', borderRadius: '50%', display: 'grid', placeItems: 'center', background: 'var(--color-neutral-800)', color: 'var(--color-neutral-300)', fontSize: 10.5 }}>{c.ini}</span>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <p style={{ margin: 0, fontSize: 12.5 }}>{c.name}</p>
                      <p style={{ margin: 0, fontSize: 11, color: 'var(--color-neutral-600)' }}>{c.sub}</p>
                    </div>
                    <span style={{ fontSize: 11, color: 'var(--color-neutral-600)' }}>{c.last}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {view === 'settings' && (
            <div className="umc-fadein" style={{ maxWidth: 900, display: 'flex', flexDirection: 'column', gap: 14 }}>
              <h1 style={{ fontSize: 26, letterSpacing: '-.02em', margin: '0 0 4px' }}>Settings</h1>
              <div style={{ borderRadius: 10, background: 'var(--color-surface)', boxShadow: 'var(--shadow-sm)', overflow: 'hidden' }}>
                <p style={{ margin: 0, padding: '12px 16px', borderBottom: '1px solid var(--color-divider)', fontSize: 11, letterSpacing: '.09em', textTransform: 'uppercase', color: 'var(--color-neutral-500)' }}>Meeting defaults</p>
                {[['Default type', 'Used when you skip the picker', 'Instant'], ['Default join access', 'Who can join without an invite', 'Anyone'], ['Camera on by default', '', 'Yes']].map(([t, s, v], i, arr) => (
                  <div key={t} className="rw" style={{ display: 'flex', alignItems: 'center', gap: 14, padding: '12px 16px', borderBottom: i < arr.length - 1 ? '1px solid var(--color-divider)' : 'none' }}>
                    <div style={{ flex: 1 }}>
                      <p style={{ margin: 0, fontSize: 13 }}>{t}</p>
                      {s && <p style={{ margin: '1px 0 0', fontSize: 11.5, color: 'var(--color-neutral-600)' }}>{s}</p>}
                    </div>
                    <span style={{ fontSize: 12.5, color: 'var(--color-accent-300)' }}>{v}</span>
                  </div>
                ))}
              </div>
              <div style={{ borderRadius: 10, background: 'var(--color-surface)', boxShadow: 'var(--shadow-sm)', overflow: 'hidden' }}>
                <p style={{ margin: 0, padding: '12px 16px', borderBottom: '1px solid var(--color-divider)', fontSize: 11, letterSpacing: '.09em', textTransform: 'uppercase', color: 'var(--color-neutral-500)' }}>Account</p>
                {[['Plan', currentUser?.isAnonymous ? 'Guest' : 'Free'], ['Timezone', 'Local']].map(([t, v], i, arr) => (
                  <div key={t} className="rw" style={{ display: 'flex', alignItems: 'center', gap: 14, padding: '12px 16px', borderBottom: i < arr.length - 1 ? '1px solid var(--color-divider)' : 'none' }}>
                    <div style={{ flex: 1 }}><p style={{ margin: 0, fontSize: 13 }}>{t}</p></div>
                    <span style={{ fontSize: 12.5, color: 'var(--color-accent-300)' }}>{v}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </main>
      </div>

      {/* ── bottom-sheet scrim (mobile, full detent) ── */}
      {mobile && detent === 2 && (
        <div onClick={() => setDetent(1)} style={{ position: 'fixed', inset: 0, zIndex: 55, background: 'rgba(0,0,0,.42)' }} />
      )}

      {/* ── right tool panel / rail / bottom sheet ── */}
      <ToolPanel
        mobile={mobile} wide={wide} detent={detent} sheetH={sheetH}
        panelOpen={mobile ? detent > 0 : wide} railOpen={!mobile && !wide}
        tab={tab} setTab={setTab} setPanel={setPanel} setDetent={setDetent}
        tabMeta={tabMeta} selectType={selectType} inviteContact={inviteContact}
      />

      {/* ── mobile bottom nav ── */}
      {mobile && (
        <nav style={{ position: 'fixed', left: 0, right: 0, bottom: 0, zIndex: 70, display: 'flex', borderTop: '1px solid var(--color-divider)', background: 'var(--color-surface)', padding: '6px 0 10px' }}>
          {[
            { Icon: Plus, label: 'Create', on: view === 'create', go: () => go('create') },
            { Icon: LayoutList, label: 'Meetings', on: view === 'meetings', go: () => go('meetings') },
            { Icon: Search, label: 'Search', on: cmd, go: () => { setCmd(true); setQ(''); } },
            { Icon: Users, label: 'Contacts', on: view === 'contacts', go: () => go('contacts') },
          ].map(({ Icon, label, on, go: onGo }) => (
            <button key={label} className="bn" data-on={on ? '1' : '0'} onClick={onGo} style={{ flex: 1, minHeight: 46, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 3, padding: '4px 0', border: 0, background: 'transparent', color: 'var(--color-neutral-600)', font: 'inherit', fontSize: 10.5, cursor: 'pointer' }}>
              <Icon size={20} strokeWidth={1.8} />{label}
            </button>
          ))}
        </nav>
      )}

      {/* ── command palette ── */}
      {cmd && (
        <div onClick={() => setCmd(false)} style={{ position: 'fixed', inset: 0, zIndex: 80, background: 'color-mix(in srgb,#161826 72%,transparent)', backdropFilter: 'blur(3px)', display: 'flex', justifyContent: 'center', alignItems: 'flex-start', padding: mobile ? 0 : '12vh 20px 20px' }}>
          <div onClick={(e) => e.stopPropagation()} style={{ width: mobile ? '100%' : 'min(680px,100%)', height: mobile ? '100%' : 'auto', borderRadius: mobile ? 0 : 14, background: 'var(--color-surface)', boxShadow: 'var(--shadow-lg)', overflow: 'hidden', display: 'flex', flexDirection: 'column', maxHeight: mobile ? '100vh' : '70vh' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 11, padding: '14px 18px', borderBottom: '1px solid var(--color-divider)' }}>
              <Search size={17} color="var(--color-accent)" strokeWidth={1.8} />
              <input autoFocus placeholder="Meetings, contacts, actions…" value={q} onChange={(e) => setQ(e.target.value)} style={{ flex: 1, border: 0, background: 'transparent', color: 'var(--color-text)', font: 'inherit', fontSize: 15, outline: 'none' }} />
              <span style={{ fontSize: 10.5, padding: '3px 7px', borderRadius: 4, border: '1px solid var(--color-divider)', color: 'var(--color-neutral-600)' }}>esc</span>
            </div>
            <div style={{ flex: 1, overflowY: 'auto', padding: 8 }}>
              {cmdGroups.map((g) => (
                <div key={g.group} style={{ padding: '8px 10px 2px' }}>
                  <p style={{ margin: '0 0 4px', fontSize: 10, letterSpacing: '.11em', textTransform: 'uppercase', color: 'var(--color-neutral-600)' }}>{g.group}</p>
                  {g.items.map((r, i) => (
                    <button key={i} className="cmd" onClick={() => runCommand(r)} style={{ display: 'flex', alignItems: 'center', gap: 11, width: '100%', padding: '9px 10px', border: 0, borderRadius: 8, background: 'transparent', color: 'inherit', font: 'inherit', textAlign: 'left', cursor: 'pointer' }}>
                      <r.Icon size={15} color="var(--color-accent)" strokeWidth={1.8} style={{ flex: 'none' }} />
                      <span style={{ flex: 1, minWidth: 0, fontSize: 13.5 }}>{r.label}</span>
                      <span style={{ fontSize: 11, color: 'var(--color-neutral-600)' }}>{r.meta}</span>
                    </button>
                  ))}
                </div>
              ))}
              {cmdGroups.length === 0 && (
                <p style={{ margin: 0, padding: '26px 12px', textAlign: 'center', fontSize: 13, color: 'var(--color-neutral-600)' }}>Nothing matches that yet.</p>
              )}
            </div>
            {!mobile && (
              <div style={{ display: 'flex', gap: 16, padding: '9px 16px', borderTop: '1px solid var(--color-divider)', fontSize: 11, color: 'var(--color-neutral-600)' }}>
                <span>↑↓ navigate</span><span>↵ open</span><span>⌘K anywhere</span>
                <span style={{ marginLeft: 'auto' }}>Searches meetings, contacts and actions</span>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

/* ── right tool panel (extracted for readability) ─────────────────────── */

function ToolPanel({ mobile, wide, detent, sheetH, panelOpen, railOpen, tab, setTab, setPanel, setDetent, tabMeta, selectType, inviteContact }) {
  const panelWidth = mobile ? '100%' : wide ? 340 : 48;
  const asideStyle = {
    width: panelWidth,
    height: mobile ? sheetH : 'auto',
    position: mobile ? 'fixed' : 'static',
    left: 0,
    bottom: mobile ? (detent === 2 ? 0 : 62) : 'auto',
    zIndex: 60,
    flex: 'none',
    display: 'flex',
    flexDirection: 'column',
    background: 'var(--color-surface)',
    borderLeft: mobile ? 'none' : '1px solid var(--color-divider)',
    borderTop: mobile ? '1px solid var(--color-accent-800)' : 'none',
    borderRadius: mobile && detent > 0 ? '16px 16px 0 0' : 0,
    boxShadow: mobile ? '0 -12px 30px rgba(0,0,0,.45)' : 'none',
    transition: 'height .24s ease',
    overflow: 'hidden',
  };

  return (
    <aside style={asideStyle}>
      {/* peek teaser (mobile, detent 0) */}
      {mobile && detent === 0 && (
        <button onClick={() => setDetent(1)} style={{ width: '100%', border: 0, background: 'transparent', color: 'inherit', font: 'inherit', cursor: 'pointer', textAlign: 'left', padding: 0 }}>
          <div style={{ padding: '7px 0 4px', display: 'grid', placeItems: 'center' }}>
            <span style={{ width: 36, height: 4, borderRadius: 2, background: 'var(--color-neutral-700)' }} />
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 11, padding: '2px 16px 14px' }}>
            <Zap size={16} color="var(--color-accent)" strokeWidth={1.9} />
            <span style={{ flex: 1, fontSize: 13.5 }}>Quick-start templates</span>
            <span className="tag tag-accent" style={{ fontSize: 10.5, padding: '2px 8px' }}>5</span>
          </div>
        </button>
      )}

      {panelOpen && (
        <div style={{ display: 'flex', flexDirection: 'column', height: '100%', width: mobile ? '100%' : 340 }}>
          {mobile && (
            <>
              <div style={{ position: 'relative', display: 'flex', alignItems: 'center', padding: '8px 12px 6px' }}>
                <button onClick={() => setDetent((d) => (d === 2 ? 1 : 2))} style={{ flex: 1, border: 0, background: 'transparent', padding: '4px 0', cursor: 'pointer' }}>
                  <span style={{ display: 'block', width: 36, height: 4, borderRadius: 2, background: 'var(--color-neutral-600)', margin: '0 auto' }} />
                </button>
                <button onClick={() => setDetent(0)} style={{ position: 'absolute', right: 8, top: 4, width: 36, height: 36, display: 'grid', placeItems: 'center', border: 0, background: 'transparent', color: 'var(--color-neutral-500)', borderRadius: 8, cursor: 'pointer' }}>
                  <X size={17} strokeWidth={1.9} />
                </button>
              </div>
              <div style={{ display: 'flex', gap: 16, padding: '0 16px', borderBottom: '1px solid var(--color-divider)', overflowX: 'auto' }}>
                {TABS.map((t) => (
                  <button key={t.id} className="tb" data-on={tab === t.id ? '1' : '0'} onClick={() => setTab(t.id)} style={{ flex: 'none', padding: '8px 0 9px', border: 0, background: 'transparent', font: 'inherit', fontSize: 12.5, cursor: 'pointer', whiteSpace: 'nowrap' }}>{t.label}</button>
                ))}
              </div>
            </>
          )}

          {!mobile && (
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, padding: '8px 10px', borderBottom: '1px solid var(--color-divider)' }}>
              {TABS.map((t) => (
                <button key={t.id} className="tb" data-on={tab === t.id ? '1' : '0'} onClick={() => setTab(t.id)} title={t.label} style={{ flex: 1, display: 'grid', placeItems: 'center', padding: '7px 0', border: 0, background: 'transparent', color: 'var(--color-neutral-600)', cursor: 'pointer' }}>
                  <t.Icon size={16} strokeWidth={1.8} />
                </button>
              ))}
            </div>
          )}

          <div style={{ padding: '12px 14px 6px' }}>
            <p style={{ margin: 0, fontSize: 11, letterSpacing: '.1em', textTransform: 'uppercase', color: 'var(--color-accent)' }}>{tabMeta.label}</p>
            <p style={{ margin: '3px 0 0', fontSize: 11.5, color: 'var(--color-neutral-600)' }}>{tabMeta.hint}</p>
          </div>

          <div style={{ flex: 1, overflowY: 'auto', padding: '8px 14px 16px' }}>
            {tab === 'templates' && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 9 }}>
                {TYPES.map((t) => (
                  <div key={t.id} className="qa" onClick={() => selectType(t.id)} style={{ display: 'flex', alignItems: 'center', gap: 10, borderRadius: 9, padding: '11px 12px', background: 'var(--color-bg)', border: '1px solid var(--color-divider)', cursor: 'pointer' }}>
                    <t.Icon size={15} color="var(--color-accent)" strokeWidth={1.8} style={{ flex: 'none' }} />
                    <div style={{ minWidth: 0, flex: 1 }}>
                      <p style={{ margin: 0, fontSize: 12.5 }}>{t.label}</p>
                      <p style={{ margin: '1px 0 0', fontSize: 11, color: 'var(--color-neutral-600)' }}>{t.desc}</p>
                    </div>
                  </div>
                ))}
              </div>
            )}
            {tab === 'recent' && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 9 }}>
                {RECENT.map((r, i) => (
                  <div key={i} style={{ borderRadius: 9, padding: 12, background: 'var(--color-bg)', border: '1px solid var(--color-divider)' }}>
                    <p style={{ margin: '0 0 3px', fontSize: 12.5 }}>{r.title}</p>
                    <p style={{ margin: 0, fontSize: 11, color: 'var(--color-neutral-600)' }}>{r.when} · {r.tag}</p>
                  </div>
                ))}
              </div>
            )}
            {tab === 'contacts' && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 9 }}>
                {CONTACTS.map((c, i) => (
                  <div key={i} className="qa" onClick={() => inviteContact(c.name)} style={{ display: 'flex', alignItems: 'center', gap: 10, borderRadius: 9, padding: '10px 12px', background: 'var(--color-bg)', border: '1px solid var(--color-divider)', cursor: 'pointer' }}>
                    <span style={{ width: 24, height: 24, flex: 'none', borderRadius: '50%', display: 'grid', placeItems: 'center', background: 'var(--color-neutral-800)', color: 'var(--color-neutral-300)', fontSize: 10 }}>{c.ini}</span>
                    <div style={{ minWidth: 0, flex: 1 }}>
                      <p style={{ margin: 0, fontSize: 12.5 }}>{c.name}</p>
                      <p style={{ margin: 0, fontSize: 11, color: 'var(--color-neutral-600)' }}>{c.sub}</p>
                    </div>
                    <span style={{ fontSize: 10.5, color: 'var(--color-accent-300)' }}>Invite</span>
                  </div>
                ))}
              </div>
            )}
            {tab === 'notes' && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                <textarea className="input" placeholder="Scratchpad for this meeting…" style={{ minHeight: 190, fontSize: 13, lineHeight: 1.55 }} />
                <button className="btn btn-primary btn-block" style={{ fontSize: 12.5 }}>Save</button>
              </div>
            )}
          </div>
        </div>
      )}

      {railOpen && (
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4, padding: '10px 0', width: 48 }}>
          {TABS.map((t) => (
            <button key={t.id} className="icb" onClick={() => { setTab(t.id); setPanel(true); }} title={t.label} style={{ width: 34, height: 34, display: 'grid', placeItems: 'center', border: 0, borderRadius: 8, background: 'transparent', color: 'var(--color-neutral-600)', cursor: 'pointer' }}>
              <t.Icon size={16} strokeWidth={1.8} />
            </button>
          ))}
        </div>
      )}
    </aside>
  );
}
