// src/admin/components/SubscriptionManagement.jsx
import React, { useState, useEffect } from 'react';
import { 
  collection, 
  query, 
  orderBy, 
  limit, 
  getDocs, 
  doc, 
  updateDoc, 
  getDoc,
  where,
  startAfter
} from 'firebase/firestore';
import { db } from '../../firebase';
import { Search, Crown, X, RefreshCw, AlertTriangle, Check, Calendar, User, Music } from 'lucide-react';
import './SubscriptionManagement.css';

const SubscriptionManagement = () => {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [actionLoading, setActionLoading] = useState(false);
  const [message, setMessage] = useState({ type: '', text: '' });
  const [filter, setFilter] = useState('all'); // 'all', 'premium', 'free', 'artists'

  // Load users with subscription data
  const loadUsers = async (searchEmail = '', filterType = 'all') => {
    setLoading(true);
    try {
      let q;
      
      if (searchEmail) {
        // Search by email - exclude anonymous users
        q = query(
          collection(db, 'users'),
          where('email', '>=', searchEmail),
          where('email', '<=', searchEmail + '\uf8ff'),
          where('isAnonymous', '!=', true), // Exclude anonymous users
          limit(20)
        );
      } else {
        // Load users based on filter
        if (filterType === 'premium') {
          q = query(
            collection(db, 'users'),
            where('isPremium', '==', true),
            where('isAnonymous', '!=', true), // Exclude anonymous users
            orderBy('premiumStartDate', 'desc'),
            limit(50)
          );
        } else if (filterType === 'free') {
          q = query(
            collection(db, 'users'),
            where('isPremium', '==', false),
            where('isAnonymous', '!=', true), // Exclude anonymous users
            orderBy('email'),
            limit(50)
          );
        } else if (filterType === 'artists') {
          q = query(
            collection(db, 'users'),
            where('isArtist', '==', true),
            where('isAnonymous', '!=', true), // Exclude anonymous users
            orderBy('email'),
            limit(50)
          );
        } else {
          // All users - exclude anonymous
          q = query(
            collection(db, 'users'),
            where('isAnonymous', '!=', true), // Exclude anonymous users
            orderBy('email'),
            limit(50)
          );
        }
      }

      const snapshot = await getDocs(q);
      const usersData = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      })).filter(user => {
        // Additional client-side filtering to ensure we only show registered users
        return user.email && 
               user.email.includes('@') && 
               !user.isAnonymous && 
               user.email !== 'anonymous@example.com';
      });

      if (searchEmail) {
        setSearchResults(usersData);
      } else {
        setUsers(usersData);
      }
    } catch (error) {
      console.error('Error loading users:', error);
      
      // If the compound query fails (likely due to missing index), fall back to simpler query
      if (error.code === 'failed-precondition') {
        console.log('Falling back to simpler query without compound index');
        try {
          let fallbackQuery;
          
          if (searchEmail) {
            fallbackQuery = query(
              collection(db, 'users'),
              where('email', '>=', searchEmail),
              where('email', '<=', searchEmail + '\uf8ff'),
              limit(20)
            );
          } else {
            if (filterType === 'premium') {
              fallbackQuery = query(
                collection(db, 'users'),
                where('isPremium', '==', true),
                limit(50)
              );
            } else if (filterType === 'artists') {
              fallbackQuery = query(
                collection(db, 'users'),
                where('isArtist', '==', true),
                limit(50)
              );
            } else {
              fallbackQuery = query(
                collection(db, 'users'),
                orderBy('email'),
                limit(50)
              );
            }
          }
          
          const snapshot = await getDocs(fallbackQuery);
          const usersData = snapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data()
          })).filter(user => {
            // Filter out anonymous users client-side
            const isRegistered = user.email && 
                               user.email.includes('@') && 
                               !user.isAnonymous && 
                               user.email !== 'anonymous@example.com';
            
            // Apply filter type
            if (filterType === 'premium') {
              return isRegistered && user.isPremium === true;
            } else if (filterType === 'free') {
              return isRegistered && user.isPremium !== true;
            } else if (filterType === 'artists') {
              return isRegistered && user.isArtist === true;
            }
            return isRegistered;
          });
          
          if (searchEmail) {
            setSearchResults(usersData);
          } else {
            setUsers(usersData);
          }
        } catch (fallbackError) {
          console.error('Fallback query also failed:', fallbackError);
          setMessage({ type: 'error', text: 'Failed to load users: ' + fallbackError.message });
        }
      } else {
        setMessage({ type: 'error', text: 'Failed to load users: ' + error.message });
      }
    } finally {
      setLoading(false);
    }
  };

  // Search users
  const handleSearch = async () => {
    if (!searchTerm.trim()) {
      setSearchResults([]);
      return;
    }
    await loadUsers(searchTerm.toLowerCase());
  };

  // Reset user subscription
  const resetUserSubscription = async (userId, userEmail) => {
    if (!window.confirm(`Are you sure you want to reset the subscription for ${userEmail}?`)) {
      return;
    }

    setActionLoading(true);
    try {
      const userRef = doc(db, 'users', userId);
      
      await updateDoc(userRef, {
        isPremium: false,
        premiumTier: null,
        premiumStartDate: null,
        premiumEndDate: null,
        subscriptionLastUpdated: new Date(),
        adminResetDate: new Date(),
        adminResetReason: 'Admin panel reset'
      });

      setMessage({ 
        type: 'success', 
        text: `Successfully reset subscription for ${userEmail}` 
      });

      // Refresh the user lists
      loadUsers();
      if (searchTerm) {
        handleSearch();
      }

      // Update selected user if it's the one we just reset
      if (selectedUser && selectedUser.id === userId) {
        const updatedUser = await getDoc(userRef);
        setSelectedUser({ id: userId, ...updatedUser.data() });
      }

    } catch (error) {
      console.error('Error resetting subscription:', error);
      setMessage({ 
        type: 'error', 
        text: 'Failed to reset subscription: ' + error.message 
      });
    } finally {
      setActionLoading(false);
    }
  };

  // Grant premium access
  const grantPremiumAccess = async (userId, userEmail, days = 30) => {
    const customDays = prompt(`Grant premium access for how many days?`, days.toString());
    if (!customDays || isNaN(customDays)) return;

    const durationDays = parseInt(customDays);
    if (durationDays <= 0) return;

    setActionLoading(true);
    try {
      const now = new Date();
      const endDate = new Date(now.getTime() + (durationDays * 24 * 60 * 60 * 1000));

      const userRef = doc(db, 'users', userId);
      
      await updateDoc(userRef, {
        isPremium: true,
        premiumTier: 'Premium',
        premiumStartDate: now,
        premiumEndDate: endDate,
        subscriptionLastUpdated: now,
        adminGrantedDate: now,
        adminGrantedDays: durationDays
      });

      setMessage({ 
        type: 'success', 
        text: `Granted ${durationDays} days of premium access to ${userEmail}` 
      });

      // Refresh the user lists
      loadUsers();
      if (searchTerm) {
        handleSearch();
      }

    } catch (error) {
      console.error('Error granting premium access:', error);
      setMessage({ 
        type: 'error', 
        text: 'Failed to grant premium access: ' + error.message 
      });
    } finally {
      setActionLoading(false);
    }
  };

  // Load initial data
  useEffect(() => {
    loadUsers('', filter);
  }, [filter]);

  // Clear message after 5 seconds
  useEffect(() => {
    if (message.text) {
      const timer = setTimeout(() => {
        setMessage({ type: '', text: '' });
      }, 5000);
      return () => clearTimeout(timer);
    }
  }, [message]);

  return (
    <div className="subscription-management">
      <div className="subscription-header">
        <h2>Subscription Management</h2>
        <p>Manage user subscriptions and premium access for registered users only</p>
        <div className="filter-info">
          <small>📧 Only showing registered users with valid email addresses (anonymous users are excluded)</small>
        </div>
      </div>

      {/* Message Display */}
      {message.text && (
        <div className={`message ${message.type}`}>
          {message.type === 'success' ? <Check size={16} /> : <AlertTriangle size={16} />}
          <span>{message.text}</span>
          <button onClick={() => setMessage({ type: '', text: '' })}>
            <X size={14} />
          </button>
        </div>
      )}

      {/* Search Section */}
      <div className="search-section">
        <div className="search-bar">
          <Search className="search-icon" />
          <input
            type="email"
            placeholder="Search by email address..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSearch()}
          />
          <button onClick={handleSearch} disabled={loading}>
            Search
          </button>
        </div>
      </div>

      {/* Filter Tabs */}
      <div className="filter-tabs">
        <button 
          className={filter === 'all' ? 'active' : ''}
          onClick={() => setFilter('all')}
          disabled={loading}
        >
          All Users
        </button>
        <button 
          className={filter === 'premium' ? 'active' : ''}
          onClick={() => setFilter('premium')}
          disabled={loading}
        >
          <Crown size={16} />
          Premium Users
        </button>
        <button 
          className={filter === 'free' ? 'active' : ''}
          onClick={() => setFilter('free')}
          disabled={loading}
        >
          Free Users
        </button>
        <button 
          className={filter === 'artists' ? 'active' : ''}
          onClick={() => setFilter('artists')}
          disabled={loading}
        >
          <Music size={16} />
          Artists
        </button>
        <button onClick={() => loadUsers('', filter)} disabled={loading}>
          <RefreshCw size={16} />
          Refresh
        </button>
      </div>

      {/* Search Results */}
      {searchResults.length > 0 && (
        <div className="search-results">
          <h3>Search Results</h3>
          <div className="users-grid">
            {searchResults.map(user => (
              <UserCard 
                key={user.id}
                user={user}
                onReset={resetUserSubscription}
                onGrant={grantPremiumAccess}
                onSelect={setSelectedUser}
                actionLoading={actionLoading}
              />
            ))}
          </div>
        </div>
      )}

      {/* All Users List */}
      <div className="users-section">
        <h3>
          {filter === 'premium' ? 'Premium Users' : 
           filter === 'free' ? 'Free Users' : 
           filter === 'artists' ? 'Artists' : 'All Users'}
          {!loading && ` (${users.length})`}
        </h3>
        
        {loading ? (
          <div className="loading-container">
            <RefreshCw className="loading-spinner" />
            <p>Loading users...</p>
          </div>
        ) : (
          <div className="users-grid">
            {users.map(user => (
              <UserCard 
                key={user.id}
                user={user}
                onReset={resetUserSubscription}
                onGrant={grantPremiumAccess}
                onSelect={setSelectedUser}
                actionLoading={actionLoading}
              />
            ))}
          </div>
        )}
      </div>

      {/* User Details Modal */}
      {selectedUser && (
        <UserDetailsModal 
          user={selectedUser}
          onClose={() => setSelectedUser(null)}
          onReset={resetUserSubscription}
          onGrant={grantPremiumAccess}
          actionLoading={actionLoading}
        />
      )}
    </div>
  );
};

// User Card Component
const UserCard = ({ user, onReset, onGrant, onSelect, actionLoading }) => {
  const isPremium = user.isPremium === true;
  const isArtist = user.isArtist === true;
  const isExpired = isPremium && user.premiumEndDate && 
    new Date(user.premiumEndDate.seconds ? user.premiumEndDate.seconds * 1000 : user.premiumEndDate) < new Date();
  
  // Check if this is an anonymous user (shouldn't happen but just in case)
  const isAnonymous = user.isAnonymous || !user.email || user.email === 'anonymous@example.com';
  
  if (isAnonymous) {
    // Don't render anonymous users
    return null;
  }

  return (
    <div className={`user-card ${isPremium ? 'premium' : 'free'} ${isExpired ? 'expired' : ''} ${isArtist ? 'artist' : ''}`}>
      <div className="user-info">
        <div className="user-avatar">
          {user.photoURL ? (
            <img src={user.photoURL} alt={user.displayName} />
          ) : (
            <User />
          )}
          {isArtist && (
            <div className="artist-badge">
              <Music size={12} />
            </div>
          )}
        </div>
        <div className="user-details">
          <h4>
            {user.displayName || 'No Name'}
            {isPremium && !isExpired && <Crown className="premium-icon" />}
            {isArtist && <Music className="artist-icon" />}
          </h4>
          <p className="user-email">{user.email}</p>
          <div className="subscription-status">
            {isPremium ? (
              <span className={`status ${isExpired ? 'expired' : 'active'}`}>
                {isExpired ? 'Expired Premium' : 'Premium Active'}
              </span>
            ) : (
              <span className="status free">Free Account</span>
            )}
            {isArtist && (
              <span className="status artist">
                Artist
              </span>
            )}
          </div>
          {isPremium && user.premiumEndDate && (
            <div className="premium-details">
              <Calendar size={12} />
              <small>
                Expires: {new Date(user.premiumEndDate.seconds ? 
                  user.premiumEndDate.seconds * 1000 : 
                  user.premiumEndDate
                ).toLocaleDateString()}
              </small>
            </div>
          )}
          {/* Show registration info */}
          <div className="registration-info">
            <small>
              📧 Registered User
              {isArtist && <span> • 🎵 Verified Artist</span>}
              {user.createdAt && (
                <span> • {new Date(user.createdAt.seconds ? 
                  user.createdAt.seconds * 1000 : 
                  user.createdAt
                ).toLocaleDateString()}</span>
              )}
            </small>
          </div>
        </div>
      </div>
      
      <div className="user-actions">
        <button 
          onClick={() => onSelect(user)}
          className="btn btn-secondary btn-sm"
        >
          View Details
        </button>
        {isPremium ? (
          <button 
            onClick={() => onReset(user.id, user.email)}
            disabled={actionLoading}
            className="btn btn-danger btn-sm"
          >
            Reset Subscription
          </button>
        ) : (
          <button 
            onClick={() => onGrant(user.id, user.email)}
            disabled={actionLoading}
            className="btn btn-primary btn-sm"
          >
            Grant Premium
          </button>
        )}
      </div>
    </div>
  );
};

// User Details Modal Component
const UserDetailsModal = ({ user, onClose, onReset, onGrant, actionLoading }) => {
  const isPremium = user.isPremium === true;
  const isArtist = user.isArtist === true;
  
  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-content" onClick={e => e.stopPropagation()}>
        <div className="modal-header">
          <h3>User Details</h3>
          <button onClick={onClose} className="close-btn">
            <X />
          </button>
        </div>
        
        <div className="modal-body">
          <div className="user-profile">
            <div className="profile-avatar">
              {user.photoURL ? (
                <img src={user.photoURL} alt={user.displayName} />
              ) : (
                <User size={48} />
              )}
              {isArtist && (
                <div className="artist-badge large">
                  <Music size={16} />
                </div>
              )}
            </div>
            <div className="profile-info">
              <h4>
                {user.displayName || 'No Name'}
                {isArtist && <Music className="artist-icon" />}
              </h4>
              <p>{user.email}</p>
              {isArtist && (
                <div className="artist-indicator">
                  🎵 Verified Artist
                </div>
              )}
            </div>
          </div>

          <div className="details-grid">
            <div className="detail-item">
              <strong>User ID:</strong>
              <div className="debug-value">
                <code>{user.id}</code>
                <button 
                  onClick={() => navigator.clipboard.writeText(user.id)} 
                  className="copy-btn"
                  title="Copy User ID"
                >
                  📋
                </button>
              </div>
            </div>
            <div className="detail-item">
              <strong>Account Type:</strong>
              <div className="account-types">
                <span className={`status ${isPremium ? 'active' : 'free'}`}>
                  {isPremium ? 'Premium' : 'Free'}
                </span>
                {isArtist && (
                  <span className="status artist">
                    Artist
                  </span>
                )}
              </div>
            </div>
            {isPremium && (
              <>
                <div className="detail-item">
                  <strong>Premium Tier:</strong>
                  <span>{user.premiumTier || 'Premium'}</span>
                </div>
                {user.premiumStartDate && (
                  <div className="detail-item">
                    <strong>Started:</strong>
                    <span>
                      {new Date(user.premiumStartDate.seconds ? 
                        user.premiumStartDate.seconds * 1000 : 
                        user.premiumStartDate
                      ).toLocaleDateString()}
                    </span>
                  </div>
                )}
                {user.premiumEndDate && (
                  <div className="detail-item">
                    <strong>Expires:</strong>
                    <span>
                      {new Date(user.premiumEndDate.seconds ? 
                        user.premiumEndDate.seconds * 1000 : 
                        user.premiumEndDate
                      ).toLocaleDateString()}
                    </span>
                  </div>
                )}
                {user.transactions && user.transactions.length > 0 && (
                  <div className="detail-item">
                    <strong>Last Transaction:</strong>
                    <span>${user.transactions[user.transactions.length - 1].amount}</span>
                  </div>
                )}
              </>
            )}
          </div>
        </div>

        <div className="modal-actions">
          {isPremium ? (
            <button 
              onClick={() => onReset(user.id, user.email)}
              disabled={actionLoading}
              className="btn btn-danger"
            >
              Reset Subscription
            </button>
          ) : (
            <button 
              onClick={() => onGrant(user.id, user.email)}
              disabled={actionLoading}
              className="btn btn-primary"
            >
              Grant Premium Access
            </button>
          )}
          <button onClick={onClose} className="btn btn-secondary">
            Close
          </button>
        </div>
      </div>
    </div>
  );
};

export default SubscriptionManagement;