// src/components/WidgetManager.jsx
import React, { useState } from 'react';
import { useSiteConfig } from '../contexts/SiteConfigContext';
import { X, ChevronUp, ChevronDown, Check, Settings, Eye, EyeOff } from 'lucide-react';
import CirclePlus from '../components/ui/CirclePlus';


const WidgetManager = () => {
  const { config, updateConfigField } = useSiteConfig();
  const [activeTab, setActiveTab] = useState('manage'); // 'manage' or 'settings'
  
  // Defined widget types and their properties
  const widgetTypes = [
    { type: 'topics', title: 'Hot Topics', description: 'Shows the most active conversation topics' },
    { type: 'users', title: 'Active Users', description: 'Displays currently active users' },
    { type: 'stats', title: 'Activity Stats', description: 'Shows message and topic activity statistics' },
    { type: 'trending', title: 'Trending Tags', description: 'Displays trending hashtags and topics' }
  ];
  
  // Get current widgets or initialize empty array
  const widgets = config?.widgets || [];
  
  // Add a new widget
  const addWidget = (type) => {
    const newWidget = {
      id: `widget-${Date.now()}`,
      type,
      title: widgetTypes.find(w => w.type === type)?.title || 'New Widget',
      position: widgets.length,
      enabled: true,
      settings: {}
    };
    
    updateConfigField('widgets', [...widgets, newWidget]);
  };
  
  // Remove a widget
  const removeWidget = (id) => {
    const updatedWidgets = widgets.filter(widget => widget.id !== id);
    // Re-calculate positions
    updatedWidgets.forEach((widget, index) => {
      widget.position = index;
    });
    updateConfigField('widgets', updatedWidgets);
  };
  
  // Toggle widget enabled state
  const toggleWidgetEnabled = (id) => {
    const updatedWidgets = widgets.map(widget => {
      if (widget.id === id) {
        return { ...widget, enabled: !widget.enabled };
      }
      return widget;
    });
    updateConfigField('widgets', updatedWidgets);
  };
  
  // Update widget position
  const moveWidget = (id, direction) => {
    const index = widgets.findIndex(widget => widget.id === id);
    if (index === -1) return;
    
    const newIndex = direction === 'up' ? index - 1 : index + 1;
    if (newIndex < 0 || newIndex >= widgets.length) return;
    
    const updatedWidgets = [...widgets];
    const temp = updatedWidgets[index];
    updatedWidgets[index] = updatedWidgets[newIndex];
    updatedWidgets[newIndex] = temp;
    
    // Update positions
    updatedWidgets.forEach((widget, idx) => {
      widget.position = idx;
    });
    
    updateConfigField('widgets', updatedWidgets);
  };
  
  // Update widget title
  const updateWidgetTitle = (id, newTitle) => {
    const updatedWidgets = widgets.map(widget => {
      if (widget.id === id) {
        return { ...widget, title: newTitle };
      }
      return widget;
    });
    updateConfigField('widgets', updatedWidgets);
  };
  
  // Update widget settings
  const updateWidgetSettings = (id, newSettings) => {
    const updatedWidgets = widgets.map(widget => {
      if (widget.id === id) {
        return { 
          ...widget, 
          settings: { ...widget.settings, ...newSettings }
        };
      }
      return widget;
    });
    updateConfigField('widgets', updatedWidgets);
  };
  
  // Get options for a select dropdown
  const getSelectOptions = (options) => {
    return options.map(option => (
      <option key={option} value={option}>{option}</option>
    ));
  };
  
  // Render widget settings based on type
  const renderWidgetSettings = (widget) => {
    switch (widget.type) {
      case 'topics':
        return (
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium mb-1">Time Range</label>
              <select
                value={widget.settings?.timeRange || 'Last 4 Hours'}
                onChange={(e) => updateWidgetSettings(widget.id, { timeRange: e.target.value })}
                className="w-full p-2 border border-gray-300 rounded-md"
              >
                {getSelectOptions(['Last Hour', 'Last 4 Hours', 'Last 12 Hours', 'Last 24 Hours', 'Last Week'])}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Number of Topics</label>
              <select
                value={widget.settings?.topicCount || 5}
                onChange={(e) => updateWidgetSettings(widget.id, { topicCount: parseInt(e.target.value) })}
                className="w-full p-2 border border-gray-300 rounded-md"
              >
                {getSelectOptions([3, 5, 10, 15])}
              </select>
            </div>
          </div>
        );
      case 'users':
        return (
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium mb-1">Display Style</label>
              <select
                value={widget.settings?.displayStyle || 'Avatars with Names'}
                onChange={(e) => updateWidgetSettings(widget.id, { displayStyle: e.target.value })}
                className="w-full p-2 border border-gray-300 rounded-md"
              >
                {getSelectOptions(['Avatars Only', 'Avatars with Names', 'List View'])}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Number of Users</label>
              <select
                value={widget.settings?.userCount || 5}
                onChange={(e) => updateWidgetSettings(widget.id, { userCount: parseInt(e.target.value) })}
                className="w-full p-2 border border-gray-300 rounded-md"
              >
                {getSelectOptions([5, 10, 15, 20])}
              </select>
            </div>
          </div>
        );
      case 'stats':
        return (
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium mb-1">Stats to Show</label>
              <div className="space-y-2">
                <div className="flex items-center">
                  <input
                    type="checkbox"
                    id={`${widget.id}-messages`}
                    checked={widget.settings?.showMessages !== false}
                    onChange={(e) => updateWidgetSettings(widget.id, { showMessages: e.target.checked })}
                    className="mr-2"
                  />
                  <label htmlFor={`${widget.id}-messages`}>Messages Count</label>
                </div>
                <div className="flex items-center">
                  <input
                    type="checkbox"
                    id={`${widget.id}-topics`}
                    checked={widget.settings?.showTopics !== false}
                    onChange={(e) => updateWidgetSettings(widget.id, { showTopics: e.target.checked })}
                    className="mr-2"
                  />
                  <label htmlFor={`${widget.id}-topics`}>Active Topics</label>
                </div>
                <div className="flex items-center">
                  <input
                    type="checkbox"
                    id={`${widget.id}-users`}
                    checked={widget.settings?.showUsers !== false}
                    onChange={(e) => updateWidgetSettings(widget.id, { showUsers: e.target.checked })}
                    className="mr-2"
                  />
                  <label htmlFor={`${widget.id}-users`}>Active Users</label>
                </div>
              </div>
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Time Period</label>
              <select
                value={widget.settings?.timePeriod || 'Last 24 Hours'}
                onChange={(e) => updateWidgetSettings(widget.id, { timePeriod: e.target.value })}
                className="w-full p-2 border border-gray-300 rounded-md"
              >
                {getSelectOptions(['Last 24 Hours', 'Last Week', 'Last Month'])}
              </select>
            </div>
          </div>
        );
      case 'trending':
        return (
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium mb-1">Time Period</label>
              <select
                value={widget.settings?.timePeriod || 'Last 24 Hours'}
                onChange={(e) => updateWidgetSettings(widget.id, { timePeriod: e.target.value })}
                className="w-full p-2 border border-gray-300 rounded-md"
              >
                {getSelectOptions(['Last 24 Hours', 'Last Week', 'Last Month'])}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Number of Tags</label>
              <select
                value={widget.settings?.tagCount || 5}
                onChange={(e) => updateWidgetSettings(widget.id, { tagCount: parseInt(e.target.value) })}
                className="w-full p-2 border border-gray-300 rounded-md"
              >
                {getSelectOptions([5, 10, 15, 20])}
              </select>
            </div>
            <div className="flex items-center">
              <input
                type="checkbox"
                id={`${widget.id}-show-growth`}
                checked={widget.settings?.showGrowth !== false}
                onChange={(e) => updateWidgetSettings(widget.id, { showGrowth: e.target.checked })}
                className="mr-2"
              />
              <label htmlFor={`${widget.id}-show-growth`}>Show Growth Indicators</label>
            </div>
          </div>
        );
      default:
        return <p>No specific settings for this widget type.</p>;
    }
  };
  
  return (
    <div className="widget-manager">
      <h2 className="text-2xl font-bold mb-6">Widget Manager</h2>
      
      <div className="mb-4 border-b border-gray-200">
        <ul className="flex flex-wrap -mb-px">
          <li className="mr-2">
            <button
              className={`inline-block p-4 ${activeTab === 'manage' 
                ? 'text-indigo-600 border-b-2 border-indigo-600' 
                : 'text-gray-500 hover:text-gray-700'}`}
              onClick={() => setActiveTab('manage')}
            >
              Manage Widgets
            </button>
          </li>
          <li className="mr-2">
            <button
              className={`inline-block p-4 ${activeTab === 'settings' 
                ? 'text-indigo-600 border-b-2 border-indigo-600' 
                : 'text-gray-500 hover:text-gray-700'}`}
              onClick={() => setActiveTab('settings')}
            >
              Widget Settings
            </button>
          </li>
        </ul>
      </div>
      
      {activeTab === 'manage' && (
        <div>
          <div className="mb-6">
            <h3 className="text-lg font-medium mb-2">Active Widgets</h3>
            <p className="text-gray-600 mb-4">
              Configure the widgets that appear on your site. Drag to reorder, toggle to enable/disable.
            </p>
            
            <div className="bg-gray-50 rounded-lg">
              {widgets.length === 0 ? (
                <div className="p-8 text-center text-gray-500">
                  No widgets configured. Add your first widget below.
                </div>
              ) : (
                <ul className="divide-y divide-gray-200">
                  {widgets
                    .sort((a, b) => a.position - b.position)
                    .map(widget => (
                      <li key={widget.id} className="p-4 flex items-center justify-between">
                        <div className="flex items-center">
                          <span className={`inline-block w-3 h-3 rounded-full mr-3 ${widget.enabled ? 'bg-green-500' : 'bg-gray-400'}`}></span>
                          <div>
                            <input
                              type="text"
                              value={widget.title}
                              onChange={(e) => updateWidgetTitle(widget.id, e.target.value)}
                              className="font-medium text-gray-900 focus:outline-none focus:ring-2 focus:ring-indigo-500 rounded px-2 py-1"
                            />
                            <p className="text-sm text-gray-500">
                              {widgetTypes.find(w => w.type === widget.type)?.description}
                            </p>
                          </div>
                        </div>
                        
                        <div className="flex items-center gap-2">
                          <button
                            onClick={() => moveWidget(widget.id, 'up')}
                            disabled={widget.position === 0}
                            className={`p-1 rounded ${widget.position === 0 ? 'text-gray-300 cursor-not-allowed' : 'text-gray-600 hover:bg-gray-200'}`}
                            title="Move up"
                          >
                            <ChevronUp size={18} />
                          </button>
                          <button
                            onClick={() => moveWidget(widget.id, 'down')}
                            disabled={widget.position === widgets.length - 1}
                            className={`p-1 rounded ${widget.position === widgets.length - 1 ? 'text-gray-300 cursor-not-allowed' : 'text-gray-600 hover:bg-gray-200'}`}
                            title="Move down"
                          >
                            <ChevronDown size={18} />
                          </button>
                          <button
                            onClick={() => toggleWidgetEnabled(widget.id)}
                            className="p-1 rounded text-gray-600 hover:bg-gray-200"
                            title={widget.enabled ? 'Disable' : 'Enable'}
                          >
                            {widget.enabled ? <Eye size={18} /> : <EyeOff size={18} />}
                          </button>
                          <button
                            onClick={() => removeWidget(widget.id)}
                            className="p-1 rounded text-red-600 hover:bg-red-100"
                            title="Remove"
                          >
                            <X size={18} />
                          </button>
                        </div>
                      </li>
                    ))}
                </ul>
              )}
            </div>
          </div>
          
          <div>
            <h3 className="text-lg font-medium mb-2">Add New Widget</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
              {widgetTypes.map(widget => (
                <div
                  key={widget.type}
                  className="border border-gray-200 rounded-lg p-4 hover:border-indigo-500 hover:shadow-md transition cursor-pointer"
                  onClick={() => addWidget(widget.type)}
                >
                  <div className="flex justify-between items-start mb-2">
                    <h4 className="font-medium">{widget.title}</h4>
                    <CirclePlus className="text-indigo-600" size={18} />
                  </div>
                  <p className="text-sm text-gray-600">{widget.description}</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
      
      {activeTab === 'settings' && (
        <div>
          <div className="widget-settings">
            <h3 className="text-lg font-medium mb-4">Configure Widget Appearance</h3>
            
            <div className="bg-gray-50 rounded-lg p-6">
              <div className="mb-6">
                <label className="block text-sm font-medium mb-1">Widget Layout</label>
                <select
                  value={config?.widgetSettings?.layout || 'Grid'}
                  onChange={(e) => {
                    updateConfigField('widgetSettings', {
                      ...config?.widgetSettings,
                      layout: e.target.value
                    });
                  }}
                  className="w-full p-2 border border-gray-300 rounded-md"
                >
                  {getSelectOptions(['Grid', 'Stack', 'Masonry'])}
                </select>
              </div>
              
              <div className="mb-6">
                <label className="block text-sm font-medium mb-1">Widget Container Style</label>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs text-gray-500 mb-1">Border Radius</label>
                    <select
                      value={config?.widgetSettings?.borderRadius || 'Medium'}
                      onChange={(e) => {
                        updateConfigField('widgetSettings', {
                          ...config?.widgetSettings,
                          borderRadius: e.target.value
                        });
                      }}
                      className="w-full p-2 border border-gray-300 rounded-md"
                    >
                      {getSelectOptions(['None', 'Small', 'Medium', 'Large', 'Full'])}
                    </select>
                  </div>
                  <div>
                    <label className="block text-xs text-gray-500 mb-1">Shadow</label>
                    <select
                      value={config?.widgetSettings?.shadow || 'Small'}
                      onChange={(e) => {
                        updateConfigField('widgetSettings', {
                          ...config?.widgetSettings,
                          shadow: e.target.value
                        });
                      }}
                      className="w-full p-2 border border-gray-300 rounded-md"
                    >
                      {getSelectOptions(['None', 'Small', 'Medium', 'Large'])}
                    </select>
                  </div>
                </div>
              </div>
              
              <div className="mb-6">
                <label className="block text-sm font-medium mb-1">Chart Style</label>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs text-gray-500 mb-1">Color Theme</label>
                    <select
                      value={config?.widgetSettings?.chartTheme || 'Default'}
                      onChange={(e) => {
                        updateConfigField('widgetSettings', {
                          ...config?.widgetSettings,
                          chartTheme: e.target.value
                        });
                      }}
                      className="w-full p-2 border border-gray-300 rounded-md"
                    >
                      {getSelectOptions(['Default', 'Monochrome', 'Colorful', 'Pastel', 'Dark'])}
                    </select>
                  </div>
                  <div>
                    <label className="block text-xs text-gray-500 mb-1">Animation</label>
                    <select
                      value={config?.widgetSettings?.chartAnimation || 'Fade'}
                      onChange={(e) => {
                        updateConfigField('widgetSettings', {
                          ...config?.widgetSettings,
                          chartAnimation: e.target.value
                        });
                      }}
                      className="w-full p-2 border border-gray-300 rounded-md"
                    >
                      {getSelectOptions(['None', 'Fade', 'Slide', 'Bounce'])}
                    </select>
                  </div>
                </div>
              </div>
              
              <div>
                <label className="block text-sm font-medium mb-1">Detail View Options</label>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs text-gray-500 mb-1">Default Tab</label>
                    <select
                      value={config?.widgetSettings?.defaultTab || 'First'}
                      onChange={(e) => {
                        updateConfigField('widgetSettings', {
                          ...config?.widgetSettings,
                          defaultTab: e.target.value
                        });
                      }}
                      className="w-full p-2 border border-gray-300 rounded-md"
                    >
                      {getSelectOptions(['First', 'Last Selected'])}
                    </select>
                  </div>
                  <div>
                    <label className="block text-xs text-gray-500 mb-1">Detail Height</label>
                    <select
                      value={config?.widgetSettings?.detailHeight || 'Standard'}
                      onChange={(e) => {
                        updateConfigField('widgetSettings', {
                          ...config?.widgetSettings,
                          detailHeight: e.target.value
                        });
                      }}
                      className="w-full p-2 border border-gray-300 rounded-md"
                    >
                      {getSelectOptions(['Compact', 'Standard', 'Expanded'])}
                    </select>
                  </div>
                </div>
              </div>
            </div>
            
            <div className="mt-8">
              <h3 className="text-lg font-medium mb-4">Individual Widget Configuration</h3>
              
              {widgets.length === 0 ? (
                <div className="bg-gray-50 rounded-lg p-8 text-center text-gray-500">
                  No widgets configured yet. Add widgets in the "Manage Widgets" tab first.
                </div>
              ) : (
                <div className="space-y-6">
                  {widgets.map(widget => (
                    <div key={widget.id} className="bg-gray-50 rounded-lg p-6 border border-gray-200">
                      <h4 className="text-lg font-medium mb-4 flex items-center">
                        <Settings size={18} className="mr-2" />
                        {widget.title} Settings
                      </h4>
                      
                      {renderWidgetSettings(widget)}
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default WidgetManager;