/**
 * Check if a user has access to an event based on access level
 * @param {Object} user - User object
 * @param {string} eventAccessLevel - Event access level from Firebase
 * @returns {Object} Access result with canAccess and reason
 */
export const checkEventAccess = (user, eventAccessLevel) => {
  const accessType = ACCESS_DESCRIPTIONS[eventAccessLevel];
  
  if (!accessType) {
    return {
      canAccess: false,
      reason: 'invalid_access_level',
      message: 'Invalid event access level'
    };
  }

  // Anonymous or completely unauthenticated user
  if (!user || user.isAnonymous) {
    if (accessType.anonymousAccess) {
      return {
        canAccess: true,
        reason: 'anonymous_allowed',
        message: 'Anonymous access granted for free event'
      };
    }
    return {
      canAccess: false,
      reason: 'registration_required',
      message: `This event requires ${accessType.requirements.toLowerCase()}`
    };
  }

  // Registered user
  if (!user.isPremium && !user.isVIP) {
    if (accessType.registeredAccess) {
      return {
        canAccess: true,
        reason: 'registered_access',
        message: 'Access granted for registered user'
      };
    }
    return {
      canAccess: false,
      reason: 'upgrade_required',
      message: `This event requires ${accessType.requirements.toLowerCase()}`
    };
  }

  // Premium user
  if (user.isPremium && !user.isVIP) {
    if (accessType.premiumAccess) {
      return {
        canAccess: true,
        reason: 'premium_access',
        message: 'Access granted for premium user'
      };
    }
    return {
      canAccess: false,
      reason: 'vip_required',
      message: 'This event requires VIP membership'
    };
  }

  // VIP user
  if (user.isVIP) {
    return {
      canAccess: true,
      reason: 'vip_access',
      message: 'Access granted for VIP user'
    };
  }

  return {
    canAccess: false,
    reason: 'unknown_error',
    message: 'Unable to determine access level'
  };
};

/**
 * Get appropriate button text for event access
 * @param {Object} user - User object
 * @param {string} eventAccessLevel - Event access level from Firebase
 * @param {string} eventStatus - Event status (live, scheduled, ended)
 * @returns {string} Button text
 */
export const getEventButtonText = (user, eventAccessLevel, eventStatus = 'scheduled') => {
  const accessResult = checkEventAccess(user, eventAccessLevel);
  
  if (accessResult.canAccess) {
    switch (eventStatus) {
      case 'live':
        return 'Join Now';
      case 'scheduled':
        return eventAccessLevel === EVENT_ACCESS_TYPES.FREE ? 'Join Free Event' : 'Join Event';
      case 'ended':
        return 'Watch Replay';
      default:
        return 'Join Event';
    }
  }

  // Access denied - show requirement for unauthenticated users
  if (!user || user.isAnonymous) {
    switch (eventAccessLevel) {
      case EVENT_ACCESS_TYPES.VIP:
        return 'VIP Required';
      case EVENT_ACCESS_TYPES.PREMIUM:
        return 'Premium Required';
      default:
        return 'Registration Required';
    }
  }

  // Registered user but needs upgrade
  switch (eventAccessLevel) {
    case EVENT_ACCESS_TYPES.VIP:
      return 'VIP Required';
    case EVENT_ACCESS_TYPES.PREMIUM:
      return 'Premium Required';
    default:
      return 'Join Event';
  }
};