// src/components/community/ChatRooms.jsx
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { MessageSquare, Users } from 'lucide-react';
import { getDatabase, ref, onValue } from 'firebase/database';
import { rtdb } from '../../firebase';
import { useAuth } from '../../contexts/AuthContext';
import './ChatRooms.css';
import { startTiming, endTiming } from '../../utils/performance-monitor';

const ChatRooms = ({ onJoinRoom, onError }) => {
  const [rooms, setRooms] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();
  const { currentUser } = useAuth();

  useEffect(() => {
    const fetchRooms = async () => {
      startTiming('ChatRooms:fetchRooms');
      
      // Add a timeout to prevent hanging
      const timeoutId = setTimeout(() => {
        console.warn('ChatRooms fetch timed out after 3 seconds - using fallback data');
        setRooms([
          { id: 'general', name: 'General Chat (Timeout Fallback)', description: 'General discussion', activeUsers: 3, type: 'public' },
          { id: 'help', name: 'Help & Support (Timeout Fallback)', description: 'Get assistance', activeUsers: 1, type: 'public' }
        ]);
        setLoading(false);
        endTiming('ChatRooms:fetchRooms');
      }, 3000); // 3 second timeout
      try {
        const roomsRef = ref(rtdb, 'chats/public');
        
        // Set up real-time listener
        const unsubscribe = onValue(roomsRef, (snapshot) => {
          try {
            if (snapshot.exists()) {
              const roomsData = [];
              
              let totalRoomsProcessed = 0;
              let publicRoomsFound = 0;
              
              snapshot.forEach((childSnapshot) => {
                const roomId = childSnapshot.key;
                const roomData = childSnapshot.val();
                totalRoomsProcessed++;
                
                // Skip entries without a name
                if (!roomData.name) {
                  console.log(`Skipping room ${roomId} - no name`);
                  return;
                }
                
                // Get room type - default to 'public' if not specified
                const roomType = roomData.type || 'public';
                
                if (roomType === 'public') {
                  publicRoomsFound++;
                }
                
                // For anonymous users, only include public rooms
                // For logged-in users, include public and registered rooms
                // For private rooms, additional checks are done in the room page
                if (!currentUser && roomType !== 'public') {
                  console.log(`Filtering out room ${roomData.name} (${roomId}) for non-authenticated user - type: ${roomType}`);
                  return; // Skip non-public rooms for anonymous users
                }
                
                if (currentUser?.isAnonymous && roomType !== 'public') {
                  console.log(`Filtering out room ${roomData.name} (${roomId}) for anonymous user - type: ${roomType}`);
                  return; // Skip non-public rooms for anonymous users
                }
                
                // Get active users count (if available)
                let activeUsers = 0;
                if (roomData.activeUserTimestamps) {
                  const now = Date.now();
                  const fiveMinutesAgo = now - 5 * 60 * 1000;
                  
                  // Count users active in the last 5 minutes
                  Object.values(roomData.activeUserTimestamps).forEach(timestamp => {
                    if (timestamp > fiveMinutesAgo) {
                      activeUsers++;
                    }
                  });
                }
                
                // Filter out messages and other large data
                const { messages, ...roomWithoutMessages } = roomData;
                
                roomsData.push({
                  id: roomId,
                  name: roomData.name,
                  description: roomData.description || '',
                  activeUsers: activeUsers,
                  lastActive: roomData.lastActivityTimestamp || 0,
                  type: roomType,
                  ...roomWithoutMessages
                });
              });
              
              console.log(`ChatRooms component: Processed ${totalRoomsProcessed} total rooms`);
              console.log(`ChatRooms component: Found ${publicRoomsFound} public rooms`);
              console.log(`ChatRooms component: Showing ${roomsData.length} rooms to ${currentUser?.isAnonymous ? 'anonymous' : (currentUser ? 'logged-in' : 'non-authenticated')} user`);
              
              // Sort by active users and then by last activity
              roomsData.sort((a, b) => {
                if (b.activeUsers !== a.activeUsers) {
                  return b.activeUsers - a.activeUsers;
                } else {
                  return b.lastActive - a.lastActive;
                }
              });
              
              // Set all rooms without limiting
              setRooms(roomsData);
              setLoading(false);
              clearTimeout(timeoutId); // Clear the timeout on success
              endTiming('ChatRooms:fetchRooms');
            } else {
              // Set default rooms if none found
              setRooms([
                { id: 'general', name: 'General Chat', description: 'General discussion', activeUsers: 3, type: 'public' },
                { id: 'help', name: 'Help & Support', description: 'Get assistance', activeUsers: 1, type: 'public' }
              ]);
              setLoading(false);
              clearTimeout(timeoutId); // Clear the timeout on success
              endTiming('ChatRooms:fetchRooms');
            }
          } catch (error) {
            console.error("Error processing rooms:", error);
            onError?.();
            setLoading(false);
            clearTimeout(timeoutId); // Clear the timeout on error
            endTiming('ChatRooms:fetchRooms');
          }
        }, (error) => {
          console.error("Firebase error:", error);
          onError?.();
          setLoading(false);
          clearTimeout(timeoutId); // Clear the timeout on error
          endTiming('ChatRooms:fetchRooms');
        });
        
        // Clean up listener
        return () => {
          clearTimeout(timeoutId); // Clear timeout on unmount
          unsubscribe();
        };
      } catch (error) {
        console.error("Error setting up rooms listener:", error);
        onError?.();
        setLoading(false);
        clearTimeout(timeoutId); // Clear timeout on error
        endTiming('ChatRooms:fetchRooms');
      }
    };
    
    fetchRooms();
  }, [onError, currentUser]);

  const handleJoinRoom = async (roomId, roomType) => {
    try {
      if (onJoinRoom) {
        // If parent component provides a handler, use it
        onJoinRoom(roomId);
      } else {
        // Direct navigation to room - for anonymous users, this should
        // still allow viewing of public rooms
        navigate(`/room/${roomId}`);
      }
    } catch (error) {
      console.error("Error joining room:", error);
    }
  };

  if (loading) {
    return <div className="rooms-loading">Loading chat rooms...</div>;
  }

  if (rooms.length === 0) {
    return <div className="no-chat-rooms">No active chat rooms found</div>;
  }

  return (
    <div className="chat-rooms-container">
      <div className="chat-rooms-list">
        {rooms.map(room => (
          <div key={room.id} className="chat-room-item">
            <div className="room-icon">
              <MessageSquare size={20} />
            </div>
            <div className="room-content">
              <div className="room-header">
                <span className="room-name">{room.eventTitle || room.name || 'Untitled Room'}</span>
                <span className="room-participants">
                  <Users size={12} style={{ marginRight: '4px' }} />
                  {room.activeUsers || 0}
                </span>
              </div>
              <div className="room-description">{room.description || 'No description'}</div>
              {room.tags && room.tags.length > 0 && (
                <div className="room-tags">
                  {room.tags.slice(0, 3).map((tag, index) => (
                    <span key={`${room.id}-tag-${index}`} className="room-tag">
                      #{tag}
                    </span>
                  ))}
                  {room.tags.length > 3 && (
                    <span className="room-tag">+{room.tags.length - 3} more</span>
                  )}
                </div>
              )}
            </div>
            <button 
              className="room-join-button" 
              onClick={() => handleJoinRoom(room.id, room.type)}
            >
              Join
            </button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ChatRooms;