// src/components/audio/TrackCard.jsx
//
// Reusable track card: inline play, like, remix, copy-share-link.
// Used on the profile Music tab and the /track/:id page. Pass a shared
// `player` from useJamPlayer so a list of cards uses one engine.

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Play, Square, Heart, GitBranch, Link2, Check } from 'lucide-react';

import { likeJam, trackUrl } from '../../services/jamService';

const TrackCard = ({ jam, player, showCreator = true, onLiked }) => {
  const navigate = useNavigate();
  const [liked, setLiked] = useState(false);
  const [copied, setCopied] = useState(false);

  const isPlaying = player.playingId === jam.id;
  const chain = (jam.attribution || []).map(a => a.name).join(' → ');

  const like = async () => {
    if (liked) return;
    setLiked(true);
    onLiked && onLiked(jam.id);
    try { await likeJam(jam.id); } catch (_) { /* optimistic */ }
  };

  const copyLink = async () => {
    try {
      await navigator.clipboard.writeText(trackUrl(jam.id));
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch (_) { /* noop */ }
  };

  return (
    <div
      style={{
        background: '#15151e',
        border: '0.5px solid ' + (isPlaying ? '#3C3489' : '#25252e'),
        borderRadius: 12,
        padding: 14,
        marginBottom: 10,
        color: '#e8e8f0',
        fontFamily: '-apple-system, BlinkMacSystemFont, system-ui, sans-serif',
      }}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
        <button
          onClick={() => player.toggle(jam)}
          title={isPlaying ? 'Stop' : 'Play'}
          style={{
            background: isPlaying ? '#E24B4A' : '#534AB7',
            color: 'white', border: 'none',
            width: 42, height: 42, borderRadius: '50%',
            cursor: 'pointer', flexShrink: 0,
            display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
          }}
        >
          {isPlaying ? <Square size={16} fill="white" /> : <Play size={18} />}
        </button>

        <div style={{ flex: 1, minWidth: 0 }}>
          <div
            onClick={() => navigate(`/track/${jam.id}`)}
            style={{ fontSize: 14, fontWeight: 500, cursor: 'pointer', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}
            title="Open track page"
          >
            {jam.title}
          </div>
          <div style={{ fontSize: 11, color: '#6b6b7a', marginTop: 2 }}>
            {jam.theory ? `${jam.theory.keyName} ${jam.theory.scaleName} · ${jam.theory.tempo} bpm · ` : ''}
            {(jam.layers || []).length} layers
            {jam.parentJamId ? ' · remix' : ''}
            {typeof jam.plays === 'number' ? ` · ${jam.plays} plays` : ''}
          </div>
          {showCreator && chain && (
            <div
              onClick={() => jam.createdBy?.uid && navigate(`/profile/${jam.createdBy.uid}`)}
              style={{ fontSize: 11, color: '#5DCAA5', marginTop: 2, cursor: 'pointer', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}
              title="View creator profile"
            >
              {chain}
            </div>
          )}
        </div>

        <div style={{ display: 'flex', gap: 6, flexShrink: 0 }}>
          <CardButton onClick={like} active={liked} activeColor="#F0999A" title="Like">
            <Heart size={13} fill={liked ? 'currentColor' : 'none'} />
            {(jam.likes || 0) + (liked ? 1 : 0)}
          </CardButton>
          <CardButton
            onClick={() => navigate(`/sketch?remix=${jam.id}`)}
            activeColor="#5DCAA5"
            title="Remix this track"
            style={{ background: '#0d1f1a', border: '1px solid #1D9E75', color: '#5DCAA5' }}
          >
            <GitBranch size={13} />
            {jam.remixCount || 0}
          </CardButton>
          <CardButton onClick={copyLink} active={copied} activeColor="#5DCAA5" title="Copy share link">
            {copied ? <Check size={13} /> : <Link2 size={13} />}
          </CardButton>
        </div>
      </div>

      {isPlaying && (
        <div style={{ height: 3, background: '#0a0a12', borderRadius: 2, overflow: 'hidden', marginTop: 10 }}>
          <div
            style={{
              width: `${Math.round(player.progress * 100)}%`, height: '100%',
              background: 'linear-gradient(90deg, #7F77DD, #5DCAA5)',
              transition: 'width 0.1s linear',
            }}
          />
        </div>
      )}
    </div>
  );
};

const CardButton = ({ children, onClick, active, activeColor, title, style }) => (
  <button
    onClick={onClick}
    title={title}
    style={{
      background: 'transparent',
      border: '1px solid #25252e',
      color: active ? activeColor : '#8b8b9a',
      padding: '6px 10px', borderRadius: 8, cursor: 'pointer',
      display: 'inline-flex', alignItems: 'center', gap: 5, fontSize: 12,
      ...style,
    }}
  >
    {children}
  </button>
);

export default TrackCard;
