// src/utils/environment-debugger.js
/**
 * Utility to help debug environment variables during application startup
 * This is especially useful for production deployments
 */

// Detect current environment
const getCurrentEnvironment = () => {
  const hostname = window.location.hostname;
  
  if (hostname.includes('localhost') || hostname.includes('127.0.0.1')) {
    return 'development';
  } else if (hostname.includes('ondigitalocean.app')) {
    return 'testing';
  } else if (hostname.includes('talkstudio.space') || hostname.includes('talkstud.io')) {
    return 'production';
  }
  
  return 'unknown';
};

export const debugEnvironmentVariables = () => {
  const environment = getCurrentEnvironment();
  
  // Only show detailed environment debug in development/testing
  if (environment === 'production') {
    console.log('🔧 Environment debugging disabled in production');
    return {
      environment: 'production',
      hasRequiredVars: true
    };
  }
  
  console.group('🔧 Environment Variables Debug');
  
  // Detect environment
  const isProduction = window.location.hostname.includes('talkstudio.space') || hostname.includes('talkstud.io');
  const isTest = window.location.hostname.includes('oyster-app');
  const isDev = window.location.hostname.includes('localhost') || window.location.hostname.includes('127.0.0.1');
  
  console.log('Detected environment:', {
    hostname: window.location.hostname,
    isProduction,
    isTest,
    isDev
  });
  
  // Check critical environment variables
  console.log('Payment environment variables:', {
    VITE_PAYMENT_MODE: import.meta.env.VITE_PAYMENT_MODE || 'not set',
    VITE_APP_ENV: import.meta.env.VITE_APP_ENV || 'not set'
  });
  
  // Check Stripe keys (safely - only show if they exist and mask most of the key)
  const testKey = import.meta.env.VITE_STRIPE_TEST_PUBLIC_KEY;
  const liveKey = import.meta.env.VITE_STRIPE_LIVE_PUBLIC_KEY;
  const publishableKey = import.meta.env.VITE_STRIPE_PUBLISHABLE_KEY;
  
  console.log('Stripe keys:', {
    // If key exists, show first 8 chars and last 4; otherwise show 'not set'
    VITE_STRIPE_TEST_PUBLIC_KEY: testKey ? 
      `${testKey.substring(0, 8)}...${testKey.substring(testKey.length - 4)}` : 'not set',
    VITE_STRIPE_LIVE_PUBLIC_KEY: liveKey ? 
      `${liveKey.substring(0, 8)}...${liveKey.substring(liveKey.length - 4)}` : 'not set',
    VITE_STRIPE_PUBLISHABLE_KEY: publishableKey ? 
      `${publishableKey.substring(0, 8)}...${publishableKey.substring(publishableKey.length - 4)}` : 'not set'
  });
  
  // Check URL configurations
  console.log('API URLs:', {
    VITE_PAYMENT_PROXY_URL: import.meta.env.VITE_PAYMENT_PROXY_URL || 'not set',
    VITE_CORS_PROXY_URL: import.meta.env.VITE_CORS_PROXY_URL || 'not set'
  });
  
  // Non-secret build config, listed one property at a time.
  //
  // NEVER iterate or log `import.meta.env` as a whole here. Vite resolves
  // `import.meta.env.VITE_X` at build time by substituting the literal value,
  // but a bare `import.meta.env` forces it to inline the ENTIRE env object --
  // every VITE_ var on the build machine, including ones this app never reads.
  // The masking below runs in the browser, long after the raw values are
  // already sitting in the bundle, so it protects nothing. A `for...in` here is
  // what put an Anthropic API key in a production build and tripped GitHub's
  // push protection. Add explicit entries; never a loop.
  //
  // Secret-shaped vars are omitted outright rather than reported as
  // "set"/"not set", because even a presence check inlines the value.
  console.log('Vite build config (non-secret):', {
    VITE_APP_ENV: import.meta.env.VITE_APP_ENV || 'not set',
    VITE_PAYMENT_MODE: import.meta.env.VITE_PAYMENT_MODE || 'not set',
    VITE_OVERRIDE_TIER: import.meta.env.VITE_OVERRIDE_TIER || 'not set',
    VITE_PAYMENT_PROXY_URL: import.meta.env.VITE_PAYMENT_PROXY_URL || 'not set',
    VITE_CORS_PROXY_URL: import.meta.env.VITE_CORS_PROXY_URL || 'not set',
    VITE_MFA_API_URL: import.meta.env.VITE_MFA_API_URL || 'not set',
    VITE_RECORDING_API_URL: import.meta.env.VITE_RECORDING_API_URL || 'not set',
    VITE_STREAMING_BASE_URL: import.meta.env.VITE_STREAMING_BASE_URL || 'not set',
    VITE_STREAMING_MODE: import.meta.env.VITE_STREAMING_MODE || 'not set',
    VITE_LIVEKIT_SERVER_URL: import.meta.env.VITE_LIVEKIT_SERVER_URL || 'not set',
    VITE_FIREBASE_PROJECT_ID: import.meta.env.VITE_FIREBASE_PROJECT_ID || 'not set',
    VITE_FIREBASE_AUTH_DOMAIN: import.meta.env.VITE_FIREBASE_AUTH_DOMAIN || 'not set',
    MODE: import.meta.env.MODE,
  });
  
  console.groupEnd();
  
  // Return true if all required variables are available
  return {
    hasRequiredVars: !!(
      // Check that we have either test or live keys depending on mode
      ((import.meta.env.VITE_PAYMENT_MODE === 'test' && testKey) || 
       (import.meta.env.VITE_PAYMENT_MODE === 'live' && (liveKey || publishableKey))) &&
      import.meta.env.VITE_PAYMENT_PROXY_URL
    ),
    environment: isDev ? 'development' : (isTest ? 'testing' : (isProduction ? 'production' : 'unknown'))
  };
};