// CDC PLACES client (Socrata API — no key required).
//
// PLACES provides model-based small-area estimates for 27 chronic-disease
// and health-behavior measures. We pull the national county-level dataset
// and average across counties (population-weighting would be ideal but
// requires a second Census lookup — we accept the approximation for a
// slow-moving reference signal).
//
// Dataset: https://data.cdc.gov/500-Cities-Places/PLACES-County-Data-GIS-Friendly-Format-2024-releas/i46a-9kgh
// Endpoint: https://data.cdc.gov/resource/i46a-9kgh.json
//
// Measures targeted (2022-BRFSS release, short IDs used by PLACES):
//   OBESITY_CrudePrev  — Adult obesity prevalence, %
//   MHLTH_CrudePrev    — Mental health not good 14+ days past month, %
//
// The Socrata field for the short-measure prevalence varies by release;
// we request a compact select list and handle missing columns gracefully.

import { corsFetch } from '../../utils/corsFetch'

const CDC_DATASET = 'i46a-9kgh'  // PLACES county 2024 release
const CDC_URL = `https://data.cdc.gov/resource/${CDC_DATASET}.json`

const MEASURES = [
  {
    field: 'obesity_crudeprev',
    tag: 'health.obesity.national',
    label: 'US Adult Obesity (avg county)',
    id: 'cdc.obesity.national',
    sentimentHint: 'negative',
  },
  {
    field: 'mhlth_crudeprev',
    tag: 'health.mental_not_good.national',
    label: 'US Mental-Health-Not-Good (avg county)',
    id: 'cdc.mhlth.national',
    sentimentHint: 'negative',
  },
]

function buildUrl() {
  const fields = ['statedesc', 'countyname', ...MEASURES.map(m => m.field)].join(',')
  const params = new URLSearchParams({
    $select: fields,
    $limit: '5000',
  })
  return `${CDC_URL}?${params}`
}

function mean(values) {
  const nums = values.map(Number).filter(Number.isFinite)
  if (nums.length === 0) return null
  return +(nums.reduce((a, b) => a + b, 0) / nums.length).toFixed(1)
}

function buildSignals(rows) {
  const asOf = new Date().toISOString()
  const period = '2022'  // PLACES 2024 release uses 2022 BRFSS data
  const signals = []
  for (const m of MEASURES) {
    const avg = mean(rows.map(r => r[m.field]))
    if (avg === null) continue
    signals.push({
      id: m.id,
      tag: m.tag,
      category: 'health',
      label: m.label,
      value: avg,
      unit: '%',
      trend: 'stable',
      delta: null,
      deltaLabel: null,
      period,
      asOf,
      source: 'CDC PLACES 2024',
      sourceUrl: 'https://www.cdc.gov/places/',
      reliability: 0.92,
      sentimentHint: m.sentimentHint,
    })
  }
  return signals
}

const cdcService = {
  async fetchAll() {
    const res = await corsFetch(buildUrl(), {
      method: 'GET',
      parse: 'json',
      timeout: 15000,
    })
    if (!res.ok) return { signals: [], error: res.error || 'CDC fetch failed' }
    const rows = Array.isArray(res.data) ? res.data : []
    if (rows.length === 0) return { signals: [], error: 'CDC returned no rows' }
    return { signals: buildSignals(rows), error: null }
  },
}

export default cdcService
