// src/services/LikeService.js
import { 
    getFirestore, 
    collection, 
    doc, 
    getDoc, 
    setDoc, 
    deleteDoc, 
    updateDoc, 
    increment,
    arrayUnion,
    arrayRemove,
    serverTimestamp 
  } from 'firebase/firestore';
  import { getAuth } from 'firebase/auth';
  
  class LikeService {
    /**
     * Toggle like status for a post with enhanced error handling
     */
    static async togglePostLike(postId) {
      try {
        console.log('Starting togglePostLike for postId:', postId);
        
        const auth = getAuth();
        const user = auth.currentUser;
        
        if (!user) {
          console.error('No user logged in');
          throw new Error('User must be logged in to like posts');
        }
        
        if (!postId) {
          console.error('No postId provided');
          throw new Error('Post ID is required');
        }
        
        console.log('Current user:', user.uid, 'Anonymous:', user.isAnonymous);
        
        const db = getFirestore();
        const userId = user.uid;
        
        // Create references
        const postRef = doc(db, 'posts', postId);
        const likesCollection = collection(db, 'likes');
        const likeId = `${postId}_${userId}`;
        const likeRef = doc(likesCollection, likeId);
        
        console.log('Checking if post exists and if already liked');
        
        // Check if post exists and if already liked - run these in parallel
        try {
          const [postDoc, likeDoc] = await Promise.all([
            getDoc(postRef),
            getDoc(likeRef)
          ]);
          
          if (!postDoc.exists()) {
            console.error('Post not found:', postId);
            throw new Error('Post not found');
          }
          
          const postData = postDoc.data();
          console.log('Post exists, current likes:', postData.likesCount || 0);
          console.log('Like document exists?', likeDoc.exists());
          
          if (likeDoc.exists()) {
            // Already liked, so unlike
            console.log('Post was liked, now unliking');
            
            try {
              // Delete the like document
              await deleteDoc(likeRef);
              console.log('Like document deleted');
              
              // Update post like count and remove user from likedBy array
              await updateDoc(postRef, {
                likesCount: increment(-1),
                likedBy: arrayRemove(userId),
                lastModified: serverTimestamp()
              });
              console.log('Post document updated - like removed');
            } catch (error) {
              console.error('Error during unlike operation:', error);
              // Try a simpler approach if the first method failed
              try {
                // Just update the likes count as a fallback
                await updateDoc(postRef, {
                  likesCount: increment(-1)
                });
                console.log('Fallback - updated like count only');
              } catch (subError) {
                console.error('Fallback error:', subError);
                throw error; // Re-throw original error if fallback fails
              }
            }
            
            return {
              liked: false,
              likesCount: Math.max((postData.likesCount || 1) - 1, 0) // Prevent negative counts
            };
          } else {
            // Not liked yet, so like it
            console.log('Post was not liked, now liking');
            
            try {
              // Create the like document
              await setDoc(likeRef, {
                postId,
                userId,
                createdAt: serverTimestamp(),
                userDisplayName: user.displayName || 'Anonymous',
                userPhotoURL: user.photoURL,
                isAnonymous: user.isAnonymous
              });
              console.log('Like document created');
              
              // Update post like count and add user to likedBy array
              await updateDoc(postRef, {
                likesCount: increment(1),
                likedBy: arrayUnion(userId),
                lastModified: serverTimestamp()
              });
              console.log('Post document updated - like added');
            } catch (error) {
              console.error('Error during like operation:', error);
              // Try a simpler approach if the first method failed
              try {
                // Just update the likes count as a fallback
                await updateDoc(postRef, {
                  likesCount: increment(1)
                });
                console.log('Fallback - updated like count only');
              } catch (subError) {
                console.error('Fallback error:', subError);
                throw error; // Re-throw original error if fallback fails
              }
            }
            
            return {
              liked: true,
              likesCount: (postData.likesCount || 0) + 1
            };
          }
        } catch (error) {
          console.error('Error in database operations:', error);
          
          // Return optimistic result based on user intent
          // This helps UI still feel responsive even if database operations fail
          return {
            liked: !await this.isPostLiked(postId),
            likesCount: 0 // Without knowing the exact count, we return 0
          };
        }
      } catch (error) {
        console.error('Error in togglePostLike:', error);
        throw error;
      }
    }
    
    /**
     * Check if a post is liked by the current user
     */
    static async isPostLiked(postId) {
      try {
        const auth = getAuth();
        const user = auth.currentUser;
        
        if (!user || !postId) {
          return false;
        }
        
        const db = getFirestore();
        const likeId = `${postId}_${user.uid}`;
        const likeRef = doc(collection(db, 'likes'), likeId);
        
        const likeDoc = await getDoc(likeRef);
        return likeDoc.exists();
      } catch (error) {
        console.error('Error checking if post is liked:', error);
        return false; // Default to not liked on error
      }
    }
  }
  
  export default LikeService;