// src/components/audio/MelodyRoll.jsx
//
// Piano-roll view of a composed melody, with the chord bed underneath and a
// playhead. A melody creator that shows you nothing but a progress bar is
// asking you to judge a tune by ear alone on the first listen — seeing the
// shape is how you decide whether to keep it, vary it, or start again.

import React, { useMemo } from 'react';

const W = 1000;   // viewBox units; the SVG scales to its container
const H = 190;
const CHORD_LANE = 26;
const SECTION_LANE = 16;
const ROLL_TOP = SECTION_LANE + 4;
const ROLL_H = H - CHORD_LANE - SECTION_LANE - 8;

// Energy read at a glance: a drop should look like a drop.
const SECTION_COLOR = {
  intro:     'rgba(127,119,221,0.14)',
  breakdown: 'rgba(93,202,165,0.18)',
  build:     'rgba(226,150,74,0.22)',
  drop:      'rgba(226,75,74,0.30)',
  outro:     'rgba(127,119,221,0.14)',
  loop:      'rgba(127,119,221,0.16)',
};

const MelodyRoll = ({ melody = [], chords = [], sections = [], duration = 1, barSec = 2, position = 0 }) => {
  const { notes, bars, lowMidi, span } = useMemo(() => {
    const pitches = melody.map(n => n.midi[0]);
    const lo = pitches.length ? Math.min(...pitches) : 60;
    const hi = pitches.length ? Math.max(...pitches) : 72;
    // Always show at least an octave so a narrow melody doesn't fill the frame.
    const pad = Math.max(0, (12 - (hi - lo)) / 2);
    const low = Math.floor(lo - pad - 1);
    const high = Math.ceil(hi + pad + 1);
    return {
      notes: melody,
      bars: Math.max(1, Math.round(duration / barSec)),
      lowMidi: low,
      span: Math.max(1, high - low),
    };
  }, [melody, duration, barSec]);

  const x = (t) => (t / duration) * W;
  const y = (midi) => ROLL_TOP + ROLL_H - ((midi - lowMidi) / span) * ROLL_H;
  const noteH = Math.max(3, ROLL_H / span - 1);
  // On a 4-minute arrangement every bar line would be noise; show phrases.
  const gridEvery = bars > 48 ? 16 : bars > 24 ? 4 : 1;

  if (!melody.length) {
    return (
      <div
        style={{
          height: 150, borderRadius: 12, border: '0.5px dashed #2b2b36',
          background: 'rgba(20,20,30,0.5)', display: 'flex',
          alignItems: 'center', justifyContent: 'center',
          color: '#5b5b6a', fontSize: 12,
        }}
      >
        no melody yet — write one below
      </div>
    );
  }

  return (
    <svg
      viewBox={`0 0 ${W} ${H}`}
      preserveAspectRatio="none"
      style={{
        width: '100%', height: 150, display: 'block',
        borderRadius: 12, border: '0.5px solid #25252e',
        background: 'linear-gradient(180deg, rgba(127,119,221,0.07), rgba(10,10,18,0.75))',
      }}
    >
      {/* section map — the arrangement, so a drop looks like a drop */}
      {sections.map((s, i) => {
        const sx = x(s.startBar * barSec);
        const sw = Math.max(2, x(s.lengthBars * barSec) - 1);
        return (
          <g key={`s${i}`}>
            <rect
              x={sx} y={0} width={sw} height={SECTION_LANE}
              fill={SECTION_COLOR[s.kind] || SECTION_COLOR.loop} rx={2}
            />
            <rect
              x={sx} y={ROLL_TOP} width={sw} height={ROLL_H}
              fill={SECTION_COLOR[s.kind] || SECTION_COLOR.loop} opacity={0.35}
            />
            {sw > 44 && (
              <text
                x={sx + 4} y={SECTION_LANE - 5}
                fill="rgba(232,232,240,0.75)" fontSize={9}
                style={{ fontFamily: 'inherit' }}
              >
                {s.kind}
              </text>
            )}
          </g>
        );
      })}

      {/* bar grid */}
      {Array.from({ length: Math.floor(bars / gridEvery) + 1 }).map((_, i) => {
        const bar = i * gridEvery;
        const major = bar % (gridEvery * 4) === 0;
        return (
          <line
            key={`bar${i}`}
            x1={x(bar * barSec)} x2={x(bar * barSec)} y1={ROLL_TOP} y2={ROLL_TOP + ROLL_H}
            stroke={major ? 'rgba(255,255,255,0.14)' : 'rgba(255,255,255,0.05)'}
            strokeWidth={major ? 1.5 : 1}
            vectorEffect="non-scaling-stroke"
          />
        );
      })}

      {/* chord bed */}
      {chords.map((c, i) => (
        <rect
          key={`c${i}`}
          x={x(c.t) + 0.5} y={ROLL_TOP + ROLL_H + 8}
          width={Math.max(1, x(barSec) - 1)} height={CHORD_LANE - 12}
          rx={2} fill="rgba(93,202,165,0.18)" stroke="rgba(93,202,165,0.35)"
          strokeWidth={0.5} vectorEffect="non-scaling-stroke"
        />
      ))}

      {/* melody notes — brightness tracks velocity, so phrasing is visible */}
      {notes.map((n, i) => (
        <rect
          key={`n${i}`}
          x={x(n.t)} y={y(n.midi[0]) - noteH / 2}
          width={Math.max(2, x(n.dur))} height={noteH}
          rx={1.5}
          fill={`rgba(175,169,236,${0.45 + Math.min(0.55, n.vel * 0.7)})`}
        />
      ))}

      {/* playhead */}
      <line
        x1={x(position)} x2={x(position)} y1={0} y2={H}
        stroke="#fff" strokeWidth={1.5} vectorEffect="non-scaling-stroke"
        opacity={position > 0 ? 0.85 : 0}
      />
    </svg>
  );
};

export default MelodyRoll;
