import React, { useState, useEffect, useCallback } from 'react';
import { useParams, useLocation } from 'react-router-dom';
import { generateAllRoomNames, debugRoomNames } from '../../utils/roomNaming.js';
import LiveKitStreamManagerUpdated from '../livekit/LiveKitStreamManagerUpdated.jsx';
import LiveKitDebugPanel from '../livekit/LiveKitDebugPanel.jsx';
import { 
  Radio, 
  Users, 
  Zap, 
  AlertCircle, 
  CheckCircle,
  Info,
  Monitor,
  Settings
} from 'lucide-react';

/**
 * UnifiedStreamManager - Ensures consistent LiveKit room naming across all pages
 * 
 * This component:
 * 1. Extracts eventId from URL or props
 * 2. Generates standardized room names
 * 3. Ensures all pages connect to the same LiveKit room
 * 4. Provides debugging information
 */
const UnifiedStreamManager = ({
  eventId: propEventId,
  creatorId = null, // artistId of the event creator
  eventInfo = null, // { creatorName, eventTime } for overlay display
  mode = 'viewer', // 'viewer', 'streamer', 'chat'
  showDebug = false,
  className = '',
  onStreamingStatusChange = null, // Callback when streaming status changes
  ...props
}) => {
  const { eventId: urlEventId } = useParams();
  const location = useLocation();
  
  // Determine eventId from props or URL
  const eventId = propEventId || urlEventId;
  
  // State for room management
  const [roomNames, setRoomNames] = useState(null);
  const [currentPage, setCurrentPage] = useState('');
  const [sharingStatus, setSharingStatus] = useState(null);
  const [debugInfo, setDebugInfo] = useState(null);

  // Detect current page context
  useEffect(() => {
    const path = location.pathname;
    
    if (path.includes('/studio')) {
      setCurrentPage('Artist Studio');
    } else if (path.includes('/chat')) {
      setCurrentPage('Event Chat');
    } else if (path.includes('/events/')) {
      setCurrentPage('Event Theatre');
    } else {
      setCurrentPage('Stream Viewer');
    }
  }, [location.pathname]);

  // Generate unified room names
  useEffect(() => {
    if (eventId) {
      try {
        const names = generateAllRoomNames(eventId);
        setRoomNames(names);
        
        // Debug room naming in development
        if (process.env.NODE_ENV === 'development') {
          debugRoomNames(eventId, names.liveKitRoom);
          
          setDebugInfo({
            eventId,
            currentPage,
            roomNames: names,
            urlPath: location.pathname,
            mode,
            timestamp: new Date().toISOString()
          });
        }
        
        setSharingStatus({
          isUnified: true,
          roomName: names.liveKitRoom,
          sessionId: names.sessionId,
          message: `All pages will connect to: ${names.liveKitRoom}`
        });
        
        console.log('🔗 Unified Stream Manager initialized:', {
          eventId,
          page: currentPage,
          liveKitRoom: names.liveKitRoom,
          mode
        });
        
      } catch (error) {
        console.error('❌ Failed to generate unified room names:', error);
        setSharingStatus({
          isUnified: false,
          error: error.message,
          message: 'Failed to unify stream sharing'
        });
      }
    }
  }, [eventId, currentPage, location.pathname, mode]);

  const copyRoomName = useCallback(async () => {
    if (roomNames?.liveKitRoom) {
      try {
        await navigator.clipboard.writeText(roomNames.liveKitRoom);
        console.log('📋 Copied room name:', roomNames.liveKitRoom);
      } catch (error) {
        console.error('Failed to copy room name:', error);
      }
    }
  }, [roomNames]);

  if (!eventId) {
    return (
      <div style={{
        padding: '2rem',
        textAlign: 'center',
        backgroundColor: 'rgba(239, 68, 68, 0.1)',
        border: '1px solid rgba(239, 68, 68, 0.3)',
        borderRadius: '8px',
        color: '#dc2626'
      }}>
        <AlertCircle size={24} style={{ marginBottom: '0.5rem' }} />
        <h3>No Event ID Found</h3>
        <p>Unable to determine which event to connect to.</p>
        <div style={{ fontSize: '0.8rem', marginTop: '1rem', opacity: 0.8 }}>
          Current URL: {location.pathname}
        </div>
      </div>
    );
  }

  if (!roomNames) {
    return (
      <div style={{
        padding: '2rem',
        textAlign: 'center',
        backgroundColor: 'rgba(251, 191, 36, 0.1)',
        border: '1px solid rgba(251, 191, 36, 0.3)',
        borderRadius: '8px',
        color: '#d97706'
      }}>
        <Settings size={24} style={{ marginBottom: '0.5rem' }} />
        <h3>Initializing Stream Sharing</h3>
        <p>Setting up unified room names...</p>
      </div>
    );
  }

  return (
    <div className={`unified-stream-manager ${className}`} style={{ height: '100%' }}>
      {/* Main Stream Manager - Full height */}
      <LiveKitStreamManagerUpdated
        eventId={eventId}
        sessionId={roomNames.sessionId}
        creatorId={creatorId}
        eventInfo={eventInfo}
        className="unified-stream-component"
        onStreamingStatusChange={onStreamingStatusChange}
        options={{
          mode,
          showControls: mode === 'streamer',
          autoJoin: mode === 'viewer',
          enableChat: mode !== 'streamer',
          ...props
        }}
      />
    </div>
  );
};

export default UnifiedStreamManager;