/**
 * Fix for Firebase Performance initialization issues
 * This module provides a safe wrapper for Firebase Performance monitoring
 * to prevent "start is not a function" errors
 */

// Create a safe wrapper for Firebase Performance
const createSafePerformanceMonitor = () => {
  // Check if Firebase is available
  if (!window.firebase || !window.firebase.performance) {
    console.log('[Firebase] Performance monitoring not available - using fallback');
    
    // Return a fallback implementation
    return {
      trace: (traceName) => ({
        start: () => console.log(`[Performance] Started trace: ${traceName}`),
        stop: () => console.log(`[Performance] Stopped trace: ${traceName}`),
        putAttribute: () => {},
        incrementMetric: () => {}
      }),
      // Additional Firebase Performance methods
      mark: (name) => console.log(`[Performance] Marked: ${name}`)
    };
  }
  
  try {
    // Get the original performance instance
    const originalPerformance = window.firebase.performance();
    
    // Create a safer trace function
    const safeTrace = (traceName) => {
      try {
        const originalTrace = originalPerformance.trace(traceName);
        
        // Check if the trace has the required methods
        if (!originalTrace || typeof originalTrace.start !== 'function') {
          console.log(`[Performance] Creating safe trace for: ${traceName}`);
          
          // Return a dummy trace object with all expected methods
          return {
            start: () => console.log(`[Performance] Started trace: ${traceName}`),
            stop: () => console.log(`[Performance] Stopped trace: ${traceName}`),
            putAttribute: () => {},
            incrementMetric: () => {}
          };
        }
        
        return originalTrace;
      } catch (e) {
        console.warn(`[Performance] Error creating trace for ${traceName}:`, e);
        
        // Return a dummy trace object
        return {
          start: () => console.log(`[Performance] Started trace: ${traceName}`),
          stop: () => console.log(`[Performance] Stopped trace: ${traceName}`),
          putAttribute: () => {},
          incrementMetric: () => {}
        };
      }
    };
    
    // Replace the original performance method
    const safePerformance = {
      ...originalPerformance,
      trace: safeTrace
    };
    
    console.log('[Firebase] Performance monitoring patched successfully');
    return safePerformance;
  } catch (error) {
    console.warn('[Firebase] Failed to patch Performance monitoring:', error);
    
    // Return a dummy performance object
    return {
      trace: (traceName) => ({
        start: () => console.log(`[Performance] Started trace: ${traceName}`),
        stop: () => console.log(`[Performance] Stopped trace: ${traceName}`),
        putAttribute: () => {},
        incrementMetric: () => {}
      }),
      mark: (name) => console.log(`[Performance] Marked: ${name}`)
    };
  }
};

// Apply the fix when this module is imported
const applyPerformanceFix = () => {
  try {
    if (window.firebase && window.firebase.performance) {
      // Store the original method
      const originalPerformanceMethod = window.firebase.performance;
      
      // Replace with our safe version
      window.firebase.performance = function() {
        try {
          // Create a safe performance instance
          const safePerfInstance = createSafePerformanceMonitor();
          return safePerfInstance;
        } catch (e) {
          console.warn('[Firebase] Error in performance() method:', e);
          
          // Return a dummy performance object
          return {
            trace: (traceName) => ({
              start: () => console.log(`[Performance] Started trace: ${traceName}`),
              stop: () => console.log(`[Performance] Stopped trace: ${traceName}`),
              putAttribute: () => {},
              incrementMetric: () => {}
            }),
            mark: (name) => console.log(`[Performance] Marked: ${name}`)
          };
        }
      };
      
      console.log('[Firebase] Performance API patched successfully');
    } else {
      console.log('[Firebase] Performance API not available, nothing to patch');
    }
  } catch (error) {
    console.warn('[Firebase] Failed to patch Performance API:', error);
  }
};

// Export the fix function
export const initFirebasePerformanceFix = () => {
  // Apply the fix immediately
  applyPerformanceFix();
  
  // Check if the fix was successful
  if (window.firebase && typeof window.firebase.performance === 'function') {
    try {
      const perfInstance = window.firebase.performance();
      const testTrace = perfInstance.trace('test_trace');
      
      if (testTrace && typeof testTrace.start === 'function') {
        console.log('[Firebase] Performance fix verification: SUCCESS');
        return true;
      } else {
        console.warn('[Firebase] Performance fix verification: FAILED - trace.start is not a function');
        return false;
      }
    } catch (error) {
      console.warn('[Firebase] Performance fix verification error:', error);
      return false;
    }
  } else {
    console.log('[Firebase] Performance API not available after patching');
    return false;
  }
};

// Automatically apply the fix
initFirebasePerformanceFix();

export default {
  initFirebasePerformanceFix
};
