import PredictionCard from './PredictionCard'

export default function PredictionList({ predictions, loading }) {
  if (loading) {
    return (
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {Array.from({ length: 6 }).map((_, i) => (
          <div key={i} className="bg-gray-900 border border-gray-800 rounded-xl p-5 animate-pulse">
            <div className="h-4 bg-gray-800 rounded w-20 mb-3" />
            <div className="h-5 bg-gray-800 rounded w-full mb-2" />
            <div className="h-5 bg-gray-800 rounded w-3/4 mb-4" />
            <div className="space-y-2">
              <div className="h-3 bg-gray-800 rounded" />
              <div className="h-3 bg-gray-800 rounded" />
            </div>
          </div>
        ))}
      </div>
    )
  }

  if (!predictions.length) {
    return (
      <div className="text-center py-16">
        <p className="text-gray-500 text-lg">No predictions match your filters</p>
        <p className="text-gray-600 text-sm mt-1">Try adjusting your search or category filter</p>
      </div>
    )
  }

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
      {predictions.map(p => (
        <PredictionCard key={p.id} prediction={p} />
      ))}
    </div>
  )
}
