// src/components/layout/TalkStudioNav.jsx
//
// The 60px chrome shared by Discover, the scheduling form, rooms and host
// profiles (the Studio draws its own bar). Design: dark indigo nav on
// #0d1220 with a hairline, centre nav items, search pill, and — on Discover
// only — the primary "Schedule a room" action.

import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Search } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import logo from '../../assets/talkstudio-logo.svg';

const NAV_ITEMS = [
  { id: 'discover', label: 'Discover', to: '/' },
  { id: 'schedule', label: 'Schedule', to: '/schedule/all' },
  { id: 'replays', label: 'Replays', to: '/replays' },
  { id: 'following', label: 'Following', to: '/following' },
];

export const initialsOf = (nameOrUser) => {
  const name =
    typeof nameOrUser === 'string'
      ? nameOrUser
      : nameOrUser?.displayName || nameOrUser?.email || '';
  const parts = name.trim().split(/[\s@._-]+/).filter(Boolean);
  if (!parts.length) return '··';
  return (parts[0][0] + (parts[1]?.[0] || '')).toUpperCase();
};

const TalkStudioNav = ({ active = 'discover', compactSearch = false, rightNote = null }) => {
  const { currentUser } = useAuth();
  const navigate = useNavigate();
  const [term, setTerm] = useState('');

  // "Following" is a signed-in view; the handoff shows it on Discover only.
  const items = NAV_ITEMS.filter(item => item.id !== 'following' || currentUser);

  const submitSearch = (e) => {
    e.preventDefault();
    const q = term.trim();
    if (q) navigate(`/search?q=${encodeURIComponent(q)}`);
  };

  return (
    <nav className="ts-nav">
      <Link to="/" className="ts-nav-brand">
        <img src={logo} alt="TalkStudio" />
        <span className="ts-nav-wordmark">TalkStudio</span>
      </Link>

      <div className="ts-nav-items">
        {items.map(item => (
          <Link
            key={item.id}
            to={item.to}
            className={`ts-nav-item ${active === item.id ? 'active' : ''}`}
          >
            {item.label}
          </Link>
        ))}
      </div>

      <div className="ts-nav-right">
        <form
          onSubmit={submitSearch}
          className={`ts-nav-search ${compactSearch ? 'ts-nav-search--compact' : ''}`}
        >
          <Search size={14} />
          <input
            value={term}
            onChange={e => setTerm(e.target.value)}
            placeholder="Search shows, DJs, genres"
            aria-label="Search shows, DJs, genres"
          />
        </form>

        {rightNote}

        {active === 'discover' && !rightNote && (
          <Link to="/schedule" className="ts-btn ts-btn--primary ts-btn--pill">
            Schedule a room
          </Link>
        )}

        {currentUser ? (
          <Link to={`/artist/${currentUser.uid}`} className="ts-avatar" title="Your profile">
            {initialsOf(currentUser)}
          </Link>
        ) : (
          <Link to="/login" className="ts-btn ts-btn--neutral ts-btn--pill">
            Sign in
          </Link>
        )}
      </div>
    </nav>
  );
};

export default TalkStudioNav;
