// src/components/auth/LoginPromptModal.jsx
import React, { useState } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import './LoginPromptModal.css';

const LoginPromptModal = () => {
  const { showLoginPrompt, dismissLoginPrompt, convertAnonymousUser } = useAuth();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  if (!showLoginPrompt) {
    return null;
  }

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    // Validate inputs
    if (password !== confirmPassword) {
      setError('Passwords do not match');
      return;
    }
    
    if (password.length < 6) {
      setError('Password must be at least 6 characters');
      return;
    }
    
    try {
      setError('');
      setLoading(true);
      await convertAnonymousUser(email, password);
      dismissLoginPrompt();
    } catch (error) {
      if (error.code === 'auth/email-already-in-use') {
        setError('This email is already in use. Please try a different email.');
      } else {
        setError('Failed to create an account: ' + error.message);
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-prompt-modal-overlay">
      <div className="login-prompt-modal">
        <h2>Create an Account</h2>
        <p>You've been using Talk Studio anonymously for 12 hours. Create an account to save your data and access all features!</p>
        
        {error && <div className="error-message">{error}</div>}
        
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label htmlFor="email">Email</label>
            <input
              type="email"
              id="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              disabled={loading}
            />
          </div>
          
          <div className="form-group">
            <label htmlFor="password">Password</label>
            <input
              type="password"
              id="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              disabled={loading}
            />
          </div>
          
          <div className="form-group">
            <label htmlFor="confirmPassword">Confirm Password</label>
            <input
              type="password"
              id="confirmPassword"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              required
              disabled={loading}
            />
          </div>
          
          <div className="form-actions">
            <button 
              type="button" 
              onClick={dismissLoginPrompt} 
              className="secondary-button"
              disabled={loading}
            >
              Maybe Later
            </button>
            <button 
              type="submit" 
              disabled={loading} 
              className="primary-button"
            >
              {loading ? 'Creating Account...' : 'Sign Up'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default LoginPromptModal;