// src/pages/TrackPage.jsx
//
// Shareable track page (/track/:id) — the "advertise your content" URL.
// Plays the jam, links to the creator's profile, and offers remix +
// copy-link. This is what users send around when they're not live.

import React, { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { ChevronLeft, Music2, Loader } from 'lucide-react';

import { getJam } from '../services/jamService';
import { useJamPlayer } from '../hooks/useJamPlayer';
import TrackCard from '../components/audio/TrackCard';

const TrackPage = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const player = useJamPlayer();
  const [jam, setJam] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    (async () => {
      try {
        const j = await getJam(id);
        if (j) setJam(j); else setError('Track not found');
      } catch (e) {
        setError(e.message || 'Could not load track');
      }
    })();
  }, [id]);

  return (
    <div
      style={{
        minHeight: '100vh',
        background:
          'radial-gradient(circle at 20% 0%, rgba(127, 119, 221, 0.18), transparent 55%),' +
          'radial-gradient(circle at 80% 100%, rgba(93, 202, 165, 0.10), transparent 60%),' +
          '#0a0a12',
        color: '#e8e8f0',
        fontFamily: '-apple-system, BlinkMacSystemFont, system-ui, sans-serif',
        padding: '1rem',
      }}
    >
      <div style={{ maxWidth: 640, margin: '0 auto' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <button
            onClick={() => navigate(-1)}
            style={{
              background: 'transparent', border: 'none', color: '#8b8b9a',
              display: 'inline-flex', alignItems: 'center', gap: 4,
              padding: '0.5rem 0', cursor: 'pointer', fontSize: '0.85rem',
            }}
          >
            <ChevronLeft size={16} /> Back
          </button>
          <button
            onClick={() => navigate('/jams')}
            style={{
              background: 'transparent', border: '1px solid #25252e', color: '#8b8b9a',
              display: 'inline-flex', alignItems: 'center', gap: 6,
              padding: '6px 12px', borderRadius: 8, cursor: 'pointer', fontSize: 12,
            }}
          >
            <Music2 size={14} /> Jam feed
          </button>
        </div>

        <h1 style={{ fontSize: '1.4rem', fontWeight: 600, margin: '0.75rem 0 0.25rem' }}>
          {jam ? jam.title : 'Track'}
        </h1>
        {jam && jam.createdBy && (
          <p style={{ color: '#8b8b9a', fontSize: '0.9rem', margin: '0 0 1.25rem' }}>
            by{' '}
            <span
              onClick={() => navigate(`/profile/${jam.createdBy.uid}`)}
              style={{ color: '#5DCAA5', cursor: 'pointer' }}
            >
              {jam.createdBy.name}
            </span>
          </p>
        )}

        {!jam && !error && (
          <div style={{ textAlign: 'center', color: '#6b6b7a', padding: '3rem 0' }}>
            <Loader size={24} style={{ animation: 'track-spin 1s linear infinite' }} />
            <style>{`@keyframes track-spin { from { transform: rotate(0); } to { transform: rotate(360deg); } }`}</style>
          </div>
        )}
        {error && <div style={{ color: '#fca5a5', fontSize: 13 }}>{error}</div>}

        {jam && <TrackCard jam={jam} player={player} showCreator />}

        {jam && (
          <p style={{ color: '#6b6b7a', fontSize: 12, marginTop: 16 }}>
            This track was made in the Jam Studio — the sound re-renders live
            from its note data. Hit remix to build on it.
          </p>
        )}
      </div>
    </div>
  );
};

export default TrackPage;
