import { useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { signInAnonymously } from 'firebase/auth';
import { auth } from '../../firebase';

/**
 * Component to handle anonymous authentication
 * This will automatically sign in users anonymously if they're not already authenticated
 */
const AnonymousAuth = () => {
  const { currentUser, loginAnonymously } = useAuth();
  
  useEffect(() => {
    // Check if user is already authenticated
    if (!currentUser) {
      console.log('No user detected, signing in anonymously...');
      
      // Sign in anonymously
      const signInAnon = async () => {
        try {
          await loginAnonymously();
          console.log('Anonymous sign-in successful');
        } catch (error) {
          console.error('Error signing in anonymously:', error);
        }
      };
      
      signInAnon();
    }
  }, [currentUser, loginAnonymously]);
  
  // This component doesn't render anything
  return null;
};

export default AnonymousAuth;
